window.HB_TR["genesis"]["ks"]=["1. ابتداہس مَنٛز چُھ خداین اسمانس تہٕ زمین تخلیق کٔرمٕژ۔\n2. تہٕ زمین ٲس بے شکل، تہٕ خٲلی۔ تہٕ سرٛنِس بُتھِس پیٹھ اوس انہِ گوٚٹ۔ تہٕ خدایہ سُند روح ووت آبس پیٹھ پٔکۍ۔\n3. تہٕ خداین ووٚن گاش آسُن، تہٕ گاش آسہِ۔\n4. تہٕ خداین وُچھ گاش، زِ یہِ اوس اصل، تہٕ خداین کٔر گاش انہِ گٹہِ نِش تقسیم۔ {گاش پیٹھ...: ہیب۔ گاشس تہٕ اندھیرس درمیان}\n5. تہٕ خداین ووٚن گاشس دۅہہ، تہٕ انہِ گٹہِ وَنُن رٲژ۔ تہٕ شام تہٕ صُبح اوس گۄڈنیُک دۄہ۔ {تہٕ شام...: ہیب۔ تہٕ شام اوس، تہٕ صبح اوس وغیرہ۔}\n6. تہٕ خداین ووٚن آبس منز آسُن اکھ آسمان، تہٕ آبس سٍتـ̡ الگ کرُن۔ {آسمان: ہیب۔ توسیع}\n7. تہٕ خداین بنوو آسمان، تہٕ کٔرٕن آب یُس آسمانس تل اوس، تِمن آبس سٍتۍ تقسیم یُس آسمانس پیٹھۍ اوس، تہٕ یہ اوس یۅہے گومُت۔\n8. تہٕ خداین وون آسمانس جنت۔ تہٕ شام تہٕ صُبح اوس دوٚیِم دۄہ۔ {تہٕ شام...: ہیب۔ تہٕ شام اوس، تہٕ صبح اوس وغیرہ۔}\n9. تہٕ خداین ووٚن، آسمانس تل آب گژھن أکسٕے جایہ جمع کرنہٕ، تہٕ خشک زمینہٕ گژھہِ ظٲہر کرنہٕ، تہٕ یہِ سپُد یِتھُے ۔\n10.\\tتہٕ خداین وون خشک زمین۔ تہٕ آبن ہٕندِس اجتماعس سٍتـ̡ وُچھِتھ سمندر: تہٕ خداین وُچھ زِ یہِ چُھہ اصل۔\n11.\\tتہٕ خداین ووٚن زِ زمینہِ نیرُن گاسہٕ، کُلۍ یُس بیول دِوان چھُ، تہٕ سُہ پھلہٕ کُلِس یُس پننہِ قسمہ پتہٕ پھل دِوان چھُ، یٔمۍ سُند بیول بذات خود چھُ، زمینس پیٹھ۔ {گاس: ہیب۔ ٹینڈر گاسہٕ}\n12.\\tتہٕ زمینہِ کٔر گاسہٕ پٲدٕ کٔرِتھ، تہٕ کُلِس کُلِس سٍتـ̡ پھل دِنہٕ آمُت، یێمہِ سُند بیول اوس بذات خۅد تہٕ خداین وُچھ زِ یہِ چُھہ اصل۔\n13. تہٕ شام تہٕ صُبح اوس تریم دۅہ۔ {تہٕ شام...: ہیب۔ تہٕ شام اوس، تہٕ صبح اوس وغیرہ۔}\n14.\\tتہٕ خداین ووٚن زِ اسمانس منز گژھہِ گاش آسُن یُس دۅہہٕ تہٕ رٲژ الگ کرُن۔ تہٕ تِم گژھن علامتن خٲطرٕ، تہٕ موسمن خٲطرٕ، تہٕ دۄہن تہٕ ؤرین خٲطرٕ: {دۅہ...: ہیب۔ دۅہس تہ رٲژ درمیان}\n15.\\tتہٕ تِم گژھن آسمانس منز گاشہٕ خٲطرٕ زمینس پیٹھ گاش دِنہٕ خٲطرٕ، تہٕ یہِ سپُد۔\n16. تہٕ خداین بنوو زٕ بٔڈ گاش۔ دۅہس پیٹھ حکمرٲنی کرنہٕ خٲطرٕ زیادٕ گاش، تہٕ راتس پیٹھ حکمرٲنی کرنہٕ خٲطرٕ کم گاش: {تٔمۍ بنوو}ستارٕ تہِ۔ {دۅہس پیٹھ حکمرٲنی کرُن...: ہیب۔ دوہ کہ اصولن خاطرٕ، وغیرہ۔}\n17. تہٕ خداین تھوو تِم آسمانہٕ کِس آسمانس مَنٛز زمینس پیٹھ گاش دِنہٕ خٲطرٕ،\n18.\\tتہٕ دۅہس تہٕ راتس پیٹھ حکومت کرُن، تہٕ گاش انہِ گٹہِ نِش الگ کرُن، تہٕ خداین وُچھ زِ یہِ چُھ اصل۔\n19. تہٕ شام تہٕ صُبح اوس ژوٗرِم دۄہ۔ {تہٕ شام...: ہیب۔ تہٕ شام اوس، تہٕ صبح اوس وغیرہ۔}\n20.\\tتہٕ خداین ووٚن زِ آبس گژھہِ سُہ حرکت پذیر مخلوق یُس زندگی آسہِ، تہٕ جاناوار گژھہِ آسمانہ کِس کھُلہٕ آسمانس منز زمینہِ پیٹھۍ وُڈان۔ {حرکت کَرُن: یا، کریپِنگ} {زندگی: ہیب۔ روح} {پرند...: ہیب۔ کۅکرِ وُڈُن} {کھُلہِ...: ہیب۔ آسمانک آسمانک بُتھ}\n21.\\tتہٕ خداین بنوو بٔڈۍ وہیل تہٕ پرٮ۪تھ کانہہ جاندار یُس حرکت کران چُھ، یُس آبس سٍتـ̡ وافر پٲٹھـ̡ نیران چُھ، تہٕ پرٮ۪تھ پَکھہٕ دار جاناوار پننہِ قسمہٕ پتہٕ، تہٕ خداین وُچھ زِ یہِ چُھ اصل۔\n22.\\tتہٕ خداین دِژ تِمن برکت دِتھ زِ پھلدار گژھِو تہٕ بڑاوُن تہٕ سمندرن مَنٛز آبس بٔرِتھ تہٕ کُنہِ سٍتـ̡ بٔرِتھ تہٕ کُنہِ س�\n23. تہٕ شام تہٕ صُبح اوس پوٗنٛژِم دۄہ۔ {تہٕ شام...: ہیب۔ تہٕ شام اوس، تہٕ صبح اوس وغیرہ۔}\n24.\\tتہٕ خداین ووٚن زِ زمینہِ ہٕندِس قٕسمس پۯاوُن جاندار، چاروٲے تہٕ کُنہِ چیزس پَتہٕ تہٕ زمینہِ ہُند جانور تہٕ یِتھے پٲٹھۍ سپدُن۔\n25. تہٕ خداین بنوو زمینُک جانور پننہِ قسمہ پتہٕ، تہٕ چاروٲے تہٕ پریتھ کانہہ چیز یُس پننہِ قسمہ پتہٕ زمینس پیٹھ کھسان چُھ، تہٕ خداین وُچھ زِ یہِ چُھ اصل۔\n26.\\tتہٕ خداین ووٚن زِ أسۍ بناوو انسان پننہِ شکلہِ منز، پننہِ شکلہِ پٲٹھۍ، تہٕ سمندرٕ کِس گاڈَس پیٹھ، ہوہٕکِس مرغن پیٹھ، چارواین پیٹھ، تہٕ سارِنٕے زمینس پیٹھ تہٕ زمینس پیٹھ کھسنہٕ وٲلِس پرٮ۪تھ کُنہِ چیزس پیٹھ غلبہٕ حٲصل کرُن۔\n27. چنانچہ خداین بنوو انسان پننہِ شکلہِ منز، خدایہ سٕنزِ شکلہِ منز بنوو سُہ ۔ مرد تہٕ زنانہٕ بنوو تِم۔\n28. تہٕ خداین کٔر تِمن برکت تہٕ خداین ووٚن تِمن پھلہٕ دار تہٕ بڑاوُن تہٕ زمینہٕ بٔرِتھ تہٕ زیر کرُن، تہٕ سمندرٕچ گاڈٕ تہٕ ہوہٕچ مرغن تہٕ زمینس پیٹھ پکان وٲلِس پرٮ۪تھ کُنہِ جاندارس پیٹھ گژھن غلبہٕ۔ {moveth: Heb. کریپتھ}\n29. تہٕ خداین ووٚن، وچھ میہ دِژ ژے پرتھ کُلۍ یُس سٲرۍسٕے زمینہٕ کِس بُتھِس پیٹھ چُھ، تہٕ پرٮ۪تھ کُلِس مَنٛز چُھہ کُلِس پھل دِنہٕ آمُت۔ ژےٚ آسہِ یہ مازٕ خٲطرٕ۔ {بیئرنگ...: ہیب۔ بیٛول بیٛٲل} {پٲداوار...: Heb. بیٲلۍ بیٛول دِنہٕ}\n30.\\tتہٕ زمینہٕ کِس پرٮ۪تھ کُنہِ درندَس تہٕ ہوہٕکِس پرٮ۪تھ کُنہِ چیزس یُس زمینہِ پیٹھ وسان چھُ، یَتھ مَنٛز زندگی چھِ، {مے دِژمُت} پرٮ۪تھ سبز کُلۍ بوٹی ماز خٲطرٕ: تہٕ یہِ اوس یِتھُے ۔ {زندگی: ہیب۔ اکھ زندٕ روح}\n31.\\tتہٕ خداین وُچھ پریتھ کانہہ چیز یُس تمۍ بنوومت اوس، تہٕ وچھ یہ اوس واریاہ اصل۔ تہٕ شام تہٕ صُبح اوس شیٚیِم دۄہ۔ {تہٕ شام...: ہیب۔ تہٕ شام اوس، تہٕ صبح اوس وغیرہ۔}","1. یِتھٕ پٲٹھـ̡ گۆو آسمانن تہٕ زمینن تہٕ تِمن ہٕندِس سارِنٕے لشکرس ختم۔\n2. تہٕ سٔتِمہِ دۅہہٕ کٔر خداین پنٕنۍ کٲم ختم۔ تہٕ سٔتِم دۅہہ آرام دِژ پننہِ سارِنٕے کامہِ نِش یُس تٔمۍ کٔرمٕژ ٲس۔\n3.\\tتہٕ خداین دِژ سٔتِم دۅہہٕ برکت تہٕ کوٚرُن سُہ پاکس، تکیازِ اتھ مَنٛز اوس تٔمِس پنہٕ نِس سارِنٕے کامہِ نِش آرام دِژمُت یُس خداین تخلیق کٔرِتھ تہٕ بنوو۔ {تخلیق...: ہیب۔ بناونہٕ خٲطرٕ بناونہٕ آمُت}\n4. یِم چھِ آسمانن تہٕ زمینٕچ نسلہٕ یێلہِ یێلہِ یِم تخلیق گٔیہِ، ییمہِ دۅہہٕ خداوند خداین زمینہٕ تہٕ آسمانن بنوومُت،\n5. تہٕ امہِ برونہہ اوس کھہُک پرٮ۪تھ کُل زمینس مَنٛز، تہٕ امہِ برونہہ اوس کھہُک پرٮ۪تھ کانہہ کُلہِ وُچھمُت، تکیازِ خداوند خداین اوس نہٕ زمینس پیٹھ روٗد وومُت، تہٕ نہ اوس کانہہ انسان زمینہِ پیٹھ ووتمُت۔\n6.\\tمگر ووت زمینہِ منزہ اکھ وُنلہِ، تہٕ دِژ سٲرۍسٕے زمینہٕ سٍتـ̡ آب۔ {تتہِ...: یا، اکھ وُنَل یُس تھوٚد کھوٚت وغیرہ۔}\n7. تہٕ خداوند خداین بنوو انسان زمینہِ ہٕنزِ گردِ سٍتـ̡ تہٕ دِژُن تسٕنزِ نستہِ مَنٛز زندگی ہُند شاہ۔ تہٕ انسان بنیوو اکھ زندٕ روح۔ {گردِ ہُند...: ہیب۔ زمینچ گرد}\n8. تہٕ خداوند خداین لگٲو عیدن مَنٛز مشرقس کُن اکھ باغ۔ تہٕ تتہِ تھوو سُہ نفر یُس تٔمۍ بنٲومُت اوس۔\n9. تہٕ زمینہٕ منزٕ بنوو خداوند خدایہ پریتھ کُل وۄپداونہٕ یُس وچھنہٕ خٲطرٕ خۄشگوار آسہِ، تہٕ کھینہٕ خٲطرٕ اصل آسہِ۔ زندگی ہند کُل تہِ باغس منز، تہٕ نیکی تہٕ بدی ہٕندِس علمُک کُل۔\n10. تہٕ باغ آب دِنہٕ خٲطرٕ دراو اکھ دریاو عدن منز۔ تہٕ تتہٕ پیٹھہٕ آو یہٕ الگ کرنہٕ، تہٕ بنیوو ژۄن کلن منٛز۔\n11.\\tگۅڈنچہ {is} پیسن ہند ناو: یعنی {is} یُس سورے حویلہ کس سرزمینس اندۍ پکھۍ چھہ، ییتہِ {اتہِ} سون چھہِ۔\n12.\\tتہٕ تمہِ زمینُک سون {چُھ} اصل: اتہِ {چُھ} بڈیلیم تہٕ اونکس کٔن۔\n13.\\tتہٕ دوٚیمِس دٔریاوُک ناو چُھہ گیہون: سُے {چُھ} یُس ایتھوپیا کِس پوٗرٕ سرزمینس سٍتـ̡ گھیرِتھ چُھ۔ {ایتھوپیا: ہیب۔ کُش}\n14.\\tتہٕ تریمہِ دریاوُک ناو {is} ہدیکیل: یعنی {is} یُس اشوریہ کِس مشرقس کُن واتان چُھ۔ تہٕ ژوٗرِم دٔریاو چھُ فرات ۔ {کُن...: یا، مشرقس کُن اسریاہس کُن}\n15.\\tتہٕ خداوند خداین نیو یہِ انسان تہٕ تھووُن عدن کِس باغس مَنٛز۔ {مرد: یا، آدم}\n16.\\tتہٕ خداوند خداین دِیُت انسانس حکم دِتھ زِ باغ کِس پرٮ۪تھ کُلِس مَنٛز گژھِو ژے آزادانہٕ کھٮ۪ن: {توہ...: ہیب۔ کھیوٚن کھیوٚن}\n17.\\tمگر نیکی تہٕ بدی ہٕندِس علمہٕ کُلِس سٍتـ̡ گژھِ نہٕ اَمہ سٍتـ̡ کھیوٚن، تکیازِ ییمہِ دۅہہٕ ژے اَمہ سٍتـ̡ چُھہ یێلہِ تہٕ یێلہِ تُہٕندِس دۅہہٕ سٍتـ̡ مَرُن۔ {ژیہ پزۍ پاٹھۍ کرُن...: ہیب۔ مرنہٕ سٍتۍ گژھہِ ژیہ مرُن}\n18. تہٕ خداوند خداین ووٚن، {یہٕ چُھنہٕ اصل} زِ انسان گژھہِ کُنی آسُن۔ بہٕ بناوٕ أمِس خٲطرٕ اکھ مدد۔ {مِلُن...: ہیب۔ یِتھ کٔنۍ أمِس برٛونٛہہ}\n19.\\tتہٕ زمینہٕ منزٕ بنوو خداوند خداین میدانُک پرٮ۪تھ کانہہ جانور تہٕ ہوہُک پرٮ۪تھ کُنہِ جاناوار۔ تہٕ أنِن آدمس نِش زِ سُہ کیا وَنُن تِمن کیا وَنُن: تہٕ یُس آدم پرٮ۪تھ جاندار وَنُن اوس، سُہ اوس اَمیُک ناو۔ {آدم: یا، مرد}\n20. تہٕ آدمن دِژ سارنٕے چارواین تہٕ ہوہٕکۍ جاناوارن تہٕ کھہہٕ کِس پرٮ۪تھ کُنہِ جاناوارس ناو۔ مگر آدم سٕندِ خٲطرٕ لوٚب نہٕ أمِس خٲطرٕ کانہہ مدد۔ {دِیُت: ہیب۔ بلاو}\n21.\\tتہٕ خداوند خداین دیت آدم سٕندِس سٍتـ̡ گۆو سرٛوٚن نوٚندر، تہٕ سُہ گۆو شوٚنگِتھ تہٕ تٔمۍ رٔٹِتھ پَنٕنہِ پَنٕنـ̡ پى۪ٹھٕ رٔٹِتھ تہٕ دِژُن ماز بنٛد کٔرِتھ۔\n22.\\tتہٕ یُس رِب یُس خداوند خداین انسانس نِش نِش نِیومُت اوس، سُہ بنوو زنانہٕ تہٕ أنِن مردس نِش۔ بَناونہٕ آمُت}\n23.\\tتہٕ آدمن ووٚن، یہِ چُھہ وۅنۍ میانین اڈجن ہٕنز ہڈی تہٕ میانہِ مازُک ماز، أمِس گژھہِ زنانہٕ وننہٕ یُن، تکیازِ سۅ ٲس انسانہٕ نِش کڈنہٕ آمٕژ۔ ایشہ} {انسان: ہیب۔ ایش}\n24.\\tتێلہِ گژھہِ مرد پننِس مٲلِس تہٕ ماجہ ترٲوِتھ پننہِ زنانہِ سٍتـ̡ ژٔٹِتھ تہٕ تِم گژھن اَکہِ ماز بٔنِتھ۔\n25.\\tتہٕ تِم ٲسۍ دۅشوے ننگہٕ، مرد تہٕ تٔمۍ سٕنز خانٛدارِنہِ، تہٕ ٲسٕکھ نہٕ شرمندٕ۔","1.\\tوۅنۍ اوس ناگ کھیت کِس کُنہِ تہِ درندٕ کھۅتہٕ زیادٕ لطیف یُس خداوند خداین بنوومُت اوس۔ تہٕ تٔمۍ ووٚن زنانہِ آ، آ، کیا خدایہ چُھہ ووٚنمُت، باغ کُلِس منز کیا کھیوٚو نہٕ؟ {آ...: ہیب۔ آ، کیازِ، وغیرہ}\n2. تہٕ زنانہِ ووٚن ناگس زِ أسۍ ہیکو باغ کین کُلٮ۪ن ہٕندِس پھلہٕ سٍتـ̡ کھٮ۪وان:\n3.\\tمگر باغس منز موجود کُلِس مٮ۪وٕ سٍتـ̡ خداین چُھ وَنُن زِ تُہہِ چُھہ نہٕ اَتھ مَنٛز کھٮ۪وان تہٕ نہ گژھِو اَتھ اَتھٕ لاگُن، نۂ مَرُن۔\n4.\\tتہٕ ناگن ووٚن زنانہِ زِ ژیہ گژھہِ نہ مرُن:\n5.\\tخدا چُھ زانان زِ یێمہِ دۅہہٕ یێلہِ تہٕ یێلہِ گژھہِ تُہٕنزِ أچھ یلہٕ تہٕ نیکی تہٕ بدی زانِتھ گژھِو خداہٕ۔\n6.\\tتہٕ ییلہ زنانہِ وُچھ زِ یہ کُل چُھہ کھٮ۪نہٕ خٲطرٕ اصل، تہٕ یہِ چُھہ أچھن خٲطرٕ خۅش تہٕ اکھ کُل یُس عقلمند بناوُن یُس یُس کُل دِنہٕ یُن، تٔمۍ نِش نِش پھل تہٕ کھیوٚن تہٕ دیتُن پننِس خاوندس تہِ۔ تہٕ تٔمۍ کھیوٚو کھٮ۪وان۔ {خوشگوار: ہیب۔ اکھ خواہش}\n7.\\tتہٕ یِمن دۄشوٕنی ہٕنزِ أچھ گٔیہٕ یلہٕ، تہٕ تِمن ٲس پتاہ زِ تِم چھِ ننگہٕ۔ تہٕ تِمو سِوۍ انجیر پنہٕ ؤتھٕر اکوٹہٕ، تہٕ بنوو پانس ایپرن۔ {ایپرون: یا، چیز ٹو گرڈ}\n8. تہٕ تِمو بوز خداوند سٕنز آواز یُس دۅہہٕ کِس ٹھنڈس مَنٛز باغس مَنٛز پکان اوس، تہٕ آدم تہٕ تٔمۍ سٕنزِ زنانہِ کٔر باغ کِس کُلِس مَنٛز خدایہ سٕنزِ موجودگی نِش ژورِ۔ {ٹھنڈ: ہیب۔ ہوا}\n9. تہٕ خداوند خداین بُلوو آدمس تہٕ وونُن تٔمِس کتہِ؟\n10.\\tتہٕ تٔمۍ ووٚن، میہ بوز تہنز آواز باغس منز، تہٕ بہٕ اوسس کھوژان، تکیازِ بہٕ اوسُس ننگہٕ اوسمُت۔ تہٕ میہ کٔر پان ژور۔\n11.\\tتہِ ووٚن ژیہ کٔمۍ ووٚن ژیہ ننگہ؟ ژے چھکھ کُلِس کھیوٚمُت، یُس میہ حُکُم دِتمُت چھُس نہٕ کھیوٚن؟\n12.\\tتہٕ مردس ووٚن، یۅسہٕ زنانہٕ ژے میہ سٍتـ̡ دِژمٕژ ٲس، سۅ دِژ میہ کُلِس منز، تہٕ میہ کھیوٚو کھیوٚن۔\n13.\\tتہٕ خداوند خداین ووٚن زنانہِ زِ یہِ کیا چُھہ ژے کورمُت؟ تہٕ زنانہِ ووٚن، ناگن کٔر میہ دھوکہ، تہٕ مے کھیوٚو کھیوٚن۔\n14.\\tتہٕ خداوند خداین ووٚن ناگس سٍتـ̡، کیازِ ژے چُھہ یہِ کورمُت، تہٕ چُھکھ سارِنٕے چارواین تہٕ کھہہٕ کِس پرٮ۪تھ درندَس پیٹھٕ لعنت۔ ژیہ گژھہِ پننہِ یٔڈ پیٹھ، تہٕ ژیہ ژیہ پننہ زندگی ہندۍ سٲری دۅہ کھیوٚن:\n15. تہٕ بہٕ کٔرٕ ژےٚ تہٕ زنانہِ درمِیان تہٕ چانہِ بُلِس تہٕ تٔمۍ سٕندِس بُلِس درمِیان دُشمنی ۔ یہ گژھہِ تۅہہِ کلہ زخم تہ ژیہ لگہِ کھورِ کھور۔\n16.\\tزنانہِ سٍتـ̡ وۆن، بہٕ کرٕ چانہِ غم تہٕ تُہند تصور واریاہ زیادٕ۔ غم سٍتـ̡ کٔرِو شُرِ پٲدٕ۔ تہٕ تہنز خواہش آسہِ پننِس خاوندس سٍتۍ، تہٕ سُہ کرِ تۅہہِ پیٹھ حکمرٲنی کرنہٕ۔ {تۅہہِ...: یا، پننِس خاوندس تابع}\n17.\\tتہٕ آدمس ووٚن تکیازِ ژے چُھہ پننہِ زنانہِ ہٕنز آواز بوزمٕژ، تہٕ کُلِس کھیوٚمُت، یُس میہ ژے حکم دِتمُت اوس، تہٕ وونُن زِ ژے گژھ نہٕ اتھ منز کھیوٚن، تہٕ چُھہ ژے خٲطرٕ زمینہِ پیٹھ لعنت۔ غم سٍتـ̡ چُھہ ژیہ پننہ زندگی ہٕندِس سارِنٕے دۅہس کھٮ۪وان۔\n18.\\tکانٹہٕ تہٕ کُلہٕ تہِ دِیہِ تۅہہِ برونہہ کُن۔ تہٕ کھہٕچ جڑی بوٹی کھیوٚن؛ {انن...: ہیب۔ وجہ ٹو بڈ}\n19.\\tبُتھِس پسینہٕ سٍتـ̡ کھیوٚو روٹی کھٮ۪وان، یوتام نہٕ ژے زمینس پیٹھ واپس۔ تکیازِ تۅہہ آو اَمہ منزٕ نِنہٕ: تہٕ ژے گٔژھِتھ تہٕ گردِ کُن واپس۔\n20. تہٕ آدم ووٚن پننہِ زنانہِ ہُند ناو حوا۔ تکیازِ سۅ ٲس سارنٕے زندن ہنز موج۔ {حوا: ہیب۔ چاواہ: سہ چھہ زندہ}\n21. آدم سٕندِ تہٕ تٔمۍ سٕنزِ زنانہِ ہٕندِ خٲطرٕ تہِ بنوو خداوند خداین کھالٕکۍ کوٹ تہٕ پلو۔\n22. تہٕ خداوند خداین ووٚن، وُچھ، انسان چُھ اسہِ منزٕ اکھ بنیومُت، نیکی تہٕ بدی زاننہٕ خٲطرٕ، تہٕ وُن، یُس پَنُن اَتھٕ تُلِتھ تہٕ زندگی ہٕندِس کُلِس تہٕ کھٮ۪نہٕ تہٕ ہمیشہٕ خٲطرٕ زندٕ روزِ۔\n23. تێمہِ کِنۍ سُہ خداوند خداین سُہ عدن کِس باغہٕ پى۪ٹھہٕ دِنہٕ آمُت، تَمہِ مۄکھٕ یێلہِ سُہ نِنہٕ آمُت چھُ۔\n24. تہٕ تٔمۍ ژٔٹۍ أمِس نفرس کٔڑ۔ تہٕ تٔمۍ تھوو ایڈن کروبمز کِس باغس مشرقس منٛز، تہٕ اکھ آتش تلوار یۄس زندگی ہٕنٛدس کُلِس وتھ برقرار تھاونہٕ خٲطرٕ پریتھ وتہٕ پھیران ٲس۔","1. تہٕ آدم اوس حوا سٕنز زنانہٕ زانان۔ تہٕ تٔمۍ کٔر حاملہٕ، تہٕ کٔرٕن قابیل، تہٕ وونُن، مے چُھ خداوند سٕندِ طرفہٕ اکھ مرد حٲصل کوٚرمت۔ {کین: یعنی، گوٹن، یا، حاصل}\n2. تہٕ سُہ دُبارٕ پنُن بوے ہابیل زٲلِتھ۔ تہٕ ہابیل اوس دانٛد رچھن وول مگر قابیل اوس زمینہِ ہُند کاشر۔ {ہابیل: ہیب۔ ہیبل} {اکھ کیپر: ہیب۔ اکھ فیڈر}\n3.\\tتہٕ وقتس سٍتـ̡ سپد یہِ سپدُن، قایِن اوٚن زمینہِ ہٕندِ پھلہٕ سٍتـ̡ خداوند سٕندِ خٲطرٕ نذرانہ دِنہٕ۔ {عملہِ منز...: ہیب۔ دۅہن ہندِس ٲخرس پیٹھ}\n4.\\tتہٕ ہابیل، تٔمۍ تہِ أنۍ پننِس ریوڑس تہٕ تِمن ہٕندِس چربی ہٕندِس گۄڈنِکِس بچس منز۔ تہٕ خداوند اوس ہابیل تہٕ تٔمۍ سٕنزِ نذرانہ ہُند احترام: {ریوڑ: ہیب۔ کٹہٕ، یا ژھاوٕل}\n5.\\tمگر قابیل تہٕ تٔمۍ سٕنزِ نذرانہ سٍتـ̡ اوس نہٕ تس کانہہ احترام۔ تہٕ قابیل گوٚو سٮ۪ٹھاہ شرارت، تہٕ تٔمۍ سُند بُتھ پیوٚو پیوٚو۔\n6. تہٕ خداوند ووٚن قایِنس زِ ژے کیازِ چُھکھ شرارت؟ تہٕ تُہند بُتھ کیازِ چھُ؟\n7.\\tاگر ژیہ رژھ تہٕ اگر نہٕ ژیہ ٹھیٖک کٔرِو، گۅناہ گژھہِ دروازس پیٹھ۔ تہٕ تٔمۍ سٕنٛز خواہش آسہٕ تہٕ تٔمۍ سٕنٛز حُکوٗمت کٔرٕنۍ۔ {قبول: یا، ہیو دی ایکسلینسی} {تو...: یا، تابع ژے}\n8.\\tتہٕ قایِن کٔر پننِس بٲیِس ہابیلس سٍتـ̡ کتھ تہٕ سپُد ییلہ تِم میدانس مَنٛز ٲسۍ، قایِن ووت پننِس بٲیِس ہابیلس خٕلاف تہٕ مارُن سُہ ۔\n9. تہٕ خداوند ووٚن قایِن، کتہِ چُھہ ہابیل تُہند بوے ؟ تہٕ تٔمۍ ووٚن، بہٕ چھُس نہٕ پتاہ: {بہٕ چھُس} پننِس بٲے سُند رٲچھ کَرُن؟\n10.\\tتہِ ووٚن ژیہ کیا کورمُت؟ چانہِ بٲے سٕندِ خونٕچ آواز چھے زمینہٕ پیٹھٕ میہ کُن فریاد کران۔ {خون: ہیب۔ بلڈز}\n11.\\tتہٕ وُنہِ چھُکھ ژے زمینہِ سٍتـ̡ لعنت دِژمٕژ، یێمہِ سٍتـ̡ تُہٕندِس اتھہٕ سٍتـ̡ بٲے سُند خوُن رٹنہٕ مۅکھہٕ چُھہ پننِس بٲے سُند خون رٹنہٕ مۅکھہٕ چُھہ چُھہ تُہٕندِس\n12.\\tییلہ ژیہ زمینہِ ہٕندِس کُنہِ کُنہِ تہِ دِیہِ نہٕ تۅہہِ ہٕندِس طاقتس سٍتـ̡ دِنہٕ۔ ژیہ گژھہِ زمینس منز اکھ فرار تہٕ آوارہ وار۔\n13. تہٕ قایِن ووٚن خداوند سٍتـ̡ میٲنۍ سزا چُھہ بہٕ سٍتـ̡ زیادٕ زیادٕ۔ {میانۍ...: یا، میون بدکار چھہ امہ کھوتہ زیادہ زِ یہ گژھہِ معاف}\n14.\\tوُچھ، ژے کٔر میہ از دۅہہ زمینہِ پیٹھٕ ژٔٹِتھ کٔڈِتھ۔ تہٕ ژےٚ بُتھِ نِش گژھٕ بہٕ پوشہٕ۔ تہٕ بہٕ روزٕ زمینس منز اکھ فرار تہٕ اکھ آوارہ وار۔ تہٕ یہِ سپدِ سپدِ، {یُس} یُس میہ لبان آسہِ سُہ کرِ میہ مارُن۔\n15.\\tتہٕ خداوند ووٚن أمِس زِ یُس تہِ قاین مارِ، سُہ گژھہِ تس سَتھ گنہٕ انتقام نِنہٕ۔ تہٕ خداوند کٔر قایِنس پیٹھ نشانہٕ، یُس نہٕ کانہہ تہِ لٔبِتھ سُہ مارِ۔\n16. تہٕ قابیل دراو خداوند سٕنزِ حضوری منز، تہٕ رودُن عدن کِس مشرقس مَنٛز نود کِس سرزمینس مَنٛز۔\n17. تہٕ قابیل اوس پننہِ زنانہِ زانان۔ تہٕ تٔمۍ کٔر حاملہٕ، تہٕ حنوک: تہٕ تٔمۍ بنوو اکھ شہر، تہٕ تھووُن شہرُک ناو پننِس نیچوِس حنوک سٕندِس ناوس پیٹھ۔ {حنوک: ہیب۔ چانوچ}\n18.\\tتہٕ حنوکس زامُت اِراد: تہٕ اِراد زاو مہوجایل، تہٕ میہوجیل زاے میتھوسیل: تہٕ میتھوسیلن زاے لمیخ۔ {Lamech: Heb. Lemech}\n19.\\tتہٕ لمیخن رٔٹۍ أمِس نِش زٕ زنانہٕ: أکِس سُند ناو اوس عدہ تہٕ بیٚیِس زیلہ ہُند ناو۔\n20.\\tتہٕ آدہ بارے جبل: سُہ اوس خیمن مَنٛز روزَن والٮ۪ن ہُند مول تہٕ یِمن ہُند مول آسہِ۔\n21.\\tتہٕ تٔمۍ سٕندِس بٲے سُند ناو اوس جُبل: سُہ اوس سارِنٕے ہُند مول یُس ہارپ تہٕ آرگن رَٹان اوس۔\n22.\\tتہٕ زِلہ، سُہ تہِ چھُ طبلکین تہِ زٲلِتھ، یُس پرٮ۪تھ کُنہِ کاریگر سُند ہیچھناوُن اوس، تہٕ طبلکین سٕنز بینہِ ٲس۔ {انسٹرکٹر : ہیب۔ ویٹر}\n23.\\tتہٕ لمیخن ووٚن پننہِ زنانہِ عادہ تہٕ زیلہ، بوزو میٲنۍ آواز۔ اے لامیک سٕنزِ زنانہٕ، میانہِ کتھ بوزو: کیازِ مے چُھ اکھ نفر پننِس زخمس سٍتـ̡ مارمُت، تہٕ اکھ جوان چُھس پننہِ زخمس سٍتـ̡ مارمُت۔ {میہ چُھ...: یا، بہٕ مارٕ اکھ نفر پننِس زخمس منز، وغیرہ} {میانہِ تکلیف تام: یا، میٲنس دکھس منز}\n24. اگر قابیل سَتھ گنہٕ انتقام ییہِ دِنہٕ، پٔزۍ پٲٹھۍ لامیک ستتھ تہٕ ستھ گنہٕ۔\n25.\\tتہٕ آدم اوس پننہِ زنانہِ ہُند دُبارٕ زانان۔ تہٕ أمِس زاے اکھ نیٚچُو، تہٕ تٔمِس ناو سیٹھ تھووُن: خدایہِ سٕندِ بدلہٕ چُھس مے ہابیل سٕندِ بدلہٕ بیاکھ بیاکھ بیول مقرر کورمُت، یُس قاینن مارُن۔ {سیٹھ: ہیب۔ شیتھ: یعنی مقرر کرنہٕ آمُت، یا، پُٹ}\n26.\\tتہٕ شیٹھس تہِ اوس اکھ نیچو زامُت۔ تہٕ تٔمۍ ووٚن پنُن ناو اینوس: پتہٕ لوگُن خداوند سُند ناو پکارُن شروع۔ {اینوس: ہیب۔ Enosh} {بلاوُن...: یا، پانس رب سٕندِ ناوٕ سٍتۍ وَنُن}","1.\\tیہ {چھہ} آدم سنزِ نسلن ہنز کتاب۔ ییمہ دۅہہ خداین انسان بنوو، خدایہ سندِ شکلہِ منز بنوو سُہ سُہ۔\n2. مرد تہٕ زنانہٕ بنوو تِم تہٕ دِتُکھ تِمن دُعا دُعا تہٕ تِمن ہُند ناو آدم ناو، ییمہِ دۅہہ تِم تخلیق گٔیہِ۔\n3.\\tتہٕ آدم اوس ہتھ ترہ ؤری زندٕ، تہٕ تٔمۍ سٕنزِ شکلہٕ پتہٕ پیوو اکھ نیٚچُو۔ تہٕ وَنُن أمِس ناو سیٹھ:\n4. تہٕ آدم سٕندِ دۅہہٕ گٔیہِ ستھ زیٚنہٕ پتہٕ ٲٹھ ہتھ ؤری: تہٕ أمِس زاے نیٚچِوِ تہٕ کورِ۔\n5.\\tتہٕ سُہ اوس نَو ہتھ ترہ ؤری زندٕ۔\n6.\\tتہٕ سیٹھ روٗد ہتھ پانژَن ؤرین زندٕ، تہٕ حِنوس پیدٕ۔ اینوش}\n7.\\tتہٕ سیٹھ روٗد حنوس ٲٹھ ہتھ ستھ ؤری زیٚنہٕ پتہٕ زندٕ، تہٕ نیچوۍ تہٕ کورِ زیٚو۔\n8. تہٕ سیٹھ سٕندِ سارِنٕے دۅہہٕ ٲسۍ نَو ہتھ بَہہ ؤری: تہٕ سُہ موٗد۔\n9. تہٕ اینوس روٗد نَتھ ؤری زندٕ، تہٕ پیدٕ کینان: {Cainan: Heb. کینان}\n10.\\tتہٕ اینوس زِندٕ ییلہ تٔمۍ سٕندِ کاینان ٲٹھ ہتھ پندہ ؤری زیٚو، تہٕ نیچوۍ تہٕ کورِ زیٚیہِ۔\n11.\\tتہٕ اینوس سٕندِ سارِنٕے دۅہہٕ ٲسۍ نَو ہتھ پانژھ ؤری: تہٕ سُہ موٗد۔\n12.\\tتہٕ کاینان روٗد ستتھ ؤری زندٕ، تہٕ زٲوِن مہللیل: {مہلالیل: Gr. Maleleel}\n13.\\tتہٕ کینان زِندٕ ییلہ أمس مہللیل زیٚنہٕ پتہٕ ٲٹھ ہتھ ژتٲجی وُہُر، تہٕ نیچوۍ تہٕ کورِ زیٚو۔\n14.\\tتہٕ کینان سٕندِ سارِنٕے دۅہہٕ ٲسۍ نَو ہتھ دَہ ؤری: تہٕ سُہ گۆو مُرد۔\n15.\\tتہٕ مہللیل گۆو شیٹھ تہٕ پانژٕ وُہرۍ زندٕ، تہٕ پیوو جیرد: {جیرڈ: ہیب۔ جیرڈ}\n16.\\tتہٕ مَہلالیل زِندٕ زِندٕ یَردَس ٲٹھ ہتھ ترٕہ وُہُر، تہٕ زاے نیٚچِوؠ تہٕ کورِ۔\n17.\\tتہٕ مہللیل سٕندِ سارِنٕے دۅہہٕ ٲسۍ ٲٹھ ہتھ نَتھ پانژھ ؤری: تہٕ سُہ گۆو مُرد۔\n18.\\tتہٕ جیرڈ روٗد ہتھ شیٹھن ؤرین زندٕ، تہٕ تٔمۍ زٲو حنوک:\n19. تہٕ جیرد رود حنوک زینہٕ پتہٕ ٲٹھ ہتھ ؤری زندٕ، تہٕ نیچوۍ تہٕ کورِ زیٚو۔\n20. تہٕ جیرڈ سٕندِ سارِنٕے دۅہہٕ ٲسۍ نَو ہتھ شیٹھ تہٕ زٕ ؤری: تہٕ سُہ موٗد۔\n21.\\tتہٕ حنوک روٗد شیٹھ تہٕ پانژٕ ؤری زندٕ، تہٕ میتھوسیلاہ زٲوِو: {میتھوسیلہ: Gr. Mathusala}\n22. تہٕ حنوخ پوٚک خدایس سٍتـ̡ ییلہ تٔمۍ میتھوسیلہ تریہ ہتھ ؤری زیٚو، تہٕ نیچوۍ تہٕ کورِ پٲدٕ کٔرِتھ:\n23. تہٕ حنوک سٕندِ سارِنٕے دۅہہٕ ٲسۍ ترے ہتھ شیٹھ تہٕ پانژھ ؤری:\n24. تہٕ حنوک پوٚک خدایس سٍتـ̡ تہٕ سُہ اوس نہٕ۔ تکیازِ خداین نیو سُہ ۔\n25.\\tتہٕ میتھوسیلاہ روٗد ہتھ تہٕ ستتھ ؤری زندٕ، تہٕ زاو لامیخ:\n26.\\tتہٕ میتھوسیلہ زِندٕ ییلہ تٔمۍ سٕندِ لمیخس سَتھ ہتھ تہٕ زٕ وُہرۍ زیٚنہٕ پتہٕ، تہٕ زاے نیٚچوۍ تہٕ کورِ: {Lamech: Heb. Lemech}\n27. تہٕ میتھوسیلہ سٕندِ سارِنٕے دۅہہٕ ٲسۍ نَو ہتھ شیٹھ تہٕ نو ؤری: تہٕ سُہ گۆو مُرد۔\n28.\\tتہٕ لامیچ روٗد اکھ ہتھ تہٕ زٕ وُہُر، تہٕ زٲوُن اکھ نیٚچُو:\n29.\\tتہٕ تٔمۍ ووٚن پنُن ناو نوح تہٕ وونُن، یێمہِ سٍتـ̡ کرِ سانہِ کامہِ تہٕ سانہِ اتھن ہٕنزِ محنتہٕ سٍتـ̡ تسلی دِنہٕ، ییمہِ زمینہٕ سٍتـ̡ خداوند دِژ دِژمٕژ۔ {نوح: Gr. Noe: یعنی آرام، یا، آرام}\n30.\\tتہٕ لامیخ زِندٕ ییلہ تٔمۍ نوح زیٚنہٕ پتہٕ پانژھ ہتھ تہٕ پانژٕ وُہُر تہٕ نیچو تہٕ کورِ زیٚو۔\n31.\\tتہٕ لامیخ سٕندِ سارِنٕے دۅہہٕ ٲسۍ ستھ ہتھ ستتھ ستھ ؤری: تہٕ سُہ گۆو مُرد۔\n32. تہٕ نوح اوس پانژھ ہتھ وُہُر: تہٕ نوح زاے شم، حام تہٕ یافتھ۔","1.\\tتہٕ سپُد ییلہ انسانو زمینہِ پیٹھ بڈُن ہیوٚت، تہٕ تِمن ہٕندِ خٲطرٕ کورِ پٲدٕ گٔیہِ،\n2.\\tزِ خدایہ سٕندِس نیچویو وُچھ انسانن ہٕنزِ کورِ زِ تِم آسہٕ اچھے پٲٹھۍ۔ تہٕ تِمو رٔٹۍ تِمن سارِنٕے سارِنٕے خانٛدارِنۍ یِم تِمو ژٲرِ۔\n3. تہٕ خداوند ووٚن زِ میون روح روزِ نہٕ ہمیشہ انسانس سٍتـ̡ کوشش، تێمہِ سٍتـ̡ سُہ تہِ چُھہ ماز تہِ: توتہِ آسہِ تٔمۍ سُند دۅہ ہتھ وُہ ؤری۔\n4.\\tتمن دۅہن ٲس زمینس منز دیو آسان۔ تہٕ تمہ پتہ ییلہ خدایہ سٕندِ نیچوۍ انسانن ہٕنزِ کورِ نِش آیہ، تہٕ تِمو زاے {بچہ} تِمن خٲطرٕ، تِم بنییہِ طاقتور انسان یِم پرٲنِس زمانہٕ سٍتـ̡ مشہور ٲسۍ۔\n5.\\tتہٕ خداین وُچھ زِ انسانہ سٕنز بدکاری ٲس زمینس منز بٔڈ، تہٕ {یہ} تٔمۍ سٕندِس دِلٕکۍ خیالن ہُند پرٮ۪تھ کانہہ تصور {اوس} صرف بُرۍ۔ {پرٮ۪تھ کُن...: یا، سورے تخیل: عبرانی لفظ چھہ نہ صرف تخیلچ نشاندہی کران بلکہ چھہ مقصد تہ خواہشچ تہِ نشاندہی کران} {مسلسل: ہیب۔ پرٮ۪تھ دۄہ}\n6. تہٕ أمِس کٔر خداوند سُند توبہ زِ تٔمۍ اوس انسانس زمینس پیٹھ بنوومُت، تہٕ یہ گۆو أمِس دِلس سٍتـ̡ غم۔\n7. تہٕ خداوند ووٚن زِ بہٕ کرٕ انسان تباہ یُس میہ زمینہِ پیٹھٕ تخلیق کورمُت چھُ۔ انسان تہٕ درندٕ، تہٕ نژان چیز تہٕ ہوہٕکۍ جاناوار؛ تکیازِ یہ چھہ میہ توبہ کران زِ میہ چھہ تم بنوومت۔ {دۄشوے...: ہیب۔ انسان پیٹھہٕ درندٕ تام}\n8. مگر نوح لوٚب خداوند سٕنزِ نظرِ مَنٛز رحمت۔\n9. یِم {چھِ} نوح سٕنزِ نسلہٕ: نوح اوس اکھ عادل انسان {تہٕ} پننین نسلن مَنٛز کامل، {تہٕ} نوح اوس خدایہ سٍتـ̡ پکان ۔ {کامل: یا، سید}\n10. تہٕ نوح زاے ترے نیچوۍ، شم، حام تہٕ یافتھ۔\n11.\\tزمین تہِ ٲس خدایہ سٕندِ برونہہ کُن بدکار تہٕ زمین ٲس تشددٕ سٍتـ̡ بٔرِتھ۔\n12. تہٕ خداین وُچھ زمینس کُن، تہٕ وُچھ، یہ ٲس بدکار گٔمٕژ۔ تکیازِ سارِنٕے ماز اوس زمینس پیٹھ پنٕنۍ وتھ خراب کٔرمٕژ۔\n13. تہٕ خداین ووٚن نوحس زِ سارِنٕے مازُک انجام چُھ میانہِ برونہہ کُن آمُت۔ تکیازِ زمین چھیہ تمن ہندِ ذریعہ تشددٕ سٍتۍ بٔرِتھ۔ تہٕ وچھ، بہٕ کرٕ تمن زمینہٕ سۭتۍ تباہ کرنہٕ۔ {زمینہِ سٍتۍ: یا، زمینہِ پیٹھ}\n14. گوفر لٔکرِ ہُند صندوق بناوُن۔ صندوقس منز کُٹھہٕ بناوُن، تہٕ اتھ اندر تہٕ نیبَر کٔرِتھ دِنہٕ۔ {کمرہٕ: ہیب۔ نیسٹس}\n15.\\tتہِ چھہ یہ {فیشن} یُس ژیہ بناوُن: صندوقُک زیچھر آسہِ تریہ ہتھ کیوبِٹ، امیک کھجر آسہِ پنژاہ کیوبِٹ، تہٕ امیک تھزر آسہِ ترہ کیوبِٹ۔\n16.\\tصندوقس منز اکھ دٲر بناوٕن، تہٕ اتھ کُنہِ ک تہٕ صندوقُک دروازٕ چُھہ اَمہ کِس اندس منز تھاوُن۔ {سٍت} بٔنِتھ، دۆیم تہٕ تریم {افسانہٕ} ژے بناوِ یہِ۔\n17. تہٕ وُچھِو، بہٕ تہِ چُھس زمینس پیٹھ آبُک سٔہلاب انان، یُس سارِنٕے ماز تباہ کٔرِتھ، یتھ مَنٛز زندگی ہُند دم چُھ، اسمانس تلہ کنہِ۔ {تہ} زمینس منز موجود پریتھ چیز گژھہِ مرُن۔\n18. مگر بہٕ کٔرٕ ژے سٍتـ̡ پنُن عہد قٲیم۔ تہٕ تُہۍ گژھِو تہٕ پنٕنۍ نیچوۍ، تہٕ پنٕنۍ خانٛدارِنۍ تہٕ پننٮ۪ن نیٚچوٮ۪ن ہٕنٛزن زنانن ہٕنز زنانہٕ پانس سٍتۍ۔\n19.\\tتہٕ سارِنٕے ماز سٕندِس پرٮ۪تھ کُنہِ جاندارس منزٕ زٕ اَنِتھ تہٕ تِمن پانس سٍتـ̡ زِندٕ تھاونہٕ خٲطرٕ۔ تم گژھن مرد تہٕ زنانہٕ۔\n20.\\tتِمن ہٕندِس قٕسمس پٲٹھۍ، تہٕ تِمن ہٕندِس قٕسمس پَتہٕ کُنہِ\n21.\\tتہٕ یُس کھٮ۪نہٕ یِنہٕ وول کھٮ۪نہٕ چُھہ، تہٕ ژے کٔرِو پانس نِش جمع کرنہٕ۔ تہٕ یہ آسہِ تۅہہِ خٲطرٕ تہٕ تِمن ہٕندِ خٲطرٕ کھٮ۪نہٕ خٲطرٕ۔\n22.\\tنوح کٔر یتھہ پاٹھۍ۔ یُس خداین أمس حکم دِیُت، تِتھۍ مطٲبق کوٚر تٔمۍ تہِ۔","1. تہٕ خداوند ووٚن نوحس زِ ژے تہٕ پنُن سارِوٕے گرٕ آو کشتیَس مَنٛز۔ ژے خٲطرٕ وُچھمُت میہ یَتھ زمانس منز پانس برونہہ کُن نیکی ۔\n2. پرٮ۪تھ کُنہِ پاک درندٕ سٍتـ̡ چُھہ سَتھ سٍتـ̡ نِنہٕ آمُت، نر تہٕ تٔمۍ سٕنزِ زنانہٕ سٍتـ̡ تہٕ یِمن درندن ہٕندِس سٍتـ̡ دۅشوٕے سٍتـ̡ پاک آسہِ۔ {ستھ ذریعہ: ہیب۔ ستھ ستھ}\n3. جاناوارن ہٕندِس سَتَس سٍتـ̡ سَتھ سٍتـ̡ کُنہِ سارِنٕے زمینہٕ کِس بُتھِس پیٹھ بیٲلۍ زِندٕ تھاونہٕ خٲطرٕ۔ {ستھ ذریعہ: ہیب۔ ستھ ستھ}\n4. وُنہِ تہِ ستن دۅہن تہٕ بہٕ کرٕ ژتٲجی دۅہن تہٕ ژتٲجی رٲژ زمینس پیٹھ روٗد۔ تہٕ پریتھ کانہہ جاندار چیز یُس میہ بنوومت چھُ، سہ کرِ بہٕ زمینہِ پیٹھٕ تباہ کرنہٕ۔ {تباہ: ہیب۔ بلٹ آوٹ کٔرِو}\n5.\\tتہٕ نوح کٔر تِمن سارِنٕے مُطٲبِق یُس خداوند أمِس حُکُم دِیُت۔\n6. تہٕ نوح اوس شیہ ہتھ ؤری وٲنسہِ ییلہ آبُک سٔلاب زمینس پیٹھ آو۔\n7. تہٕ نوح ژاو سٔہلاب کِس آبس مۅکھہٕ سٍتـ̡ سٍتـ�\n8. پاک درندَن ہٕندِ، تہٕ یِم نہٕ پاک چھِ، تہٕ جاناوارن ہٕندِ، تہٕ پرٮ۪تھ کُنہِ چیزس سٍتـ̡ یُس زمینس پیٹھ رٔژان چُھ،\n9.\\tنوح سٕندِس سٍتـ̡ گٔیہِ دۄن تہٕ دۄن سٍتـ̡ ناوَس مَنٛز، مرد تہٕ زنانہٕ، یێلہِ خداین اوس نوح ہُند حُکُم دِتمُت۔\n10.\\tتہٕ سَتھ دۅہہٕ پَتہٕ سپُد زِ سٔہلابُک آب اوس زمینس پیٹھ۔ {پتہٕ...: یا، سٔتِم دۅہہ}\n11. نوح سٕنزِ زندگی ہٕندِس شیہ ہتھ ؤریس منز، دٔیمِس ریتس منز، ریتہٕ کِس سداہمس دۅہس منز، امی دۅہہ گٔیہٕ عظیم سرٛنِس چشمہٕ پھُٹراونہٕ، تہٕ اسمانٕچ دارِ آیہ کھولنہٕ۔ {دٲر: یا، فلڈ گیٹس}\n12. تہٕ روٗد روٗد ژتٲجی دۅہ تہٕ ژتٲجی رٲژ زمینس پیٹھ۔\n13.\\tامی دۅہہ ژاو نوح تہ سام تہ حام تہ یافتھ تہ نوح سنز زنانہ تہ تمن سٍتۍ تٔمۍ سٕندٮ۪ن نیچوین ہٕنزِ تریہ زنانہٕ ژاو کشتی منز۔\n14.\\tتِم تہٕ پرٮ۪تھ کانہہ جانور پننہِ قٕسمس پتہٕ، تہٕ سارِنٕے چاروٲے یُس پننہِ قٕسمس پَتہٕ زمینس پیٹھ نژان چھُ، تہٕ پرٮ۪تھ کُنہِ جاناوار، پرٮ۪تھ قٕسمُک پرٮ۪تھ کانہہ جاناوار۔ {ترتیب دِنہٕ: ہیب۔ ونگ}\n15.\\tتہٕ تِم گٔیہِ نوح سٕندِس سٍتـ̡ سٲرۍسٕے ماز سٍتـ̡ زٕ تہٕ زٕ سٍتـ̡ دِنہٕ آمُت۔\n16. تہٕ یُس اژان چُھ، تِم گٔیہِ سارِنٕے ماز سٍتـ̡ مرد تہٕ زنانہٕ، یِتھہٕ کٔنۍ خداین أمِس حُکُم اوس دِژمُت، تہٕ خداوند کٔر سُہ بنٛد۔\n17.\\tتہٕ سٔہلاب اوس ژتٲجی دۅہہٕ زمینس پیٹھ۔ تہٕ آب ہیوٚت ہُریر، تہٕ ووت صندوق، تہٕ یہ آو زمینہٕ پیٹھٕ تھوٚد۔\n18.\\tتہٕ آب ووت غالب، تہٕ زمینس پیٹھ آو واریاہ ہُریر۔ تہٕ کشتی گٔیہِ آبس بُتھِس پیٹھ۔\n19. تہٕ آبس اوس زمینس پیٹھ واریاہ زیادٕ غٲلب۔ تہٕ سٲری تھدِ بال، یُس پورٕ آسمانس تل اوس، اوس ؤلتھ۔\n20.\\tپندہ کیوبِٹ ہیوٚر کُن آب۔ تہٕ پہاڑ ٲسۍ ؤلتھ۔\n21. تہٕ سارِوٕے ماز موٗد یُس زمینس پیٹھ پکان اوس، کۅکرِ تہٕ چاروٲے تہٕ جانور تہٕ پرٮ۪تھ کُنہِ چیزس سٍتـ̡ یُس زمینس پیٹھ ژلان چُھ، تہٕ پرٮ۪تھ کانہہ انسان۔\n22.\\tیمۍ سٕنزِ نستہِ منز زندگی ہُند دم اوس، سارِنٕے سٍتۍ یُس {اوس} خشک {زمین} منز، موٗد۔ {شہس ...: ہیب۔ زندگی ہٕندِ روحُک شاہ}\n23.\\tتہٕ پریتھ کانہہ جاندار چیز سپُد تباہ یُس زمینہِ کِس بُتھِس پیٹھ اوس، انسان تہٕ چاروا، تہٕ رینگنہٕ وٲلس چیزن تہٕ اسمانٕچ مرغ۔ تہٕ تِم گٔیہِ زمینہٕ پٮ۪ٹھٕ تباہ تہٕ نوح روٗد صرف {زندٕ}، تہٕ تِم ٲسۍ أمِس سٍتـ̡ سٍتـ�\n24.\\tتہٕ آب رود زمینس پیٹھ ہتھ پنژاہ دۅہن تام۔","1.\\tتہٕ خداین یاد نوح تہٕ پرٮ۪تھ کانہہ جاندار تہٕ سارِنٕے چاروٲے یُس أمِس سٍتـ̡ اوس، تہٕ خداین بنوو زمینس پیٹھ واو تہٕ آبس ہُند وُپھ۔\n2. سرٛنِس تہٕ آسمانٕچ دارِ تہِ آیہ بند کرنہٕ، تہٕ آسمانہٕ پیٹھٕ روٗد آو رُکاونہٕ۔\n3. تہٕ آب آو زمینہٕ پیٹھٕ مسلسل واپس: تہٕ ہتھ تہٕ پنژاہ دۅہہٕ ختم گژھنہٕ پتہٕ آو آب کم کرنہٕ۔ {مسلسل: ہیب۔ گژھنس تہٕ واپسس منٛز}\n4.\\tتہٕ سٔتِمہِ رٮ۪تہٕ کِس سداہِمہِ دۅہہٕ آو آرارت کِس پہاڑن پیٹھ۔\n5.\\tتہ دٔہمہِ ریتس تام رود آب مسلسل کم: دٔہمہِ ریتس منز، امہ ریتہ کس گۅڈنکس {دوہ} دۅہس منز ٲسۍ پہاڑن ہندۍ تینتٲلۍ وچھنہ یوان۔ {کٔمی...: ہیب۔ ٲسۍ گَژھان تہٕ کم گَژھان}\n6.\\tتہٕ ژتٲجی دۅہہٕ سپدِتھ سپد نوح سٕندِ سٍتـ̡ دٲر کھولنہٕ یُس تٔمۍ بنوومُت اوس۔\n7.\\tتہٕ تٔمۍ سوٗز اکھ کاو یُس یُس یور کُن نیران اوس، یوٚت تام آب زمینہٕ پیٹھٕ خشک گوو۔ {to...: Heb. برونٹھ گژھنس تہٕ واپسس منٛز}\n8.\\tتٔمۍ سوٗز أمِس نِش اکھ کۅتر، یہِ وُچھنہٕ خٲطرٕ زِ آب چھا زمینہٕ پیٹھٕ ژوٚٹمُت۔\n9.\\tمگر کۅترِ لوٚگ نہٕ پننِس کھورِ ہٕندِس تُلِس سٍتـ̡ آرام تہٕ سُہ آو أمِس نِش صندوق کِس سٍتـ̡ واپس، تکیازِ سٲرۍسٕے زمینہِ ہٕندِس بُتھِس پیٹھ اوس آب، تمہ پتہٕ تروو تٔمۍ پنُن اتھہٕ تہٕ نِتھ پانس نِش کٔرِن صندوقس منز۔ {لٔٹۍ...: ہیب۔ سُہ آو یُن}\n10. تہٕ سُہ روٗد باقی سَتن دۅہن ۔ تہٕ بییہِ سوٗز تٔمۍ کۅتر صندوقہٕ منزٕ نیبر۔\n11.\\tتہٕ کۅتر آو شامس أمِس نِش۔ تہٕ اوس، تٔمۍ سٕندِس ٲسس منز زیتون پنہٕ تُلنہٕ آمُت، تہٕ نوح اوس پتاہ زِ آب چُھ زمینہٕ پیٹھٕ ژٹنہٕ آمُت۔\n12. تہٕ سُہ روٗد باقٕے سَتن دۅہہٕ۔ تہٕ سوٗزُن کۅتر۔ یُس نہٕ تس پتہٕ واپس آو نہٕ۔\n13.\\tتہٕ یہ سپُد شیہ ہتھ تہٕ گۅڈنکس ؤریس منز، گۅڈنچہ {ریتھ} منز، ریتہ کس گۅڈنکس {دۅہ} منز، آب آو زمینہِ منزہ خشک کرنہ۔ تہ نوح کٔر کشتی ہند پردہ تہ وُچھن زمینہِ ہند بُتھ خشک گومُت۔\n14. تہٕ دٔیمِس رٮ۪تس مَنٛز، سٔتِمہِ تہٕ وُہمہِ دۅہہٕ گٔیہِ زمینہٕ خۄشٕک۔\n15.\\tتہٕ خداین ووٚن نوح سٍتـ̡ وَنُن\n16.\\tژے تہٕ پننہِ زنانہِ تہٕ پنٕنۍ نیچوۍ تہٕ نیچوۍ تہٕ نیچوین ہٕنزِ زنانہٕ سٍتـ̡ نیرِو پانس سٍتـ̡ س\n17.\\tپانس سٍتـ̡ أنِو پرٮ۪تھ کانہہ جاندار یُس پانس سٍتـ̡ چُھہ، سارِنٕے ماز سٍتـ̡ {چُھ} جاناوار، تہٕ چاروٕنـ̡ تہٕ زمینس پیٹھ رٔژِھتھ پرٮ۪تھ کُنہِ چیزس سٍتـ̡ تاکہ تِم گژھن زمینس مَنٛز واریاہ زیادٕ افزائش کٔرِتھ، تہٕ پھل دار گژھن تہٕ زمینس پیٹھ بٔڑِتھ۔\n18. تہٕ نوح دراو تہٕ تٔمۍ سٕندِ نیچوۍ، تہٕ أمۍ سٕنزِ زنانہٕ تہٕ تٔمۍ سٕندٮ۪ن نیچوٮ۪ن ہٕنزِ زنانہٕ تہٕ أمِس سٍتـ̡\n19.\\tپرٮ۪تھ کانہہ جانور، پرٮ۪تھ کُنہِ چیز، تہٕ پرٮ۪تھ کُنہِ جاناوار، یُس تہٕ یُس تہِ زمینس پیٹھ ژلان چُھ، سُہ دراو صندوقہٕ منزٕ نیبر۔ {قسم: ہیب۔ خاندان}\n20. تہٕ نوح بنوو خداوند سٕندِ خٲطرٕ اکھ قربان گاہ۔ تہٕ رٔٹِن پرٮ۪تھ صاف جانور تہٕ پرٮ۪تھ صاف جاناوار، تہٕ قربان گاہس پیٹھ دِژٕن نذرانہ پیش۔\n21. تہٕ خداوند ہیوٚت مٔدٕر مَزٕ۔ تہٕ خداوند ووٚن پننِس دِلس منٛز، بہٕ کَرٕ نہٕ اِنسانہٕ سٕندِ خٲطرٕ دُبارٕ زمینس پیٹھ لعنت۔ تکیازِ انسان سندِ دِلُک تخیل چھہ جوانی پیٹھے بد کار۔ نہ کرٕ بہٕ بییہ پریتھ زندٕ چیزس مار، یتھہ پاٹھۍ میہ کورمُت۔ {اکھ مٔٹھۍ...: ہیب۔ آرام یا، اطمینان} {تخیلُک ذریعہٕ: یا، تخیلُک ذریعہٕ}\n22. یوتام زمین روزِ، بیٲلۍ تہٕ فصل، تہٕ سردی تہٕ گرمی، تہٕ رٮ۪تہٕ کالہٕ تہٕ وند، تہٕ دۄہ تہٕ رات روزِ نہٕ ختم۔ {ییلہ زن ...: ہیب۔ وُنہِ تہِ چھُ زمینہِ ہٕندِس سارِنٕے دۅہہ}","1. تہٕ خداین کٔر نوح تہٕ تٔمۍ سٕندِس نیچوِس برکت تہٕ تِمن وونُن، پھلدار گژھِو تہٕ بٔرِو تہٕ زمینہٕ بٔرِتھ۔\n2. تہٕ تۅہہِ ہُند خوف تہٕ تۅہہِ ہُند خوف آسہِ زمینہٕ کِس پرٮ۪تھ درندَس پیٹھ، تہٕ ہوہٕکِس پرٮ۪تھ کُنہِ جاناوارس پیٹھ، زمینہٕ کِس سارِنٕے گاڈَن پیٹھ۔ تُہٕندِس اتھس منز چھِ تِم دِنہٕ آمٕتۍ۔\n3.\\tپریتھ کانہہ حرکت کرن وول چیز یُس زندٕ روزان آسہِ تہندِ خٲطرٕ ماز آسہِ۔ یتھے پاٹھۍ چھہ سبز کُلۍ ژیہ ژیہ سورے چیز دِژمُت۔\n4.\\tمگر ماز یُس امہِ سٍتـ̡ خوُن چُھ، یُس نہٕ تُہۍ کھٮ۪و۔\n5. تہٕ یٔقیٖنی طور چُھس چانہِ زِندٕ ہُند خون۔ پرٮ۪تھ درندٕ سٕندِس اتھس سٍتۍ تہٕ انسان سٕندِس اتھس سٍتـ̡ چُھس بہٕ أمِچ ضرورت۔ پریتھ انسان سٕندِس بٲے سٕندِس اتھس پیٹھ گژھہِ میہ انسانہ سٕنز زُو ضرورت۔\n6. یُس انسان سُند خون تراوِ، تٔمۍ سُند خون گژھہِ انسان سٕندِ ذریعہٕ بہاونہٕ: کیازِ خدایہ سٕنزِ شکلہِ منز بنوو سُہ انسان۔\n7. تہٕ توہ، پھل دار تہٕ بٔرِو زیادٕ۔ زمینس مَنٛز واریاہ پٲدٕ کٔرِو تہٕ اَتھ مَنٛز بَڑاو۔\n8. تہٕ خداین کٔر نوح تہٕ تٔمِس سٍتـ̡ تٔمۍ سٕندِس نیچوِس سٍتـ̡ کتھ کرنہٕ،\n9. تہٕ بہٕ چُھس ژے سٍتـ̡ تہٕ چانہِ سٍتـ̡ پنُن عہد قایم کٔرِتھ تہٕ ژے پَتہٕ چُھس سٍتـ̡\n10. تہٕ پریتھ جانورس سٍتـ̡ یُس توے سٍتـ̡ چُھہ، جاناوارن سٍتـ̡ تہٕ ژے سٍتـ̡ زمینہٕ کِس پریتھ جانورس سٍتـ̡ چُھہ صندوقہٕ منزٕ نیرن وٲلِس سارِنٕے سٍتـ̡ چُھہ زمینہٕ کِس پرٮ۪تھ درندَس تام۔\n11. تہٕ بہٕ کٔرٕ توے سٍتـ̡ پنُن عہد قایم کرنہٕ۔ نہ گژھہِ سٲری ماز سیلابک آبہٕ سٍتۍ ژٹنہٕ۔ نہ گژھہِ بییہ کانہہ سٔلاب یُس زمینہِ تباہ کرُن۔\n12. تہٕ خداین ووٚن، یہِ چُھہ اَتھ عہدٕچ نشانی یُس بہٕ پانس تہٕ ژے تہٕ پرٮ۪تھ کُنہِ جاندارس درمِیان چُھس یُس تۅہہِ سٍتـ̡ دٲیرٕ نسلن خٲطرٕ چُھہ کرنہٕ آمُت:\n13. بہٕ چُھس پنُن کمان اوٚبرس مَنٛز تھوومُت، تہٕ یہِ آسہِ میانہِ تہٕ زمینہِ درمِیان عہد کِس نشانہٕ خٲطرٕ۔\n14.\\tتہٕ یێلہِ بہٕ زمینہِ پیٹھ اوٚبر اَنِتھ تہٕ کمان ییہ اوٚبرس مَنٛز وُچھنہٕ:\n15. تہٕ بہٕ کرٕ پنُن عہد یاد، یُس میانہِ تہٕ ژے تہٕ سارِنٕے ماز سٕندِس پرٮ۪تھ جاندارس درمِیان چُھ۔ تہٕ آب گژھِ نہٕ وۄنۍ سٔہلاب بنہٕ یُس سارِنٕے ماز تباہ کٔرِتھ۔\n16. تہٕ کمان آسہِ اوٚبرس منز۔ تہٕ بہٕ کٔرٕ اتھ پیٹھ نظر، یُتھ بہٕ خدایہ تہٕ زمینس پیٹھ موجود تمام جاندارن ہٕندِس پرتھ جاندارس درمیان ابدی عہد یاد تھاوُن۔\n17. تہٕ خداین ووٚن نوح سٕندِس عہدُک نشانہٕ، یُس میہ پانس تہٕ سارِنٕے جسمس درمِیان قایم کورمُت چُھ۔\n18.\\tتہٕ نوح سٕندِ نیچوۍ یُس کشتی منزہ نیران اوس، تم ٲسۍ شم، حام تہٕ یافتھ، تہٕ حام اوس کنعانُک مول۔ {کنعان: ہیب۔ چینان}\n19.\\tیِم چھِ نوح سٕندِ تریہ نیچوۍ: تہٕ یِمو منزٕ ٲس سٲرۍسٕے زمینہِ ہٕندِس سٍتـ̡ پھٔہلِتھ ۔\n20.\\tتہٕ نوح ہیوٚتُن اکھ زٔمیٖندار بنُن، تہٕ تٔمۍ لگٲو اکھ انگور۔\n21.\\tتہٕ سُہ چُھ شراب، تہٕ اوس شراب۔ تہٕ سُہ آو پننِس خیمہٕ اندر بے نقاب کرنہٕ۔\n22.\\tتہٕ کنعانُک مول حام وُچھ پننِس مٲلہِ سُند ننگہٕ تہٕ وونُن پننین دون باین نیبر۔\n23.\\tتہٕ شیم تہٕ یافتھ تُل اکھ پلو، تہٕ تھووُن دۄشوٕے پھیکس پیٹھ، تہٕ پتھ کُن گٔژھِتھ تہٕ لوٚگُن پننِس مٲلہِ سُند ننگہٕ۔ تہٕ تِہُند بُتھ اوس پتھ کُن، تہٕ تِمو وُچھ نہٕ پننِس مٲلہِ سُند ننگہٕ۔\n24.\\tتہٕ نوح ووت پننہِ شرابہٕ نشہِ بیدار، تہٕ پتاہ زِ تٔمۍ سٕندِس لۄکٹِس نیچوِس کیا اوس أمِس سٍتـ̡ کوٚرمُت۔\n25.\\tتہٕ وۆنُن لعنت {be} کنعان۔ سُہ گژھِ پننٮ۪ن باین ہُند خادم آسُن۔\n26.\\tتہٕ وۆنُن بابرکت {بنہ} خداوند شیمُک خدا۔ تہٕ کنعان آسہِ تٔمۍ سُند خادم۔ {تسُند خادم: یا، تِمن ہُند خادم}\n27.\\tخدا کرِ یافتھ بٔڈِتھ تہٕ سُہ روزِ شیم کِس خیمن مَنٛز۔ تہٕ کنعان آسہِ تٔمۍ سُند خادم۔ {بڑاوُن: یا، قائل کٔرِو}\n28. تہٕ نوح روٗد سٔہلاب پتہٕ ترے ہتھ پنژاہ ؤری زندٕ۔\n29. تہٕ نوح سٕندِ سارِنٕے دۅہہٕ ٲسۍ نَو ہتھ پنژاہ ؤری: تہٕ سُہ گۆو مُرد۔","1.\\tوۅنۍ چھہِ یم نوح، شم، حام تہٕ یافتھ سٕندٮ۪ن نیچوین ہٕنزِ نسلہٕ: تہٕ یِمن سٍتـ̡ ٲسۍ سٔہلاب پَتہٕ زامٕتـ̡ نیٚچوۍ۔\n2. یافتھ سٕندِ نیچو۔ گومر، تہٕ ماگوگ، تہٕ مدای، تہٕ جاوان، تہٕ توبل، تہٕ میشچ، تہٕ تیراس۔\n3. تہٕ گومر سٕندِ نیچو۔ اشکناز، تہٕ ریفتھ، تہٕ ٹوگرمہ۔\n4. تہٕ جاوان سٕندِ نیچو۔ الیشاہ، تہٕ ترشیش، کِٹِم تہٕ ڈوڈنیم۔ {ڈوڈنیم: یا، یِتھ کٔنۍ کینہہ پران چھِ، رودانیم}\n5. یِمو سٍتـ̡ ٲس غیر قومن ہٕندِ جزیرٕ پننین زمینن منز تقسیم کرنہٕ آمٕتۍ۔ پرٮ۪تھ کانٛہہ پننہِ زبانہِ پتہٕ، پننین عیالن پتہٕ، پننین قومن منٛز۔\n6. تہٕ ہام سٕندِ نیٚچوۍ۔ کُش، تہٕ مزرایم، تہٕ پھُٹ تہٕ کنعان۔\n7. تہٕ کُش سٕندِ نیٚچوۍ۔ سیبا تہٕ حویلہ تہٕ سبتہ تہٕ راماہ تہٕ سبتیخا: تہٕ رامہ سٕندۍ نیٚچۍ۔ شیبا، تہٕ ڈیڈن۔\n8.\\tتہٕ کُش زاو نمرود: سُہ ہیوٚتُن زمینس مَنٛز طاقتور بنُن۔\n9.\\tسُہ اوس خداوند سٕندِس برونہہ کُن اکھ طاقتور شِکار: اَمہِ مۅکھٕ چُھ وننہٕ یِوان زِ نمرود تہِ اوس خداوند سٕندِس برونہہ کُن طاقتور شِکار۔\n10.\\tتہٕ تٔمۍ سٕنزِ بادشٲہی ہُند آغاز اوس شِنار کِس سرزمینس مَنٛز بابل، تہٕ اریخ، تہٕ اکاڈ تہٕ کالنہ۔ {بابل: Gr. Babylon}\n11.\\tاَمہِ زمینہٕ منزٕ دراو اشوٗر، تہٕ بنووُن نینوا تہٕ شہر رہوبوت تہٕ کالہ، {گٔیہِ...: یا سُہ دراو اشوریا کُن} {شہر...: یا شہرٕچ سڑکہٕ}\n12.\\tنینوا تہٕ کالاہس درمِیان رسین: یۅہے {چُھ} اکھ بٔڈ شہر۔\n13.\\tتہٕ مزریمن پیدہ لُدم، تہٕ انامیم، تہٕ لہبیم تہٕ نفتوہیم۔\n14.\\tتہٕ پتھرُسم، تہٕ کاسلوہِم، (یِمو منزٕ فِلسطِم دراو تہٕ کَفتورِم۔\n15.\\tتہٕ کنعانن زاو سُہ سُند گۄڈنیُک زامُت، تہٕ ہیتھ، {سیدون: ہیب۔ Tzidon}\n16. تہٕ یبوسی، تہٕ اموری تہٕ گرگسائٹ،\n17. تہٕ حِویت، تہٕ آرکیٹ تہٕ سِنائٹ،\n18.\\tعرودی تہٕ زیماری تہٕ ہماتی: تہٕ امہ پتہ گٔیہِ کنعانین ہٕندِ خاندانہٕ یُس پردٕ پٔہلِتھ پھٔہلِتھ گٔیہِ۔\n19. تہٕ کنعانین ہُند سرحد اوس صیدون پیٹھ، یێلہِ تہٕ ژے جیرار تہٕ غزہ تام وٲتِتھ۔ یێلہِ چُھہ ژے سدوم تہٕ عمورہ تہٕ آدمہ تہٕ زیبویم تہٕ لاشاہس تام تہِ گژھُن۔ {غزہ: ہیب۔ عزا}\n20.\\tیم چھہِ حام سٕندِ نیچوۍ، پننین عیالن پتہٕ، تہنزِ زبانہِ پتہٕ، پننین ملکن منز، تہٕ پننین قومن منز۔\n21.\\tشیمس سٍتـ̡ تہِ اوس ایبر سٕندِس سارِنٕے شُرین ہُند مول یُس یافتھ بٔڈۍ سُند بٲے اوس، أمِس تہِ زاے {شُر}۔\n22. شیم سٕندِ شُرۍ۔ ایلام، تہٕ اشور، تہٕ ارفکساد، تہٕ لُد، تہٕ آرام۔ {ارفیکساد: ہیب۔ اَرپَشَد}\n23.\\tتہٕ اَرَم سٕندِ اولاد۔ از، تہٕ ہل، تہٕ گیتھر، تہٕ ماش۔\n24.\\tتہٕ ارفقسعد دیت صلاح پیدہ۔ تہٕ صلاح زاے ایبر۔ {صلاح: ہیب۔ شیلاہ}\n25.\\tتہٕ ایبرس زاے زٕ نیچوۍ: أکِس سُند ناو اوس پیلیگ۔ تکیازِ تٔمۍ سٕندِس زمانس منز ٲس زمین تقسیم کرنہٕ آمٕژ۔ تہٕ تٔمۍ سٕنٛدس بٲے سُنٛد ناو اوس جوکٹن۔ {پیلیگ: یعنی ڈویژن}\n26.\\tتہٕ جوکتن زاے الموداد، تہٕ شیلف، تہٕ ہزارمویت تہٕ یراہ۔\n27.\\tتہٕ حدورم، تہٕ عزال، تہٕ دکلہ،\n28. تہٕ اوبل، تہٕ ابیمیل تہٕ شیبا،\n29.\\tتہٕ اوفیر، تہٕ حویلہ تہٕ جوباب: یِم سٲری ٲسۍ جوکتان سٕندِ نیٚچوۍ۔\n30.\\tتہٕ تِہُند روزن اوس میشہ سٍتـ̡ یێلہِ تہٕ تُہۍ چُھکھ مشرقُک پہاڑ سِفارس کُن گژھان۔\n31.\\tیم چھہِ شیم سٕندِ نیچو، پننین عیالن پتہٕ، پننہِ زبانہِ پتہٕ، پننین ملکن منز، پننین قومن پتہٕ۔\n32.\\tیِم چھہِ نوح سٕندٮ۪ن نیچوین ہٕندِ خاندان، تہٕ یِمو سٍتـ̡ یِم قومن ہٕندِس سٍتـ̡","1. تہٕ سورے زمین ٲس اَکہِ زبانہِ ہٕنز تہٕ اَکہِ زبانہِ ہٕنز۔ {زبان: ہیب۔ لپ۔} {تقریر: ہیب۔ لفظ}\n2.\\tتہٕ ییلہ تم مشرقس پیٹھ سفر کران ٲسۍ، تمن لوٚب شِنار کِس سرزمینس منز اکھ میدان۔ تہٕ تِم ٲسۍ تتہِ روزان۔ {پیٹھ...: یا، مشرقس کُن}\n3.\\tتہٕ تِمو ووٚن اَکھ أکِس أکِس سٍتـ̡ ، گژھو أسـ̡ سیرٕ بناوُن، تہٕ یِم زٲلِتھ زالنہٕ۔ تہٕ تمن ٲس کنن خٲطرٕ سیر تہٕ لیمب ٲس تم مارٹر خٲطرٕ۔ {تِمو ووٚن...: ہیب۔ أکۍ شخژن ووٚن پننِس ہمساین {برن...: ہیب۔ زالُن زالُن}\n4.\\tتہٕ تِمو ووٚن، گژھو اسہِ اکھ شہر تہٕ اکھ مینار بناوُن، یُس آسمانس تام وٲتِتھ آسہِ۔ تہٕ اسہِ بناوو اسہِ اکھ ناو، نتہ گژھو أسۍ سارِنٕے زمینہٕ کِس بُتھِس پیٹھ منتشر گٔژھِتھ۔\n5. تہٕ خداوند آو شہر تہٕ مینار وچھنہٕ خٲطرٕ، یُس انسانن ہٕندیو بچیو بنوو۔\n6.\\tتہٕ خداوند ووٚن زِ وُچھو، لوکھ چُھ اَکھ تہٕ تِمن سارِنٕے سٍتـ̡ چُھ اَکھ زبان۔ تہٕ یِہ چھِ تِم کرُن شروع کران: تہٕ وۄنۍ ییہ نہٕ تمن نِش کانہہ تہِ رُکاونہٕ، یُس تِمو کرنُک تصور آسہِ کوٚرمُت۔\n7.\\tگژھِو اسہِ بۄن گژھُن، تہٕ تِمن ہٕنزِ زبانہِ ہُند الجھاوُن، یُتھ زن تِم اکھ أکِس سٕنز کتھ سمجھ نہٕ یِن۔\n8. تہٕ خداوند کٔر تِم اَتہِ پیٹھٕ سارِنٕے زمینہِ ہٕندِس بُتھِس پٲٹھۍ، تہٕ تِمو درٛاو شہر تعمیر کرنہٕ خٲطرٕ۔\n9.\\tامہ کنۍ چھہ امیک ناو بابل ونان۔ تِکیازِ خداوند کٔر تتہِ سارِنٕے زمینہِ ہٕنز زبان الجھاومٕژ، تہٕ تتہِ کٔر خداوند یِم سارِنٕے زمینہٕ کِس بُتھِس پیٹھ پھٔہلِتھ۔ {بابل: یعنی کنفیوز}\n10.\\tیم {چھہِ} شیم سٕنزِ نسلہٕ: شیم {اوس} ہتھ ؤری وٲنسہِ، تہٕ سُہلاب پتہٕ زٕ وُہرۍ آرفکسادس پیدہ گومُت:\n11.\\tتہٕ شیم روٗد پانژھ ہتھ ؤری زیٚنہٕ پتہٕ زندٕ، تہٕ نیچوۍ تہٕ کورِ زیٚو۔\n12.\\tتہٕ ارفکسعد روٗد پانژھ تہٕ ترہ ؤری زندٕ، تہٕ بنیوو صلاح زِ:\n13.\\tتہٕ ارفقسعد رود صلاح زیٚنہٕ پتہٕ ژور ہتھ تریہ ؤری زندٕ، تہٕ نیچوۍ تہٕ کورِ زیٚو۔\n14.\\tصلاح رود ترہ ؤری زندٕ، تہٕ ایبر پید:\n15.\\tتہٕ صلاح اوس ژور ہتھ تریہ ؤری زیٚنہٕ پتہٕ زندٕ روزان تہٕ نیچوۍ تہٕ کورِ پٲدٕ کٔرۍ۔\n16.\\tتہٕ ایبر روٗد ژور تہٕ ترہ ؤری زندٕ، تہٕ پیلیگس پیدٕ: {پیلیگ: Gr. Phalec}\n17. تہٕ ایبر رود پیلیگ زینہٕ پتہٕ ژور ہتھ ترہ ؤری زِندٕ تہٕ نیچوۍ تہٕ کورِ زیٚو۔\n18.\\tتہٕ پیلیگ روٗد ترہن ؤرین زندٕ، تہٕ پیوو ریو:\n19.\\tتہٕ پیلیگ اوس زٕ ہتھ نو ؤری زیٚنہٕ پتہٕ زندٕ، تہٕ نیچوۍ تہٕ کورِ زیٚو۔\n20.\\tتہٕ ریو روٗد زٕ ترٕہ ؤری زندٕ، تہٕ پیوو سیروگ: {Serug: Gr. Saruch}\n21.\\tتہٕ رُو زِندٕ زٕ ہتھ سَتھ وُہُر زِیوُن تہٕ زاے نیچوۍ تہٕ کورِ۔\n22.\\tتہٕ سِروگ روٗد ترہن ؤرین زندٕ، تہٕ ناہوٗر پیدٕ۔\n23.\\tتہٕ سِروگ روٗد ناہور زٕ ہتھ ؤری زیٚنہٕ پتہٕ زندٕ، تہٕ زاے نیچوۍ تہٕ کورِ۔\n24.\\tتہٕ ناہور روٗد نَو وُہُن وُہُن وُہُر، تہٕ پیوو تیراہ: {تیرہ: گر۔ تھارا}\n25.\\tتہٕ ناہور اوس ہتھ کُنوُہ وُہُر ترہ زیٚنہٕ پتہٕ زندٕ روزان تہٕ نیچوۍ تہٕ کورِ زیٚو۔\n26.\\tتہٕ تیرہ روٗد ستتھ ؤری زندٕ، تہٕ زاے ابرام، ناحوٗر تہٕ ہاران۔\n27.\\tوۅنۍ چھہِ یِم ترہ سٕنزِ نسلہٕ: تیرہ زاے ابرام، ناہور تہٕ ہاران۔ تہٕ ہارن زاو لوط۔\n28.\\tتہٕ ہارن موٗد پننِس مٲلِس تیرہ برونہہ کُن پننہِ زینہٕ کِس سرزمینس منز، یُس چالدی ہٕندِس سرزمینس مَنٛز۔\n29.\\tتہٕ اَبرام تہٕ ناہورَن رٔٹۍ تِمن خانٛدارِن: اَبرام سٕنزِ زنانہِ ہُند ناو اوس سارائی۔ تہٕ ناہور سٕنزِ زنانہِ ملکہ سُند ناو، ہارن سٕنز کورِ، ملکہ سُند مول تہٕ عیسکہ سُند مول۔\n30.\\tمگر سَراے ٲس بنجر ۔ أمِس اوس نہٕ کانٛہہ شُر۔\n31.\\tتہٕ تراہن نیو پنُن نیچو ابرام، تہٕ لوطس نیچو ہارن سُند نیچو تہٕ ساراے پنٕنۍ نچو تہٕ نیچو ابرام سٕنز زنانہٕ۔ تہٕ تِم دراو تِمن سٍتـ̡ چالدی پیٹھٕ کنعان کِس سرزمینس مَنٛز گژھنہٕ خٲطرٕ۔ تہٕ تِم آیہ ہارنس کُن تہٕ اتہِ روزُن۔\n32.\\tتہٕ تیرہ سٕندِ دۅہہٕ ٲسۍ زٕ ہتھ پانژھ ؤری: تہٕ تیرہ گۆو ہارنس مَنٛز۔","1. وۅنۍ اوس خداوند ابرامس ووٚنمُت، تہٕ پنہٕ نِس ملکہٕ منز، تہٕ پننِس مٲلہِ سٕندِ گرٕ نِش نیرِو تتھ زمینس مَنٛز یُس بہٕ ژے ہٲوِتھ دِیہٕ:\n2. تہٕ بہٕ بناوٕ ژے اکھ عظیم قوم، تہٕ بہٕ کرٕ ژے برکت تہٕ تُہند ناو عظیم بناو۔ تہٕ تُہۍ بٔنِو نعمت:\n3. تہٕ بہٕ کرٕ تِمن دُعا دِوان یُس تۅہہِ دُعا دِوان چُھ، تہٕ یُس تۅہہِ لعنتُک دُعا دِوان چُھ، تہٕ ژے مَنٛز گٔیہِ زمینہٕ کِس سارِنٕے خاندانن برکت حٲصِل۔\n4.\\tیێلہِ دراو ابرام یێلہِ خداوند سٍتـ̡ أمِس سٍتـ̡ کتھ کٔرمٕژ۔ تہٕ لوط گۆو أمِس سٍتـ̡ تہٕ اَبرام اوس ستتھ تہٕ پانٛژٕ وُہُر وُہُر ییلہ سُہ ہارن منزٕ نیرِ۔\n5.\\tتہٕ ابرامن نِیوو پننہِ زنانہِ ساراے تہٕ لوط پننِس بٲے سُند نیچو، تہٕ تِہُند سورُے مال یُس تمو جمع کورمُت اوس، تہٕ یُس روحہٕ تِمو ہارنس منز حٲصل کورمُت اوس۔ تہٕ تِم گٔیہِ کنعان کِس سرزمینس مَنٛز گژھنہٕ خٲطرٕ۔ تہٕ کنعان کِس سرزمینس مَنٛز آیہِ تِم آمٕتۍ۔\n6. تہٕ ابرام ووت زمینہٕ کِنۍ سیکیم کِس مقامس تام، مورہ کِس میدانس تام۔ تہٕ کنعانی اوس تمہ وقتہٕ زمینس منٛز۔ {سادٕ: ہیب۔ میدان}\n7. تہٕ خداوند آو ابرامس نِش ظٲہر تہٕ ووٚنُن، بہٕ دِیہ یہِ زمین، تہٕ تتہِ بنوو تٔمۍ خداوند سٕندِ خٲطرٕ اکھ قربان گاہ، یُس أمِس ظٲہر گوٚو۔\n8.\\tتہٕ تتہِ ووت تتہِ پیٹھہ بیت ایل کِس مشرقس کُن أکِس پہاڑس کُن، تہٕ کوٚرُن پنُن خیمہ تہٕ مغربس کُن بیتھل تہٕ مشرقس کُن ہاے تہٕ تتہِ بنوو خداوند سٕندِ ناوٕ سٍتـ̡ ۔\n9.\\tتہٕ ابرام ووت جنوبس کُن پکان۔ {گژان...: ہیب۔ گژھنس تہٕ سفرس منٛز}\n10.\\tتہٕ زمینس منز آو قحط، تہٕ ابرام ووت مصرس منز اتہِ روزنہٕ خٲطرٕ۔ تکیازِ قحط اوس زمینس منز خوفناک۔\n11.\\tتہ ییلہ سُہ مصرس منز اژنہٕ خٲطرٕ نزدیک آو تہ تٔمۍ ووٚن پننہِ زنانہِ ساراے زِ وُچھ، وُچھ، مے چھے پتاہ زِ ژٕ چھے اکھ خوبصورت زنانہٕ یُس وُچھان چھُ:\n12. تێمہِ کِنۍ گژھہِ یێلہِ مصری ژےٚ وُچھِن، تِم ونن زِ یہِ چھے تٔمۍ سٕنزِ زنانہٕ، تہٕ تِم مارن مے تہٕ تِم بچٲوِن ژے زِندٕ۔\n13.\\tوَن، بہٕ چُھس ژے دُعا کران زِ ژٕ چھکھ میانہِ خٲطرٕ رژھرٕ۔ تہٕ میون روح روزِ ژے سٍتـ̡ زندٕ۔\n14.\\tتہ سپد یہ زِ ییلہ ابرام مصرس منز آو، مصریو وُچھ زنانہِ زِ سۅ ٲس سٮ۪ٹھاہ خوبصورت۔\n15.\\tفرعون سٕندٮ۪و شہزادو تہِ وُچھ أمِس تہٕ کٔرٕن فرعونس برونہہ کُن أمِس تعریف۔ تہٕ زنانہٕ آیہِ فرعون سٕندِس گرس منز نِنہٕ۔\n16.\\tتہٕ تٔمۍ کٔر ابرامس تٔمۍ سٕندِ خٲطرٕ رژھ رژھ التجا تہٕ أمِس ٲسۍ کۅکر، تہٕ کٔرۍ، تہٕ گٔرۍ، تہٕ گٔرۍ، تہٕ اونٹ۔\n17.\\tتہٕ خداوند دِژ فرعونس تہٕ تٔمۍ سٕندِس گھرس سٍتـ̡ سٍتـ�\n18.\\tتہٕ فرعونن بُلوو ابرامس تہٕ وونُن، یہِ کیا چُھہ ژے میانہِ سٍتـ̡ کورمُت؟ ژیہ کیازِ ووٚن نہ میہ زِ سۅ ٲس تہنز زنانہِ؟\n19.\\tژیہ کیازِ ووٚن، سۅ چھیہ میٲنۍ بینہِ؟ تہ بہٕ ہا سۅ پانس نِش زنانہِ نِتھ، وۅنۍ وُچھِو پنٕنۍ زنانہٕ، نِش نِش تہٕ گژھ پننہِ وتہِ۔\n20. تہٕ فرعونن دیُت أمِس متعلق پننین نفرن ہُند حُکُم، تہٕ تِمو سوٗ تہٕ تٔمۍ سٕنز زنانہٕ تہٕ تٔمِس سٍتـ̡ سُہ سُہ تہٕ سُہ تہٕ سُہ سُہ تہٕ سُہ تہٕ سُہ سُہ تہ","1. تہٕ ابرام دراو مصرہٕ منزہ نیبر، سُہ تہٕ تسٕنزِ زنانہٕ تہٕ أمِس سٍتـ̡ سارِوٕے سٍتـ̡ تہٕ لوط سٍتـ̡ جنوبس کُن۔\n2. تہٕ ابرام اوس چارواین سٍتـ̡ سٍتـ̡ سٮ۪ٹھاہ مالدار۔\n3.\\tتہٕ سُہ گۆو جنوبہٕ پیٹھٕ بیتھلس تام، تتھ جایہِ تام ییتہِ تٔمۍ سُند خیمہ ابتداہس منز اوس، بیتھل تہٕ ہے ہس درمِیان اوس۔\n4.\\tقربان گاہ کِس مقامس تام، یُس تٔمۍ گۅڈنچہ لٹہِ بنوومُت اوس، تہٕ تتہِ کٔر ابرام رب سُند ناو۔\n5. تہٕ لوطس تہِ، یُس ابرامس سٍتـ̡ گۆو، تہٕ گٔیہِ تہٕ خیمہ تہِ۔\n6. تہٕ زمین ہیوٚک نہٕ تِم برداشت کٔرِتھ، یُتھ زن تِم اِکہٕ وٹہٕ روزِتھ، تِکیازِ تِہُند مال اوس واریاہ زیادٕ، یُتھ زن تِم ہیوٚک نہٕ اِکہٕ وٹہٕ روزِتھ۔\n7.\\tتہٕ اَبرام سٕندِس چارواین تہٕ لوط سٕندِس چارواین ہٕندِس چاروَن درمِیان گٔیہِ جھگڑا، تہٕ کنعانی تہٕ پیرِزِی ٲسۍ تمہِ وِزِ زمینس مَنٛز روزان۔\n8. تہٕ ابرام ووٚن لوتس زِ بہٕ گژھہِ نہ کانہہ جھگڑا گژھُن، میہ تہٕ ژے درمِیان تہٕ میانین چارواہن تہٕ تہندٮ۪ن چارواہن درمِیان گژھہِ نہٕ کانہہ جھگڑا سپدُن۔ تکیازِ أسۍ {بٔنِ} بٲے چھِ۔ {برادران: ہیب۔ مرد بھائی}\n9.\\t{کیا چُھنہ} سورے زمین چھُنہٕ ژے برونہہ کُن؟ پنُن پان الگ کرُن، بہٕ چھُس ژے دُچھُن اَتھٕ رٔٹِتھ دٔچھُنـ̡ کُن نیران۔ یا اگر {ژیہ نیرِو} دچھنہِ اتھس کُن، تیلہ گژھہِ میہ کھوورِ طرفہ۔\n10. تہٕ لوطس تُل پنٕنۍ أچھ تُل، تہٕ وُچھن اردن کِس سٲرۍسٕے میدانس زِ خداوند سٕندِ سدوم تہٕ عمورہ تباہ کرنہٕ برونہہ اوس یہِ پریتھ جایہِ آب دِنہٕ آمُت، یێلہِ تہِ چُھہ خداوند سٕندِ باغٕکۍ پٲٹھۍ، مصرٕچ سرزمینہٕ پٲٹھۍ، یێلہِ تہٕ ژے زورس کُن واتہِ۔\n11. پتہٕ لوطَن چُھ أمِس سٲرۍسٕے اردن کِس مٲدانس مَنٛز ژارنہٕ۔ تہٕ لوط کٔر مشرقس سٍتـ̡ سفر: تہٕ تِمو کٔر پانس اکھ أکِس نِش الگ ۔\n12.\\tابرام اوس کنعان کِس سرزمینس مَنٛز روزان تہٕ لوط اوس میدانی شہرن مَنٛز روزان، تہٕ کوٚرُن سدومس کُن خیمہ لگاونہٕ۔\n13. مگر سدومٕکۍ لُکھ ٲسۍ خداوند سٕندِ برونہہ کُن بدکار تہٕ گۅنہگار۔\n14. تہٕ خداوند ووٚن ابرامس زِ لوط أمِس نِش الگ گژھنہٕ پتہٕ، وُنۍ تُلِو پَنٕنۍ أچھ تُلِتھ تہٕ تَتھ جایہِ وُچھِو یُس شمالس کُن، جنوبَس کُن، تہٕ مشرقس کُن تہٕ مغربس کُن چھُو:\n15.\\tیُس سارِنٕے زمینہٕ ژے وُچھان چُھ، بہٕ دِیہ سُہ تہٕ چانہِ بُلِس ہمیشہٕ خٲطرٕ۔\n16. تہٕ بہٕ بناوٕ چانہِ بیول زمینہِ ہٕنزِ گردِ ہٕندۍ پٲٹھۍ، یُتھ زن کانہہ انسان زمینہِ ہٕنزِ گردِ ہُند گنزرٲوِتھ ہیکہِ، تیلہِ گژھہِ تُہند بیول تہِ گنزراونہٕ۔\n17. وۅتھُن، زمینہِ منزۍ پٔکِو اَمہ کس زیچھرس تہٕ کھجرس منز۔ تکیازِ بہٕ دِیہ یہ ژے دِنہٕ۔\n18.\\tاَمہِ پَتہٕ ہیوٚت ابرام پنُن خیمہ تہٕ آو تہٕ بُہُن مٔمرے کِس مٲدانس مَنٛز، یُس حبرونس مَنٛز {چُھ} چُھ، تہٕ اَتہِ بنووُن خداوند سٕندِ خٲطرٕ اکھ قربان گاہ۔ {سادٕ: ہیب۔ میدان}","1. تہٕ یہ سپُد شِنارُک بادشاہ امرافیل سٕندِس زمانس منز، ایلاسارُک بادشاہ آریوخ، ایلامُک بادشاہ چیدرلاومر تہٕ قومن ہُند بادشاہ جدل۔\n2. {یِمو کٔر سدوم کِس بادشاہ بیراہس سٍتۍ، تہٕ گومورہ کِس بادشاہ برشہ، آدمہ کِس بادشاہ شِناب، تہٕ زیبوییم کِس بادشاہ شیمبرس سٍتۍ، تہٕ بیلا کِس بادشاہس سٍتۍ، یُس زوار چھُ۔\n3.\\tیم سٲری ٲسۍ سیدیم کِس وادی منز رٔلِتھ یُس نوٗنہٕ سمندرُک چھُ۔\n4. بَہہ ؤری کٔر تِمو چیڈرلاومرٕچ خدمت، تہٕ ترٛوٲہمہِ ؤریس منٛز کٔر تِمو بغاوت۔\n5. تہٕ ژۄدٲہمہِ ؤریس مَنٛز آو چیدرلاومر، تہٕ تِم بادشاہ یِم أمِس سٍتـ̡ ٲسۍ، تہٕ دِتُکھ اشتروت کارنیمس مَنٛز رفیٖم، تہٕ ہمس مَنٛز زُزِم، تہٕ شاوے کِرِیاتھیمَس مَنٛز ایمیم، {شاوے...: یا، کِرِیاتھیمُک مٲدان}\n6. تہٕ ہوریٹس پننِس پہاڑ سیرس منز، ایلپارنس تام، یُس بیابانس منز {چُھ}۔ {ایلپران: یا، پرانُک مٲدان}\n7.\\tتہٕ تِم آیہ واپس، تہٕ آیہ اینمشپت، یُس قادیش چھُ، تہٕ کوٚرُکھ حززونتمارس منز روزن وٲلِس امالیکین ہٕندِس سارِنٕے ملکس تہٕ امورِین تہِ مار۔\n8.\\tتہٕ تتہِ دراو سدومُک بادشاہ، تہٕ عمورہُک بادشاہ، تہٕ ادمہُک بادشاہ، تہٕ زیبویمُک بادشاہ، تہٕ بیلہُک بادشاہ (یۅہے {چھُ} زور؛) تہٕ تِمو دراو تِمن سٍتـ̡ سیدیم کِس وادی مَنٛز جنگ۔\n9. ایلامُک بادشاہ چیدرلاومر، تہٕ قومن ہُند بادشاہ تہٕ شِنارُک بادشاہ امرافیل تہٕ ایلاسارُک بادشاہ آریوخس سٍتۍ۔ ژور بادشاہ پانژھ سۭتۍ۔\n10.\\tتہٕ سِدِم سٕندِس وادی سٍتۍ بٔرِتھ ٲس۔ تہٕ سدوم تہٕ عمورہ ہٕکۍ بادشاہ ژٔلِتھ تہٕ گٔیہِ تتہِ پیوٚو۔ تہٕ تِم ژٔلِتھ پہاڑس کُن۔\n11.\\tتہٕ تِمو نِش سدوم تہٕ عمورہ ہُک سورُے سامان تہٕ تِہُند سارِوٕے سامان تہٕ تِمن ہٕندِس سارِنٕے سامانہٕ نِش گٔیہِ۔\n12.\\tتہٕ تِمو نِیوو ابرام سٕندِس بٲے سُند نیچو لوط، یُس سدومس منز روزان اوس، تہٕ تٔمۍ سُند مال تہٕ نیرِ۔\n13.\\tتہٕ اَکھ آو یُس ژلِتھ تہٕ وونُن ابرامس عبرانی۔ تکیازِ سُہ اوس ممرے سٕندِس مٲدانس مَنٛز روزان، یُس ایشکول سُند بوے تہٕ انیر سُند بوے اوس، تہٕ یِمو ٲسۍ ابرامس سٍتۍ رٔلِتھ۔ {سادٕ: ہیب۔ میدان}\n14.\\tتہٕ ییلہ ابرامن بوٗز زِ تٔمۍ سُند بوے آو قٲد کرنہٕ، تٔمۍ کٔر پننین تربیت یافتہٕ خادمَن ہتھیار ، یُس پننِس گرس منز زامُت، تریہ ہتھ ارداہ وُہُر، تہٕ کوٚرُن تِمن ہُند پیچھا دانس تام۔ {ہتھیار بند: یا، برونہہ کُن} {تربیت: یا، ہدایت دِنہٕ}\n15.\\tتہٕ تٔمۍ کٔر رٲژ تِمن خٕلاف، تِمن تہٕ تٔمۍ سٕندِس خادمَن ہٕندِس خٕلاف تہٕ لٔگِن تِمن ہُند پیچھا یُس دمشق کِس کھوورِ طرفہٕ چُھ۔\n16.\\tتہٕ اوٚن سٲرۍے مال واپس، تہٕ أنِن پنُن بوے لوط، تہٕ پنُن سامانہٕ تہٕ زنانہٕ تہٕ لوکھ تہِ۔\n17.\\tتہٕ سدومُک بادشاہ دراو أمِس مِلنہٕ خٲطرٕ تہٕ تِمن بادشاہن ہٕندِس قتلہٕ سٍتـ̡ واپس یِنہٕ پتہٕ، یُس شاہہ سٕندِس دَلس مَنٛز اوس۔\n18.\\tتہٕ سالمُک بادشاہ میلکیزیدک اوٚن روٹی تہٕ شراب، تہٕ سُہ اوس اعلیٰ خدایہ سُند پادٕر۔\n19.\\tتہٕ تٔمۍ کٔر أمِس دُعا دُعا تہٕ وونُن، اَبرام سُند مُبارک، یُس اسمانس تہٕ زمینُک مالک چھُ:\n20. تہٕ خدایہ سُند مُبارک، یٔمۍ تُہند دُشمن تُہٕندِس اتھس مَنٛز دِژمُت چھُ۔ تہٕ تٔمۍ دِژ أمِس سارِنٕے سارِنٕے ہُنٛد دٔہِم۔\n21. تہٕ سدوم کِس بادشاہن ووٚن ابرامس زِ مے دِیُن نفر تہٕ نِن پانس نِش۔ {افراد: ہیب۔ روح}\n22.\\tتہٕ ابرامَن ووٚن سدوم کِس بادشاہس سٍتـ̡ ، مے تُلِتھ پَنُن اَتھٕ تُلُمُت، یُس خدایہِ سٍتـ̡ آسمانُک تہٕ زمینُک مالک چُھ،\n23.\\tیہ زِ بہٕ کٔرٕ نہٕ تۅہہِ سٍتـ̡ کانہہ چیز یُس تۅہہِ ہُند {چُھ} آسہِ، یێلہِ ژے ونُن زِ مے چُھس ابرام امیر بنوومُت:\n24.\\tصرف سُہ بچٲوِتھ یُس نوجوانو کھیوٚمُت چُھ، تہٕ یِمن نفرن ہُند حصہٕ یُس میانہِ سٍتـ̡ گٔیہ، انیر، ایشکول تہٕ ممرے۔ تِمن نِن پنُن حصہٕ۔","1. یِمو کتھٕ پَتہٕ آو خداوند سُند کلام ابرامس أکِس خوابس مَنٛز ووتُن، یُس نہٕ خوف کرُن، ابرام: بہٕ چُھس تُہند ڈھال تہٕ تُہند واریاہ بوٚڈ انعام۔\n2.\\tتہٕ ابرامَن ووٚن، خدایہ، ژٕ کیا دِیُکھ مے دِیُن، یێلہِ بہٕ بےٚ اولاد گٔژھِتھ تہٕ میانہِ گرُک رٲچھ دار چھُس دمشقُک یہِ ایلیزر ؟\n3. تہٕ ابرامَن ووٚن، وُچھ، ژے چُھہ نہٕ مےٚ کانٛہہ تہِ بیول دِژمُت، تہٕ یُس میٲنِس گرس مَنٛز زامُت چُھ، سُہ چُھ میون وٲرِث۔\n4.\\tتہٕ وُچھِو خداوند سُند کلام أمِس نِش آمُت، یہِ گژھِ نہٕ تُہند وٲرِث آسُن۔ مگر یُس تۅہہِ پننہِ أنٛدرِ منزٕ نیرِ، سُہ آسہِ تُہند وٲرِث۔\n5.\\tتہٕ تٔمۍ اوٚن سُہ نیبر کُن تہٕ وونُن، وُچھِو آسمانس کُن تہٕ ستارن وَنُن، اگر تہٕ تِمن ہُند گنزراونہٕ لایق آسہِ، تہٕ تٔمۍ ووٚن أمِس زِ تُہند بُل تہِ آسہِ۔\n6. تہٕ سُہ اوس خداوند سُند ایمان تھاوان۔ تہٕ تٔمۍ اوس یہِ نیکی خٲطرٕ أمِس گنزران۔\n7.\\tتہٕ تٔمۍ ووٚن أمِس زِ بہٕ چُھس خداوند یُس ژے چالدی منزٕ نیبر کٔرِتھ تہٕ ژے یہِ زمین دِنہٕ خٲطرٕ دِنہٕ خٲطرٕ۔\n8. تہٕ تٔمۍ ووٚن، خداوند، کمہِ سٍتـ̡ بہٕ پتاہ زِ بہٕ چُھس أمِس وٲرث حٲصِل کٔرِتھ؟\n9.\\tتہٕ أمِس ووٚن، میہ نِن تریہ ؤری وٲنسہِ ہُند اکھ ژھاوُر، تہٕ تریہ ؤری وٲنسہِ ہُند اکھ کۅکر، تہٕ اکھ کچھوُر تہٕ اکھ جوان کبوتر۔\n10.\\tتہٕ تٔمۍ نِن یم سٲری پانس نِش، تہٕ کٔرٕن درمِیان تقسیم، تہٕ تھووُن پرٮ۪تھ اکھ أکِس سٍتـ̡ ، مگر جاناوارو کٔر نہٕ تٔمِس تقسیم۔\n11.\\tییلہ جاناوار لاشن پیٹھ وسۍ، ابرام ژٔلِتھ ژٔلِتھ ژٔلِتھ۔\n12.\\tتہٕ ییلہ آفتاب لوسُن اوس تہٕ ابرامس پیوٚو سرٛوٚن نندر ۔ تہٕ لو، تس پیوٚو سٮ۪ٹھاہ انہِ گٹہِ ہُند وحشت۔\n13. تہٕ تٔمۍ ووٚن ابرامس زِ تُہند بُل گژھہِ تِمن ہٕندِس ملکس مَنٛز اجنبی تہٕ تِہنز خدمت کرٕنۍ۔ تہٕ تِم کرِ تِمن ژور ہتھ ؤری۔\n14. تہٕ سُہ قوم، یٔمِس سٍتـ̡ تِم خدمت کرِ، بہٕ کٔرٕ بہٕ فٲصلہٕ: تہٕ پَتہٕ گژھن تِم سٮ۪ٹھاہ سٍتـ̡ نیرن۔\n15. تہٕ ژٕ گژھ پننین مٲلن نِش امن سان گژھُن۔ ژٕ یِیہٕ اصل بُزرگس منٛز دفن کرنہٕ۔\n16.\\tمگر ژوٗرمہِ پٔرِس مَنٛز یِن تِم دُبارٕ یِنہٕ: کیازِ امورِین ہٕنز بدکاری چھے نہٕ وُنیُک تام پوٗرٕ سپدمٕژ۔\n17.\\tتہ سپد یہ زِ ییلہ آفتاب لوس، تہ انہِ گوٚٹ گوو، وُچھ اکھ دزُن بھٹہ، تہٕ اکھ دزان چراغ یُس یمن ٹکڑن درمیان گزران اوس۔ {اکھ دزُن...: ہیب۔ نارُک شمع}\n18.\\tامی دۅہہ کوٚر خداوند ابرامس سٍتـ̡ عہد تہٕ وونُن زِ مے چُھس یہِ زمین، دریائے مصر پیٹھٕ دریائے فرات تام دِژمُت:\n19.\\tکینیٹس، تہٕ کینیزیٹس تہٕ کڈمونیتس،\n20. تہٕ حِتی، تہٕ پٔرِزِی، تہٕ رِفیم،\n21.\\tتہٕ امورِی، کنعانی، گرگاشی تہٕ یبوسی۔","1.\\tوۅنۍ زاے سراے ابرام سنزِ زنانہِ زاے نہ تس کانہہ شُر: تہٕ أمِس ٲس اکھ دٲیر، اکھ مصری، یٔمۍ سُند ناو اوس ہاجر۔\n2.\\tتہٕ سارایی ووٚن ابرامس زِ وُچھو وُنہِ خداوندَن رُکٲوِتھ مے دِنہٕ نِش: بہٕ چھُس ژے دُعا کٔرِتھ، گژھ میانہِ نونہِ نِش اژُن۔ یہ ہیکہِ ٲسِتھ زِ بہٕ ہیوٚک أمِس سٍتۍ شُرِ حٲصِل کٔرِتھ۔ تہٕ ابرامن بوز سارایی سٕنز آواز۔ {حاصل...: ہیب۔ تٔمۍ سٕنٛدِ ذریعہٕ بناوُن}\n3.\\tتہٕ ساراے ابرام سٕنزِ زنانہِ نییہِ ہاجر، یُس مصری ٲس، یُس کنعان کِس سرزمینس مَنٛز دَہ ؤری روزان اوس، تہٕ دیتُن پننِس خانٛدار ابرامس پننہِ خانٛدارِنہِ خٲطرٕ۔\n4. تہٕ سُہ گوٚو ہاجرس نِش تہٕ أمِس گٔیہِ حاملہٕ، تہٕ ییٚلہِ أمِس وُچھ زِ أمِس ٲس حاملہٕ گٔمٕژ، تٔمۍ سٕنزِ مالکن گٔیہِ أمِس نظرن منز حقارت کرنہٕ۔\n5.\\tتہٕ سارایی ووٚن ابرامس زِ میٲنۍ غلطی چھےٚ، مے چھے پنٕنۍ دٲر چانہِ ہٕندِس سٍتـ̡ دِژمٕژ۔ تہٕ ییلہ تس وُچھ زِ تس چھہ حاملہ گومُت، میہ کٔر تسٕنزِ نظرن منز حقارت کرنہٕ: خداوند کرِ میہ تہٕ ژے درمیان فیصلہٕ۔\n6.\\tمگر ابرامَن ووٚن سَراے یَس وُچھِو، تُہٕنزِ دٲیرِ چُھہ تُہٕندِس اتھس مَنٛز۔ أمِس کٔرِو تِتھہٕ پٲٹھۍ یُس ژےٚ خۅش آسہِ۔ تہٕ ییٚلہِ سارایی أمِس مُشکِل کٔرِتھ، سۄ ژٔل أمِس بُتھِ نِش۔ {as...: Heb. یُس تۅہہِ اچھن منز اصل چھُ} {ڈیلٹ...: ہیب۔ أمِس مُتٲثِر کٔرِتھ}\n7.\\tتہٕ خداوند سٕندِ فرشتہٕ لوٚب سُہ بیابانس مَنٛز آبہٕ کِس چشمہٕ نِش، شورس کُن وتہِ کُن چشمہٕ نِش۔\n8.\\tتہٕ ووٚن ہاجر، ساراے سٕنزِ دٲیر، کتہِ آیہ ژےٚ؟ تہٕ کوٚت گژھِو؟ تہٕ تٔمۍ ووٚن، بہٕ ژٔلِتھ پننہِ مالکن ساراے سٕنٛدِ بُتھِ نِش۔\n9. تہٕ خداوند سٕندِ فرشتن ووٚن أمِس زِ پَنٕنِس مالہِ نِش واپس، تہٕ پَنُن پان کٔرِو تٔمۍ سٕندِس اَتھَس تَل تابع۔\n10. تہٕ خداوند سٕندِ فرشتن ووٚن أمِس زِ بہٕ کٔرٕ تُہند بیول واریاہ زیادٕ، زِ یہِ گژھِ نہٕ بٔڑِس تعدادس سٍتـ̡ گنزراونہٕ۔\n11.\\tتہٕ خداوند سٕندِ فرشتن ووٚن أمِس زِ وُچھ، تہٕ ژے چھے بچہٕ ہیتھ تہٕ نیچو زیٚو، تہٕ تٔمِس ناو اسماعیل وَنُن۔ کیازِکہ خداوند چُھ تُہند مصیبت بوزمُت۔ {اسماعیل: یعنی خدا بوزِ}\n12. تہٕ سُہ آسہِ اکھ جنگلی انسان۔ تٔمۍ سُند اَتھٕ آسہِ پرٮ۪تھ أکِس شخصس خٕلاف، تہٕ پرٮ۪تھ أکِس انسانس خلاف اَتھ؛ تہٕ سُہ روزِ پننین سارِنٕے باین ہٕندِس حٲضِرس منز۔\n13. تہٕ تٔمۍ ووٚن خداوند سُند ناو یُس أمِس سٍتـ̡ وُچھمُت چُھ، تہٕ تٔمۍ ووٚن یێلہِ تہِ چُھس یُس میہ وُچھان چُھ؟\n14.\\tاَمہِ کِنۍ اوس اتھ کُورِ بیرلہیرویی وننہٕ آمُت۔ وُچھِو، {یہِ} چھُ کادیش تہٕ بیرڈس درمِیان ۔ {بیرلہروئی: یعنی سُہ کیور یُس زندٕ روزان تہٕ وچھان چُھ}\n15.\\tتہٕ ہاجرن زاے ابرامس اکھ نیچو: تہٕ ابرام ووٚن پننِس نیچوِس سُند ناو، یُس ہاجرن ہُند ناو اوس، اسماعیل۔\n16.\\tتہٕ ابرام اوس ژورہ تہٕ شیہ وُہُر، ییلہ ہاجرن اسماعیل ابرامس تام زٲو۔","1. تہٕ ییلہ ابرام نَتھ وُہُر تہٕ نو وُہُر اوس، خداوند آو ابرامس نِش ظٲہر تہٕ وونُن تٔمِس زِ بہٕ چُھس قادر مطلق خدا۔ میانہِ برونہہ پکان تہٕ ژٕ گژھ کامل۔ {کامل: یا، سید، یا، مخلص}\n2. تہٕ بہٕ کرٕ پانس تہٕ ژے درمیان پنُن عہد تہٕ کرٕ ژے واریاہ زیادٕ۔\n3.\\tتہٕ اَبرام پیوٚو بُتھِس پٲٹھۍ، تہٕ خداین کٔر أمِس سٍتـ̡ کتھ کٔرِتھ وونُن،\n4. یوتام میانہِ خٲطرٕ، وُچھ، میون عہد چُھہ ژے سٍتـ̡ تہٕ ژٕ بنہٕ واریہن قومن ہُند مول۔ {واریاہ ...: ہیب۔ قومن ہٕنٛز کثیر}\n5. تُہند ناو گژھہِ نہ ابرام وننہٕ یُن، بلکہ گژھہِ تُہند ناو ابراہیم وننہٕ۔ میہ بنوو ژے واریاہن قومن ہٕندِس مٲلس سٍتـ̡ ۔ {ابراہیم: یعنی بٔڈۍ بٔڈِ ہُند مول}\n6. تہٕ بہٕ بناوٕ ژے سٮ۪ٹھاہ پھلدار تہٕ بہٕ بناوٕ ژے نِش قومہٕ، تہٕ بادشاہ یِن ژے نِش نیرن۔\n7. تہٕ بہٕ کَرٕ پنُن عہد پانس تہٕ تُہٕندِس پَتہٕ تُہٕندِس نسلس درمِیان تہٕ تُہٕندِس پَتہٕ تُہٕندِس نسلس سٍتـ̡ ابدی عہد قایم کرنہٕ، یُس تہٕ تُہٕندِس پَتہٕ تُہٕندِس اولادس سٍتـ̡ خدا بنہٕ۔\n8. تہٕ بہٕ دِیہٕ ژے تہٕ تۅہہِ پتہٕ تہندِس نسلس سُہ زمین یتھ منز تہٕ ژے اجنبی چُھ، سٲرۍسٕے کنعانٕچ سرزمین، ہمیشہٕ خٲطرٕ دِنہٕ۔ تہٕ بہٕ آسہٕ تِہُند خدا۔ {یتھ منز...: ہیب۔ چانہِ سفرُک }\n9. تہٕ خداین ووٚن ابراہیمس زِ تێہہ تہٕ تُہٕندِس نسلس پَتہٕ پَتہٕ پۯاوُن میٲنۍ عہد پورٕ۔\n10. یہِ چُھ میٲنۍ عہد یُس ژے میانِس تہٕ ژے تہٕ پننہِ اولادس درمِیان تھاوُن۔ تۄہہِ مَنٛز گژھِ پرٮ۪تھ أکِس مرد شُرِس ختنہٕ کرنہٕ یُن۔\n11.\\tتہٕ پَنٕنِس کھالُک ماز کٔرِو ختنہٕ۔ تہٕ یہِ آسہِ میہ تہٕ ژےٚ درمِیان معاہدٕچ علامت۔\n12.\\tیُس ٲٹھ دۅہہِ وٲنسہِ آسہِ، سُہ گژھہِ تۅہہِ منز، یُس گرس منز زامُت آسہِ، یا کٲنسہِ اجنبی سٕندِ پٲنسہٕ سٍتۍ ہینہٕ یُن، یُس نہٕ تُہندِ نسلہٕ سٍتـ̡ آسہِ۔ {سُہ یُس ٲٹھ چھُ...: ہیب۔ ٲٹھن دوہن ہند نیچو}\n13. یُس تُہندِس گرس مَنٛز زامُت چُھ، تہٕ یُس تُہٕندِس پٲنسہٕ سٍتـ̡ ہینہٕ آمُت چُھ، سُہ گژھہِ ختنہٕ کرنُک ضروری: تہٕ میون عہد گژھہِ تُہندِس مازس مَنٛز ابدی عہد کرنہٕ خٲطرٕ۔\n14.\\tتہٕ سُہ ختنہ کرنہٕ آمُت بچہٕ یٔمۍ سُند ماز ختنہ آسہِ نہٕ کرنہٕ، سُہ روح گژھہِ پننِس لوکن نِش ژٹنہٕ۔ تٔمۍ پھُٹروو میون معاہدٕ۔\n15.\\tتہٕ خداین ووٚن ابراہیمس زِ یێلہِ تہٕ ساراے سٕنزِ زنانہِ ہُند ناو گژھ نہٕ ساراے ناو، بٔلکہِ سارہ سُند ناو {be}۔ {سارہ: یعنی شہزادی}\n16. تہٕ بہٕ دِیہٕ أمِس برکت تہٕ دِیہٕ تٔمِس سُند اکھ نیٚچُو: آ، بہٕ کرٕ أمِس برکت تہٕ سُہ بنہٕ قومن ہٕنز موج۔ لوکن ہند بادشاہ گژھن أمس سٍتۍ۔ {سُہ...: ہیب۔ سۅ بنہِ قوم}\n17.\\tاَمہِ پَتہٕ پیوٚو ابراہیم سٕندِس بُتھِس پیٹھ، تہٕ ووٚنُن دِلَس مَنٛز، یُس ہَتھ وُہُر آسہِ، یُس شُر پٲدٕ سپدِ؟ تہٕ سارہ یُس نتھ ؤری وٲنسہِ چھُ، برداشت کرُن؟\n18.\\tتہٕ ابراہیمَن ووٚن خدایہِ سٍتـ̡ زِ اسماعیل گژھہِ توے برونہہ کُن زندٕ۔\n19. تہٕ خداین ووٚن سارہ چانہِ زنانہِ زیٚیہِ ژےٚ پٔزۍ پٲٹھۍ اکھ نیٚچُو۔ تہٕ تٔمۍ سُند ناو اسحاق وَنُن، تہٕ بہٕ کرٕ أمِس سٍتـ̡ پنُن عہد ہمیشہٕ خٲطرٕ قٲیم، {تہٕ} تٔمِس پتہٕ تٔمۍ سٕندِس بولس سٍتـ̡ ۔\n20.\\tیێلہِ تہٕ اسماعیلُک تعلق چُھ، مے چُھہ تۅہہ بوزمُت: وُچھمُت بہٕ چُھس أمِس برکت دِژمُت تہٕ سُہ کرٕ سُہ پھل دِنہٕ تہٕ سُہ کرٕ سٮ۪ٹھاہ زیادٕ۔ سُہ زیٚنہٕ باہ شہزادٕ، تہٕ بہٕ بناوٕ تس اکھ عظیم قوم۔\n21. مگر بہٕ کَرٕ اسحاقس سٍتـ̡ پنُن عہد قٲیم، یُس سارہ یِنہٕ وٲلِس ؤریس مَنٛز یَتھ مُقرر وقتس پیٹھ ژےٚ دِیہِ۔\n22.\\tتہٕ تٔمۍ ترٲو أمِس سٍتـ̡ کتھ باتھ تہٕ خدا ووت ابراہیم سٍتـ̡ ۔\n23.\\tتہٕ ابراہیم نِش نیچو اسماعیل، تہٕ یُس سارِوٕے یُس أمۍ سٕندِس گرس مَنٛز زامُت اوس، تہٕ یُس سارِوٕے یُس أمۍ سٕندِس پٲنسہٕ سٍتـ̡ ہینہٕ آمُت اوس، یُس ابراہیمس سٕندِس گرس مَنٛز پرٮ۪تھ کانہہ مرد ہیوٚت۔ تہٕ کٔرٕن امی دۅہہٕ پننِس کھالُک ماز ختنہٕ، یِتھ کٔنۍ خداین أمِس ووٚنمُت۔\n24.\\tتہٕ ابراہیم اوس نَمتھ وُہُر تہٕ نو وُہُر، ییلہ أمِس پننہِ کھالہِ ہٕندِس مازس مَنٛز ختنہ کرنہٕ آو۔\n25.\\tتہٕ اسماعیل سُند نیچو اوس ترہ وُہُر، ییلہ أمِس پننہِ کھالہِ ہٕندِس مازس مَنٛز ختنہ کرنہٕ آو۔\n26.\\tاَمی دۅہہٕ آو ابراہیم سُند ختنہ کرنہٕ تہٕ اسماعیل سُند نیچو۔\n27.\\tتہٕ تٔمۍ سٕندِس گرٕکۍ سٲری مرد یِم گرس منز زامٕتۍ، تہٕ اجنبی سٕندِ پٲنسہٕ سٍتۍ ہینہٕ آمٕتۍ، آیہ أمِس سٍتـ̡ ختنہ کرنہٕ۔","1.\\tتہٕ خداوند آو أمِس نِش مامرے کِس مٲدانس مَنٛز ظٲہر تہٕ سُہ بِہتھ دۅہلہٕ کِس گرمی مَنٛز خیمہ کِس دروازس پیٹھ۔ {سادٕ: ہیب۔ میدان}\n2.\\tتہٕ تٔمۍ کٔر أچھ تُلِتھ تہٕ وُچھن تریہ نفر أمِس سٍتـ̡ کھڑا تہٕ ییلہ تٔمۍ وُچھ، سُہ ژوٚل خیمہ کِس دروازٕ پیٹھٕ تِمن سمکھنہٕ خٲطرٕ، تہٕ دوٚپ پان زمینس کُن نمُن،\n3. تہٕ وۆنُن، میانہِ خداوند، اگر وُنہِ تہِ چُھس ژے نِش احسان میلہِ، بہٕ گژھ نہٕ ژے پنٕنِس خادمس نِش دُعا کٔرِتھ:\n4. بہٕ چُھس دُعا کٔرِتھ رژھ رژھ آب اَننہٕ تہٕ پَنٕنۍ کھۅر چھلناوٕن، تہٕ کُلِس تَل آرام کٔرِو:\n5. تہٕ بہٕ اَنُن اکھ ٹُکرٕ بٔرِتھ تہٕ ژےٚ دِل دِل دِوان۔ اَمہِ پتہٕ گژھِو تُہۍ پَنٕنِس خادمَس نِش یِوان۔ تہٕ تِمو ووٚن، تِتھۍ کٔرِو یُتھ ژے وَنُن۔ {آرام: ہیب۔ روزُن} {are...: Heb. تُہۍ چھِو پاس گٔمٕتۍ}\n6.\\tتہٕ ابراہیم ووت سارہ نِش خیمہ منز، تہٕ وونُن، جلدی تریہ رٔٹِتھ کھین تیار کرُن، گُنُن تہٕ چالس پیٹھ بناوُن کیک ۔ {تیار کرو ...: ہیب۔ ہیسٹن}\n7.\\tتہٕ ابراہیم ژوٚل کھورِ کُن، تہٕ دیتُن أکِس نوجوانس دِنہٕ۔ تہٕ تٔمۍ کٔر جلدی اتھ پَلو۔\n8.\\tتہٕ تٔمۍ رٔٹِتھ تھنہٕ، تہٕ دۄد، تہٕ بَچھرٕ یُس أمِس پَلَو لٲگِتھ اوس، تہٕ تھووُن تِمن برونہہ کُن۔ تہٕ سُہ اوس تِمن نش کُلِس تلہ کھڑا تہٕ تِمو کھیوٚن۔\n9.\\tتہٕ تمو ووٚن تمس زِ سارہ کتہِ چھے تہنز زنانہٕ؟ تہٕ أمۍ ووٚن، وُچھ، خیمہ منٛز۔\n10. تہٕ ووٚن بہٕ یٔقیٖنی طور زندگی ہٕندِس وقتس مُطٲبق ژے نِش واپس۔ تہٕ لو، سارہ چانہِ زنانہِ زاے اکھ نیٚچُو۔ تہ سارہ بوز خیمہ کس دروازس منز، یُس تس پتھ کُن اوس۔\n11.\\tوۅنۍ اوس ابراہیم تہٕ سارہ وٲنسہِ منز وٲنسہِ منز مبتلا سپدان۔ {تہٕ} زنانن ہٕندِ طریقہٕ پتہٕ گٔیہٕ ساراہس سٕتۍ روزُن ختم۔\n12.\\tلہذا ووت سارہ پانس اندر اسُن، وونُن زِ بہٕ بُزرگ گژھنہٕ پتہٕ گژھہٕ بہٕ خوشی، میون آقا تہِ بُزرگ آسُن؟\n13.\\tتہٕ خداوند ووٚن ابراہیمس زِ سارہ کیازِ وۆن اسُن، وۆنُن زِ بہٕ کیا بہٕ زیٚنہٕ یُس بُزرگ چُھ؟\n14. کیا کانہہ چیز چھا خداوندٕ سٕندِ خٲطرٕ واریاہ مشکل؟ مقرر کرنہٕ آمتس وقتس پیٹھ گژھہٕ بہٕ ژےٚ نِش واپس، زندگی ہٕندِ وقتہٕ مطٲبق، تہٕ سارہ زیٚو اکھ نیٚچُو۔\n15.\\tسارہ کٔر انکار تہ وونُن میہ اسُن نہ۔ تکیازِ سۅ ٲس کھوژان۔ تہٕ تٔمۍ ووٚن، نہ۔ مگر تۅہہ کٔر اسن۔\n16.\\tتہٕ مرد ووٚتھ تتہِ پیٹھ، تہٕ سدوم کُن نظر تہٕ ابراہیم گوٚو تِمن سٍتـ̡ وتہِ اننہٕ خٲطرٕ۔\n17.\\tتہٕ خداوند ووٚن زِ بہٕ کٔرٕ ابراہیم نِش سُہ چیز یُس بہٕ کران چھُس،\n18.\\tیہ وُچھِتھ زِ ابراہیم بنہِ یقینا اکھ عظیم تہٕ طاقتور قوم تہٕ زمینہٕ کین سارِنٕے قومن گژھن أمِس سٍتـ̡ برکت حٲصِل کرنہٕ۔\n19.\\tبہٕ چُھس أمِس زانان زِ سُہ کرِ پننین شُرین تہٕ گرن ہُند حُکُم، تہٕ تِم کرِ خداوند سٕنزِ وتہِ رٔٹِتھ، انصاف تہٕ انصاف کرنہٕ خٲطرٕ۔ یُتھ خداوند ابراہیم سٕندِس بارس مُتلق کتھ کرِ۔\n20. تہٕ خداوند ووٚن زِ سدوم تہٕ عمورہ ہٕچ فریاد چِھ بٔڈ تہٕ تِہُند گۅناہ چُھ سٮ۪ٹھاہ سنگین ۔\n21.\\tبہٕ گژھہِ وۅنۍ بۄن تہ وُچھان زِ تِمو چھا امہِ کِس فریاد مطٲبق یُس میہ برونہہ کُن آمُت چھُ۔ تہٕ اگر نہٕ تیلہِ گژھہِ میہ پتہ۔\n22.\\tتہٕ مرد پھیرۍ تتہِ پَنُن بُتھ تہٕ گٔیہِ سدوم کُن، مگر ابراہیم اوس وُنہِ تہِ خداوند برونہہ کُن کھڑا۔\n23.\\tتہٕ ابراہیم ووت نزدیک، تہٕ ووٚنُن، کیا ژٕ کٔرِکھ نیکوکارن تہِ بدکارن سٍتـ̡ تباہ کٔرِتھ؟\n24.\\tشاید شہرس منز آسن پنژاہ نیکوکار: کیا ژیہ تہِ تباہ کٔرِتھ تہٕ یِمن منز موجود پنژاہ نیکوکارن ہٕندِ خٲطرٕ جاۓ تراوٕن؟\n25.\\tیُس ژے نِش دور روزُن، یُس بدکارن سٍتـ̡ مارُن، تہٕ نیک گٔژھِن بدکارن ہٕندۍ پٲٹھۍ، یُس توے نِش دور آسہِ: کیا سارِنٕے زمینُک قاضی کرِ نہٕ صحیح؟\n26.\\tتہٕ خداوند ووٚن زِ اگر بہٕ سدومس منز شہرس مَنٛز پنژاہ نیک لبنہٕ یِوان، تیلہِ کٔرٕ بہٕ تِہندِ خٲطرٕ سارِنٕے جاے بچاو۔\n27.\\tتہٕ ابراہیمَن دِیُت جواب تہٕ وونُن، وُچھو وُن، بہٕ چُھس خداوند سٍتـ̡ کتھ کرٕنـ̡ یُس {بہٕ چُھ} مٔژ تہٕ سوٗر سٍتـ̡ چُھہ ۔\n28.\\tشاید آسہِ پانژاہن منز پانژھ نیکوکارن ہنز کمی: کیا ژے کٔرِکھ سارِوٕے شہر پانژو کٔرِتھ تباہ کٔرِتھ؟ تہٕ تٔمۍ ووٚن، اگر بہٕ تتہِ ژتٲجی تہٕ پانژتٲجی لٔبِتھ، بہٕ کٔرٕ نہٕ یہِ تباہ کرنہٕ۔\n29.\\tتہٕ تٔمۍ کٔر أمِس بییہِ اکہِ لٹہِ کتھ تہٕ وونُن، شاید تتہِ گژھن ژتٲجی لبنہٕ۔ تہٕ تٔمۍ ووٚن، بہٕ کٔرٕ نہٕ ژتٲجی خٲطرٕ {یہ}۔\n30. تہٕ تٔمۍ ووٚن {أمِس}، اے خداوند گژھ نہٕ ناراض، تہٕ بہٕ کَرٕ کتھ: شاید تتہِ لبنہٕ یِنہٕ ترٕہ۔ تہٕ تٔمۍ ووٚن، بہٕ کٔرٕ نہٕ {یہ}، اگر مےٚ تتہٕ ترہ میلہٕ۔\n31.\\tتہٕ تٔمۍ ووٚن، وُچھو وُن، مے چُھس خدایہ سٕندِس سٍتـ̡ کتھ کرنٕچ ذمہٕ وٲری کٔرمٕژ: شاید تتہِ گژھن وُہ لبنہٕ۔ تہٕ تٔمۍ ووٚن، بہٕ کٔرٕ نہٕ وُہن ہٕندِ خٲطرٕ {یہ} تباہ کرنہٕ۔\n32.\\tتہٕ ووٚن، اے خداوند گژھ نہٕ ناراض، تہٕ بہٕ کرٕ وُنہِ تہِ کتھ مگر یہ اکہِ لٹہِ: شاید دَہ لٔبِتھ تتہِ۔ تہٕ تٔمۍ ووٚن، بہٕ کٔرٕ نہٕ دہن ہٕندِ خٲطرٕ {یہ} تباہ کرنہٕ۔\n33.\\tتہٕ خداوند دراو پننہِ وتہِ، یُتھ سُہ ابراہیم سٍتـ̡ کتھ باتھ کٔرِتھ نیرِ، تہٕ ابراہیم آو پننہِ جایہ واپس۔","1.\\tتہٕ سدومس تام آیہ زٕ فرشتہٕ۔ تہٕ لوط بیوٹھ سدوم کس دروازس پیٹھ: تہٕ لوط وُچھتھ ووٚتھ تمن سمکھنہٕ خٲطرٕ۔ تہٕ تٔمۍ کٔر پنُن بُتھ زمینس کُن نم۔\n2. تہٕ تٔمۍ ووٚن، وُچھِو وُن، میٛٲنۍ آقا، بہٕ چُھس دُعا کٔرِتھ، پننِس نوکر سٕندِس گَرَس مَنٛز، تہٕ سارِوٕے رٲژ روزُن، تہٕ پَنٕنۍ وَتہٕ پَنٕنـ̡ پٲٹھـ̡ پَنٕنـ� تہٕ تِمو ووٚن، نہ۔ مگر أسۍ روزو سارۍ رٲژ سڑکہِ منز۔\n3.\\tتہٕ تٔمۍ کٔر تِمن پیٹھ سٮ۪ٹھاہ دباو۔ تہٕ تِم گٔیہِ أمِس نِش تہٕ ژاو أمۍ سٕندِس گرس منز۔ تہٕ تٔمۍ بنوو تِمن دعوت تہٕ کٔرٕن خمیر روٚس روٹی تہٕ تِمو کھیوٚن۔\n4.\\tمگر یِمن ہٕندِس لٔگِس پٲٹھۍ، شہرٕکۍ مرد، حتیٰ کہ سدوم ہٕندِس مردس تہِ گٔیہِ گرس اندۍ پکھۍ، بُزرگ تہٕ جوان ، پرٮ۪تھ کُنہِ طرفہٕ سارِنٕے لُکھ ۔\n5.\\tتہٕ تِمو بُلوط بُلٲوِتھ وونُن تِم نفر کتہِ چھِ یِم رٲژ ژےٚ نِش آمٕتۍ۔ تِم أنِو اسہِ نِش، یُتھ أسۍ تِمن زانان چھِ۔\n6. تہٕ لوط دراو تِمن نِش دروازٕ پیٹھ، تہٕ کوٚرُن أمِس پتہٕ دروازٕ بند۔\n7. تہٕ وونُن، بہٕ چُھس دُعا کران زِ یێلہِ کٔرِو نہٕ یُتھ بدکار سٍتـ̡ ۔\n8. وُچھِو وُن، مےٚ چھِ زٕ کورِ یِم نہٕ انسانس زانان چھِ۔ بہٕ چُھس ژے دُعا کران زِ تِم کٔرِو پانس نِش نِش، تہٕ تِمن سٍتۍ کٔرِو تِمن سٍتـ̡ یِتھٕ پٲٹھۍ تہٕ تِمن سٍتـ̡ کٔرِو نہٕ کیٚنٛہہ تہِ۔ تکیازِ تِم آیہ میانہِ چھتہِ ہٕندِس ژھایہ تل۔\n9. تہٕ تمو ووٚن، کھڑا گژھ۔ تہٕ تِمو ووٚن {دوبارٕ}، یہِ {نفر} آو روزنہٕ خٲطرٕ، تہٕ أمِس گژھہِ قاضی بننٕچ ضرورت: وۄنۍ کٔرٕ أسۍ تِمن سٍتـ̡ زیادٕ سٍتـ̡ س� تہٕ تِمو دِژ أمِس شخصس پیٹھ دَگ تہٕ دِژ دروازٕ پھُٹراونہٕ خٲطرٕ۔\n10.\\tمگر مردو تروو اتھہ تہ لوط کٔرِن پانس کُن گرس اندر تہ دروازہ بند کٔرتھ۔\n11.\\tتہٕ تِمو دِژ مکانہٕ کِس دروازس پیٹھ یِمن نفرن انہِ سٍتـ̡ انہِ سٍتـ̡ لۅکٹۍ تہٕ بٔڈۍ ٲسۍ، یُتھ تِمو دروازٕ ژھانڈنہٕ خٲطرٕ تھکان گٔیہِ۔\n12.\\tتہٕ مردو ووٚن لوطس زِ ژیہ چھا یتہِ کانہہ تہِ؟ زامتٕر، تہٕ پنٕنۍ نیٚچوۍ، تہٕ تُہٕنٛزِ کورِ، تہٕ شہرس مَنٛز یُس تہِ چُھ، تِم أنِو یَتھ جایہِ منزٕ نٮ۪بر۔\n13. تکیازِ أسۍ کرو یہ جاے تباہ کرنہٕ، تکیازِ تِمن ہٕنز فریاد چھے خداوند سٕندِس بُتھِس برونہہ کُن بٔڈِتھ موم سپدان۔ تہٕ خداوند چُھ اسہِ یہِ تباہ کرنہٕ خٲطرٕ سوزمُت۔\n14.\\tتہٕ لوط دراو نیبر، تہٕ کورِ سٍتـ̡ خاندر کٔرِتھ پننین زامتٕرَن سٍتـ̡ کتھ باتھ کٔرِتھ وونُن، یێمہِ سٍتـ̡ کٔرِو یێمہِ جایہِ منزٕ نِش نیرُن۔ تکیازِ خداوند کرِ یہ شہر تباہ کرنہٕ۔ مگر سُہ اوس باسان یُس پننین زامترن ٹھٹھہٕ کران اوس۔\n15.\\tییلہ صُبح وۅتھ، فرشتو کٔر لوتس جلدی تہ وونُن زِ وۅتھ، پنٕنۍ زنانہِ تہٕ پنٕنۍ زٕ کورِ یِم یتھے چھِ۔ متان گژھہِ ژیہ شہر کِس بدکارس منز کھسنہٕ۔ {یتھے چھہِ: ہیب۔ لبنہٕ آو} {بدکاری: یا، سزا}\n16.\\tتہٕ ییلہ سُہ رٔٹِتھ روٗد، مردو تھپھ أمِس اتھس پیٹھ، تہٕ أمۍ سٕنزِ زنانہِ ہٕندِس اتھس تہٕ تٔمۍ سٕنزن دۄن کورِ ہٕندِس اتھس پیٹھ۔ خداوند اوس أمِس سٍتـ̡ رحم کٔرِتھ، تہٕ تِمو أنۍ سُہ نیبر، تہٕ ترٛٲوِکھ سُہ شہرٕ نیبر۔\n17.\\tتہٕ ییلہ تِمو تِم نیبر کٔرۍ، تٔمۍ ووٚن، ژٔلِو پننہِ زُو خٲطرٕ۔ پتھ کُن وچھُن نہٕ تہٕ سارِنٕے میدانس منز روزُن۔ پہاڑس تام ژلُن، نتہٕ ژٔلِتھ ژٔلِتھ ژٔلِتھ۔\n18.\\tتہٕ لوطس ووٚن تِمَن زِ اوہ، تَتھ چھُنہٕ میانہِ آقا:\n19.\\tوُچھِو وُنہِ چُھہ چانہِ خادمَس تۅہہِ ہٕندِس نظرس منز فضل میلمُت، تہٕ ژے کٔر پنٕنۍ رحمت، یُس ژے میانہِ زُو بچاونہٕ خٲطرٕ ہٲومُت چھُ۔ تہٕ بہٕ ہیوٚک نہٕ پہاڑس تام ژلِتھ، متان زِ کانہہ بد گژھہِ میہ نِن، تہٕ بہٕ مرُن:\n20.\\tوُچھو وۅنۍ یہ شہر ژلنس نزدیک، تہٕ یہ {چُھ} لۅکٹُن: اوہ، میہ ژلُن تتہِ، ({کیا یہ} چھُنہٕ لۅکٹ؟) تہٕ میون روح روزِ زندٕ۔\n21.\\tتہٕ تٔمۍ ووٚن أمِس زِ وُچھ، مے چُھس ژےٚ اَتھ چیزس مُتلِق تہِ قبوٗل کٔرمٕژ، زِ بہٕ کرٕ نہٕ یہِ شہر، یَتھ خٲطرٕ ژے کتھ کٔرمٕژ چھےٚ۔ {تھی: ہیب۔ تُہند بُتھ}\n22. ژٔلِتھ تکیازِ بہٕ ہیوٚک نہٕ توٚت تام کانہہ تہِ کٔرِتھ یوٚت تام نہٕ ژٕ تتہِ یِنہٕ۔ تَمِہ کِنۍ اوس شہرُک ناو زور۔ {زور: یعنی لٹل}\n23.\\tآفتاب ووت زمینہِ پیٹھ ییلہ لوط زورس منز اژان اوس۔ {risen: Heb. برونٹھ کُن}\n24. تێلہِ دِژ خداوند سدوم تہٕ گومورہس پیٹھ بھنور تہٕ آسمانہٕ پى۪ٹھٕ خداوند سٕندِ طرفہٕ نار۔\n25. تہٕ تٔمۍ کٔر تِم شہر، تہٕ سارِنٕے مٲدان، تہٕ شہرن ہٕندِس سارِنٕے بسکیٖن دَرن تہٕ یُس زمینس پیٹھ کھسنہٕ آمُت اوس۔\n26.\\tمگر أمۍ سٕنزِ خانٛدارِنہِ وُچھن پَتہٕ کُن تہٕ بنییہِ نوٗنُک تھَم۔\n27.\\tتہٕ ابراہیم ووت صُبحے سُلہِ تتھ جایہِ ییتہِ سُہ خداوند سٕندِ برونہہ کُن کھڑا اوس۔\n28.\\tتہٕ سُہ وُچھُن سدوم تہٕ عمورہ کُن تہٕ سٲرۍسٕے میدانس کُن تہٕ وُچھُن تہٕ وُچھُن ملکُک دھونہٕ بٹھہِ ہٕندِس دوٚہہِ ہٕندۍ پٲٹھۍ۔\n29.\\tتہٕ سپُد یێلہِ خداین میدانٕکۍ شہر تباہ کٔرِتھ، خداین کۆر ابراہیم یاد، تہٕ لوط سوٗزُن تختہٕ والہِ منزٕ نیبر، ییلہ تٔمۍ تِم شہر الٹٲوِتھ یِمن منز لوط روزان اوس۔\n30.\\tتہٕ لوط ووت زؤر منزہ نیبر تہ پہاڑس منز روزُن، تہٕ تٔمۍ سٕنزٕ زٕ کورِ گٔیہِ أمِس سٍتـ̡ ۔ تکیازِ تس اوس زورس منز روزنہٕ نِش کھوژان: تہٕ سُہ اوس أکِس گۅپھِ منز روزان، سُہ تہٕ تٔمۍ سٕنزِ دۅشوٕنۍ کورِ۔\n31.\\tتہٕ گۅڈنچہ اولاد ووٚن لۅکٹِس زِ سون مول چُھ بُزرگ، تہٕ زمینس منز چُھہ نہٕ کانہہ تہِ انسان یُس سارِنٕے زمینہِ ہٕندِس طریقس پٲٹھـ̡ اسہِ نِش یِنہٕ:\n32.\\tآو، أسۍ پَنُن مٲلِس شراب چیٚوُن، تہٕ أسۍ کرو أمِس سٍتـ̡ یُتھ أسـ̡ پننِس مٲلہِ سٕندِس بُلِس رژھراوُن۔\n33.\\tتہٕ تِمو دِژ تَمہِ رٲژ پننِس مٲلِس شراب چیوان، تہٕ گۄڈنیُک زامُت ژاو تہٕ لوٚگ پننِس مٲلِس سٍتـ̡ ۔ تہٕ تس اوس نہٕ یہ احساس زِ سۅ کر لوٚگ، تہٕ نہ کر ووٚتھ۔\n34.\\tتہٕ پَگہہ ووت زِ گۅڈنِکِس لۅکٹِس ووٚن، وُچھ، بہٕ چُھس رٲژ پننِس مٲلِس سٍتـ̡ رٲژ شراب۔ تہٕ ژٕ گژھ اژُن، {تہٕ} أمِس سٍتـ̡ روزُن، یُتھ أسۍ پننِس مٲلہِ سٕندِ بُلِس رژھراونہٕ یِوان۔\n35.\\tتہٕ تِمو دِژ تَمہِ رٲژ پننِس مٲلِس تہِ شراب، تہٕ لۄکُٹ ووٚتھ تہٕ أمِس سٍتـ̡ لوٚگ۔ تہٕ تس اوس نہٕ یہ احساس زِ سۅ کر لوٚگ، تہٕ نہ کر ووٚتھ۔\n36. یِتھٕ پٲٹھۍ گٔیہٕ لوط سٕنزِ دۅشوے کورِ مٲلہِ سٕندِس مٲلس سٍتـ̡ شُر۔\n37.\\tتہٕ گۅڈنِکِس نیٚچوِس زاے تہٕ تٔمِس ناو موآب ناوُن، یُس از تام موآبین ہُند مول اوس۔\n38.\\tتہٕ لۄکٹِس تہِ زاے أمِس نیچو، تہٕ وَنُن أمِس بَنامی ناو، یۅہے چھُ از تام عمون سٕندٮ۪ن شُرین ہُند مول ۔","1.\\tتہٕ ابراہیم گۆو تتہِ پیٹھہ جنوبی ملکس کُن سفر تہٕ قادیش تہٕ شورس درمیان روزُن تہٕ گرارس مَنٛز روزُن۔\n2.. تہٕ ابراہیم ووٚن سارہ سٕنزِ زنانہِ متعلق، سۅ چھے میٲنۍ بینہِ، تہٕ جرارُک بادشاہ ابیمیلک سوزُن تہٕ کوٚرُن سارہ نِنہٕ۔\n3.\\tمگر خدا آو رٲژ خوابس منز ابیمیلکس نِش، تہٕ وونُن تٔمِس وُچھِو، تۅہہِ چُھکھ اَکھ مُردٕ مرد، یُس ژے نِش نِیومُت چھُ۔ تکیازِ سۅ چھیہ مردہ سنز زنانہ۔ {اکھ مرد...: ہیب۔ خانٛدرٕ کٔرِتھ خانٛدر}\n4.\\tمگر ابیمیلک اوس نہٕ أمِس نزدیک آمُت، تہٕ ووٚنُن، خداوند، کیا ژٕ کٔرِکھ اکھ نیک قوم تہِ مٲرِتھ؟\n5.\\tتٔمۍ ووٚن نہ میہ زِ سۅ چھیہ میٲنۍ بینہِ؟ تہٕ سۅ تہِ ووٚن، سُہ چھُ میون بوے: میانہِ دِل چہ دیانت داری تہٕ پننین اتھن ہٕنزِ معصومیت سٍتۍ چھُ میہ یہ کورمُت۔ {دیانتداری: یا، سادگی، یا، اخلاص}\n6. تہٕ خداین ووٚن تس خوابس منز، آ، میہ چھیہ پتاہ زِ ژے کٔر یہ پننہِ دِل چہ سالمیت سٍتـ̡ کرنہٕ۔ تکیازِ میہ تہِ رُکوو ژے پانس خلاف گۅنہہ کرنہٕ نِش، لہذا کٔر میہ ژیہ نہ تس اتھہ لاگُن۔\n7.\\tتێلہِ کٔرِو مردس {تسٕن} زنانہٕ بحال ۔ تکیازِ سُہ چُھ اکھ پیغمبر، تہٕ سُہ کرِ تۅہہِ خٲطرٕ دُعا، تہٕ تۅہہ روزِ زندٕ: تہٕ اگر نہٕ تۅہہ بحال کٔرِو، تہٕ ژے گژھہِ پٔزۍ پٲٹھۍ، تہٕ تُہۍ چھِو یِمن سارِنٕے سٍتـ̡ مٔرِتھ۔\n8. اَمہِ مۄکھٕ ووٚتھُن صُبحس سُلہِ تہٕ بُلٲوِن پنٕنِس سارِنٕے خادمَن تہٕ یِم سارِنٕے کَنن وَنُن تہٕ تِمن ہٕندِس کَنَس مَنٛز وَنُن تہٕ مرد گٔیہِ خوفہٕ۔\n9. ابیمیلکن بُلوو ابراہیم تہٕ وونُن، ژے کیا چُھ اسہِ سٍتـ̡ کورمُت؟ تہٕ مے کیا چُھس ژے ناراض کورمُت، زِ ژے چُھکھ میٲنس تہٕ میٲنس سلطنتس پیٹھ اکھ بوٚڈ گۅناہ انمُت۔ ژے کٔر میانہِ سٍتۍ تِم کٲم یِم نہٕ گژھن گژھن۔\n10. تہٕ ابیمیلکن ووٚن ابراہیمس زِ ژے کیا چُھہ یہِ کٲم کٔرمٕژ۔\n11.\\tتہٕ ابراہیم ووٚن، کیازِ میہ سونچ، یقینا خدایہ سُند خوف چُھہ نہٕ یَتھ جایہ۔ تہٕ تِم مارن میہ زنانہِ ہٕندِ خٲطرٕ۔\n12. تہٕ توتہِ چھے پٔزۍ پٲٹھۍ میٲنۍ بینہِ۔ سۅ چھیہ میٲنس مٲلۍ سنز کور، مگر میانہِ ماجہ ہنز کوٗر چھیہ نہ۔ تہٕ سۄ بنییہ میٲنۍ زنانہٕ۔\n13.\\tتہٕ سپُد ییلہ خدایہ میہ مٲلہِ سٕندِ گرٕ منزٕ ژٔلِتھ دِژ، میہ ووٚن أمِس زِ یہِ چُھہ تُہند احسان یُس ژے میہ ہاوُن۔ پریتھ جایہ ییتہِ أسۍ واتہِ، میانہِ متعلق ونُن، سُہ چُھ میون بوے ۔\n14.\\tتہٕ ابیملکن رٔٹۍ کۅکر، گاڈ، مرد تہٕ خادمہ تہٕ زنانہٕ تہٕ دِژن ابراہیمس تہٕ دِژن سارہ پنٕنۍ زنانہٕ واپس۔\n15.\\tتہٕ ابیملکن ووٚن، وُچھ، میٲنۍ زمین چُھہ ژے برونہہ کُن: ییتہِ یہ ژے پسند آسہِ، تتہِ روزُن۔ {کتہِ...: ہیب۔ یتھے پاٹھۍ چھہ چانہِ اچھن منز اچھ}\n16.\\tسارہ ہس ووٚن تۅہہِ بٲیِس ساس رۅپہٕ رۅپہٕ دِژمُت، وُچھِو سُہ چُھہ تۅہہِ سٍتـ̡ أچھن ہُند پردٕ دِژمُت، یێلہِ سارِنٕے سٍتـ̡ تہٕ سارِنٕے سٍتـ̡ چُھہ سُہ ملامت کرنہٕ۔\n17. یێلہِ کٔر ابراہیمَن خدایہِ سٕنز دُعا، تہٕ خداین کٔر ابیملک، تہٕ تٔمۍ سٕنزِ خانٛدارِنۍ تہٕ تٔمۍ سٕنزِ دٲیرِ شفا ۔ تہٕ تِم چھِ {شُرۍ}۔\n18. کیازِ خداوند اوس سارہ ابراہیم سٕنزِ زنانہِ ہٕندِ وجہ سٍتـ̡ ابیمیلیک سٕندِ گرٕچ سارِنٕے رحم بند کٔرمٕژ۔","1. تہٕ خداوند کٔر سارہ سٍتـ̡ یێلہِ تٔمِس وۆنمُت اوس، تہٕ خداوند کٔر سارہ سٍتـ̡ یێلہِ تٔمِس کتھ ٲس کٔرمٕژ۔\n2. سارہ ہٕندِس بُزرگس مَنٛز پیوو تہٕ زاے ابراہیمس سُند اکھ نیٚچُو، یُس مُقرر وقتس مُتلق خداین أمِس سٍتـ̡ کتھ کٔرمٕژ ٲس۔\n3.\\tتہٕ ابراہیمَن ووٚن پننِس نیچوِس سُند ناو یُس أمِس زامُت اوس، یُس سارہ أمِس زامُت اوس، اسحاق ۔\n4.\\tتہٕ ابراہیم کٔر پننِس نیچوِس اسحاق سُند ختنہ یُس ٲٹھ دۅہہِ اوس، یُس خداین حکم دِتمُت اوس۔\n5. تہٕ ابراہیم اوس ہتھ وُہُر، ییلہ تٔمۍ سُند نیچو اسحاق زامُت اوس۔\n6.\\tتہٕ سارہ ووٚن خداین چُھس میہ اسُن، {یُتھ} سارِنٕے بوزن وول آسہِ میہ سٍتـ̡ اسُن۔\n7.\\tتہٕ ووٚن زِ کُس آسہِ ابراہیمس ووٚنمُت زِ سارہ آسہِ شُرِ دِنہٕ آمُت۔ تکیازِ میہ چھہ بُجرس منز اکھ نیچو زامُت۔\n8.\\tتہٕ شُر بوٚڈ تہٕ دوٚد دِنہٕ آمُت، تہٕ ابراہیمَن کٔر اَمہ دۅہہ اَمہ دۅہہ یُس اسحاق دۄد دِنہٕ آو۔\n9.\\tتہٕ سارہ وُچھ ہاجرہ سُند نیچو، یُس تٔمۍ ابراہیمس زامُت اوس، ٹھٹھہٕ کٔرِتھ۔\n10. اَمہِ مۄکھٕ ووٚن تٔمۍ ابراہیمس زِ یہِ خانٛدار تہٕ تٔمۍ سُنٛد نیچو کٔڑِو نہٕ میٲنِس نیٚچوِس سٍتـ̡ وٲرِث۔\n11.\\tتہٕ یہِ چیز اوس ابراہیم سٕندِس نظرِ سٍتـ̡ سٮ۪ٹھاہ خوف۔\n12. تہٕ خداین ووٚن ابراہیمس زِ یہ گژھہِ نہٕ تۅہہِ سٕندِ نظرِ سٍتـ̡ لڑکہٕ سٕندِ وجہ سٍتـ̡ تہٕ پننہِ خانٛدارِ ہٕندِ سٍتـ̡ غمگسار سپدُن۔ سارہ سٕندِس سارِنٕے کُنہِ چیزس منز بوزِو تٔمۍ سٕنزِ آواز۔ تکیازِ اسحاق سٕندِس سٍتـ̡ ییہِ تُہند بُلُک بُلاونہٕ۔\n13. تہٕ غلام سٕندِس نیچوِس سٍتـ̡ تہِ بناوٕ بہٕ قوم ، کیازِ سُہ چُھہ تُہند اولاد۔\n14.\\tتہٕ ابراہیم ووٚتھ صُبحے ووٚتھ، تہٕ روٚٹ تہٕ اکھ بوتل آبہٕ تہٕ دیتُن ہاجرس تہٕ دیتُن أمِس پھیکس پیٹھ تہٕ شُر، تہٕ سُہ روانہٕ تہٕ گٔیہٕ بیرشیبہ کِس بیابانس مَنٛز پھیران۔\n15.\\tتہٕ آب آو بوتلہِ منز تراونہٕ، تہٕ أمۍ ترٛٲو شُر أکِس کُنہِ ک\n16.\\tتہٕ سۅ گٔیہِ تہٕ بیوٹھ أمِس سٍتـ̡ سٍتـ̡ أکِس پٲٹھـ̡ دوٗر کُنـ̡ ، تکیازِ تٔمۍ ووٚن زِ بہٕ وُچھُن نہٕ شُرِ سُند مرُن۔ تہٕ سۅ بیوٹھ اتھ پیٹھ تہ آواز تھوٚد تہ رووُن۔\n17. تہٕ خداین بوز لڑکہٕ سٕنز آواز۔ تہٕ خدایہِ سٕندِ فرشتن بُلوو ہاجرس آسمانہٕ منزٕ تہٕ وونُن ہاجر، ہاجرَس کیا چُھہ گومُت؟ خوفہٕ نہٕ تکیازِ خداین چُھ لڑکہٕ سٕنز آواز بوزمٕژ ییتہِ سُہ {چُھ}۔\n18.\\tتھوٚد تھوٚد، لڑکہٕ تُلِتھ تھپھ کٔرِتھ۔ تکیازِ بہٕ بناوٕ تس اکھ عظیم قوم۔\n19.\\tتہٕ خداین کٔر امۍ سٕنزِ أچھ تہٕ وُچھ آبُک اکھ کیور۔ تہٕ سۄ گٔیہ، تہٕ بوتل بٔرِتھ آبہٕ تہٕ دِتُن لڑکہٕ چِنہٕ۔\n20. تہٕ خدا اوس لڑکہٕ سٍتـ̡ ۔ تہٕ سُہ گوٚو بٔڑِتھ، تہٕ بیابانن منٛز روزُن، تہٕ بنیوو تیر انداز۔\n21.\\tتہٕ سُہ اوس پران کِس بیابانس مَنٛز روزان: تہٕ أمۍ سٕنزِ ماجہِ نِش نِیہِ أمِس مصرٕچ سرزمینہٕ منزٕ خانٛدارِنہِ۔\n22.\\tتہٕ سپُد تمہِ وِزِ زِ ابیمیلک تہٕ تٔمۍ سٕندِس لشکرُک سردار فیچولن کٔر ابراہیمس سٍتـ̡ کتھ باتھ کٔرِتھ زِ خدا چُھہ تۅہہِ سٍتـ̡ یێلہِ تہٕ تُہٕندِس سارِنٕے سٍتـ̡ چُھہ تُہٕندِس سٍتـ̡ س�\n23. تێمہِ کِنۍ کٔرِو میہ خدایہِ سٍتـ̡ قسم، زِ ژٕ کٔرٕ نہٕ میانہِ سٍتـ̡ تہٕ میٲنِس نیچوِس سٍتـ̡ تہٕ میٲنِس نیچوِس سٍتـ̡ تہٕ میٲنِس نیچوِس سٍتـ̡ تہٕ یێلہِ سٍتـ̡ تہٕ یێلہِ سٍتـ̡ ژے سٍتـ̡ دِژمٕژ چھِ۔ {that thou...: Heb. اگر ژٕ مےٚ اپُز کٔرِو}\n24.\\tتہٕ ابراہیم ووٚن بہٕ کَرٕ قسم۔\n25.\\tتہٕ ابراہیم کٔر ابیمیلکس أکِس آبہٕ کِس کیورٕ سٍتـ̡ ملعت، یُس ابیمیلک سٕندیو خدمتگارو زور سان نِمُت اوس۔\n26.\\tتہٕ ابیمیلک ووٚن، میہ اوس نہٕ یہ کتھ کٔرمٕژ، نہ ژے ووٚنمُت تہٕ نہ وُنہِ تہِ بوزمُت، مگر از تہِ۔\n27.\\tتہٕ ابراہیم رٔٹۍ کۅکر تہٕ بیل تہٕ دیتُن ابیمیلکس نِش۔ تہٕ یِمو دۅشویو کوٚر اکھ معاہدٕ۔\n28.\\tتہٕ ابراہیمَن کٔر پانَے سَتھ دانٛدٕ کٔرِتھ۔\n29.\\tتہٕ ابیمیلکن ووٚن ابراہیمس زِ یِمن سَتھ دانٛدن ہُند کیا مطلب چُھہ یِم ژے پانہٕ رٔٹۍمٕتۍ؟\n30. تہٕ تٔمۍ ووٚن، یِمو سَتھ دانٛدٕ بچہٕ رٔٹِتھ ژے میانہِ اتھہٕ نِش رٔٹِتھ، یُتھ زن تِم میانہِ خٲطرٕ گواہ بنن، زِ مے چُھ یہِ کۄر کھننہٕ آمُت۔\n31.\\tامہ کنۍ وون تتھ جایہ بیرشیبا۔ تکیازِ تتہِ چھہِ یم دۅشوے قسم۔ {بیرشیبا: یعنی حلفُک کیور}\n32. یِتھٕ پٲٹھۍ کوٚر تِمو بیرشیباہس مَنٛز اکھ معاہدٕ: پتہٕ ووٚتھ ابیمیلک تہٕ پَنٕنِس لشکرُک چیف کپتان، تہٕ تِم گٔیہِ فلسطینن ہٕندِس ملکس منز واپس۔\n33.\\tتہٕ ابراہیم کٔر بیرشیبع مَنٛز اکھ باغ تہٕ تتہِ کوٚرُن خداوند سٕندِس ناوس سٍتـ̡ بُلاونہٕ۔ {گروو: یا، ٹری}\n34. تہٕ ابراہیم روٗد واریاہن دۅہن فلسطینن ہٕندِس سرزمینس مَنٛز روزان۔","1.\\tتہٕ یِمو پَتہٕ سپُد یہِ زِ خداین کٔر ابراہیمس آزماونہٕ تہٕ وونُن ابراہیم، تہٕ تٔمۍ ووٚن، وُچھو، {یتہِ} بہٕ چُھس۔ {وچھو...: ہیب۔ میہ وچھو}\n2.\\tتہٕ ووٚن، وۅنۍ نِو پنُن نیچو، پنُن کُنی نیچو اسحاق یُس ژے محبت کران چھُ، تہٕ ژٕ نِو موریاہ کِس سرزمینس مَنٛز۔ تہٕ أمِس کٔرِو تتہِ أکِس پہاڑس پیٹھ زالنہٕ خٲطرٕ پیش یُس بہٕ ژےٚ وَننہٕ دِیہِ۔\n3.\\tتہٕ ابراہیم ووٚتھ صُبحے ووٚتھ، تہٕ لوٚگ پنٕنۍ زٕ جوان تہٕ اسحاق پنُن نیچو پانس سٍتۍ، تہٕ ووٚتھ تہٕ ووٚتھ تتھ جایہِ یُس خداین أمس وونمُت اوس۔\n4.\\tتریمہِ دۅہہ تُل ابراہیم پنٕنۍ أچھ تُل، تہٕ وُچھن دوٗر جایہ۔\n5.\\tتہٕ ابراہیمَن ووٚن پننین نوجوانَن زِ یَتھ گَرِ سٍتـ̡ رٔٹِو۔ تہٕ بہٕ تہٕ لڑکہٕ گژھن اتہِ تہٕ عبادت کٔرِتھ، تہٕ دُبارٕ یِنہٕ ژےٚ نِش۔\n6.\\tتہٕ ابراہیم رٔٹ دزنہٕ نذرانہ ہٕنز لٔکر، تہٕ تھووُن پننِس نیچوِس اسحاق سٕندِس نیچوِس پیٹھ۔ تہٕ تٔمۍ روٚٹ نار پننس اتھس منٛز، تہٕ اکھ شراپ۔ تہٕ تِم گٔیہِ دۄشوے اکوٹہٕ۔\n7.\\tتہٕ اسحاق کٔر پننِس مٲلِس ابراہیمس سٍتـ̡ کتھ تہٕ وونُن، میون مول۔ تہٕ تٔمۍ ووٚن، نار تہٕ لٔکرِ وُچھو، مگر کتہِ چُھہ دزنہٕ خٲطرٕ کٹہٕ کُنہِ؟ {لیمب: یا، بچہ}\n8.\\tتہٕ ابراہیم ووٚن، میانہِ نیچو، خدا کرِ پانس دزنہٕ خٲطرٕ اکھ کٹہٕ داوُن، تہٕ یِمو گٔیہِ یِم دۅشوے اِکہٕ وٹہٕ۔\n9. تہٕ تِم وٲتۍ تتھ جایہِ یُس خداین أمِس وَننہٕ اوس آمُت۔ تہٕ ابراہیمَن بنوو اَتہِ اکھ قربان گاہ، تہٕ لٔکر تھووُن ترتیبہٕ پٲٹھۍ، تہٕ کوٚرُن پننِس نیچوِس اسحاق سٕندِس نیچوِس بٔنِتھ، تہٕ تھووُن لٔکرِ پیٹھ قربان گاہس پیٹھ۔\n10.\\tتہٕ ابراہیمَن پَنُن اَتھٕ تہٕ رٔٹِن پنُن نیچو مارنہٕ خٲطرٕ شراپ۔\n11. تہٕ خداوند سٕندِ فرشتن بُلووُن أمِس آسمانہٕ منزٕ بُلاونہٕ تہٕ وونُن، ابراہیم، ابراہیم، تہٕ تٔمۍ ووٚن، یێلہِ چُھہ بہ۔\n12.\\tتہٕ ووٚن، لٔڈِس پیٹھ تھاو نہٕ پنُن اتھہٕ تہٕ نہ کٔرِو أمِس کُنہِ تہِ، کیازِ وُنۍ چھُس میہ پتاہ زِ ژے چھُکھ نہٕ پنُن نیچو میانہِ نِش رُکٲومُت۔\n13.\\tتہٕ ابراہیم کٔر أچھ تُلِتھ تہٕ وُچھُن پَتہٕ کُنہِ\n14.\\tتہٕ ابراہیمَن ووٚن تَمہِ جایہِ ہُند ناو یہِ یہِ زِ از تہِ چُھ یہِ وُچھنہٕ یِوان۔ {یہوواہ جیرہ: یعنی، خداوند وُچھِ، یا فراہم کرِ}\n15. تہٕ خداوند سٕندِ فرشتن دِژ دوٚیمہِ لٹہِ اسمانس منزٕ ابراہیمس بُلاونہٕ،\n16.\\tتہٕ وونُن، میہ چُھہ پانس سٍتـ̡ قسم، خداوند چُھہ فرماوان، کیازِ ژے چُھہ یہ کٲم کٔرمٕژ، تہٕ چُھکھ نہٕ پنُن نیچو رُکٲومُت، یُس صرف نیچو چُھس:\n17.\\tیُس بہٕ برکتس سٍتـ̡ ژے برکت دِوان تہٕ ضرب دِنہٕ سٍتـ̡ بہٕ تُہند بیول آسمانٕکۍ ستارن ہٕندۍ پٲٹھۍ، تہٕ سمندرٕ بٹھِس پیٹھ {چُھ} سٍتـ̡ تہٕ تُہٕندِس بُلِس آسہِ تٔمۍ سٕندِس دُشمن ہُند دروازٕ۔ {ساحل: ہیب۔ لپ}\n18. تہٕ تُہندِس بُلِس مَنٛز گژھن زمینہٕ کِس سارِنٕے قومن بابرکت کرنہٕ۔ کیازِ ژے چھے میانہِ آوازِ ہٕنز اطاعت کٔرمٕژ۔\n19.\\tیِتھٕ ووت ابراہیم پننین جوانن نِش واپس، تہٕ تِمو ووٚتھ تہٕ گٔیہِ اِکہٕ وٹہٕ بیرشیبع کُن۔ تہٕ ابراہیم اوس بیرشیباہس منز روزان۔\n20.\\tتہٕ یِمو کتھٕ پَتہٕ سپُد یہِ زِ ابراہیمس وونُن زِ وُچھِو ملکہ، تٔمِس تہِ چھِ تُہندِس بٲیِس ناہورس بچہٕ زامٕتۍ۔\n21.\\tہُز تٔمۍ سُند گۄڈنیُک زامُت، تہٕ بوز تٔمۍ سُند بوے تہٕ کریم سُند مول،\n22. تہٕ چیسد، تہٕ ہازو، تہٕ پِلداش، تہٕ جِدلاپ، تہٕ بیتھوئیل۔\n23.\\tتہٕ بیتھوایلن زاے ربیکاہ: یِمو ٲٹھ ملکہ دِژ ابراہیم سٕندِس بٲیِس ناہورس سٍتـ̡ ۔ {ربیکا: Gr. Rebecca}\n24.\\tتہٕ تٔمۍ سٕنز لونڈی، یٔمۍ سُند ناو ریومہ اوس، سۅ تہِ ٲس تیبہ، تہٕ گہام، تہٕ تھاش تہٕ ماچہ۔","1. تہٕ سارہ ٲس ہتھ ستھ وُہُر وُہُر: {یِم ٲسۍ سارہ سٕنزِ زندگی ہٕندِ ؤری۔\n2.\\tتہٕ سارہ گٔیہِ کرجتھربہ مَنٛز۔ یۅہے چُھ کنعان کِس سرزمینس مَنٛز: تہٕ ابراہیم آو سارہ سٕندِ خٲطرٕ ماتم کرنہٕ تہٕ تٔمِس خٲطرٕ روُن۔\n3. تہٕ ابراہیم ووٚتھ پنہٕ نِس مرنہٕ برونہہ کُن، تہٕ وونُن ہیث سٕندِس نیٚچوِس سٍتـ̡ کتھ کرنہٕ،\n4.\\tبہٕ چُھس ژے سٍتۍ اکھ اجنبی تہٕ روزُن وول: مے دِژ ژے سٍتـ̡ دفن کرنٕچ جاۓ، یُتھ بہٕ پنُن مُردٕ پننہِ نظرِ نِش دفن کٔرِتھ۔\n5. تہٕ ہیث سٕندیو اولادو دیُت ابراہیمس جواب دِتھ وونُن،\n6. بوزو اسہِ آقا: ژٕ چُھکھ اسہِ مَنٛز اکھ طاقتور شہزادہٕ: سانین قبرن ہٕندِس انتخابس مَنٛز کٔرِو پنُن مُردٕ دفن؛ اسہِ منزٕ ہیوٚک نہٕ کانہہ تہِ تٔمۍ سُند قبر ژے نِش رُکٲوِتھ، مگر ژٕ کٔرِو پنُن مُردٕ دفن۔ {اکھ طاقتور...: ہیب۔ خدایہ سُند شہزادہ}\n7. تہٕ ابراہیم ووٚتھ تہٕ کٔرٕن زمینہٕ کِس لُکن برونہہ کُن، حتیٰ کہ ہیث کین بچن برونہہ کُن۔\n8.\\tتہٕ تٔمۍ کٔر تِمن سٍتـ̡ کتھ باتھ تہٕ وونُن، یێلہِ تُہُند ذہن چُھہ زِ بہٕ پَنُن مُردٕ پننہِ نظرِ نِش دفن کرُن۔ بوزو تہٕ میانہِ خٲطرٕ کٔرِو زوہار سٕندِس نیچوِس افرون سٕندِس خٲطرٕ التجا\n9.\\tیُتھ سُہ دِیہِ مے مَخپیلہ ہٕنز گۄپھ، یُس أمِس نِش چھُ، یُس تٔمۍ سٕندِس کھہٕ کِس اندس مَنٛز چھُ۔ یوتاہ پونسہٕ قٲمِل چھُ، سُہ دِیہ مے ژےٚ درمیان دفن کرنٕچ جاے حٲصِل کرنہٕ خٲطرٕ۔ {یوتاہ زیادہ...: ہیب۔ پوٗرٕ پٲنسہٕ}\n10.\\tتہٕ افرون اوس ہیث کین بچن مَنٛز روزان: تہٕ افرون دی ہِتِین دِیُت ابراہیم سُند جواب یُس تٔمۍ سٕندِس شہر کِس دروازس پیٹھ اژان اوس، {سامعین: حب۔ کَن}\n11. نہ، میانہِ آقا، بوزو: کھیت چُھس ژے دِوان، تہٕ غار یُس اتھ منز چُھ، بہٕ چُھس ژے دِوان۔ میانین لوکن ہٕندِس نیچوَن ہٕنزِ موجودگی منز دِیُن بہٕ ژے: پنُن مُردٕ دفن۔\n12.\\tتہٕ ابراہیم کٔر زمینہٕ کین لوکن برونہہ کُن سجد۔\n13.\\tتہٕ تٔمۍ ووٚن افرونس سٍتـ̡ زمینہٕ کین لوکن ہٕندِس سامنس مَنٛز وونُن، مگر یێلہِ تہٕ ژے دِیُو، بہٕ دِیہٕ ژے کھہٕ خٲطرٕ پٲنسہٕ۔ میہ نِش نِن، تہٕ بہٕ کٔرٕ پنُن مُردٕ تتہِ دفن۔\n14. تہٕ افرون دیُت ابراہیمس جواب دِتھ وونُن،\n15.\\tمیانہِ مالک، بوز میانہِ کتھہِ: زمین چھیہ ژور ہتھ شیکل رۄپہٕ برابر۔ میہ تہٕ تۅہہِ درمیان کیا چُھ؟ تَمہِ مۄکھٕ کٔرِو پنُن مُردٕ دفن۔\n16.\\tتہٕ ابراہیم کٔر افرون سٕنز بوز۔ تہٕ ابراہیم کٔر افرونس سٍتـ̡ رۄپہٕ وزن، یُس تٔمۍ حیت کین نیچوین ہٕندِس سامعینن منز ناو اوس دِژمُت، ژور ہتھ شیکل رۄپہٕ، سوداگرس سٍتـ̡ موجودٕ {پٲنسہٕ}۔\n17.\\tتہٕ ایفرون سُند کھہ، یُس {اوس} مٔمرے برونہہ کُن، کھیت تہٕ غار یُس اتھ منز {اوس}، تہٕ تِم سٲری کُلۍ یِم کھاہس منز ٲسۍ، یِم اندۍ پٔکۍ سارِنٕے سرحدن منز ٲسۍ، یِم {ٲس}\n18.\\tابراہیمس نِش یُس تٔمۍ سٕندِس شہر کِس دروازس پیٹھ اژنہٕ برونہہ ہیث کین بچن ہٕندِس حضورس منز قبضہ کرنہٕ خٲطرٕ۔\n19.\\tامہ پتہ کٔر ابراہیم پننہ زنانہِ سارہ ممرس برونہہ کُن مکھپلہ کِس کھہس منز دفن: یۅہے چھہ کنعان کِس سرزمینس مَنٛز۔\n20.\\tتہٕ کھیت تہٕ غار یُس اتھ منز چھُ، ابراہیمس دِنہٕ خٲطرٕ یُس ہیث کین نیچوین دفن کرنٕچ جاے حٲصل کرنہٕ خٲطرٕ یقینی بناونہٕ آو۔","1. تہٕ ابراہیم اوس بُزرگ تہٕ وٲنسہِ سٍتـ̡ مُتٲثِر گومُت، تہٕ خداوند اوس ابراہیم سٕندِس سارِنٕے چیزن مَنٛز برکت دِژمٕژ۔ {اچھا...: ہیب۔ دۅہن منز گٔیہِ}\n2. تہٕ ابراہیمَن ووٚن پننِس گرٕ کِس سارِوٕے کھۄتہٕ زِٹھِس خادمَس یُس أمِس سارِنٕے چیزس پیٹھ حُکوٗمت اوس کٔرِتھ، بہٕ چُھس ژےٚ دُعا کٔرِتھ پنُن اَتھٕ میٲنِس رانس تَل تھاوُن:\n3. تہٕ بہٕ کَرٕ ژے خدا، آسمانُک خدا، تہٕ زمینہٕ کِس خداہٕ سٕندِ سٍتـ̡ قسم، زِ ژٕ کٔرٕ نہٕ کنعانین ہٕنزِ کورِ ہٕندِس میٲنِس نیچوِس سٍتـ̡ خانٛدارِنۍ ، یِمن مَنٛز بہٕ روزان چُھس:\n4. مگر ژے گژھ میٲنس ملکس منز، تہٕ میٲنس رشتہ دارس نِش تہٕ میٲنس نیچوِس اسحاق سٕنز زنانہٕ نِنۍ۔\n5.\\tتہٕ خادمَن ووٚن أمِس زِ شاید زنانہٕ آسہِ نہٕ میانہِ پتہٕ یتھ سرزمینس تام یِنہٕ خٲطرٕ تیار، کیا بہٕ پزِ تُہند نیچو دُبارٕ تتھ سرزمینس منز انُن ییتہِ ژٕ آو؟\n6. تہٕ ابراہیم ووٚن أمِس خبردار زِ ژٕ گژھ نہٕ میون نیچو دُبارٕ اَننہٕ۔\n7.\\tآسمانُک خداوند خدا، یُس میہ پننِس مٲلہِ سٕندِ گرٕ نِش تہٕ میانین رشتہٕ دارن ہٕنزِ زمینہٕ پیٹھٕ نِیومُت تہٕ یُس میہ سٍتـ̡ کتھ کٔرِتھ تہٕ یُس میہ سٍتـ̡ قسم، تہٕ یُس میہ سٍتـ̡ دِنہٕ آمُت چُھ، تہٕ یُس میہ سٍتـ̡ دِنہٕ آمُت چُھ، تہٕ یُس میہ سٍتـ̡ دِنہٕ آمُت چُھ، تہٕ یُس میہ سٍتـ سُہ سوزِ پنُن فرشتہ ژے برونہہ کُن، تہٕ تتہِ نِیہِ میٲنِس نیچوِس نِش زنانہٕ۔\n8.\\tتہٕ اگر زنانہٕ تۅہہِ سٍتـ̡ پَکناونہٕ خٲطرٕ تیار آسہِ، تیلہِ گژھہِ ژے میانہِ قسمہٕ نِش صاف گژھُن: صرف گژھ نہٕ میون نیچو دُبارٕ تتہِ أنِتھ۔\n9.\\tتہٕ نوکرَن تھووُن پنُن اَتھٕ ابراہیم سٕندِس رانس تَل تہٕ کٔرٕن أمِس سٍتـ̡ اَتھ معاملس مُتلق قسم۔\n10.\\tتہٕ نوکر رٔٹۍ پننِس آقا سٕندِ اونٹَن ہٕندِ داہ ووُنٹھ تہٕ درٛاوُن۔ تکیازِ تٔمۍ سٕندِس آقا سُند سٲری مال اوس تٔمۍ سٕندِس اتھس منز، تہٕ سُہ ووٚتھ، تہٕ گوٚو میسوپوٹیمیا کُن، ناہور شہرس کُن۔ {for: or, and}\n11.\\tتہٕ تٔمۍ بنوو پننین اونٹن شامس آبہٕ کِس کۅرٕ سٍتـ̡ شہرس نِش کۅٹھہٕ بٔنِتھ، {حتیٰ کہ} تمہِ ساتہٕ ییلہ زنانہٕ {آب} کڈنہٕ خٲطرٕ نیران آسہٕ۔ {یہ...: ہیب۔ سُہ زَنان یِم آب کھینَن واجنہِ زنانہٕ نیران چھِ}\n12.\\tتہٕ وۆنُن اے خدایہ میانہِ آقا ابراہیم سٕندِس خدایہ، بہٕ چُھس ژے دُعا کران زِ اَمہ دۅہہٕ کٔرِن میہ رُکُن تہٕ کٔرِن میٲنِس آقا ابراہیمس سٍتـ̡ رحمت۔\n13. وچھ بہٕ چُھس {یتہِ} آبہٕ کِس کۅرٕ نِش کھڑا ۔ تہٕ شہرٕکۍ مردَن ہٕنٛزِ کورِ چھِ آب تُلنہٕ خٲطرٕ نیران:\n14. تہٕ یێمہِ کُنہ تہٕ سُہ وَنُن، چیٚو، تہٕ بہٕ دِیہٕ چانہِ اونٹَن تہِ چیٚنہٕ: {سُہ گژھُن} سُہ {یُس} ژے پننِس خادم اسحاق سٕندِ خٲطرٕ مقرر کورمُت۔ تہٕ اَمہ سٍتۍ گژھہِ میہ پتاہ زِ ژے چھے میٲنس آقا سٍتۍ مہربانی کٔرمٕژ۔\n15.\\tتہٕ سپُد أمِس کتھ کرنہٕ برونہہ زِ ربیکا دراو نیبر، یُس نہور سٕنزِ زنانہٕ مِلکہ سٕندِس نیچوِس بیتھوایلس زامُت اوس، یُس ابراہیم سٕندِس بٲے سٕنزِ زنانہٕ ٲس، تہٕ تٔمۍ سٕندِس پھیکس پیٹھ پنُن گھڑٕ لٲگِتھ اوس۔\n16.\\tتہٕ لڑکی ٲس سٮ۪ٹھاہ خوبصورت، اکھ کنواری، تہٕ نہ ٲس کٲنسہ تہِ أمِس زانان: تہٕ سۄ گٔیہِ کۅرَس کُن، تہٕ لٔگِن پنُن گھڑٕ بٔرِتھ تہٕ آیہِ تھوٚد۔ {سٮ۪ٹھاہ...: ہیب۔ گُڈ آف بُتھ}\n17.\\tتہٕ نوکر ژوٚل أمِس سمکھنہٕ خٲطرٕ، تہٕ وونُن، بہٕ چُھس ژےٚ دُعا کٔرِتھ پننہِ گھڑِ ہُند رژھ رژھ آب پینہٕ۔\n18.\\tتہٕ تٔمۍ ووٚن، چیٚو، میانہِ آقا، تہٕ تٔمۍ دِژ جلدی تہٕ ترووُن پنُن گھڑٕ پننِس اتھس پیٹھ، تہٕ دِتُن أمِس چِنہٕ۔\n19.\\tتہٕ ییلہ أمس چِنہٕ دِنہٕ آو، تٔمۍ ووٚن، بہٕ کٔرٕ چانہِ اونٹٮ۪ن خٲطرٕ تہِ آب دِنہٕ، یوٚت تام تِم چیٚنہٕ نِن۔\n20.\\tتہٕ سۅ ژٔلِتھ تہٕ دِژٕن پنُن گھڑٕ گرِ منز خٲلی، تہٕ دٔژٕن بییہ کُورِ کُن آب کڈنہٕ خٲطرٕ، تہٕ لٔگِن پننین سارِنٕے اونٹَن ہٕندِس خٲطرٕ۔\n21.\\tتہٕ أمِس وُچھِتھ یُس شخٕص اوسُس تٔمِس سٍتـ̡ س�\n22.\\tتہٕ یہ سپد یُتھ زن اونٹَو چیٚوان اوس، تٔمۍ نِش نٮ۪صف شیکل وزنُک سۄنہٕ بالہٕ تہٕ تٔمۍ سٕندِس اَتھن خٲطرٕ دَہ {شیکل} وزنُک زٕ کٔرۍ۔ {بالہ: یا، ڈٮ۪کہٕ خٲطرٕ جوہر}\n23.\\tتہٕ وونُن، کُس کُس کورِ چھُ؟ میہ وَن، بہٕ چُھس ژے دُعا کران: کیا چانہِ مٲلہِ سٕندِس مکانس منز چھا اسہِ روزنہٕ خٲطرٕ گنجایش؟\n24.\\tتہٕ تٔمۍ ووٚن أمِس زِ بہٕ چھُس ملکہ سٕندِس نیچوِس بیت وئیل سٕنز کوٗر ، یُس أمِس ناہورس نِش دِنہٕ آمُت۔\n25.\\tتٔمۍ ووٚن أمِس مزید زِ اسہِ چھِ دۅشوے گاسہ تہٕ پروونڈر تہٕ روزنہٕ خٲطرٕ گنجایش۔\n26.\\tتہٕ نَفر کٔر کلہٕ نوٚمُت، تہٕ کٔرٕن خداوند سٕنز پوٗزا۔\n27.\\tتہٕ وۆنُن، مُبارکَت چھُ میانہِ آقا ابراہیم سُند خدا، یُس نہٕ میٲنِس آقا سٕندِس رحمتہٕ تہٕ سچٲیِس سٍتـ̡ بے بس ترووُن: بہٕ چُھس وتہِ منز، خداوند دِژ میہ پننِس آقا سٕندِس بٲے سٕندِس گرس کُن۔\n28.\\tتہٕ لڑکی ژٔلِتھ تہٕ وونُن پننہِ ماجہ ہٕندِس گرس متعلق۔\n29.\\tتہٕ ربیکا اوس اکھ بوے تہٕ تٔمۍ سُند ناو اوس لبان، تہٕ لابن ژوٚل أمِس مردس کُن، کُنہِ کُنہِ کُن۔\n30.\\tتہ سپد تمہِ ساعتہ ییلہ تمۍ پننہِ بینہِ ہندس اتھس پیٹھ بالہِ تہ کنگن وُچھ، تہ ییلہ تمۍ پننہِ بینہِ ربیقہ سٕنز کتھ بوز، یتھے پاٹھۍ وۆن میہ سٍتۍ۔ زِ سُہ آو أمِس شخصس نِش۔ تہٕ وُچھ اوس سُہ اونٹَن نِش کُنہِ ک\n31.\\tتہٕ ووٚن اژُن، اے خداوند سٕندِ سٍتـ̡ بابرکت ۔ ژیہ کیازِ چھکھ نیبر کھڑا؟ تکیازِ مے چُھ اونٹٮ۪ن ہٕندِ خٲطرٕ مکانہٕ تہٕ جاے تیار کٔرمٕژ۔\n32.\\tتہٕ مرد آو گرس منز، تہٕ تٔمۍ دِژن پننین اونٹٮ۪ن ہٕندِ خٲطرٕ گاسہ تہٕ اونٹَن ہٕندِ خٲطرٕ گاسہٕ تہٕ کھۅر چھلنہٕ خٲطرٕ آب تہٕ یِم أمِس سٍتـ̡ ٲسۍ۔\n33.\\tتہٕ أمِس برونہہ کنہِ اوس کھٮ۪نہٕ خٲطرٕ {ماز} تھاونہٕ آمُت، مگر تٔمۍ ووٚن، بہٕ چُھس نہٕ کھٮ۪وان، یوٚت تام نہٕ بہٕ پنُن کامہٕ وَننہٕ ییہِ۔ تہٕ تٔمۍ ووٚن، کتھ کرو۔\n34.\\tتہٕ ووٚن بہٕ چھُس ابراہیم سُند خادم۔\n35. تہٕ خداوند کٔر میٲنِس آقا سٕندِس سٮ۪ٹھاہ برکت۔ تہٕ سُہ چُھ عظیم گومُت: تہٕ تٔمۍ دِژ أمِس ریوڑ، تہٕ رۄپھ، تہٕ سۄن، تہٕ نوکر، تہٕ نوکر، تہٕ اونٹ تہٕ گَرٕ دِنہٕ۔\n36.\\tتہٕ سارہ میانہِ آقا سٕنزِ زنانہِ زاے میٲنِس آقا سٕندِس نیچو ییلہ سُہ بُزرگ اوس، تہٕ أمِس دِژ سُہ سورُے یُس أمِس دِیُت۔\n37.\\tتہٕ میانہِ مالہِ کٔر میہ قسم، تہٕ وونُن زِ ژے گژھ نہٕ کنعانی کورِ ہٕندِس نیچوِس سٍتـ̡ خانٛدارِنۍ نِن، یٔمِس زمینس مَنٛز بہٕ روزان چھُس:\n38.\\tمگر ژے گژھ میٲنس مٲلہِ سٕندِس گرس منز، تہٕ میٲنس رشتہ دارس نِش تہٕ میٲنس نیچوِس نِش زنانہٕ نِنہٕ۔\n39.\\tتہٕ میہ ووٚن پننِس آقاہس زِ زنانہٕ کرِ نہٕ میانہِ پتہٕ۔\n40. تہٕ تٔمۍ ووٚن مےٚ زِ خداوند یٔمِس برونہہ کُن بہٕ پکان چھُس، سُہ سوزِ پنُن فرشتہٕ تہٕ تُہٕندِس وتہِ سٍتـ̡ ترقی۔ تہٕ ژٕ رٔٹِتھ میانہِ رشتہٕ دارس تہٕ میٲنس مٲلہِ سٕندِس گرس سٍتـ̡ میانہِ نیچوِس خٲطرٕ خانٛدارِن:\n41.\\tتیلہِ گژھہِ میانہِ قسمہ نشہِ صاف گژھُن، ییلہ تہۍ میانین رشتہ دارن نش یِن۔ تہٕ اگر نہٕ تِم دِیہِ تۅہہِ دِنہٕ، تیٚلہِ گژھہِ میانہِ قسمہٕ نِش صاف روزُن۔\n42. تہٕ بہٕ ووت اَمہ دۅہہ کُورِ کُن، تہٕ وونُن، اے خدایہ میانہِ آقا ابراہیم، اگر وۅنۍ ژے میانہِ وتہِ سٍتـ̡ کامیاب سپدِ، یُس بہٕ پکان چُھس:\n43.\\tوُچھ، بہٕ چُھس آبہٕ کِس کۅرَس نِش کھڑا ۔ تہٕ یہ گژھہِ سپدِ، ییلہ کنواری نیرِ {آب} کھیننہِ، تہٕ بہٕ چُھس أمِس ونان، بہٕ دِیُس ژے دِیُن، چانہِ گھڑِ ہُند اکھ رژھ آب چنہٕ خٲطرٕ۔\n44.\\tتہٕ سُہ چُھس مے ونان زِ دۅشوے چُھہ چُھہ تہٕ بہٕ تہٕ چُھس چانہِ اونٹن ہٕندِ خٲطرٕ تہِ کھینُن: سۅے زنانہٕ یۅسہٕ خداوند میانہِ آقا سٕندِس نیچوِس خٲطرٕ مقرر کٔرمٕژ چھےٚ۔\n45. تہٕ امہ برونہہ زِ میہ دِلس منز کتھ کرنہٕ، وُچھ ربیکا پننِس پھیکس پیٹھ پنُن گھڑٕ ہیتھ برونہہ کُن۔ تہٕ سۅ گٔیہِ کۅرِ کُنہ\n46.\\tتہٕ تٔمۍ کٔر جلدی تہٕ ترووُن پنُن گھڑٕ پننِس پھیکس پیٹھ، تہٕ وونُن، چیٚوُن، تہٕ بہٕ دِیہ چانہِ اونٹن تہِ چیٚنہٕ۔\n47.\\tتہٕ میہ پرژھ أمِس تہٕ وونُن، کٔمۍ سٕنز کورِ چھےٚ؟ تہٕ تٔمۍ ووٚن، ناہور سٕندِس نیچوِس بیتھویل سٕنز کور، یُس ملکہ أمِس زیٚوُن اوس، تہٕ مے تھووُن أمِس بُتھِس پیٹھ بالہٕ تہٕ کٔرٕن تٔمۍ سٕندِس اتھس پیٹھ۔\n48. تہٕ بہٕ کٔر کلہٕ نوٚمُت، تہٕ کٔرٕن خداوند سٕنز عبادت تہٕ کٔرٕن پننِس آقا ابراہیم سٕندِس خداہس برکت ، یٔمۍ مےٚ پننِس آقا سٕندِس بٲے سٕنزِ کورِ تٔمۍ سٕندِس نیچوِس نِش نِنہٕ خٲطرٕ صحیح وتہٕ وتہٕ واتنوو۔\n49.\\tتہٕ وۅنۍ اگر ژیہ میٲنس آقاس سٍتۍ مہربانی تہٕ پٔزۍ پٲٹھۍ سلوک کرِ، مے ونُن: تہٕ اگر نہٕ تیلہِ وَنُن۔ تاکہ بہٕ ہیکہٕ دٔچھنِس اتھس کُن پھیرِتھ، یا کھوورِ کُن۔\n50. اَمہِ پَتہٕ دِژ لابان تہٕ بِتھویلَن جواب تہٕ وونُن، یہِ چیز چُھ خداوند سٕندِ طرفہٕ نیران: أسۍ ہیکو نہٕ تۅہہِ سٍتـ̡ بُرٕ تہٕ نیکی کتھ کٔرِتھ۔\n51.\\tوُچھ، ربیکا {چُھ} ژے برونہہ کُن، رٔٹِتھ تہٕ گژھ تہٕ سُہ گژھہِ پننِس آقا سٕندِس نیچوِس سٕنز زنانہٕ، یِتھ کٔنۍ خداوند چُھ کَرنہٕ آمُت۔\n52.\\tتہٕ سپُد یہِ زِ ییلہ ابراہیم سٕندِس خادمَن تِہٕندِس کلامَس بوٗزِ، تٔمۍ کٔر خداوند سٕنز پوٗزا تہٕ کٔرٕن زمینہِ برونہہ کُن سجدٕ۔\n53.\\tتہٕ نوکرَن أنۍ رۄپہٕ سٕندِ جوٲہر تہٕ سۄنہٕ تہٕ پلو تہٕ دِتُن ربیکاہَس تہٕ دِتُن پننِس بٲیِس تہٕ ماجہِ تہِ قیمتی چیز۔ {جواہرات: ہیب۔ جہاز}\n54.\\tتہٕ تِمو کٔر کھٮ۪وان تہٕ چیٚو، سُہ تہٕ یِم نفر أمِس سٍتـ̡ ٲسۍ، تہٕ روٗدۍ سارِوٕے راتس روٗد۔ تہٕ تِم ووٚتھ صبحٲے تہٕ تٔمۍ ووٚن، مے سوز میٲنِس مٲلکَس نِش۔\n55.\\tتہٕ أمۍ سٕندِس بٲے تہٕ ماجہِ ووٚن زِ لڑکی روزِ اسہِ سٍتـ̡ کم از کم دَہہِ دۅہہٕ۔ تمہ پتہ گژھہِ سۅ نیرِ۔ {کینہہ ...: یا، پورٕ ؤری، یا دہہ ریتھ}\n56. تہٕ تٔمۍ ووٚن تِمَن زِ خداوند چُھ میانہِ وتہِ سٍتـ̡ رُکاوٹ کٔرمٕژ۔ میہ سوز میہ پننِس آقاس نِش گژھُن۔\n57.\\tتہٕ تِمو ووٚن، أسۍ کرو لڑکی بُلاونہٕ تہٕ تٔمۍ سٕندِس ٲسس پرژھہٕ۔\n58.\\tتہٕ تِمو بُلوو ربیکا تہٕ وونُن أمِس سٍتـ̡ یێمِس شخصس سٍتـ̡ نیرُن؟ تہٕ تٔمۍ ووٚن، بہٕ نیرٕ بہٕ۔\n59.\\tتہٕ تِمو سوٗزۍ ربیقاہ، پنٕنۍ بینہِ، تہٕ تٔمۍ سٕنز نٔر، تہٕ ابراہیم سٕنز نوکر تہٕ تٔمۍ سٕندِس نفر۔\n60. تہٕ تِمو کٔر ربیکا سٕنز برکت تہٕ وونُن تٔمِس زِ ژٕ چھے سٲنۍ بینہٕ، تہٕ ژٕ بٔنِتھ بٔنِتھ تِمن سٍتـ̡ نفرت۔\n61.\\tتہٕ ربیکا تہٕ تٔمۍ سٕنزِ کورِ ووٚتھ، تہٕ تِم گٔیہِ اونٹَن پیٹھ سوار تہٕ لٔگۍ أمِس مردس پَتہٕ۔ تہٕ نوکرَن رٔٹ ربیکا تہٕ گٔیہِ أمِس وتہِ۔\n62.\\tتہٕ اسحاق آو کُنہِ کُنہِ وتہِ پیٹھ۔ تکیازِ سُہ اوس جنوبی ملکس منز روزان۔\n63.\\tتہٕ اسحاق دراو شامس کھاہس منز مراقبہ کرنہِ نیبر، تہٕ تٔمۍ کٔر أچھ تُلِتھ تہٕ وُچھن ووُنٹھ یِوان۔ {مراقبہ کرُن: یا، دعا کرُن}\n64.\\tتہٕ ربیقاہن کٔر أچھ تُل، تہٕ ییلہ أمس اسحاق وُچھ، تٔمۍ کٔر اونٹُن گاش۔\n65.\\tتکیازِ تٔمۍ اوس خادمس ووٚنمُت، یہِ کُس انسان چُھ یُس اسہِ سمکھنہٕ خٲطرٕ کھاہس منز پکان چُھ؟ تہٕ خادمَن ووٚن، یہِ چھُ میون آقا، لہذا تٔمۍ رٔٹ اکھ پردٕ، تہٕ کوٚرُن پان ؤلِتھ۔\n66.\\tتہٕ نوکرَن ووٚن اسحاق سٕندِس سارِنٕے چیٖز یِم تٔمۍ کٔرۍمٕتۍ۔\n67.\\tتہٕ اسحاق اوٚن سۅ پننہِ ماجہ سارہ سٕندِس خیمس مَنٛز، تہٕ ربیکا رٔٹِتھ تہٕ سۅ بنییہِ تسٕنزِ زنانہٕ۔ تہٕ سُہ اوس أمس محبت کران: تہٕ اسحاق اوس پنٛنہ ماجہٕ ہٕنٛدِ {مرنہٕ} پتہٕ تسلی دِوان۔","1.\\tبییہِ کٔر ابراہیمس زنانہِ تہ تسند ناو اوس کتوراہ۔\n2.\\tتہٕ أمِس زِمران، جوکشَن، مدان، مدیان، تہٕ اشبک تہٕ شواہ۔\n3.\\tتہٕ جوکشنن دیت شیبا تہٕ دیدان۔ تہٕ دیدانٕکۍ نیچوۍ ٲسۍ اشوریم تہٕ لیٹوشیم تہٕ لیومیم۔\n4. تہٕ مدیانٕکۍ نیٚچوۍ۔ ایفاہ، تہٕ ایفر، تہٕ حنوخ، تہٕ عابدہ، تہٕ ایلداہ۔ یم سٲری ٲسۍ کیٹورہ سٕندۍ شُرۍ۔\n5.\\tتہٕ ابراہیم دِژ سُہ سورُے یُس أمِس نِش اوس۔\n6.\\tمگر یِمن لونڈین ہٕندِس نیچوِس یُس ابراہیمس اوس دِژمُت، ابراہیمن دِژ تحفہٕ، تہٕ سوٗزُن تِم اسحاق سٕندِس نیچوِس نِش، ییلہ سُہ مشرقس کُن مشرقس کُن روزان اوس۔\n7.\\tتہٕ یِم چھِ ابراہیم سٕنزِ زندگی ہٕندِ ؤرین ہٕندِ دۅہہٕ یِم تٔمِس ہتھ تریہ تہٕ پندہ ؤری زندٕ۔\n8. اَمہِ پَتہٕ تروو ابراہیمَن بھوت، تہٕ موٗد أکِس بُزرگ وٲنسہِ منز، بُزرگ تہٕ پوٗرٕ وٲنسہِ۔ تہٕ آو پننین لوکن خٲطرٕ جمع کرنہٕ۔\n9.\\tتہٕ تٔمۍ سٕندٮ۪و نیچویو اسحاق تہٕ اسماعیلَن دفن کٔر سُہ مکھپلہ کِس گۅپھِ مَنٛز، یُس زہار ہِٹی سٕندِس نیچوِس افرون سٕندِس کھاہس مَنٛز دفن چھُ، یُس مَمرے برونہہ کُن چھُ۔\n10.\\tسُہ کھیت یُس ابراہیمَن ہیث سٕندِس نیچوِس نِش ہیوٚت: اَتہِ اوس ابراہیم دفن کرنہٕ آمُت، تہٕ سارہ تٔمۍ سٕنز زنانہٕ۔\n11. تہٕ ابراہیم سٕندِ مرنہٕ پَتہٕ سپُد خداین پننِس نیچوِس اسحاق سٕندِس برکت۔ تہٕ اسحاق اوس کُنہِ\n12.\\tوۅنۍ چھہِ یِم اسماعیل سٕندِ نیچو، یُس سارہ سٕنزِ دٲیرِ ہاجرہ سٕندِس نیچوس سٍتـ̡ ابراہیمس سٍتـ̡ دِژمُت اوس۔\n13.\\tتہٕ یِم چھِ اسماعیل سٕندٮ۪ن نیچوین ہٕندِ ناوٕ سٍتـ̡ تہندِ نسلہٕ مُطٲبق: اسماعیل سُند گۄڈنیُک زامُت، نباجوت۔ تہٕ کیدار، تہٕ عدبیل، تہٕ مِبسام،\n14. تہٕ مشما، تہٕ دومہ تہٕ مسا،\n15.\\tحدار، تہٕ تیما، جیتور، نپھش تہٕ کدیمہ: {حضر: یا، حداد}\n16.\\tیِم چھِ اسماعیل سٕندِ نیچوۍ، تہٕ یِم چھِ تِہُند ناو، تہٕ تِہٕندِس قصبہٕ سٍتـ̡ تہٕ تِہٕندِس قلعس سٍتـ̡ ۔ باہ شہزادٕ تہندِ قومن مطٲبق۔\n17.\\tتہٕ یِم چھِ اسماعیل سٕنزِ زندگی ہٕندِ ؤری، ہتھ ترٕہ سَتھ ؤری: تہٕ تٔمۍ تروو بھوت تہٕ موٗد۔ تہٕ آو پننین لوکن نش جمع کرنہٕ۔\n18.\\tتہٕ تِم رودۍ حویلہ پؠٹھٕ شورس تام، یعنی مصرس برونہہ کُن، یێلہِ تہٕ تُہۍ أسریاہس کُن گٔژھِو، {تہٕ} سُہ موٗد پننین سارِنٕے باین ہٕندِس حضورس منز۔ {وفات: ہیب۔ گٔیہِ}\n19.\\tتہٕ یِم چھِ اسحاق سٕنزِ نسلہٕ یُس ابراہیم سُند نیچو اوس: ابراہیم سُند پیدائش:\n20.\\tتہٕ اسحاق اوس ژتٲجی وُہُر ییلہ تٔمۍ ربیکا سٕنزِ خانٛدارِنۍ نِیو، یۄسہٕ پڈانارمٕچ شامی بینہِ بیتھوئیل سٕنز کورِ ٲس۔\n21. تہٕ اسحاق کٔر خداوند سٕنزِ زنانہِ خٲطرٕ التجا کرنہٕ، تکیازِ سۅ ٲس بانجھ تہٕ خداوند کٔر أمِس سٍتـ̡ رحم تہٕ ربیکا گٔیہِ حاملہٕ۔\n22. تہٕ شُرۍ ٲسۍ أمِس اندر اِکہٕ وٹہٕ جدوجہد کران۔ تہٕ تٔمۍ ووٚن، اگر {یہ} چُھ، تیلہٕ کیازِ چُھس بہٕ یتھ؟ تہٕ سۄ گٔیہِ رب سٕندِس پرژھہٕ گٲر کرنہِ۔\n23.\\tتہٕ خداوند ووٚن أمِس زٕ قوتہٕ چُھہ تۅہہِ ہٕندِس رحمس مَنٛز، تہٕ زٕ قٕسمٕکۍ لُکھ یِن تۅہہِ ہٕندِس دٔرِس نِش الگ کرنہٕ۔ تہٕ {اکھ} لوٗکھ گژھن {باقی} لُکن کھوتہٕ زیادٕ مضبوط۔ تہٕ بٔڈۍ کرِ لۄکٹِس سٕنز خدمت۔\n24. تہٕ ییلہ تٔمۍ سٕندِ زیٚنہٕ خٲطرٕ دۅہ پوٗرٕ گٔیہ، وُچھِو تٔمۍ سٕندِس رحمس مَنٛز دُکہٕ زامٕتۍ۔\n25.\\tتہٕ گۅڈنیُک دراو وۄزل، سٲرۍسٕے مَس دار پوشہٕ ہٕندۍ پٲٹھۍ۔ تہٕ تِمو اوس تٔمۍ سُند ناو عیسو۔\n26.\\tتہٕ امہِ پتہٕ دراو تٔمۍ سُند بوے تہٕ تٔمۍ سُند اَتھٕ روٚٹ عیسو سٕنزِ کھورِ پیٹھ۔ تہٕ تٔمۍ سُند ناو اوس یعقوب وننہٕ آمُت: تہٕ اسحاق اوس تریہ وُہُر ییلہ تٔمۍ تِم نِش بٔرۍ۔\n27. تہٕ لٔڑکہٕ گٔیہِ بٔڑۍ: تہٕ عیسو اوس اکھ چالاک شِکار، کھہُک شکار۔ تہٕ یعقوب اوس اکھ سادٕ انسان، یُس خیمن منٛز روزان اوس۔\n28.\\tتہٕ اسحاق اوس عیساو سُند محبت کران، تکیازِ أمس اوس یعقوب سٍتۍ محبت کران۔ {وہ...: ہیب۔ وینیسن اوس ٲسس منٛز}\n29.\\tتہٕ یعقوب سوڈ پوٹیج: تہٕ عیسو آو کھہٕ منز، تہٕ سُہ اوس بے ہوش۔\n30.\\tتہٕ عیساو ووٚن یعقوبس زِ میہ کھیٛاوُن، بہٕ چُھس ژے دُعا کران، امی وۄزلہِ سٍتـ̡ ۔ تکیازِ بہٕ چُھس بے ہوش گومُت: لہذا اوس تٔمۍ سُند ناو ایڈوم وننہٕ آمُت۔ {with...: Heb. تتھ وۄزلس سۭتۍ، تتھ وۄزل پوٹیج سۭتۍ} {Edom: that is red}\n31.\\tتہٕ یعقوبن ووٚن، مے کٕنُن از دۅہہ پنُن پیدائشی حق۔\n32.\\tتہٕ عیسوَن ووٚن، وُچھِو، بہٕ چُھس مَرُن، تہٕ یێمہِ پیدائشی حقُک کیا فٲیدٕ واتہِ؟ {at...: Heb. مرُن گَژھُن}\n33.\\tتہٕ یعقوبن ووٚن، از دۅہہ کٔرِو میہ قسم۔ تہٕ سُہ اوس أمِس قسم: تہٕ تٔمۍ کُن پنُن پیدائشی حق یعقوبس کُن۔\n34.\\tیعقوبن دِژ عیساو روٹی تہٕ دالُک برنہٕ۔ تہٕ سُہ اوس کھٮ۪وان تہٕ ووٚتھ، تہٕ ووٚتھ، تہٕ پَنٕنہِ وَتہِ پٲٹھۍ، یِتھٕ کٔنۍ کٔر عیساو سٕندِس پیدائشی حقس نفرت۔","1.\\tتہٕ اوس زمینس منز قحط گومُت، یُس ابراہیم سٕندِس زمانس مَنٛز اوس۔ تہٕ اسحاق گوٚو فلسطینن ہٕندِس بادشاہ ابیمیلکس نِش جیرارس تام۔\n2.\\tتہٕ خداوند آو أمِس نِش ظٲہر تہٕ وونُن، گژھ نہٕ مصرس مَنٛز بۄن گژھُن۔ تتھ زمینس منز روزُن یتھ متعلق بہٕ ژیہ وَنُن:\n3. یتھ زمینس منز روزُن، تہٕ بہٕ روزٕ ژے سٍتۍ، تہٕ کرٕ ژے برکت۔ تکیازِ ژے تہٕ چانہِ اولادس دِیہ بہٕ یم سٲری ملک، تہٕ بہٕ کرٕ سُہ حلف ادا یُس بہٕ پننِس مٲلس ابراہیم سٍتـ̡ حلف کورمُت۔\n4. تہٕ بہٕ بناوٕ چانہِ بُلِس آسمانٕکۍ ستارٕ ہٕندۍ پٲٹھۍ، تہٕ دِیہٕ چانہِ بُلِس یِم سارِنٕے مُلک۔ تہٕ تہٕ تُہٕندِس بُلِس مَنٛز گٔیہِ زمینہٕ کِس سارِنٕے قومن برکت حٲصِل۔\n5.\\tکیازِ زِ ابراہیم کٔر میانہِ آوازِ ہنز فرمانبرداری، تہٕ میٲنۍ حکم، میٲنۍ قونونن تہٕ میٲنۍ قونونن ہٕنز اطاعت کٔرِتھ۔\n6. تہٕ اسحاق اوس جیرارس منز روزان:\n7.\\tتہٕ اَمہ جایہ ہٕندِس مردو پرژھ تٔمۍ سٕنزِ زنانہِ۔ تہٕ تٔمۍ ووٚن، سۅ چھیہ میٲنۍ بینہِ، تکیازِ تس ٲس یہ وننس کھوژان، {سۅ چھے} میانہِ زنانہِ۔ امہ مۅکھہ زِ امہِ جایہ ہٕندۍ نفر گژھن میہ ربیکا خٲطرٕ مارٕنۍ۔ تکیازِ سۅ ٲس وچھنہٕ خٲطرٕ منصفانہٕ۔\n8. تہٕ سپُد ییلہ سُہ واریاہس کالس اتہِ روٗدمُت، فلسطینن ہٕندِس بادشاہس ابیمیلک کٔر دارِ کُن نظر، تہٕ وُچھُن اسحاق پننہِ زنانہِ ربیقاہس سٍتـ̡ گِندان۔\n9.\\tتہٕ ابیمیلکن بُلوو اسحاق تہٕ وونُن، وُچھ، سۅ چھے تہنز زنانہٕ، تہٕ ژے کتھہ پاٹھۍ ووٚن، سۅ چھیہ میٲنۍ بینہِ۔ تہٕ اسحاق ووٚن أمِس کیازِ، کیازِ مےٚ ووٚنمُت، میہ مَرٕ أمِس خٲطرٕ۔\n10. تہٕ ابیمیلک ووٚن، ژے کیا چُھ اسہِ سٍتـ̡ کورمُت؟ لُکن منز آسہ ہا کانہہ تہِ پننہِ زنانہِ سٍتۍ ہلکہ پٲٹھۍ، تہٕ ژیہ ہا اسہِ پیٹھ قصوروار انُن۔\n11.\\tتہٕ ابیملکن دیُت سارنٕے لُکن ہُند حکم زِ یُس أمِس مردس یا تٔمۍ سٕنزِ زنانہِ اتھہٕ لاگہِ سُہ گژھہِ یٔژ مارنہٕ۔\n12.\\tاَمہِ پَتہٕ ووت اسحاق اتھ زمینس مَنٛز، تہٕ امی ؤریس مَنٛز ہتھ گنہٕ روٚٹمُت: تہٕ خداوند کٔر أمِس برکت۔ {موصول: ہیب۔ لٔب}\n13.\\tتہِ گۆو انسان بوٚڈ تہ ووت برونہہ کُن تہ بوٚڈ گۆو یوت تام سُہ واریاہ بوٚڈ بنیوو: {گٔیہ...: ہیب۔ گٔیہِ گَژھُن}\n14.\\tتکیازِ أمِس اوس ریوُن تہٕ کھورِ تہٕ نوکرَن ہُند بٔڈ ذخیرٕ، تہٕ فلسطینی ٲسۍ أمِس حسد کران۔ {خادم: یا، رچھن}\n15.\\tتِمن سارِنٕے کُرٕ یِم تٔمۍ سٕندِس مٲلہِ سٕندِس مٲلہِ سٕندِس زمانس مَنٛز تٔمۍ سٕندِس مٲلہِ سٕندِس خادمَو کھٔنِتھ ٲسمٕتۍ، تِمن رُکٲوِتھ تہٕ بٔرِتھ بٔرِتھ۔\n16.\\tتہٕ ابیملکن ووٚن اسحاقس نِش گژھ اسہِ نِش۔ تِکیازِ تُہۍ چھِو اسہِ کھوتہٕ زیادٕ طاقتور۔\n17.\\tتہٕ اسحاق دراو تتہِ تہٕ کوٚرُن گرار کِس وادی مَنٛز پنُن خیمہ تہٕ روزُن اتہِ۔\n18.\\tتہٕ اسحاق کٔر بییہ آبہٕ کۅرٕ، یُس تمو پننِس مٲلہِ ابراہیم سٕندِس زمانس منز کھننہٕ آمُت اوس۔ تکیازِ فلسطینیو اوس تم ابراہیم سٕندِ مرنہٕ پتہٕ رُکٲومٕتۍ: تہٕ تٔمۍ ووٚن تِمن ناون پیٹھ یِمو سٍتـ̡ تٔمۍ سٕندِس مٲلہِ سٕندِ ناوٕ سٍتـ̡ وَننہٕ آمُت۔\n19.\\tتہٕ اسحاق سٕندٮ۪و خدمتگارو کٔر وادی مَنٛز کھٔنِتھ تہٕ لوٚبُکھ اَتہِ وُچھُن آبُک اکھ کیور۔ {اسپرنگ: ہیب۔ زندٕ}\n20.\\tتہٕ گرارٕکۍ چرواہو کٔر اسحاق سٕندِس چاروَس سٍتـ̡ کوشش کٔرِتھ وَنُن، آب چُھہ سٲنـ̡ تہٕ تٔمۍ وَنُن کُنہِ سٍتـ̡ ناو۔ تِکیازِ تِمو ٲس أمِس سٍتۍ جدوجہد کٔرمٕژ۔ {Esek: یعنی تنازعہ}\n21.\\tتہٕ تِمو کٔر بیاکھ کۅر کھٔنِتھ تہٕ تٔمِس تہِ کٔرٕن سِتنہٕ ناو۔ {سیتنہ: یعنی نفرت}\n22. تہٕ تٔمۍ کٔر تتہِ نِش تہٕ کھٔنِن بیاکھ کیور۔ تہٕ اَمہ خٲطرٕ کٔر نہٕ تِمو کوشش: تہٕ تٔمۍ وَنُن اَمیُک ناو رِہابوت۔ تہٕ تٔمۍ ووٚن، وۄنۍ خداوند چُھ سانہِ خٲطرٕ جاے بنٲومٕژ، تہٕ أسۍ بٔنِو زمینس مَنٛز پھلدار ۔ {رہوبوتھ: سہ چھہ روم}\n23.\\tتہٕ سُہ ووت تتہِ پیٹھہ بیرشبع کُن۔\n24. تہٕ خداوند آو تٔمِس نِش ظٲہر تہٕ وونُن، بہٕ چُھس تُہند مٲل ابراہیم سُند خدا، خوف نہٕ کرُن، تہٕ بہٕ چُھس تہٕ بہٕ چُھس تہٕ بہٕ کرٕ تُہٕندِس بُلِس پننِس خادم ابراہیم سٕندِ خٲطرٕ تہٕ تُہٕندِس بُلِس بڑاوُن۔\n25.\\tتہٕ تٔمۍ بنوو اَتہِ اکھ قربان گاہ، تہٕ خداوند سُند ناو منگووُن تہٕ تتہِ لوٚگُن پنُن خیمہ تہٕ تتہِ کٔرٕن اسحاق سٕندٮ۪و خدمتگارو اکھ کیور۔\n26.\\tاَمہِ پتہٕ گوٚو ابیمیلک گرار پٮ۪ٹھٕ أمِس نِش، تہٕ آہزتھ اوس أمۍ سُنٛد اکھ دوس تہٕ فیشول أمۍ سٕنٛدِ فوجُک چیف کپتان۔\n27.\\tتہٕ اسحاق ووٚن تِمن زِ تم کیازِ آیہ میہ نِش، ییلہ تم میہ سیتۍ نفرت کران چھِو، تہٕ چھکھ میہ پانس نِش دوٗر کٔرتھ؟\n28. تہٕ تِمو ووٚن، أسۍ وُچھ پٔزۍ پٲٹھۍ زِ خداوند اوس توے سٍتـ̡ تہٕ أسـ̡ وونُن، اسہِ تہٕ تۅہہِ درمِیان گژھہِ اکھ حلف تہٕ اسہِ سٍتـ̡ تہٕ تێہہِ سٍتـ̡ عہد کرُن۔ {اسہِ وُچھ...: ہیب۔ وُچھِتھ أسۍ وُچھ}\n29.\\tیُتھ زِ ژے کٔرِو نہٕ اسہِ کانہہ تکلیف دِنہٕ، یِتھٕ کٔنۍ أسۍ چُھہ نہٕ تۅہہِ سٍتـ̡ نیکی ورٲے کینہہ تہِ کورمُت، تہٕ چُھکھ ژے امن سان سوزمُت: ژٕ چُھکھ وُنہِ خداوند سٕندِ بابرکت ۔ {یہ...: ہیب۔ اگر ژیہ کرِ}\n30.\\tتہٕ تٔمۍ بنوو تِمن دعوت تہٕ تِمو کھٮ۪وان تہٕ چیٚوان۔\n31. تہٕ تِم گٔیہِ صبحٲے وُتھ، تہٕ کٔرٕکھ اَکھ أکِس سٍتـ̡ قسم، تہٕ اسحاق سوٗزۍ تِم تہٕ تِم گٔیہِ أمِس نِش امن سان روانہٕ۔\n32.\\tتہٕ سپُد امی دۅہہ ییلہ اسحاق سٕندِ نوکر آیہ، تہٕ تمِس وونُن تتھ کُورِ مُتعلِق یُس تِمو کھنٛنہٕ اوس آمُت، تہٕ وونُن زِ اسہِ چُھ آب لوٚبمُت۔\n33.\\tتہٕ وون أمِس شبہ، تَمہِ مۄکھٕ چُھ شہرُک ناو از تام بیرشبع۔ {شیبہ: یعنی اکھ حلف} {بیرشیبا: یعنی حلفُک کیور}\n34. تہٕ عیسو اوس ژتٲجی وُہُر ییلہ تٔمۍ بیری ہِٹی سٕنز کورِ جوڈِتھ تہٕ ایلون دی ہِٹی سٕنز کورِ بشمتھ زنانہٕ نِش رٔٹۍ۔\n35.\\tیُس اسحاق تہٕ ربیکہ سٕندِ خٲطرٕ ذہنی غم اوس۔ {اکھ غم...: ہیب۔ روحچ تلخی}","1.\\tتہٕ سپُد یہِ زِ ییلہ اسحاق بُزرگ اوس تہٕ تٔمۍ سٕنزِ أچھ ٲس موٚٹ گٔمٕژ، تہٕ تٔمِس وُچھُن نہٕ، تٔمۍ ووٚنُن عیساو پَنُن زِٹھہٕ نیچو، تہٕ وونُن أمِس زِٹھہِ نیچو۔\n2. تہٕ ووٚن وُن، وُچھِو بہٕ وُنہِ وٲنسہِ، بہٕ چُھس نہٕ پننہِ مرنُک دۅہہٕ پتہٕ:\n3.\\tتێلہِ نِو بہٕ ژے پنُن ہتھیار، پنُن ہتھیار تہٕ کمان، تہٕ نِیو میدانس کُن، تہٕ نِیو مے {کینٛہہ} ہُرۍ۔ {نِیو: ہیب۔ شکار}\n4.\\tتہٕ مے بناوُن ماز یُس میہ پسند چُھ، تہٕ اَنُن میہ نِش یُتھ بہٕ کھیوٚن۔ تاکہ میانہِ مرنہٕ برونہہ کٔرِ میون روح ژے برکت۔\n5.\\tتہٕ ربیقاہن بوز ییلہ اسحاق پننِس نیچوِس عیسوس سٍتـ̡ کتھ کٔر۔ تہٕ عیسو گوٚو کھہس منز {for} ہُند شکار، {تہٕ} اننہٕ خٲطرٕ۔\n6. تہٕ ربیقاہن ووٚن پننِس نیچوِس یعقوبس سٍتـ̡ کتھ کٔرِتھ وونُن، وُچھمُت چُھس تُہند مول عیساو سٕندِس بٲیِس سٍتـ̡ کتھ کران تہٕ وونُن،\n7. میہ أنِو میہ ہُند ماز تہٕ بہٕ کھٮ۪تھ تہٕ میانہِ مرنہٕ برونہہ کٔرِتھ کرٕ خداوند سٕندِس برونہہ کُن برکت دِنہٕ۔\n8. وۅنۍ میانہِ نیچو، میانہِ آوازِ ہٕنز اطاعت کٔرِتھ یُس بہٕ ژے حکم دِوان چھُ۔\n9.\\tوۅنۍ گٔژھ کھورِ نِش تہٕ اَتہِ أنِو میہ نِش ژھاوٕنٮ۪ن ہٕندۍ زٕ اصل شُرۍ۔ تہٕ بہٕ بناوٕ تِمن پننِس مٲلہِ سٕندِ خٲطرٕ لذیذ ماز، یُس أمِس محبت چُھ:\n10. تہٕ تُہۍ أنِو یہِ پننِس مٲلِس نِش، یُتھ سُہ کھٮ۪یہِ تہٕ سُہ کرِ مرنہٕ برونہہٕ۔\n11.\\tتہٕ یعقوب ووٚن ربیقاہس پننہِ ماجہ وُچھ، وُچھِو عیسیٰ میون بوے تہٕ بہٕ چُھس اکھ نرم انسان:\n12.\\tمیون مول آسہِ میہ محسوس کران، تہٕ بہٕ کرٕ تس دھوکہ دہی باسان۔ تہٕ بہٕ اَننہٕ پانس پیٹھ لعنت، تہٕ نہٕ برکت۔\n13.\\tتہٕ تسٕنزِ ماجہ ووٚن أمِس زِ میانہِ پٲٹھۍ، میانہِ آوازِ ہٕنز اطاعت کرٕن، تہٕ گژھ میہ اَننہٕ۔\n14.\\tتہٕ سُہ گۆو تہٕ أنِتھ تہٕ أنِن ماجہ نِش، تہٕ تٔمۍ سٕنزِ ماجہ بنوو لذیذ ماز، یُس تٔمۍ سٕندِس مٲلس خۅش اوس۔\n15.\\tتہٕ ربیقاہن تُل پننِس زِٹھِس نیچوِس عیساو سُند اصل پوشاک، یُس أمِس سٍتـ̡ گرس مَنٛز اوس، تہٕ تھووُن یعقوب سٕندِس لۄکٹِس نیچوِس پیٹھ۔ پسندیدٕ}\n16.\\tتہٕ تٔمۍ تھووُن ژھاوٕنٮ۪ن ہٕندٮ۪ن شُرین ہٕندِس کھالَس پٲٹھۍ، تہٕ تٔمۍ سٕندِس گردنہِ ہٕندِس ہموار پٲٹھۍ۔\n17. تہٕ تٔمۍ دِژ لذیذ ماز تہٕ روٹی یُس تٔمۍ تیار کورمُت اوس، پننِس نیچوِس یعقوب سٕندِس اتھس منٛز۔\n18.\\tتہٕ سُہ آو پننِس مٲلِس نِش، تہٕ ووٚنُن، میون مول، تہٕ تٔمۍ ووٚن، یێلہِ چُھس بہٕ۔ ژیہ کُس چھُکھ میانہِ نیچو؟\n19.\\tتہٕ یعقوبن ووٚن پننِس مٲلِس زِ بہٕ چُھس تُہند گۄڈنیُک زُو عیسو۔ میہ کٔر تتھہ پاٹھۍ یُس ژے میہ بدکار کران چھُ، وۅتھ، بہٕ چھُس ژے دُعا کران، بِہتھ کھیوٚن میون وینیس، تاکہ چانۍ روح کرِ میہ برکت۔\n20.\\tتہٕ اسحاق ووٚن پننِس نیچوِس زِ ژے کِتھہ پٲٹھـ̡ لٔبـ̡ یێژ جلدی لٔبـ̡ ژے لٔبـ̡ یێلہِ نیچو۔ تہٕ تٔمۍ ووٚن، کیازِکہ خداوند چُھہ تُہند خدایہ میہ نِش دِژمُت۔ {میہ کُن: ہیب۔ میہ برونہہ کنہِ}\n21. تہٕ اسحاق ووٚن یعقوبس نزدیک، بہٕ چُھس ژے دُعا کران زِ بہٕ ہێکہٕ ژے محسوس کٔرِتھ، میانہِ نیچو، چاہے ژٕ میون نیچو عیسو آسہٕ یا نہ۔\n22. تہٕ یعقوب گوٚو پننِس مٲلِس اسحاق سٕندِس نزدیک۔ تہٕ تٔمۍ کٔر أمِس محسوس تہٕ وونُن، آواز {چِھ} یعقوب سٕنز آواز، مگر اتھہٕ چِھ عیساو سٕندِ اتھہٕ۔\n23.\\tتہٕ أمِس اوس نہٕ أمِس وُچھمُت، تِکیازِ تٔمۍ سٕندِ اَتھٕ ٲسۍ مَس، یِتھٕ پٲٹھۍ تٔمۍ سٕندِس بٲے عیسو سٕندِ اتھہٕ سٍتـ̡ دُعا کٔرِتھ۔\n24.\\tتہٕ تٔمۍ ووٚن، {آرٹ} ژے میون نیچو عیسو؟ تہٕ تٔمۍ ووٚن، بہٕ چھُس۔\n25.\\tتہٕ تٔمۍ ووٚن، اَنُن میہ نزدیک، تہٕ بہٕ کھیٚیہٕ پننِس نیچوۍ سُند شُر، یُتھ میون روح ژے برکت دِیہِ۔ تہٕ تٔمۍ اوٚن پانس نزدیک، تہٕ کھیوٚن تہٕ تٔمۍ اوٚن أمس شراب، تہٕ تٔمۍ چیوٚن شراب۔\n26.\\tتہٕ تٔمۍ سٕندِس مٲلہِ اسحاق ووٚن أمِس نِش یِمن نزدیک، تہٕ کٔرِو میہ بونہٕ، میانہِ نیچو۔\n27. تہٕ سُہ آو نزدیک، تہٕ کوٚرُن أمِس بوسہٕ، تہٕ أمِس دِژ تٔمِس پلوٕچ خوشبو، تہٕ کوٚرُن أمِس برکت تہٕ وونُن، وُچھ، میٲنِس نیچوِس سٕنز خوشبو چھِ کھہٕچ خوشبو یُس خداوند سٕندِ دِژمُت چھُ۔\n28. تێمہِ کِنۍ دِیُن خدایہ ژے اسمانُک شبنم، تہٕ زمینہِ ہٕنزِ چربی تہٕ سٮ۪ٹھاہ مکامل تہٕ شراب۔\n29. لُکھ گژھن تۅہہِ سٍتـ̡ سُند خدمت، تہٕ قومہٕ گژھن تۅہہِ سٍتـ̡ سجدٕ: پَنٕنـ̡ باین ہُند رب بٔنِو، تہٕ پَنٕنـ̡ ماجہِ ہٕندِس نیٚچوِس گٔژھِن تۅہہِ سٍتـ̡ نَمُت۔\n30.\\tتہٕ سپُد یێلہِ یێلہِ اسحاق یعقوب سٕندِس مٲلہِ سٕندِ حٲضِری نِش دِنہٕ آمُت تہٕ یعقوب اوس نہٕ تٔمِس مٲلہِ اسحاق سٕندِ حٲضِری نِش دِنہٕ آمُت، تہٕ یعقوب آو تٔمۍ سُند بوے عیسیٰ سُند شکارٕ نشہِ اژُن۔\n31. تہٕ تٔمۍ اوس لذیذ ماز تہِ بنوومُت، تہٕ پننِس مٲلِس نِش أنِتھ تہٕ پننِس مٲلِس ووٚنُن، میون مول وۅتھُن تہٕ تٔمۍ سٕندِس نیچوۍ سُند گُرٕ کھٮ۪ن، یُتھ تُہند روح کرِ میہ برکت۔\n32.\\tتہٕ تٔمۍ سٕندِس مٲلہِ اسحاق ووٚن تٔمِس کُس چُھہ؟ تہٕ تٔمۍ ووٚن، بہٕ چُھس تُہند نیچو، تُہند گۄڈنیُک عیسو۔\n33.\\tتہٕ اسحاق ووت سٮ۪ٹھاہ تھر تھر تہٕ وونُن، کُس؟ سُہ کتہِ چُھس یُس گُرِ رٔٹِتھ تہٕ مے اَنِمُت، تہٕ مے چُھس ژے یِنہٕ برونہہ سارِنٕے کھٮ۪وان تہٕ أمِس دُعا دِژمُت؟ آ، {تہٕ} سُہ گژھِ برکت۔ {تھرتھر...: ہیب۔ سٮ۪ٹھاہ تھرتھرٕ سٍتـ̡ لٔگِتھ لٔگِتھ لٔگـ̡ {نِنہٕ: Heb. شکار}\n34.\\tتہٕ ییلہ عیسو پننس مٲلہِ سٕنز کتھ بوز، سُہ ووٚتھ سٮ۪ٹھاہ تہٕ سٮ۪ٹھاہ تلخ کرٛٮ۪کہٕ سٍتـ̡ تہٕ وونُن پننِس مٲلِس تہٕ وونُن میہ تہِ دُعا کرُن، اے میانہِ مٲلہِ۔\n35. تہٕ ووٚن تُہند بٲے آو نزاکت سٍتـ̡ تہٕ تُہٕندِس دُعا سٍتـ̡ نِش نِیومُت۔\n36.\\tتہٕ ووٚن، کیا أمِس چھُنہٕ یعقوب ناو دِنہٕ آمُت؟ تکیازِ تٔمۍ کٔر میہ دۅیہ لٹہِ بدلٲومُت: تٔمۍ نِش میون پیدائشی حق نِش نِیومُت۔ تہٕ وُچھ، وۅنۍ چھُ تٔمۍ میون دُعا نِش نِمُت۔ تہٕ تٔمۍ ووٚن، کیا ژیہ چھے نہٕ میانہِ خٲطرٕ دُعا رژھراونہٕ آمٕژ؟ {جیکب: یعنی اکھ سپپلانٹر}\n37.\\tتہٕ اسحاق دیُت جواب تہٕ وونُن عیسوس زِ وُچھ، مے بنوو سُہ پنُن مٲلک، تہٕ تٔمۍ سٕندِس سارِنٕے بٲے چھِ أمِس خدمتگارن خٲطرٕ دِژمٕتۍ۔ تہٕ مکایہ تہٕ شرابہٕ سٍتۍ چُھس میہ رژھراونہٕ آمُت: تہٕ بہٕ کیا کرٕ وۅنۍ ژے سٍتۍ، میانہِ نیچو؟ {مَضموٗن: یا، تَحمایَت}\n38.\\tتہٕ عیسوون ووٚن پننِس مٲلِس سٍتـ̡ کیا تۅہہ چُھہ اَکھ برکت دِژمُت، میانہِ بابہٕ؟ اے بابہٕ تہِ کٔر میہ تہِ برکت۔ تہٕ عیساون کٔر آواز تھوٚد تہٕ رووُن۔\n39.\\tتہٕ اسحاق سندس مٲلہِ دیت جواب تہٕ وونُن تٔمِس زِ وُچھ، تۅہہِ ہُند روزن آسہِ زمینہِ ہُند موٚٹُر تہٕ ہیرِ پیٹھٕ آسمانُک شبنم۔ {موٹۍ: یا، چربی ہُند}\n40. تہٕ پننہِ تلوار سٍتـ̡ روزٕ تہٕ پنہٕ نِس بٲے سٕنز خدمت کٔرِو۔ تہٕ یہ گژھہِ سپدِ تمہِ ساتہٕ ییلہ ژے سلطنت حٲصل گژھہِ، تہٕ ژے ژیہ پننہِ گردنہِ نِش تٔمۍ سُند جولہٕ ژٹناوُن۔\n41.\\tتہٕ عیساو اوس یعقوبس سٍتـ̡ نفرت، ییمہِ سٍتـ̡ تٔمۍ سٕندِس مٲلہِ سٕندِس دُعا سٍتـ̡ دِژ تہٕ عیساو ووٚن پننِس دِلس مَنٛز، میانِس مٲلہِ سٕندِ خٲطرٕ ماتم کرنُک دۅہ چُھہ یِوان۔ تیلہِ کٔرٕ بہٕ پنُن بوے یعقوب مٲرِتھ۔\n42.\\tتہٕ عیسو سٕندِس بٔڈِس نیچوِس سٕندِ یِم لفظ آیہ ربیکاہَس وَننہٕ، تہٕ تٔمۍ سوٗز یعقوب پنُن لۄکُٹ نیچو، تہٕ وونُن تُہند بوے عیسو، یێلہِ چُھہ تۅہہِ سٍتـ̡ ژےٚ مارنُک ارادٕ تھاوان۔\n43.\\tتێلہِ کٔرِو میانہِ آوازِ ہٕنز فرمانبردار۔ تہٕ ووٚتھ، ژٔلِتھ لبان کُن میون بٲے ہارنس کُن۔\n44.\\tتہٕ روٗزِو أمِس سٍتـ̡ کینہہ دۅہہ، یوتام نہٕ تُہٕندِس بٲے سُند غصہٕ پھیرِ۔\n45.\\tیوٚت تام نہٕ تُہٕندِس بٲے سُند غصہٕ ژٔٹِتھ تہٕ سُہ یہِ مٔشِد گژھِ یُس ژے أمِس سٍتۍ کورمُت چھُ، تیلہِ سوزٕ بہٕ تہٕ تتہِ نِش نِن: بہٕ کیازِ گژھہِ أکِس دۅہس منز ژےٚ دۅشوے نِش محروم روزُن؟\n46.\\tتہٕ ربیقاہن ووٚن اسحاق زِ بہٕ چُھس ہیتھ سٕنزِ کورِ ہٕندِ وجہ سٍتـ̡ پننہِ زِندٕ نِش تنگ گومُت: یێلہِ یعقوب ہیث سٕنزِ کورِ ہٕنزِ خانٛدارِنۍ رٔٹِتھ، یِتھٕ پٲٹھـ̡ یِم زمینہٕ چِھہ کورِ ہٕنز، میانہِ زِندٕ کیاہ فٲیدٕ کٔرِتھ؟","1. تہٕ اسحاق کٔر یعقوب بُلوو، تہٕ دِتُن أمِس برکت تہٕ دِتُن أمِس حُکُم، تہٕ وونُن تٔمِس زِ تٔمِس گژھ نہٕ کنعان چہِ کورِ ہٕنز خانٛدارِنۍ رٔٹِتھ۔\n2.\\tوۅتھٕ وُتھ، پڈانارمس کُن، پننہِ ماجہ ہٕندِس مٲلِس بیتھوئیل سٕندِس گرس منز۔ تہٕ تتہِ نِن پننہِ ماجہ ہٕندِس بٲیِس لبان سٕنزِ کورِ ہٕنزِ خانٛدارِنہِ۔\n3. تہٕ خدایہ کرِ تۅہہِ برکت تہٕ پھلدار تہٕ بٔڑِتھ کرُن، یُتھ تہٕ تۅہہِ ہُند بٔڑِتھ بٔنِتھ۔ {اکھ تعداد...: ہیب۔ لوکن ہنز اکھ مجلس}\n4. تہٕ دِیُن ژے ابراہیم سٕنز برکت تہٕ پانس سٍتـ̡ تہٕ پننہِ اولادس سٍتـ̡ دِیُن۔ یُس خداین ابراہیمس دِژمُت چھُ، یُس خداین دِژمُت چھُ۔ {یتھ منز...: ہیب۔ چانہِ سفرُک }\n5. تہٕ اسحاق سوٗز یعقوب تہٕ سُہ گۆو پڈانارمس نِش یُس ربعہ سُند بوے یعقوب سُند بوے یعقوب تہٕ عیساو سٕنز موج ٲس۔\n6.\\tییلہ عیساون وُچھ زِ اسحاق اوس یعقوبس دُعا دِژمُت، تہٕ سوٗزُن سُہ پڈانارمس نِش تتہِ نِنہٕ خٲطرٕ۔ تہٕ یہ زِ یێلہِ أمِس دُعا دِژ تٔمِس دِژ دِژ، تہٕ وَنُن زِ ژے کٔرِو نہٕ کنعان سٕنزِ کورِ ہٕنزِ خانٛدارِنہِ ہٕنز خانٛدارِنہِ۔\n7. تہٕ یعقوب کٔر پننِس مٲلِس تہٕ ماجہِ ہٕنٛز فرمانبرداری، تہٕ گوٚو پڈانارمس کُن۔\n8.\\tتہٕ عیساو وُچھِتھ زِ کنعان سٕنزِ کورِ چھے نہٕ اسحاق سٕندِس مٲلِس خۅش کٔرِتھ۔ {خوش...: ہیب۔ اچھن منز اوس بد کار بیترِ}\n9.\\tاَمہِ پَتہٕ گۆو عیسیٰ اسماعیلِس نِش، تہٕ نِیوُن تِمن زنانن نِش یِم أمِس اسماعیل ابراہیم سٕندِس نیچوِس سٕنز کورِ ٲس، یۄسہٕ نباجوتھ سٕنزِ بینہِ ٲس۔ {محلتھ: یا، بشیمتھ}\n10.\\tتہٕ یعقوب دراو بیرشبع پیٹھٕ تہٕ دراو ہارنس کُن۔ {ہارن: Gr. Charran}\n11. تہٕ تٔمۍ روٗد أکِس خاص جایہِ گاش تہٕ روٗد سارِوٕے رٲژ اَتہِ روزان، تِکیازِ آفتاب اوس لوسُن۔ تہٕ تٔمۍ تُل تمہِ جایہِ ہٕندۍ کنۍ، تہٕ تھووُن پنٕنۍ تِلہٕ تہٕ لوٚگ اَتھ جایہِ شۄنگنہٕ خٲطرٕ۔\n12.\\tتہٕ وُچھ خواب، تہٕ وُچھ زمینس پیٹھ اکھ ہیر بٔنِتھ، تہٕ امیک تھوٚد اوس آسمانس تام ووتمت، تہٕ وُچھن خدایہ سٕندۍ فرشتہ اتھ پیٹھ کھسان تہٕ وسان وُچھان۔\n13. تہٕ وُچھِتھ وُچھِتھ خداوند اَتھ پیٹھۍ کھڑا تہٕ وونُن، بہٕ چُھس ابراہیم سُند خدا، تُہند مول تہٕ اسحاق سُند خدا، یتھ زمینس پیٹھ تہٕ ژے دِیہٕ تہٕ تُہٕندِس اولادس دِنہٕ۔\n14. تہٕ تُہُند بُل آسہِ زمینہِ ہٕندِس میژِ ہٕندۍ پٲٹھۍ، تہٕ ژے گژھہِ مغربس کُن، مشرقس کُن، شمالس کُن تہٕ جنوبس کُن پھٔہلِتھ تہٕ ژے تہٕ تُہٕندِس بُلِس مَنٛز گژھن زمینہِ ہٕندِس سارِنٕے خاندانن برکت حٲصِل۔ {پھٔلِو...: ہیب۔ بریک فورتھ}\n15.\\tتہٕ وُچھِو، بہٕ چُھس ژے سٍتـ̡ تہٕ یێلہِ تہٕ ژے یێلہِ تہٕ تکیازِ بہٕ تراوٕ نہٕ ژے توٚت تام یوٚت تام نہٕ سُہ {یہ} کرنہٕ یُس میہ ژے سٍتۍ کتھ کرِ۔\n16.\\tتہٕ یعقوب ووت نندر منزٕ بیدار تہٕ وونُن، یٔژ خداوند چُھ یَتھ جایہِ موجود۔ تہٕ میہ ٲس نہ خبر۔\n17.\\tتہٕ سُہ کھوژُن تہٕ وونُن، یہِ جاے کوتاہ خوفناک چھِ! یہِ {چُھ} خدایہِ سُند گرٕ تہٕ یہِ {چُھ} جنتُک دروازٕ۔\n18.\\tتہٕ یعقوب ووٚتھ صُبحے سُلہِ تہٕ تُل سُہ کٔنہِ یُس تٔمۍ پنہٕ نِس تِرِہٕ خٲطرٕ تھوومُت اوس، تہٕ تھووُن اَتھ تھمس پیٹھ تیٖل۔\n19.\\tتہٕ تٔمۍ ووٚن تمہِ جایہِ ہُند ناو بیتھل: مگر امہِ شہرُک ناو اوس گۅڈنچہ لٹہِ لوز وننہٕ آمُت۔ {بیتھل: یعنی خدایہ سُند گرٕ}\n20. تہٕ یعقوبن کٔر عہد تہٕ وونُن، اگر خدا آسہِ میہ سٍتۍ، تہٕ یِتھٕ پٲٹھۍ تھاوِ بہٕ یِتھٕ پٲٹھۍ تہٕ دِیہِ مے کھٮ۪نہٕ خٲطرٕ روٹی تہٕ پوشہٕ لاگنہٕ خٲطرٕ،\n21.\\tیُتھ بہٕ ییہ پننِس مٲلہِ سٕندِس گَرٕ سٍتـ̡ سُکون سان واتہٕ۔ تیلہِ گژھہِ خداوند میون خدا:\n22. تہٕ یہِ کٔن، یُس میہ اکھ ستون مقرر کورمُت چُھ، سُہ گژھہِ خدایہ سُند گرٕ تہٕ یُس تہٕ ژے مے دِنہٕ یُس تہٕ بہٕ دِیہٕ ژے دٔہِم۔","1. پَتہٕ یعقوب پَنُن سفر، تہٕ ووت مشرق کین لُکن ہٕندِس سرزمینس مَنٛز۔ {گٔیہ...: ہیب۔ تُلِو تٔمۍ سٕندِس کھۅر تُلِتھ} {لوک: ہیب۔ بچہٕ}\n2.\\tتہٕ تٔمۍ وُچھ، تہٕ وُچھُن کھہس منز اکھ کیور، تہٕ وُچھِتھ اَتھ نِش ٲسۍ تریہ کۅکرِ ہٕندِ کھورِ ہٕندِس اندۍ پکھۍ۔ تِکیازِ تِمو کٔر تَمہِ کُنہِ۔\n3.\\tتہٕ تتہِ گٔیہِ سٲری ریوڑ جمع تہٕ تِمو کٔر کنہِ کُ\n4. تہٕ یعقوبن ووٚن تِمَن، میانہِ بٲے، کتہِ چھِو؟ تہٕ تِمو ووٚن، ہارن ہٕندِس سٍتـ̡ أسـ̡\n5.\\tتہٕ تٔمۍ ووٚن تِمن زٲنِتھ زِ ناہور سُند نیچو لابان چھُ؟ تہٕ تمو ووٚن، أسۍ چھِ زانان۔\n6.\\tتہٕ تٔمۍ ووٚن تِمَن زِ سُہ چھا ٹھیٖک ٹھیٖک؟ تہٕ تِمو ووٚن، {سُہ چُھ} ٹھیٖک: تہٕ وُچھ، راحیل چھے تٔمۍ سٕنز کورِ کۅکرِ ہیتھ یوان۔ {کیا یہ...: ہیب۔ کیا تس چھا امن؟}\n7.\\tتہِ ووٚن لو، یہ چھہ وُنہِ تہِ تھوٚد دۅہ، نہ چھہ یہ وق زِ چاروو یکوٹہ جمع کرنہ یُن: ژیہ کۅکرِ آب دِنۍ، تہٕ گژھ {تہِ} کھیوٚن۔ {یہِ چھُ...: ہیب۔ توتہِ چھہ دۅہ عظیم}\n8.\\tتہٕ تِمو ووٚن، أسۍ ہیوٚک نہٕ توٚت تام نہٕ توٚت تام یِم سارِنٕے کھورِ ہٕندِس کُنہِ سٍتـ̡ رٔلِتھ یِن۔ امہ پتہ چھہِ اسۍ دانٛد آب دوان۔\n9.\\tتہٕ یێلہِ سُہ تِمن سٍتـ̡ کتھ کٔرِتھ، راحیل آیہِ پننِس مٲلہِ سٕندِس کۅکرس سٍتـ̡ ہٮ۪تھ، تکیازِ تٔمۍ ٲس تِم رژھراونہٕ آمٕژ۔\n10.\\tتہٕ سپُد یعقوب ییلہ یعقوب پننہِ ماجہ ہٕندِس بٲیِس لابان سٕنزِ کورِ راحیل تہٕ ماجہ ہٕندِس بٲے لابان سٕندِس کۅکرس وُچھ، یعقوب ووت نزدیک، تہٕ کٔرٕن کُنہِ تہٕ دِژُن پننہِ ماجہ ہٕندِس بٲیِس لابان سٕندِس کھورِس آب\n11.\\tتہٕ یعقوبن کٔر راحیلَس بوسہٕ، تہٕ تُلِن پنٕنۍ آواز تھوٚد تہٕ ووٚنُن۔\n12. تہٕ یعقوبن ووٚن راحیلس زِ سُہ اوس تٔمۍ سٕندِس مٲلہِ سُند بوے تہٕ سُہ اوس ربیکا سُند نیچو۔\n13.\\tتہٕ سپُد ییلہ لبانن پننہِ بینہِ ہٕندِس نیچوِس یعقوب سٕنز خبر بوٗز، سُہ ژوٚل أمِس سمکھنہٕ خٲطرٕ، تہٕ رٔلِتھ تہٕ بوسہ دِتھ أنِن أمِس گَرٕ۔ تہٕ تٔمۍ ووٚن لابنس یم سٲری چیز۔ {خبر: ہیب۔ بوزُن}\n14.\\tتہٕ لابن ووٚن أمِس زِ ژٕ چھُکھ میٲنۍ أڈجہِ تہٕ میٲنۍ ماز ۔ تہٕ سُہ روٗد أمِس سٍتۍ أکِس ریتس ہُند وقفہٕ۔ {جاے ...: ہیب۔ دۅہن ہند اکھ ریتھ}\n15.\\tتہٕ لابن ووٚن یعقوبس زِ تۅہہ چُھکھ میون بوے تہٕ کیا ژٕ کٔرِکھ میانہِ خدمت کٔرِتھ؟ مے وَن، تُہند مزدور کیا چُھہ؟\n16.\\tتہٕ لابانس ٲس زٕ کورِ: بٔڈۍ سُند ناو اوس لیہ، تہٕ لۄکٹِس سُند ناو اوس راحیل۔\n17. لیہ {ٲس} نرم اچھ۔ مگر ریچل ٲس خوبصورت۔\n18. تہٕ یعقوب اوس راحیلس محبت کران۔ تہٕ ووٚنُن، بہٕ کَرٕ ژےٚ سَتن ؤرین راحیل سٕندِ خٲطرٕ پننہِ لۄکچہِ کورِ ہٕنز خدمت۔\n19.\\tتہٕ لابن ووٚن، {یہِ} چُھہ بہتر زِ بہٕ چُھس سۅ بییِس مردس دِنہٕ بجایہ بہٕ سُہ بییِس مردس دِنہٕ: مے سٍتـ̡ روزُن۔\n20. تہٕ یعقوب کٔر راحیل سٕندِ خٲطرٕ ستن ؤرین خدمت۔ تہٕ تِم ٲسۍ أمِس {مگر} کیٚنٛہہ دۄہ باسان، تٔمِس محبتہٕ خٲطرٕ۔\n21.\\tتہٕ یعقوبن ووٚن لابانس زِ میانہِ زنانہِ دِیُن میٲنۍ دۅہ پورٕ، یُتھ بہٕ گژھہٕ تس نِش اژُن۔\n22.\\tتہٕ لابن کٔر امہِ جایہِ ہٕندِس سارِنٕے نفر جمع تہٕ کوٚرُن دعوت ۔\n23.\\tتہٕ شامَس سپد یہِ زِ تٔمۍ نِیہِ لیہ پنٕنۍ کورِ تہٕ أنِن پانس نِش۔ تہٕ سُہ گوٚو أمِس نِش۔\n24.\\tتہٕ لابن دِژ پننہِ کورِ لیہ زلپاہ پنٕنۍ دٲیرِ خٲطرٕ۔\n25.\\tتہ سپد یہ زِ صبحس وچھ یہ لیہ تہ تمۍ وونُن لابانس زِ ژے کیا چھہ میہ سیتۍ کورمُت۔ کیا میہ اوسس نہٕ راحیل سٕندِ خٲطرٕ ژے سٍتۍ خدمت کٔرمٕژ؟ تیلہِ کیازِ چھکھ ژے میہ دھوکہٕ دِژمٕژ؟\n26.\\tتہٕ لابن ووٚن زِ سانہِ ملکس منز گژھہِ نہ یۅہے کرنہٕ یُن، یُس گۅڈنچہ بچہ برونہہ کُن دِنہٕ یُن۔ {ملک: ہیب۔ جاے}\n27.\\tتٔمۍ سُند ہفتہٕ پوٗرٕ کرُن، تہٕ أسۍ دِیہ ژے یہِ تہِ تمہِ خدمتہٕ خٲطرٕ یُس ژے باقی سَتن ؤرین میہ سٍتۍ خدمت کرِ۔\n28.\\tتہٕ یعقوبن کٔر یۅہے تہٕ کورُن پنُن ہفتہٕ پورٕ۔\n29.\\tتہٕ لابن دِژ راحیلس پنٕنۍ کورِ بلحاہ پنٕنۍ دٲیرِ دِنہٕ خٲطرٕ۔\n30. تہٕ سُہ گوٚو راحیلس نِش تہِ، تہٕ سُہ اوس لیہ کھوتہٕ زیادٕ راحیلس سٍتـ̡ محبت کران، تہٕ سُہ اوس أمِس سٍتـ̡ خدمت کٔرمٕژ۔\n31. تہٕ ییلہ خداوند وُچھ زِ لیہ ٲس نفرت، تٔمۍ کٔر تٔمۍ سُند رحم کھولُن: مگر راحیل ٲس بانجھ۔\n32.\\tتہٕ لیہ زاو تہٕ زاو اکھ نیٚچُو، تہٕ تٔمۍ ووٚن تٔمِس ناو روبن، تکیازِ تٔمۍ ووٚن، یٔمۍ ووٚن، یێلہِ خداوند چُھ میانہِ مصیبت وُچھمُت۔ وۅنۍ کرِ میون خاوند میہ محبت۔ {روبن: یعنی وچھو اکھ نیچو}\n33.\\tتہٕ أمِس گٔیہِ دُبارٕ حاملہٕ، تہٕ کوٚرُن اکھ نیٚچُو۔ تہٕ ووٚنُن، کیازِ خداوند چُھس بوزمُت زِ بہٕ اوسُس نفرت، تٔمۍ دِژ مے یہِ {نیٚچُو} تہِ: تہٕ تٔمۍ ووٚن أمِس ناو شمعون ۔ {شمعان: یعنی بوزن}\n34.\\tتہٕ سۅ گٔیہِ دُبارٕ حاملہٕ، تہٕ کوٚرُن اکھ نیٚچُو۔ تہٕ ووٚنُن، وۅنۍ گژھہِ میون خانٛدار میہ سٍتـ̡ رٔلِتھ، کیازِ میہ چھِ تس ترے نیچوۍ زامٕتۍ، تێمہِ کِنۍ اوس تٔمِس ناو لیوی ناو۔ {لیوی: یعنی شٲمل}\n35. تہٕ أمِس دُبارٕ حاملہٕ تہٕ زیٚوُن اکھ نیٚچُو، تہٕ تٔمۍ ووٚن، وۄنۍ کٔرٕ بہٕ خداوند سٕنٛز حمد تہٕ تٔمۍ ووٚن أمِس یہوداہ ناو۔ تہٕ کھوورِ بیئرنگ۔ {یہوداہ: یعنی تعریف} {دٔچھُن...: ہیب۔ بیئرنگ نش کھڑا}","1. تہٕ ییلہ راحیلن وُچھ زِ أمِس چُھنہٕ یعقوب کانہہ شُر، راحیلن کٔر پننہِ بینہِ سٍتـ̡ حسد۔ تہٕ ووٚنُن یعقوبس زِ مے دِیُن شُرۍ، نتہٕ بہٕ مرُن۔\n2. تہٕ یعقوب سُند غصہٕ آو راحیلس سٍتـ̡ دِنہٕ، تہٕ تٔمۍ ووٚن، {بہ} چُھس خدایہ سٕندِ بدلہٕ ، یُس ژے نِش رحمُک پھل رُکٲومُت چُھ؟\n3.\\tتہٕ ووٚن، وُچھ میانہِ دٲر بلہ، گژھ أمِس نِش۔ تہٕ سۅ گژھہِ میانین کۅٹھن پیٹھ بٔرتھ، تاکہ میہ تہِ آسہِ أمس سٍتۍ شُرۍ۔ {ہیو...: ہیب۔ تٔمۍ سٕنٛدِ ذریعہٕ بناوُن}\n4.\\tتہٕ تٔمۍ دِژ أمِس بِلہ پنٕنۍ خانٛدارِنہِ خٲطرٕ، تہٕ یعقوب گوٚو أمِس نِش۔\n5.\\tتہٕ بلحہ گوو حاملہٕ تہٕ یعقوب کوٚرُن اکھ نیٚچُو۔\n6. تہٕ راحیلن ووٚن، خداین چُھ میہ فیصلہ کورمُت، تہٕ میٲنۍ آواز تہِ بوزمٕژ، تہٕ دیتُن میہ اکھ نیٚچُو، لہذا وون أمس تٔمۍ سُند ناو دان۔ {دان: یعنی، عدالت}\n7.\\tتہٕ بلحہ راحیل سٕنزِ دٲیرِ گٔیہِ دُبارٕ حاملہٕ، تہٕ یعقوب دوٚیُم نیچو۔\n8.\\tتہٕ راحیلن ووٚن، بٔڈۍ ریسلنگ سٍتـ̡ چُھس میہ پننہِ بینہِ سٍتـ̡ کُشتی کٔرمٕژ، تہٕ بہٕ چُھس فتح حٲصل کٔرمُت: تہٕ تٔمۍ ووٚن تٔمۍ سُند ناو نفتالی۔ {عظیم...: ہیب۔ ریسلنگ آف گاڈ} {نفتالی: یعنی میٲنۍ ریسلنگ: Gr. Nephthalim}\n9.\\tییلہ لیہ یہ وُچھ زِ سۅ چھیہ نیبر نیران، تٔمۍ نیو زلپاہ پنٕنۍ دٲر تہٕ دیتُن پنُن یعقوب زنانہٕ۔\n10.\\tتہٕ زِلپاہ لیہ سٕنزِ دٲیرِ زاے یعقوب اکھ نیچو۔\n11.\\tتہٕ لیہ ووٚن اکھ فوج یِوان تہٕ تٔمۍ ووٚن أمِس ناو گاد۔ {گاڈ: یعنی اکھ ٹروپ، یا، کمپنی}\n12. تہٕ زِلپاہ لیہ سٕنزِ دٲیرِ زاے یعقوب سُند دوٚیِم نیچو۔\n13.\\tتہٕ لیہ ووٚن میہ خۅش گومُت، تکیازِ کورِ کرِ میہ بابرکت ونان، تہٕ تٔمۍ ووٚن تٔمۍ سُند ناو آشر۔ {خوشی...: ہیب۔ میانہِ خوشی منز} {آشر: یعنی خوشی}\n14.\\tتہٕ روبن گۆو کٕنکہٕ فصلہٕ کِس دۅہہَس مَنٛز، تہٕ لوٚبُن کھہَس مَنٛز مینڈریک، تہٕ أنِن پننہِ ماجہِ لیہ نِش۔ اَمہ پتہٕ ووٚن راحیلَن لیہ زِ بہٕ دِیُس ژے دِیُن پننہِ نیچوۍ سٕندِس مینڈریکس۔\n15.\\tتہٕ تٔمۍ ووٚن أمِس {یہ} چھَا لۄکٕٹ کتھ یُس ژے میون خانٛدار نِیومُت چھُ؟ تہٕ کیا ژٕ نِنہٕ میٲنِس نیچوۍ سٕندِ مینڈریک تہِ؟ تہٕ راحیلن ووٚن، لہذا روزِ سُہ تہندِس نیچوۍ سٕندِ مۅکھہٕ راتس ژے سٍتـ̡ روزُن۔\n16.\\tتہٕ یعقوب دراو شامس کھہٕ منزہ نیبر، تہٕ لیہ دراو أمِس سمکھنہٕ خٲطرٕ، تہٕ وونُن، ژے گژھہِ میانہِ نِش اژُن۔ یقینا مے چُھس ژے پننِس نیچوۍ سٕندِس مینڈرکس سٍتۍ کٲم کٔرمٕژ۔ تہٕ سُہ لوٚگ تٔمۍ رٲژ أمِس سۭتۍ۔\n17.\\tتہٕ خداین کٔر لیہ سُند بوز، تہٕ سُہ گٔیہِ حاملہٕ، تہٕ یعقوب زاو پوٗنٛژِم نیٚچُو۔\n18.\\tتہٕ لیہ ووٚن، خداین دِژ میہ پنُن کرایہ دِژمُت، تکیازِ میہ چھیہ پنٕنۍ کۅکرِ پننِس خاوندس دِژمٕژ، تہٕ تٔمۍ ووٚن تٔمِس ناو اِساکر۔ {اِساکر: یعنی اکھ کرایہ}\n19. تہٕ لیہ دُبارٕ حاملہٕ، تہٕ یعقوب دیت شیٚیِم نیٚچُو۔\n20.\\tتہٕ لیہ ووٚن خداین دِژ میہ اکھ جان داج دِژمٕژ۔ وۅنۍ روزِ میون خاوند میہ سٍتۍ، تکیازِ میہ چھہِ تس شیہ نیچوۍ زامتۍ، تہ تمۍ ووٚن تس زیبولن ناو۔ {زیبولون: یعنی رہائش: Gr. Zabulon}\n21.\\tتہٕ امہ پتہ زاے أمس اکھ کور، تہٕ وونُن أمس دینہ ناو۔ {دینا: یہ چھہ فیصلہ}\n22.\\tتہٕ خداین کٔر راحیل یاد، تہٕ خداین کٔر أمِس کُن بوزنہٕ تہٕ کھولُن تٔمِس رحم۔\n23.\\tتہٕ أمِس گٔیہِ حاملہٕ، تہٕ کوٚرُن نیچو۔ تہٕ وونُن، خداین ہیوٚت میون ملامت دور:\n24. تہٕ تٔمۍ ووٚن تٔمۍ سُند ناو یوسف۔ تہٕ ووٚنُن، خداوند کرِ میانہِ سٍتـ̡ بیاکھ نیچو۔ {جوزف: یعنی اضافہ}\n25.\\tتہٕ ییلہ راحیلن یوسف زامُت اوس، یعقوبن ووٚن لابانس زِ بہٕ گژھ پننہِ جایہ تہٕ پننِس ملکس کُن۔\n26. میٲنۍ زنانہٕ تہٕ شُرۍ، یِمن ہٕندِ خٲطرٕ بہٕ ژےٚ خدمت کٔرمٕژ، تہٕ دِیُن مے نیرُن، تکیازِ ژے چھے میٲنۍ خدمت زانان یۄس میہ ژےٚ کٔرمٕژ چھےٚ۔\n27.\\tتہٕ لابن ووٚن أمِس زِ بہٕ چُھس ژے دُعا کٔرِتھ، اگر میہ چانہِ نظرن منز احسان میلہِ، کیازِ} میہ چُھہ تجربہٕ سٍتـ̡ ہیچھمُت زِ خداوند چُھہ تێنہِ خٲطرٕ میہ برکت دِژمُت۔\n28.\\tتہٕ تٔمۍ ووٚن، پنُن تنخواہ مقرر کرُن، تہٕ بہٕ دِیہ یہِ۔\n29. تہٕ تٔمۍ ووٚن أمِس زِ ژےٚ چھے پتاہ زِ بہٕ کِتھہ کٔنۍ چُھس تۅہہِ خدمت کٔرمٕژ، تہٕ کِتھہ کٔنۍ ٲس تُہند چاروٕ مےٚ سٍتـ̡ ۔\n30. تکیازِ {یہ} اوس کم یُس میانہِ برونہہ تہِ اوس، تہٕ یہ چھہ {وۅن} بٔڈِتھ بٔڈِتھ ہُریومُت۔ تہٕ خداوند چُھ میانہِ یِنہٕ پتہٕ ژے برکت دِژمٕژ: تہٕ وۄنۍ کَر بہٕ پنُن گرٕ تہِ فراہم کٔرِتھ؟ {اضافہٕ: ہیب۔ پھُٹُن} {چونکہ ...: ہیب۔ میٲنس قدمس پیٹھ}\n31. تہٕ تٔمۍ ووٚن، بہٕ کیا دِیہٕ ژےٚ؟ تہٕ یعقوبن ووٚن، ژے دِیہ نہٕ مے کانہہ چیز، اگر ژٕ میانہِ خٲطرٕ یہِ کٲم کرِ، بہٕ کرٕ بییہ پنُن کھیٚرٕ تہٕ رژھرٕ رژھرٕن:\n32.\\tبہٕ کٔرِس از تام چانہِ سارِنٕے کھورِ منز، تتہِ نِش سارِنٕے داغدار تہٕ داغدار چارو، تہٕ ژھاوٕنٮ۪ن مَنٛز سارِنٕے کاژرِ چارو، تہٕ ژھاوٕنٮ۪ن مَنٛز داغدار تہٕ داغدار چارو، تہٕ یِتھٕ کٔرِتھ آسہٕ میون کرایہٕ۔\n33.\\tیِتھے پٲٹھۍ کرِ میانہِ نیکی یِنہٕ وٲلِس وقتس سٍتـ̡ میانہِ خٲطرٕ جواب، یێلہِ سُہ میانہِ کرایہِ ہٕندِس بُتھِس برونہہ کنہِ ییہِ: پرٮ۪تھ کانہہ یُس نہٕ ژھاوٕنـ̡ مَنٛز داغدار تہٕ کۅکرِ ہٕندِس مَنٛز آسہِ، یُس میانہِ سٍتـ̡ ژوٗرِ نِنہٕ ییہِ۔ {وقتس منز...: ہیب۔ پگہہ کُن}\n34.\\tتہٕ لابن ووٚن، وُچھ، بہٕ چُھس چانہِ کلامَس مُطٲبق آسُن۔\n35.\\tتہٕ تٔمۍ کٔر تمہ دۅہہ ژھاوٕنۍ یِم رٔنگۍ تہٕ داغ ٲس، تہٕ سارِنٕے ژھاوٕل یِم داغدار تہٕ داغدار ٲسۍ، تہٕ سارِنٕے ژھاوٕنۍ یِمن منز سفید، تہٕ سارِنٕے ژھاوٕل یِمن منز سفید، تہٕ سارِنٕے کۅکرِ ہٕندِس اتھس منز، تہٕ دِژن پننین نیچوین ہٕندِس اتھس منز۔\n36.\\tتہٕ یعقوب کٔر پانس تہٕ یعقوب سٕندِس درمِیان تریہ دۅہن ہُند سفر۔\n37.\\tتہٕ یعقوبن نِن أمِس سَبٕز پوپلرٕچ لوڑ، تہٕ ہیزل تہٕ شطرنج کُلِس سٍتـ̡ ۔ تہٕ تمن منٛز کٔرٕن سفید سٹریک، تہٕ کورُن سفید ظٲہر یُس لورین منٛز {اوس}۔\n38.\\tتہٕ تٔمۍ تھووُن تِم لٔرۍ، یِم تٔمۍ آبہٕ چنہٕ خٲطرٕ گٹرَن مَنٛز کھورِ برونہہ کُن دِژمٕژ ٲس، یُتھ زن تِم چنہٕ یِنہٕ وِزِ حاملہٕ گژھن۔\n39.\\tتہٕ کٔرِکھ لٔرِس برونہہ کُن حاملہٕ، تہٕ کٔرِکھ چاروٲے دِنہٕ آمٕتۍ۔\n40.\\tتہٕ یعقوبن کٔر کۅکرِ کۅکرِ بُتھ، تہٕ کٔرٕن لبن ہٕندِس ریوڑس کُن سارِنٕے کۅکرِ کُن۔ تہٕ تٔمۍ تھووُن پنُن پَنُن پٲٹھۍ، تہٕ تھووُن نہٕ لبان سٕندِس چارواین منٛز۔\n41.\\tتہٕ سپُد یێلہِ مضبوٗط چارواین ہٕندِس أچھن برونہہ کُن لٔرِتھ یُتھ تِم لٔرِن لٔگِس مَنٛز حاملہٕ گٔژھِتھ۔\n42.\\tمگر ییلہ چارو کمزور ٲس، تمٔۍ تھوو نہٕ تِمن منز، یِتھے پٲٹھۍ اوس کمزور لبان تہٕ یعقوب سُند۔\n43.\\tتہٕ أمِس سٍتـ̡ ہُریر تہٕ گٔیہِ وارِیاہ چاروایہ، نوکر، نوکر، تہٕ اونٹ تہٕ گَرٕ۔","1.\\tتہٕ تٔمۍ بوز لابان سٕندٮ۪ن نیچوین ہٕنز کتھ یُس سٲنِس مٲلہِ سُند اوس، یعقوبن نِش چھُ سٲنِس مٲلہِ سُند سُہ سورُے نِمُت۔ تہٕ {یہ} یُس {اوس} سٲنِس مٲلہِ سُند اوس، أمِس مِلیوٚو یہِ سورُے عظمت۔\n2.\\tتہٕ یعقوب وُچھ لبان سُند بُتھ تہٕ وُچھِتھ اوس نہٕ تس کُن گوڈٕ پٲٹھۍ۔ {گوڈٕ پٲٹھۍ: ہیب۔ یِتھ کٔنۍ راتھ تہٕ برٛونٛہمہِ دۄہ}\n3. تہٕ خداوند ووٚن یعقوبس زِ پننین مٲلن ہٕندِس سرزمینس کُن واپس، تہٕ پننین رشتہ دارن کُن واپس۔ تہٕ بہٕ آسہٕ ژےٚ سۭتۍ۔\n4. تہٕ یعقوبن سوٗز تہٕ بُلووُن راحیل تہٕ لیہ پننِس ریوڑس نِش کھاہس منٛز۔\n5.\\tتہٕ وونُن تِمَن زِ بہٕ چُھس چُھس مٲلہِ سُند بُتھ وُچھان، زِ یہِ چُھنہٕ میہ سٍتـ̡ گۅڈٕ پٲٹھـ̡ ۔ مگر میٲنِس مٲلہِ سُند خدا چُھ میہ سٍتـ̡ آسان۔\n6. تہٕ ژیہ چھے پتاہ زِ بہٕ چُھس پنٕنِس مٲلِس سٍتـ̡ خدمت کٔرمٕژ۔\n7. تہٕ چُھس مٲلہِ دِژمُت تہٕ دَہ لٹہِ بدلٲوِتھ میانہِ تنخواہ بدلٲومٕژ۔ مگر خداین دیت نہ میہ تکلیف دوان۔\n8.\\tاگر تٔمۍ یِتھٕ پٲٹھۍ وَنُن چُھ، تُہٕندِس اجرَس آسہِ تُہُند معاوضہٕ۔ اَمہ پتہٕ گٔیہِ سارِنٕے چاروٲے نِش نِش تہٕ اگر تٔمۍ یِتھٕ پٲٹھۍ وَنُن زِ رِنٛگہٕ آسہِ تُہُند کرایہٕ دِنہٕ۔ پتہٕ کٔرِن سارِنٕے چاروٲے نِش رٔنگۍ۔\n9. یِتھٕ پٲٹھۍ چھُ خداین تُہٕندِس مٲلہِ سٕندِ چاروٲے نِتھ دِژمٕتۍ۔\n10.\\tتہ سپد تمہِ ساعتہ ییلہ چاروو حاملہ گوو، میہ کٔر پنن اچھ تُلتھ تہ خوابس منز وُچھمُت، تہ وُچھان یِم چارواین پیٹھ وۄٹھ دِوان ٲسۍ، تہٕ وُچھِتھ گٔیہِ رٔنگۍ لٔگۍ، پھیپھ تہٕ گٔرۍ۔ {رامس: یا، سہ ژھایہِ}\n11. تہٕ خدایہ سٕندِ فرشتہٕ کٔر میہ خوابس مَنٛز کتھ {ونان}، یعقوب: تہٕ مے ووٚنمُت، یێلہِ چُھس بہٕ\n12.\\tتہٕ تٔمۍ ووٚن، وُچھِو پنٕنۍ أچھ تُلِتھ تہٕ وُچھِو، تِم سارِنٕے کٔرِتھ یِم چارواین پیٹھ وۄٹھ دِوان چھِ، تِکیازِ مے چھُ وُچھمُت یُس لبان ژےٚ کران چھُ۔\n13.\\tبہٕ چُھس بیت لُک خدا، یێتہِ ژے تھم مسح کٔرِتھ، تہٕ یێتہِ ژے میانہِ سٍتـ̡ عہد کورمُت: وۅنۍ وُتھ، ژٕ نیرِو یَتھ زمینہٕ منزٕ نٮ۪بر تہٕ واپس۔\n14.\\tتہٕ راحیل تہٕ لیہ دیت جواب تہٕ وونُن أمِس زِ کیا سانہِ مٲلہِ سٕندِس گرس مَنٛز چھا اسہِ خٲطرٕ کانہہ حصہٕ یا وراثت؟\n15.\\tاسہِ چھا نہ تس اجنبی گنزراونہ یوان؟ تکیازِ تمۍ چھہ اسہِ کُنمت تہ سانۍ پونسہ تہِ کھٲلۍمٕتۍ۔\n16. یُس خداین سٲنِس مٲلہِ سٍتـ̡ نِش نِیومُت چُھ، یُس سانہِ تہٕ سانین شُرین ہُند چُھ، تێلہِ یُس تہِ خداین چُھہ ژیہ وَننہٕ آمُت، سُہ کرُن۔\n17.\\tیعقوب ووٚتھ تہٕ بیوُن پنٕنۍ نیچوۍ تہٕ زنانہٕ اونٹَن پیٹھ۔\n18.\\tتہٕ تٔمۍ نِتھ پنُن سٲرِے چاروا، تہٕ پنُن سورُے سامانہٕ یُس أمِس حٲصِل اوس کوٚرمُت، یُس أمِس پڈانارمس مَنٛز حٲصِل اوس کوٚرمُت، یُس کنعان کِس سرزمینس مَنٛز پننِس مٲلِس اسحاق نِش گژھنہٕ مۅکھٕ حٲصِل اوس کوٚرمُت۔\n19.\\tتہٕ لابن گۆو پنٕنۍ دانٛد ژوٗرِ تہٕ راحیلن ٲس تِم شکلہٕ ژوٗرِ نِمٕژ یِم تٔمۍ سٕندِس مٲلہِ سٕنزِ ٲس۔ {تصویر: ہیب۔ ٹیرافیم}\n20.\\tتہٕ یعقوب ژوٗرِ ژوٗرِ بے خبری منز لبان شامس کُن، یتھ منز تٔمۍ ووٚن نہٕ تس زِ سُہ ژوٚل نہٕ۔ {بے خبر...: ہیب۔ لبان سُند دِل}\n21. تہٕ ژوٚل سُہ سُہ س تہٕ سُہ ووٚتھ تھوٚد، تہٕ دریاوس اپارِ پٔکۍ، تہٕ کوٚرُن بُتھ کُن کُن کُن۔\n22.\\tتہٕ تریمہِ دۅہہ آو لابنس وننہ زِ یعقوب ژوٚل ژوٚلُن۔\n23. تہٕ تٔمۍ نِیہِ پنٕنۍ بٲے پانس سٍتۍ، تہٕ لوٚگ تس پتہٕ ستن دۅہن ہُند سفر۔ تہٕ تِمو لٔگۍ أمِس کوہ گلاڈس منٛز۔\n24.\\tتہٕ خدا آو رٲژ خوابس منز لبان شامس نِش تہٕ وونُن زِ یعقوب سٍتـ̡ گژھہِ نہ خیر تہٕ بُرٕچ کتھ کرنہٕ۔ {یا تہ...: ہیب۔ اچھ پیٹھہٕ خرابس تام}\n25.\\tلبان کٔر یعقوب پتھ کُن۔ وۅنۍ اوس یعقوب پہاڑس منز پنُن خیمہ لگٲومُت: تہٕ لبان اوس پننین باین سٍتۍ گلعاد کِس پہاڑس منز کھڑا گومُت۔\n26.\\tتہٕ لابن ووٚن یعقوبس زِ ژے کیا کوٚر ژے میہ نِش بے خبری ژوٗرِ تہٕ میانہِ کورِ تلوار ہیتھ قٲد کٔرِتھ نِتھ نِتھ۔\n27. کیازِ ژٔلِتھ تہٕ کیا ووٚن نہٕ مے زِ مے آسہ ژے خۅش ہیتھ تہٕ گیونہٕ سٍتۍ، ٹیبریٹ تہٕ ہارپ سٍتۍ سوزمُت؟ {ژوٗرِ...: ہیب۔ میہ ژورِ کٔرۍ}\n28.\\tتہٕ کیا چُھس نہٕ میہ پننین نیچوٮ۪ن تہٕ کورِ بوسہ دِنہٕ خٲطرٕ دِنہٕ آمُت؟ ژے چھکھ وۅنۍ بیوقوفی کٔرمٕژ۔\n29.\\tیہ چُھہ میانہِ اَتھٕ سٍتـ̡ چُھہ تۅہہِ تکلیف دِنہٕ خٲطرٕ، مگر تێہٕندِس مٲلہِ سٕندِس خداین وۆن پتھ رٲژ میہ سٍتـ̡ وَنُن زِ ژے کٔرِو نہٕ یعقوبس سٍتـ̡ خیر تہٕ بُرٕ کتھ کرنہٕ۔\n30.\\tتہٕ وۅنۍ چُھہ ژیہ ژیہ نیرُن، تکیازِ ژے چھکھ پننس مٲلہِ سٕندِس گرس سٍتـ̡ ژٔرِتھ ژٔل\n31.\\tتہٕ یعقوبن دیُت جواب تہٕ وونُن لابانس کیازِ بہٕ اوسُس کھوژان، تکیازِ میہ ووٚنمُت زِ ژے کٔرِکھ پننہِ کورِ زبردستی میانہِ نِش۔\n32.\\tیُس تہِ ژیہ پَنٕنـ̡ خدایہ میلان چُھ، سُہ گژھہِ نہٕ زندٕ: امہ برونہہ زِ سانین بٲے گژھن ژیہ یہ سمجھن زِ تُہند کیا چُھہ میانہِ سٍتـ̡ تہٕ نِن پانس نِش۔ تکیازِ یعقوبس ٲس نہ پتاہ زِ راحیلن ٲس تم ژورِ نِمژ۔\n33.\\tتہٕ لابن ژاو یعقوب سٕندِس خیمس منز، تہٕ لیہ سٕندِس خیمس منز، تہٕ دۅن نوکرن ہٕندِس خیمس منز۔ مگر تمس لوٚب نہٕ۔ تمہ پتہ دراو سہ لیہ سندِ خیمہ منزہ نیبر تہ ژاو راحیل سٕندِس خیمس منز۔\n34.\\tوۅنۍ ٲس راحیلن تصویرہ تُلتھ اونٹِس فرنیچرس منز تھووُن تہ بیوٹھ تمن پیٹھ۔ تہٕ لابن کٔر سارِنٕے خیمہ تلاش، مگر لوٚب نہٕ۔ {ژھانڈ: حب۔ محسوس}\n35.\\tتہٕ تٔمۍ ووٚن پننِس مٲلِس زِ میانہِ آقا گژھِ نہٕ ناراض زِ بہٕ ہیٛکہٕ نہٕ ژےٚ برونہہ کُن تھوٚد کٔرِتھ۔ تکیازِ زنانن ہُند رسم {چُھ} میانہِ پیٹھ۔ تہٕ تٔمۍ ژھانڈ، مگر لٔبۍ نہٕ شکلہٕ۔\n36.\\tتہٕ یعقوب گوٚو شرارت تہٕ لابن سٍتـ̡ ژٔٹِتھ تہٕ یعقوبن دیُت جواب تہٕ وونُن لابانس زِ میون گناہ کیا چُھہ؟ میون گۅناہ کیا چُھ، یُس ژے میانہِ پَتہٕ یُتھ پَتہٕ پَتہٕ کٔرِتھ؟\n37.\\tییلہ ژے میٲنۍ سارِنٕے سامانہٕ ژھانڈان چھِ، ژے کیا لوٚب پننہِ سارِنٕے گرِ ہُند سامانہٕ؟ یێلہِ تھٲوِو میانین باین تہٕ تہندین باین برونہہ کُن، یُتھ زن تِم اسہِ دۅشوٕنی درمیان فیصلہ کٔرِتھ۔ {تلاش: ہیب۔ محسوس}\n38.\\tیہ وُہن ؤرین چھُس میہ ژے سٍتـ̡ سٍتـ̡ {رودمُت}۔ چانہِ کۅکرِ تہٕ چانہِ ژھاوٕرۍ چھِنہٕ پنٕنۍ بچہٕ ترٛٲومٕژ، تہٕ چانہِ کھورِ ہٕندِس کۅکرِ ہٕندِس کۅکرِ ہُند کھیوٚو نہٕ۔\n39.\\tیُس ژٔٹِتھ ژٔٹِتھ اوس، سُہ اوس نہٕ ژے نِش اوٚنمُت۔ میہ چھہ امیک نقصان برداشت کران۔ میانہِ اتھہٕ سٍتۍ اوسُکھ ژٔرِتھ، دۅہلہٕ ژوٗرِ نِنہٕ آمُت یا رٲژ ژوٗرِ نِنہٕ۔\n40. {یتھہ پاٹھۍ} میہ اوسس؛ دۅہس اوس خشک سالی میہ کھیوان، تہٕ رٲژ ٲس ٹھنڈ۔ تہٕ میٲنۍ نندر گٔیہِ میانیو أچھن نِش دور۔\n41.\\tیِتھٕ پٲٹھۍ چھُس بہٕ وُہن ؤرین تہٕ تۅہہِ ہٕندِس گرس مَنٛز روٗدمُت۔ مے کٔر ژۄداہ ؤری چانہِ دۄن کورٮ۪ن خٲطرٕ تہٕ شیٚن ؤرین چانہِ چارواین خٲطرٕ، تہٕ ژے بدلٲوۍ میٲنۍ تنخواہ دَہ لٹہِ۔\n42.\\tمیٲنس مٲلہِ سُند خدا، ابراہیم سُند خدا، تہٕ اسحاق سُند خوف اوسُس میہ سٍتـ̡ اوسمُت، یقینا ژے اوسُکھ میہ وُنہِ خٲلی سوزمُت۔ خداین وچھ میٲنۍ مصیبت تہٕ میانین اتھن ہٕنز محنت، تہٕ ژے کٔر پتھ رٲژ ملامت کرنہٕ۔\n43.\\tتہٕ لابن دیُت جواب تہٕ وونُن یعقوبس زِ {یِم} کورِ چھے میٲنۍ کورِ، تہٕ {یِم} شُرۍ چھِ میٲنۍ شُرۍ، تہٕ {یِم} چاروٲے {چھِ} میٲنۍ چاروٕ، تہٕ یُس تہٕ ژے وُچھان چھُ، تہٕ بہٕ کیا ہیکہٕ از کل میانین کورٮ۪ن یا تِہندین شُرین سٍتۍ کٔرِتھ، یِم تِمو زامٕتۍ چھِ۔\n44. تێلہِ چُھہ یێلہِ چُھہ أسـ̡ اکھ عہد کرُن، بہٕ تہٕ ژے تہٕ یہ گژھہِ میہ تہٕ ژے درمیان گواہ آسُن۔\n45.\\tتہٕ یعقوب تُل اکھ کٔن، تہٕ تھووُن اکھ تھم۔\n46.\\tتہٕ یعقوبن ووٚن پننین باین زِ کٔنۍ جمع کرُن۔ تہٕ تِمو تُل کٔنہِ تہٕ اکھ ڈھیر: تہٕ تِمو کھیوٚو تتہِ ڈھیرس پیٹھ۔\n47.\\tتہٕ لابن وون اتھ جیگرسہدوتھا، مگر یعقوب اوس اتھ گلید وونمُت۔ {جیگرسہدوتھا: یعنی، گواہَن ہُند ڈھیر، چالدی} {گلید: یعنی، گواہَن ہُند ڈھیر، حب۔}\n48.\\tتہٕ لابن ووٚن زِ یہ ڈھیر چھہ از میہ تہٕ تۅہہِ درمیان گواہ۔ تَمہِ کِنۍ اوس اَمِس ناو گلید وننہٕ آمُت۔\n49. تہٕ مزپاہ۔ تکیازِ تٔمۍ ووٚن، خداوند چُھہ میہ تہٕ ژے درمِیان نظر تھاوان، ییلہ أسۍ اکھ أکِس نِش غٲب۔ {مزپاہ: یعنی اکھ بیکن، یا، واچ ٹاور}\n50.\\tاگر ژے میانین کورِ سٍتـ̡ دِیُن، یا اگر تہٕ میانین کورِ سٍتـ̡ باقٕے زنانہٕ رٔٹِو، تێلہِ چُھہ نہٕ کانٛہہ تہِ مرد اسہِ سٍتـ̡ سٍتـ� وُچھو، خدایہ چُھہ میہ تہٕ ژے درمیان گواہ۔\n51.\\tتہٕ لابن ووٚن یعقوبس زِ یہ ڈھیر وُچھِو، تہٕ وُچھِو یہِ تھم، یُس میہ تہٕ ژے درمِیان ترٛٲومُت چھُ۔\n52.\\tیہ انبار گواہ تہٕ {یہ} ستون گواہی دِیُن زِ بہٕ کٔرٕ نہٕ اتھ ڈھیرس پیٹھ ژے نِش واتناوُن، تہٕ ژٕ گژھ نہٕ اتھ ڈھیرس تہٕ اتھ تھمس پیٹھ میانہِ نِش نقصان واتناوُن۔\n53.\\tابراہیم سُند خدا، تہٕ ناحوُر سُند خدا، یُس تہندِس مٲلہِ سُند خدا، اسہِ درمیان فیصلہ کٔرِتھ۔ تہٕ یعقوب چُھ پننِس مٲلِس اسحاق سٕندِس خوفس سٍتـ̡ قسم۔\n54.\\tیعقوبن کٔر پہاڑس پیٹھ قربانی تہٕ بُلووُن پننین باین روٹی کھٮ۪نہٕ خٲطرٕ، تہٕ تِمو کھیوٚو روٹی تہٕ روٗدۍ سارِوٕے رٲژ پہاڑس مَنٛز۔ {پیشکش...: یا، مارۍ درندٕ}\n55.\\tتہٕ صُبحٲے ووٚتھ لبان ووٚتھ، تہٕ پننٮ۪ن نیچوٮ۪ن تہٕ کورٮ۪ن بوسہ دِتھ دِژُن تہٕ دُعا دِژُن تہٕ لبان دراو تہٕ ووت پننہِ جایہ واپس۔","1.\\tتہٕ یعقوب پوٚت پننہِ وتہِ، تہٕ خدایہِ سٕندِ فرشتہٕ گٔیہِ أمِس سٍتـ̡ سمکھنہٕ۔\n2.\\tییلہ یعقوب یِم وُچھِ، تٔمۍ ووٚن یہِ خدایہِ سُند میزبان، تہٕ تٔمۍ ووٚن اَتھ جایہِ ہُند ناو مہانیم۔ {مہنایم: یعنی زٕ میزبان، یا، کیمپ}\n3.\\tتہٕ یعقوبن سوٗزۍ تس برونہہ کُن پیغمبر پننِس بٲیِس عیساو نِش یُس ادوم کِس ملکس منز سیر کِس سرزمینس مُتلِق اوس۔ {ملک: ہیب۔ فیلڈ}\n4.\\tتہٕ تٔمۍ دِیُت تِمن حُکُم زِ یِتھٕ پٲٹھۍ کٔرِو تُہۍ میٲنِس آقا عیساو سٍتـ̡ کتھ کرنہٕ۔ تُہند خادم یعقوب چُھ یِتھٕ پٲٹھۍ ونان زِ بہٕ چُھس لابانس سٍتـ̡ روزمُت، تہٕ وُنیُک تام روٗدمُت:\n5. تہٕ مےٚ چھِ بیل، گَر، گَرٕ تہٕ نوکر تہٕ خادم، تہٕ بہٕ چُھس پننِس آغس وننہٕ خٲطرٕ سوزمُت، یُتھ بہٕ تُہٕندِس نظرس منز فضل میلہٕ۔\n6. تہٕ رسول آو یعقوب نِش واپس، یہِ وَنُن زِ أسۍ آیہ تُہنٛدِس بٲیِس عیسوس نِش، تہٕ سُہ تہِ آو تۅہہِ سٍتـ̡ مِلنہٕ خٲطرٕ، تہٕ تس سٍتـ̡ ژور ہتھ نفر تہِ۔\n7.\\tیعقوب گوٚو سٮ۪ٹھاہ خوفزدہ تہٕ پریشان، تہٕ تٔمۍ کٔرٕن پانس سٍتـ̡ لُکھ تہٕ ریوُن، تہٕ گٔیہِ تہٕ اونٹھ دۄن جمٲژن مَنٛز تقسیم۔\n8.\\tتہٕ وونُن، یێلہِ عیسو أکِس جمٲژ نِش یِیہِ تہٕ أمِس مارٕ دِیہِ، تیلہِ گژھہِ بیٛاکھ کمپنی یُس بچان آسہِ۔\n9. تہٕ یعقوب ووٚن، اے میٲنِس مٲلِس ابراہیم سُند خدا، تہٕ میٲنِس باپ اسحاق سُند خدا، یُس میہ ووٚنمُت چھُ، پنہٕ نِس ملکس کُن واپس، تہٕ پنہٕ نِس رشتہٕ دارن کُن واپس، تہٕ بہٕ کرٕ ژے سٍتـ̡ رژھ رژھ رٔٹ۔\n10. بہٕ چُھس نہٕ سارِنٕے رحمتَن تہٕ سارِنٕے حقیقتس لایق، یُس ژے پننِس خادمس ہٲومُت چھُ۔ تکیازِ بہٕ اوسُس پننِس عٲلمہٕ سٍتـ̡ یَتھ اردنس کُن گذران۔ تہٕ وۄنۍ چھُس بہٕ زٕ بینڈ بنیمٕتۍ۔ {میہ چھہ نہ...: ہیب۔ بہٕ چھُس سارِنٕے کھۄتہٕ کم}\n11.\\tبہٕ چھُس ژے پننِس بٲے سٕندِ اتھہٕ نِشہ عیسو سٕندِ اتھہٕ نِش نجات دِنٕچ دعا کران، کیازِ بہٕ چُھس أمِس کھوژان زِ سُہ یِنہٕ تہٕ یِنہٕ سٍتـ̡ یِنہٕ سٍتـ̡ تہٕ ماجہ ہٕندِس شُرِس سٍتـ̡ دِنہٕ۔ {سۭتۍ: ہیب۔ اَپَن}\n12. تہٕ ژے ووٚن، بہٕ کٔرٕ ژے نیکی تہٕ تُہند بیول بناوٕ سمندرٕچ سیکہِ ہٕندۍ پٲٹھۍ، یُس نہٕ بٔڑۍ بٔڑِس سٍتـ̡ گٔنزراوِتھ ہیکو نہٕ۔\n13. تہٕ سُہ روٗد اَمی رٲژ اَتہِ روزان۔ تہٕ تٔمۍ سٕندِس اتھس منز یُس عیسو سٕندِس بٲیِس خٲطرٕ تحفہٕ دِنہٕ آمُت اوس۔\n14.\\tزٕ ہتھ ژھاوٕل تہٕ وُہ ژھاوٕر، زٕ ہتھ کۅکرِ تہٕ وُہ کۅکر۔\n15.\\tترہ دۄدٕ اونٹ، ژتٲجی گٲر تہٕ داہ داند ، وُہ گٔرِ تہٕ داہ بچہٕ۔\n16.\\tتہٕ تٔمۍ دِژ تِمن پننین خدمتگارن ہٕندِس اتھس منز، پرٮ۪تھ کانہہ اوس پانَے پانَے چلاوان۔ تہٕ ووٚنُن پننٮ۪ن خادمَن ، میانہِ برونہہ کُن نیرُن، تہٕ تھووُن گٲڑۍ چلاونَس تہٕ گٲڑۍ چلاونَس درمیان اکھ جاے۔\n17.\\tتہٕ تٔمۍ دِیُت سارِوٕے کھۄتہٕ برٛونٛہمِس حُکُم کٔرِتھ، یێلہِ یێلہِ عیسیٰ میون بٲے ژےٚ مِلِتھ تہٕ ژےٚ پرژھہِ، تہٕ وۆنُن زِ تُہۍ کُس چُھہ؟ تہٕ کوٚت چھکھ ژیہ گٔژھمٕژ؟ تہٕ یِم کٔمۍ سٕندِ برونہہ کُن؟\n18.\\tتیلہِ گژھہِ تۅہہ ونُن، {تِم آسن} تُہند خادم یعقوب سٕندِ۔ یہِ چُھہ میٲنِس آقا عیسوس سوزنہٕ آمُت اکھ تحفہٕ: تہٕ وُچھِو سُہ تہِ چُھہ اسہِ پَتہٕ پَتہٕ۔\n19.\\tتہٕ یِتھٕ پٲٹھۍ دِیُت تٔمۍ دویمِس تہٕ تریٚیمِس تہٕ سارِنٕے یِمن ہٕندِس لٔبِس سٍتـ̡ حُکُم تہٕ وَنُن زِ یِتھٕ پٲٹھۍ کٔرِو عیسوس سٍتـ̡ کتھ کرنہٕ۔\n20. تہٕ وُچھِو تُہُند خادم یعقوب اسہِ پَتہٕ پَتہٕ۔ تکیازِ تٔمۍ ووٚن، بہٕ کٔرٕ تس تسٕندِ بُتھ یُس میہ برونہہ کُن یِنہٕ وول تحفہٕ سٍتۍ خوش کٔرِتھ، تہٕ پتہٕ وُچھٕ بہٕ تٔمۍ سُند بُتھ وُچھان۔ شاید سُہ کرِ میہ قبول۔ {میہ منز: ہیب۔ میون بُتھ}\n21.\\tیتھے پاٹھۍ گۆو تس برونہہ کنہِ موجود: تہ پانہ اوس تمہ رٲژ صحبتس منز روزان۔\n22.\\tتہٕ سُہ ووٚتھ تَمہِ رٲژ تہٕ رٔٹِتھ پنٕنۍ زٕ خانٛدارِن، تہٕ پنٕنۍ زٕ زنانہٕ تہٕ کاہ نیچوِ، تہٕ ژٔٹِتھ گٔیہِ فورڈ جبوک۔\n23.\\tتہٕ تٔمۍ رٔٹِتھ تہٕ سوٗزِن تِم نالہٕ اپارِ تہٕ سوٗزُن یُس أمِس نِش اوس۔ {سوزمُت: ہیب۔ گزرُن}\n24. تہٕ یعقوب آو کُنی زُن۔ تہٕ تتہِ رود أمس سٍتۍ أکِس شخژس سٍتۍ کُشتی دۅہہ پھُٹنس تام۔ {بریکنگ...: ہیب۔ صبحُک کھسُن}\n25.\\tتہٕ ییلہ أمس وُچھ زِ سُہ چُھ نہٕ أمِس خٕلاف غلبہٕ حٲصل کٔرِتھ، تٔمۍ لوٚگ پننہِ رانہِ ہٕندِس کھوکھرِس پیٹھ اتھہٕ۔ تہ یعقوب سنزِ رانچ کھوکھر ٲس نیبر، ییلہ سہ أمس سیتۍ کشتی کران اوس۔\n26. تہٕ تٔمۍ ووٚن، مے گژھ گژھُن، یُس دۅہ پھُٹان چُھ۔ تہٕ تٔمۍ ووٚن، بہٕ دِیہ نہٕ ژےٚ نیرُن، یوٚت تام نہٕ ژٕ مےٚ دُعا دِیہِ۔\n27.\\tتہٕ تٔمۍ ووٚن تُہند ناو کیا چُھ؟ تہٕ أمۍ ووٚن جیکب۔\n28.\\tتہٕ ووٚن تُہند ناو یعقوب بٔلکہِ اسرٲیل، تکیازِ ژے چُھہ أکِس شہزادس سٍتـ̡ خدایہ سٍتـ̡ تہٕ انسانس سٍتـ̡ اقتدار حٲصل کٔرِتھ تہٕ چُھہ فتح حٲصل کٔرمٕژ۔ {اسرائیل: یعنی خدایہ سُند شہزادہ}\n29.\\tتہٕ یعقوبن پرژھ تہٕ وونُن، وَنُن {مے}، بہٕ چُھس چانہِ ناو دُعا کران۔ تہٕ تٔمۍ ووٚن، یہِ کیازِ چھُکھ میون ناو پرژھان؟ تہٕ تٔمۍ کٔر تٔمِس اَتہِ دُعوا۔\n30.\\tتہٕ یعقوبن ووٚن پینیئل جایہِ ہُند ناو، تکیازِ مے چُھہ خدایہ بُتھِ بُتھِ وُچھمُت، تہٕ میٲنۍ زندگی چھے رژھراونہٕ آمٕژ۔ {پینیل: یعنی خدایہ سُند بُتھ}\n31. تہٕ ییلہ سُہ پینویلس پیٹھ پکان اوس، آفتاب ووت تس پیٹھ، تہٕ سُہ رُکاو پننِس رانس پیٹھ۔\n32.\\tلہذا چھہ نہ بنی اسرائیل سٍتـ̡ سُہ کھیوان یُس از تام رانہِ ہندس کھوکھرس پیٹھ ژھوٚٹمت اوس، تکیازِ تٔمۍ اوس یعقوب سٕنزِ رانہِ ہٕندِس کھوکھرِس سٍتـ̡ اتھہٕ لاگان۔","1. تہٕ یعقوبن کٔر أچھ تُلِتھ تہٕ وُچھُن عیسیٰ تہٕ أمِس سٍتـ̡ ژور ہتھ نفر۔ تہٕ تٔمۍ کٔر شُرۍ لیاہس تہٕ راحیلس تہٕ دون داین تام تقسیم۔\n2.\\tتہٕ تٔمۍ تھووُن دٲیرٕ تہٕ تِہندِ شُرِ برونہہ کُن، تہٕ لیہ تہٕ تٔمۍ سٕندِس شُرِ تہٕ راحیل تہٕ یوسف رُکاوٹ۔\n3.\\tتہٕ سُہ گۆو تِمن برونہہ کُن تہٕ سَتھ لٹہِ نمُت زٔمیٖنس پیٹھ، یوٚت تام سُہ پننِس بٲیِس نِش ووتُن۔\n4.\\tتہٕ عیسو ژوٚل أمِس سمکھنہٕ خٲطرٕ، تہٕ رٔٹِتھ گٔیہِ أمِس گٔژھِتھ تہٕ لوٚگُن أمِس بونہٕ۔\n5.\\tتہٕ تٔمۍ کٔر أچھ تُل، تہٕ وُچھن زنانہٕ تہٕ شُرۍ۔ تہٕ ووٚنن، تم کُس چِھہ ژےٚ سٍتۍ؟ تہٕ تٔمۍ ووٚن، تِم شُرۍ یِم خداین تُہٕندِس خادمَس دِژمٕژ چھِ۔ {with...: Heb. توے کُن}\n6.\\tاَمہِ پَتہٕ آیہِ دٲیرٕ نزدیک، تِم تہٕ تِہٕندِ شُرۍ، تہٕ تِمو گٔیہِ نمُن۔\n7.\\tتہٕ لیہ تہِ آیہ پننین شُرین سٍتـ̡ نزدیک، تہٕ کٔرٕن نمُن، تہٕ پَتہٕ آو یوسف تہٕ راحیل، تہٕ تِمو کٔر نمان۔\n8.\\tتہٕ تٔمۍ ووٚن، ژے کیا چُھس اتھ سارِنٕے سٍتـ̡ یُس بہٕ سمکھہٕ چُھس؟ تہٕ تٔمۍ ووٚن، {یِم} چھِ میانہِ آقا سٕندِس نظرس منز فضل حٲصل کرنہٕ خٲطرٕ۔ {کیا...: ہیب۔ یہ سورے بینڈ کیا چُھ ژےٚ خٲطرٕ؟}\n9.\\tتہٕ عیساو ووٚن، میہ چُھہ کٲفی، میانہِ بٲے۔ یُس ژے پانس تام تھاوُن۔ {کیپ...: ہیب۔ تۅہہ آسہِ تۅہہِ سٍتۍ}\n10. تہٕ یعقوبن ووٚن، نہ، بہٕ چُھس ژےٚ دُعا کٔرتھ، یێلہِ وُنہِ میہ چانہِ نظرِ منز فضل میلہِ، تێلہِ کٔرِو میون تحفہٕ میانہِ اتھس پیٹھ، تێکیازِ تێلہِ چُھہ میہ تُہند بُتھ وُچھمُت، یێلہِ زن میہ خدایہ سُند بُتھ وُچھمُت اوس، تہٕ ژٕ ٲسکھ میہ سٍتـ̡ خۅش گٔمٕژ۔\n11. رٔٹِو، بہٕ چھُس ژے دُعا کٔرِتھ، میون دُعا یُس ژے تام واتناونہٕ آمُت چھُ۔ تکیازِ خداین چھہ میہ سٍتۍ مہربانی کٔرمٕژ، تہٕ کیازِ میہ چھہ کٲفی۔ تہٕ تٔمۍ کٔر أمِس زور دِنہٕ، تہٕ تٔمۍ رٔٹِتھ {یہ}۔ {کافی: ہیب۔ سارِنٕے چیٖز}\n12. تہٕ تٔمۍ ووٚن، أسۍ پَنُن سفر کرُن، تہٕ گژھو تہٕ بہٕ گژھٕ ژےٚ برونہہ کُن۔\n13.\\tتہٕ تٔمۍ ووٚن أمِس زِ میانہِ آقا چُھ پتاہ زِ شُرۍ چھِ نرم تہٕ بچہٕ تہٕ بچہٕ چھِ میہ سٍتۍ، تہٕ اگر انسان اکہِ دۅہہ یِمن ہٕندِس سٍتـ̡ ژٔلِتھ تہٕ سارِوٕے کھورِ مرُن۔\n14.\\tبہٕ چُھس ژے دُعا کران زِ بہٕ گژھہِ پننِس خادمس برونہہ کُن نیرُن، تہٕ بہٕ کرٕ نرمی سان برونہہ کُن یُس میہ برونہہ کُن گژھان چُھس تہٕ شُرۍ گژھن برداشت کٔرِتھ، یوتام بہٕ پننِس آقا سیٖرس نِش واتہٕ۔ {مطٲبق...: ہیب۔ کامہِ ہندِ کھۅر بیترِ مطٲبق تہ بچن ہندِ کھۅر مطابق\n15.\\tتہٕ عیساون ووٚن، بہٕ چُھس وۅنۍ ژے سٍتـ̡ تِمن لُکن سٍتـ̡ نیرُن یِم {چِھ} میہ سٍتـ̡ چِھہ تہٕ ووٚن امچ کیا ضرورت؟ میہ میلہِ پننِس رب سٕندِس نظرس منز رحمت۔ {تراوُن: ہیب۔ سیٹ، یا، پلیس} {کیا...: ہیب۔ یہِ کیازِ چھُ؟}\n16. تہٕ عیسو آو تمہِ دۅہہ سیر کُن واپس۔\n17.\\tتہٕ یعقوب کٔر سکوتھس کُن سفر، تہٕ بنوو أمِس اکھ مکانہٕ، تہٕ بنووُن پننین چارواین ہٕندِ خٲطرٕ بوتھ، تَمہِ کِنۍ چُھ اتھ جایہِ ہُند ناو سوکوتھ ونان۔ {سوکوتھ: یعنی بوتھس}\n18.\\tتہٕ یعقوب آو شیکیمُک أکِس شہر، یُس کنعان کِس سرزمینس مَنٛز چھُ، ییلہ سُہ پڈانارم پیٹھٕ آو۔ تہٕ لوٚگ شہرس برونہہ کنہِ پنُن خیمہ ۔ {شیکیم: Gr. Sychem}\n19.\\tتہٕ تٔمۍ ہیوٚت أکِس کھہُک اکھ ٹُکر، ییتہِ تٔمۍ شیکیم سٕندِس مٲلِس حمور سٕندِس شُرین ہٕندِس دٔسۍ پنُن خیمہ بٔنِتھ ہتھ پونسہٕ دِتھ۔ {ہیمور: Gr. Emmor} {ٹُکرٕ...: یا، کٹہٕ بچہٕ}\n20.\\tتہٕ تٔمۍ کٔر اَتہِ اکھ قربان گاہ کھڑا تہٕ وونُن اَتھ ایلوہی اسرٲیل۔ {Elelohe-Israel: یعنی خدا چُھ اسرٲیلُک خدا}","1.\\tتہٕ لیہ سٕنز کورِ دینا، یۅسہٕ یعقوبس نِش زٲژ، گٔیہِ زمینہٕ چہِ کورِ وچھنہٕ خٲطرٕ۔\n2. تہٕ ییلہ ملکُک شہزادہ حمور سٕندِ نیچوِس شیخمن وُچھ، تٔمۍ نِش أمِس نِش تہٕ لوٚگ أمِس سٍتـ̡ تہٕ کٔرٕن أمِس ناپاک ۔ {ناپاک ...: ہیب۔ أمِس کٔر عاجز}\n3.\\tتہٕ تٔمۍ سُند روح روٚٹ یعقوب سٕنزِ کورِ دیناہ سٍتـ̡ تہٕ أمِس کورُن لڑکہِ سٍتـ̡ محبت، تہٕ کورُن لڑکہِ سٍتـ̡ مہربانی سٍتـ̡ کتھ کرنہٕ۔ {مہربانی...: ہیب۔ لڑکی ہٕندِس دلس تام}\n4.\\tتہٕ شیکیمَن ووٚن پننِس مٲلِس حمورس سٍتـ̡ وَنُن زِ مے أنِو یہِ زنانہٕ خٲطرٕ۔\n5.\\tتہٕ یعقوب بوز زِ تٔمۍ کٔر پننہِ کورِ دیناہ ناپاک کٔرمٕژ، وۅنۍ اوس تٔمۍ سٕندِس نیچوِس کھاہس مَنٛز تہٕ یعقوب روٗد توٚت تام خاموش یوٚت تام تِم یِمن ہٕندِس یِنس سٍتـ̡ ۔\n6. تہٕ شیکیم سُند مول ہیمور دراو یعقوب نِش أمِس سٍتـ̡ کتھ کرنہٕ خٲطرٕ۔\n7.\\tتہٕ یعقوب سٕندِ نیچوۍ درٛاو میدانہٕ منزٕ ییلہ تِمو بوٗزِ، تہٕ مرد گٔیہِ غمگسار تہٕ تِم گٔیہِ سٮ۪ٹھاہ شرارت، تکیازِ تٔمۍ ٲس یعقوب سٕنزِ کورِ سٍتـ̡ بیوقوفی کٔرمٕژ، تکیازِ تٔمۍ ٲس یعقوب سٕنزِ کورِ سٍتـ̡ بیوقوفی کٔرمٕژ۔ کُس چیز گژھہِ نہٕ کرُن۔\n8.\\tتہٕ ہمورن کٔر تِمن سٍتـ̡ کتھ باتھ کٔرِتھ زِ میانہِ نیچوِس شیکیم سُند روح چُھہ چانہِ کورِ ہٕندِ خٲطرٕ طمع کران: بہٕ چُھس دُعا کران زِ ژٕ دِیُن أمِس زنانہٕ۔\n9. تہٕ کٔرِو اسہِ سٍتـ̡ خاندر تہٕ پَنٕنہِ کورِ دِیُن اسہِ نِش تہٕ نِیُن سٲنۍ کورِ پانس نِش۔\n10. تہٕ تُہۍ روزو اسہِ سٍتـ̡ تہٕ زمین آسہِ توے برونہہ کُن۔ اَتھ منز روزو تہٕ تجارت کٔرِو، تہٕ اَتھ مَنٛز حٲصِل کٔرِو۔\n11. تہٕ شیکیمَن ووٚن پننِس مٲلِس تہٕ پننِس باین زِ بہٕ دِیُن چانہِ نظرن مَنٛز فضل تہٕ یُس تہٕ ژٕ مے وَنُن بہٕ دِیہٕ۔\n12.\\tمیہ منگ نہ زانہہ تہِ داج تہٕ تحفہٕ، تہٕ بہٕ دِیہ مُطٲبق یُتھ ژے میہ وَنُن: مگر مے دِیُن زنانہٕ دِنہٕ۔\n13.\\tتہٕ یعقوب سٕندِس نیچویو دیُت شیکیم تہٕ حمورس پننِس مٲلِس دھوکہٕ دِتھ جواب تہٕ وونُن، کیازِ تٔمۍ ٲس تِہٕنزِ بینہِ دیناہ ناپاک کٔرمٕژ:\n14. تہٕ تِمو ووٚن تِمن زِ أسۍ ہیٛکو نہٕ یہِ کٲم کٔرِتھ، پنٕنۍ بینہِ یُس ختنہ نہٕ آسہِ۔ اَمہ مۅکھٕ ٲس اسہِ خٲطرٕ اکھ ملامت :\n15. مگر اتھ مَنٛز کرو أسۍ ژےٚ رضامندی دِوان: اگر تہٕ أسـ̡ ہِش بٔنِو، تێلہِ گژھہِ پرٮ۪تھ کانہہ مرد ختنہ کرنہٕ یُن۔\n16. تیلہِ کرو أسۍ پنٕنۍ کورِ ژےٚ دِنہٕ، تہٕ أسۍ نِو چانۍ کورِ پانس نِش، تہٕ أسۍ بٔنِو توے سٍتـ̡ تہٕ أسۍ بٔنِو اَکھ لوک۔\n17. مگر اگر نہٕ اسہِ بوزو، ختنہ کرُن۔ تیلہ نِو أسۍ پنٕنۍ کورِ تہٕ أسۍ نیرِو۔\n18.\\tتہٕ یِہٕندِس کلامَس سٍتـ̡ خۅش گٔیہِ حمورس تہٕ شکیم حمورُن نیچو۔\n19.\\tتہٕ نوجوانَن کٔر یہِ کٲم نہ کرنہٕ خٲطرٕ مُلت، تکیازِ أمِس اوس یعقوب سٕنزِ کورِ سٍتـ̡ خۅش تہٕ سُہ اوس پننِس مٲلہِ سٕندِس سارِنٕے گرٕ کھۅتہٕ زیادٕ عزتدار۔\n20.\\tتہٕ تٔمۍ سُند نیچو حمور تہٕ شیکیم آو تہندِس شہرٕ کِس دروازس پیٹھ، تہٕ وونُن پننِس شہرٕ کین نفرن سٍتـ̡ کتھ باتھ\n21.\\tیِم نفر چھِ اسہِ سٍتـ̡ امن تھاوان؛ لہذا گژھن تم زمینس منز روزُن، تہٕ اَتھ منز گژھن تجارت۔ زمینہٕ خٲطرٕ، وُچھ، {یہٕ} چُھ تِہندِ خٲطرٕ کٲفی بٔڑ۔ أسۍ نِو تِہٕنٛزِ کورِ پانس نِش زنانہٕ خٲطرٕ، تہٕ دِیِو تِمن پنٕنۍ کورِ۔\n22.\\tصرف اتھ منز گژھن مرد اسہِ سٍتـ̡ روزنہٕ خٲطرٕ، اکھ قوم بننہٕ خٲطرٕ رضامندی دِن، یێلہِ اسہِ منزٕ پرتھ کانہہ مرد ختنہ کرنہٕ ییہِ، یێلہِ زن تِم ختنہ کرنہٕ آمٕتۍ۔\n23.\\tتِہُند چارواے تہٕ تِہُند مال تہٕ تِہُند پرٮ۪تھ کانہہ جانور آسہِ نہٕ سٲنِس سٍتـ̡ ؟ صرف گژھو أسۍ تمن سٍتۍ رضامندی دِنۍ، تہٕ تِم روزن اسہِ سٍتـ̡ روزن۔\n24.\\tتہٕ ہمورس تہٕ شیکیمس تام بوز تٔمۍ سٕندِس نیچوِس سٍتـ̡ یُس تٔمۍ سٕندِس شہرٕ کہِ دروازٕ منزٕ نیبر نیران اوس۔ تہٕ پرٮ۪تھ أکِس مردس اوس ختنہ کرنہٕ آمُت، یُس أمۍ سٕندِ شہرٕ کہِ دروازٕ منزٕ نیبر نیران اوس۔\n25. تہٕ تریمہِ دۅہہ سپد یۅسہٕ یعقوب سٕندیو زٕ نیچوۍ، شمعون تہٕ لیوی یُس دینہ سٕندِ بٲے اوس، پریتھ أکِس نِش تلوار نِش تہٕ دِلیری سان شہرس منز وٲتِتھ مارِکھ سارِنٕے مرد۔\n26.\\tتہٕ تِمو مارۍ حمور تہٕ شیکیم تٔمۍ سُند نیچو تلوار ہٕندِ کُنہِ کُنہِ سٍتـ̡ تہٕ نِیوُن دینہ شیکیم سٕندِ گَرٕ منزٕ نٮ۪بر تہٕ نٮ۪بر نیرِ۔ {ایج: ہیب۔ ٲس}\n27.\\tیعقوب سٕندِ نیچوۍ آو مقتولن نِش تہٕ کوٚرُکھ شہر برباد، تکیازِ تِمو ٲس پننہِ بینہِ ناپاک کٔرمٕژ۔\n28.\\tتِمو رٔٹۍ پنٕنۍ کۅکر، تہٕ تِہٕندِس گَردٕ تہٕ یُس شہرس مَنٛز اوس، تہٕ یُس کھاہس مَنٛز اوس،\n29.\\tتہٕ تِہُند سورُے مال، تہٕ تِہٕندِس سارِنٕے لۄکٹۍ شُرۍ، تہٕ تِہٕنزِ زنانہٕ رٔٹِتھ تہٕ کٔرٕکھ گرس مَنٛز موجود سورُے چیز تہِ برباد۔\n30.\\tتہٕ یعقوبن ووٚن شمعون تہٕ لاویَس زِ تۅہہ چُھہ میہ تنگ کٔرِتھ زِ میہ کٔرِو زمینہٕ کین بسکینن، کنعانی تہٕ پیرِزِین مَنٛز، تہٕ بہٕ چُھس تعدادس منز کم آسنہٕ کِنۍ، تِم کٔرِن پانس مُتلق جمع تہٕ مارُن مےٚ۔ تہٕ بہٕ گٔیہٕ تباہ کرنہٕ، بہٕ تہٕ میون گرٕ۔\n31.\\tتہٕ تِمو ووٚن زِ سُہ پزِ سانہِ بینہِ سٍتۍ بدکار سٍتۍ سلوک کرُن؟","1. تہٕ خداین ووٚن یعقوبس زِ وۅتھ، وۅتھ، بیتھلس تام گژھ تہٕ اتہِ روزُن، تہٕ اتہِ بنوو خدایہ سٕندِ خٲطرٕ اکھ قربان گاہ، یُس ژے ظٲہر سپدِ، یُس ژے عیسو سٕندِس بُتھِس پیٹھ ژٔلِتھ ۔\n2.\\tیعقوبن ووٚن پننِس گرس تہٕ أمِس سٍتـ̡ سارِنٕے سٍتـ̡ یِمن عجیب دیوتا ترٲوِو تہٕ صاف گژھِو تہٕ پَنٕنۍ پَلَو بدلاوٕنـ̡ ۔\n3. تہٕ أسۍ وۅتھان تہٕ بیتھلس تام گژھُن۔ تہٕ بہٕ بناوٕ اتہِ خدایہ سٕندِ خٲطرٕ اکھ قربان گاہ، یٔمۍ میانہِ مصیبت ہٕندِس دۅہہٕ جواب دِیُت، تہٕ یُس بہٕ گٔژھمُت اوس، تتھ وتہِ اوس مےٚ سٍتـ̡ ۔\n4.\\tتہٕ یِمو دِژ یعقوبس سٲری عجیب دیوتا یِم تہندِس اتھس مَنٛز ٲسۍ، تہٕ تِہندِ سارِنٕے بالہٕ یِم تہندِس کنن مَنٛز ٲسۍ۔ تہٕ یعقوبن کٔر تم بلوطس تل ژورِ یُس شیکیمس {اوس}۔\n5.\\tتہٕ تِمو گٔیہِ سفر تہٕ خدایہِ سُند خوف اوس تِمن شہرن پیٹھ یِمن اندۍ پٔکھۍ ٲس، تہٕ تِمو کٔر نہٕ یعقوب سٕندِس نیچوِس پَتہٕ پَتہٕ۔\n6. یعقوب آو لوزس نِش، یُس {چُھ} کنعان کِس سرزمینس مَنٛز، یعنی {is}، بیتھل، سُہ تہٕ تِم سٲری لُکھ یِم أمِس سٍتـ̡ ٲسۍ۔\n7.\\tتہٕ تٔمۍ بنوو اَکھ قربان گاہ، تہٕ وَنُن اَتھ جایہ ایلبیتھل، تکیازِ تتہِ آو خدا أمِس نِش ظٲہر، ییلہ سُہ پننِس بٲے سٕندِس بُتھِ نِش ژٔلِتھ ژٔلِتھ۔ {البیتھل: یعنی بیت لُک دیوتا}\n8.\\tمگر دبورہ ربیکا سنز نرس گٔیہ، تہٕ سۅ آیہ بیتھلس تل أکِس بلوطس تل دفن کرنہٕ: تہٕ اتھ ناو اوس ایلونباچوتھ وننہٕ۔ {ایلن باچوتھ: یعنی روونُک اوک}\n9.\\tتہٕ خدا آو یعقوبس نِش دُبارٕ ظٲہر، ییٚلہِ سُہ پڈانارم پٮ۪ٹھٕ درٛاو، تہٕ دِتُن أمِس دُعا دِنہٕ۔\n10. تہٕ خداین ووٚن تٔمِس زِ تُہند ناو چُھہ یعقوب تہٕ تُہند ناو یعقوب یُس نہٕ وَننہٕ یُن، مگر اسرٲیلُک ناو گژھہِ تُہند ناو تہٕ تٔمۍ ووٚن تٔمۍ سُند ناو اسرٲیل۔\n11. تہٕ خداین ووٚن تس زِ بہٕ چُھس خدایہ قادر مطلق چُھس: پھل دار گژھ تہٕ بڑاوُن؛ اکھ قوم تہٕ قومن ہٕنز اکھ جماعت آسہِ تۅہہِ منز، تہٕ بادشاہ گژھن تُہنزِ کمرہ منزٕ نیرن۔\n12. تہٕ یُس زمین میہ ابراہیم تہٕ اسحاق دِژمُت چھُ، بہٕ دِیہ تہٕ ژے پتہٕ دِیہٕ تہٕ ژےٚ پتہٕ دِیہٕ تہٕ ژےٚ سٕندِس نسلس دِیہٕ زمین۔\n13. تہٕ خدا ووت أمِس نِش تتھ جایہِ ییتہِ أمِس سٍتـ̡ کتھ کٔر۔\n14.\\tتہٕ یعقوبن کٔر تتھ جایہِ اکھ تھم، یێلہِ أمِس سٍتـ̡ کتھ ٲس کٔرمٕژ، تہٕ تٔمِس ترووُن اَتھ پیٹھ تیٖل۔\n15.\\tتہٕ یعقوبن ووٚن تمہِ جایہِ ہُند ناو ییتہِ خداین أمِس سٍتـ̡ کتھ کٔر، بیتھل۔\n16.\\tتہٕ تِمو کٔر بیتھل پیٹھٕ سفر۔ تہٕ افراتس تام واتنچ ٲس صرف کم وتھ: تہٕ راحیلن کٔر سختی تہٕ تٔمِس ٲس سخت محنت۔ {تھوڑا ...: ہیب۔ زمینُک اکھ لۄکُٹ ٹُکر}\n17.\\tتہ ییلہ سۅ سخت محنت کران ٲس، دٲی ووٚن أمس زِ نہ ڈر نہ۔ ژے گژھہِ یہِ نیچو تہِ۔\n18.\\tتہٕ ییلہ تٔمۍ سُند روح نیران اوس، (تکیازِ سۅ ٲس مٔرۍ) تٔمۍ سُند ناو بینونی وونُن، مگر تٔمۍ سُند مول اوس أمس بینجمن۔ {بینونی: یعنی میانہِ غمُک نیٚچُو} {بینجمن: یعنی دچھنہِ اتھہٕ سُند نیٚچُو}\n19.\\tتہٕ راحیل مٔرۍ، تہٕ آیہ افرات کِس وتہِ مَنٛز دفن کرنہٕ، یُس بیت اللحم چُھ۔\n20. تہٕ یعقوبن تھوو تٔمۍ سٕنزِ قبرِ پیٹھ اکھ تھم: یۅسہٕ از تام راحیل سٕنزِ قبرِ ہُند ستون چُھ۔\n21. تہٕ اسرٲیلَن کٔر سفر تہٕ کوٚرُن پنُن خیمہ ایدار کِس برتہٕ نیبر۔\n22.\\tتہٕ سپُد یہِ سپدُن، ییلہ اسرٲیلِس اَتھ زمینس مَنٛز روزان اوس، زِ روبن گۆو تہٕ پننِس مٲلہِ سٕنزِ لونڈی بلحاہ سٍتـ̡ لوٚگ۔ وۅنۍ ٲسۍ یعقوب سٕندِ نیچوۍ باہ وُہُر:\n23. لیہ سٕندۍ نیٚچوۍ۔ روبن، یعقوب سُند گۅڈنیُک زامُت، تہٕ شمعون تہٕ لیوی، تہٕ یہوداہ، تہٕ عیساکر، تہٕ زبولون:\n24. راحیل سٕندۍ نیٚچوۍ۔ جوزف تہٕ بینجمن:\n25.\\tتہٕ بلہہ سٕندِ نیچوۍ، راحیل سٕنز دٲیر؛ ڈین، تہٕ نفتالی:\n26.\\tتہٕ لیہ سٕنزِ دٲیرِ زِلپاہ سٕندِ نیچو۔ گاد، تہٕ آشر: یِم چھِ یعقوب سٕنٛدۍ نیٚچِوۍ، یِم أمِس پڈانارمس منٛز زامٕتۍ ٲسۍ۔\n27.\\tتہٕ یعقوب آو اسحاق نِش پننِس مٲلِس ممرے، اربہ شہرس مَنٛز، یُس حبرون چھُ، یَتہِ ابراہیم تہٕ اسحاق روزان ٲسۍ۔\n28. تہٕ اسحاق سٕندِ دۅہ ٲسۍ ہتھ ژۅن ؤری۔\n29.\\tتہٕ اسحاق تروو بھوت، تہٕ موٗد تہٕ سپُد پننین لوکن مَنٛز جمع کرنہٕ، یُس بُزرگ تہٕ بٔرِتھ اوس، تہٕ تٔمۍ سٕندِس نیچویو عیسو تہٕ یعقوبن کٔر سُہ دفن۔","1. وۅنۍ چھہِ یِم عیسو سٕنزِ نسلہٕ، یُس {چُھ} ادوم چُھ۔\n2.\\tعیسوہن نِش نِیہِ کنعان سٕنزِ کورِ ہٕنزِ زنانہٕ۔ آداہ ایلون دی ہیتی سٕنز کوٗر تہٕ احولیبامہ چھے زبیبون دی ہیوی سٕنز کورِ آناہ سٕنز کوٗر۔\n3.\\tتہٕ بشیمتھ اسماعیل سٕنز کوٗر یۄس نباجوتھ سٕنز بینہِ۔ {بشیمتھ: یا، مہلات}\n4.\\tتہٕ عیسیٰ الیفازس کُن بٔرۍ۔ تہٕ بشیمتھ بیئر ریویل۔\n5.\\tتہٕ اہولیبامہ یێلہِ عیسیٰ سٕندِس نیچِھس تہٕ یِم حضرت عیسیٰ سٕندِ نیچِھ، یِم کنعان کِس سرزمینس مَنٛز أمِس زامٕتـ̡ ٲسۍ۔\n6. تہٕ عیساو نِش نِش پنٕنۍ خانٛدارِنہِ، نیچوۍ، کورِ، تہٕ پنٕنِس گرٕکۍ سارِنٕے نفر، تہٕ پنٕنۍ چاروٲے تہٕ پنٕنۍ سٲری جانور تہٕ پنُن سٲرِی مال یُس أمِس کنعان کِس سرزمینس مَنٛز حٲصل اوس کوٚرمُت۔ تہٕ گوٚو پننِس بٲیِس یعقوب سٕندِ بُتھِ سٍتـ̡ مُلکس منز۔ {افراد: ہیب۔ روح}\n7.\\tتِہُند دولت اوس اَکہٕ وٹہٕ روزنہٕ کھوتہٕ زیادٕ۔ تہٕ یتھ زمینس منز تم اجنبی ٲسۍ، سُہ ہیوٚک نہٕ تِمن ہٕندِس چارواین ہٕندِ وجہ سٍتۍ برداشت کٔرِتھ۔\n8. یِتھٕ پٲٹھۍ اوس عیسو پہاڑ سیرس مَنٛز روزان: عیسو {is} Edom۔\n9. تہٕ یِم {چِھ} عیسو سٕنزِ نسلہٕ یُس کوہ سیرس مَنٛز ادومی سُند مول چُھ: {The Edomites: Heb. ایڈوم}\n10.\\tیِم چھِ عیسو سٕندٮ۪ن نیچوین ہٕندِ ناو۔ عیسو سٕنز زنانہٕ عداہ سُند نیچو الیفاز، عیسو سٕنز زنانہٕ بشیمتھ سُند نیچو ریوئیل۔\n11.\\tتہٕ الیفاز سٕندِ نیچوۍ ٲسۍ تیمان، عمر، زیفو تہٕ گاتم تہٕ کناز۔ {زیفو: یا، زیفی}\n12. تہٕ تیمنا ٲس الیفاز عیسو سٕندِس نیچوِس سٕنز لونڈی۔ تہٕ سۅ گٔیہِ الیفاز امالیکَس نِش: یِم ٲسۍ ادہ عیساو سٕنزِ زنانہِ ہٕندِ نیچوۍ۔\n13.\\tتہٕ یِم چھہِ رئیل سٕندِ نیچوۍ۔ ناحت، تہٕ زراہ، شماہ تہٕ مِزہ: یِم ٲسۍ بشمتھ عیسیٰ سٕنزِ زنانہِ ہٕندۍ نیٚچِوۍ۔\n14.\\tتہٕ یِم ٲسۍ عیسیٰ سٕنزِ زنانہٕ عناہ سٕنزِ کورِ احولیبامہ سٕندِ نیچِو، یُس عیسیٰ سٕنزِ کورِ ٲس، تہٕ یِمو زاے عیسیٰ عیسیٰ تہٕ جَلام تہٕ کورہ سٕندِس سٍتـ̡ زاے ۔\n15.\\tیِم ٲسۍ عیسو سٕندِس نیچوِس سٍتـ̡ الیفاز سٕندِ نیچوۍ: عیسو سُند گۅڈنیُک {نیٚچُو}۔ ڈیوک ٹیمان، ڈیوک عمر، ڈیوک زیفو، ڈیوک کیناز\n16.\\tڈیوک کورہ، ڈیوک گاتم، {تہ} ڈیوک امالک: یِم {چھِ} ڈیوک {یُس اِلفازٕکِس سرزمینس مَنٛز آو}۔ یِم ٲسۍ عدہ سٕندِ نیٚچِوۍ۔\n17.\\tتہٕ یِم چھِ رئیل عیسو سٕندِس نیچوِس سٕندِ نیچوۍ۔ ڈیوک نہات، ڈیوک زراہ، ڈیوک شمہ، ڈیوک میزاہ: یم {چِھ} ڈیوک {یُس ریوئلُک آیا} ادوم کِس سرزمینس مَنٛز۔ یِم چھِ بشیمتھ عیسو سٕنزِ زنانہِ ہٕندۍ نیٚچِوۍ۔\n18.\\tتہٕ یِم چھِ اہولیبامہ عیسو سٕنزِ زنانہِ ہٕندِ نیچوۍ۔ ڈیوک یسوع، ڈیوک جلم، ڈیوک کورہ: یم {ٲس} ڈیوک {یُس آو} احولیبامہ سٕنز کور، یُس عیسو سٕنزِ زنانہٕ ٲس۔\n19.\\tیِم چھہِ عیسو سٕندِ نیچوۍ، یُس ادوم چُھ، تہٕ یِم چھِ تِہٕندِ ڈیوک۔\n20. یم چھہِ سیر حوریت سٕندِ نیچوۍ، یِم زمینس منز آباد ٲسۍ۔ لوتان، تہٕ شوبل، تہٕ زیبیون، تہٕ عناہ،\n21.\\tتہٕ دِشون، تہٕ ایزر، تہٕ دیشان: یِم چھِ حورِیَن ہٕندِ ڈیوک، یِم چھِ ادوم کِس سرزمینس مَنٛز سیرٕکۍ شُرۍ۔\n22.\\tتہٕ لوٹن سٕندِ شُرۍ ٲسۍ ہوری تہٕ ہیمام۔ تہٕ لوٹن سنز بینہٕ ٲس تیمنا۔ {ہیم: یا، ہوم}\n23.\\tتہٕ شوبل سٕندِ شُرۍ ٲسۍ یِم۔ الوان، تہٕ مناہتھ، تہٕ ایبل، شیفو تہٕ اونم۔ {الوان: یا، الیان} {شیفو: یا، شیفی}\n24. تہٕ یِم چھِ زِبیونٕکۍ شُرۍ۔ اَج تہٕ آناہ دۅشوے: یہ اوس سُہ عناہ یمۍ بیابانن منز خچر لٔبۍ، ییلہ تٔمۍ پننِس مٲلس زبیعون سٕندِس گَرَس کھٮ۪وان اوس۔\n25.\\tتہٕ عناہ سٕندِ بچہٕ ٲسۍ یِم۔ دیشون، تہٕ احولیبامہ آنا سٕنز کوٗر۔\n26.\\tتہٕ یِم {چھِ} دِشَن سٕندِ شُرۍ۔ ہیمدان، تہٕ اشبان، تہٕ ایتھران، تہٕ چیران۔ {ہیمدان: یا، امرم}\n27. ایزر سٕندِ بچہٕ {چِھ} یِم؛ بلہان تہٕ زاون تہٕ اکان۔ {اکان: یا، جاکان}\n28.\\tدِشَن سٕندِ شُرِ چھِ یِمَن ہٕندِس شُرۍ۔ اُز تہٕ آران۔\n29. یم {چِھ} ڈیوک {یم آۓ} ہورائٹس سٕندِ۔ ڈیوک لوٹن، ڈیوک شوبل، ڈیوک زیبیون، ڈیوک آناہ،\n30.\\tڈیوک ڈِشن، ڈیوک ایزر، ڈیوک دیشان: یِم {چھِ} ڈیوک {یُس آو} ہوری ہٕندِس ڈیوکس منز، سیر کِس سرزمینس مَنٛز۔\n31.\\tتہٕ یِم بادشاہ چھِ یِم اِسرٲیلِس پؠٹھ کُنہِ بادشاہ سٕندِس ملکَس مَنٛز حکومت کٔرۍ۔\n32.\\tتہٕ بیور سُند نیچو بیلہ کٔر ادومس مَنٛز بادشاہت: تہٕ تٔمۍ سٕندِس شہرُک ناو اوس دینہابا۔\n33.\\tتہٕ بیلہ موٗد تہٕ بوزرہ کِس زرہ سُند نیچو جوباب کٔر أمِس بدلہٕ حکوٗمت۔\n34.\\tتہٕ جوباب موٗد تہٕ تیمانی ہٕندِس سرزمینُک حشام کٔر أمِس بدلہٕ حکوٗمت۔\n35.\\tتہ حشام گۆو تہ بیداد سُند نیچو حداد، یمۍ موآب کِس میدانس مَنٛز مدیانس پیٹھ مار دِژ، تٔمۍ سٕندِ جایہ کٔر حُکوٗمت: تہٕ تٔمۍ سٕندِس شہرُک ناو اوس اویتھ۔\n36.\\tحداد گٔیہ مٔرِتھ تہ مسرکہ ہٕندِس بدلہٕ کٔر سملہ بادشاہ۔\n37.\\tتہٕ سملہ مٔرِتھ تہٕ ساؤل آف ریہوبوتھ کٔر تٔمِس بدلہٕ دٔرِیاو دٔریاو۔\n38.\\tتہٕ ساؤل موٗد تہٕ اَچبور سُند نیچو بعلہانن کٔر أمِس بدلہٕ حکوٗمت۔\n39.\\tتہٕ اچبور سُند نیچو بعلحنان موٗد، تہٕ حدر کٔر أمِس بدلہٕ حُکوٗمت: تہٕ تٔمۍ سٕندِس شہرُک ناو اوس پاو۔ تہٕ تٔمۍ سٕنزِ زنانہِ ہُند ناو اوس محتابل، یۄس میزاہاب سٕنز کورِ ماترید سٕنز کوٗر ٲس۔ {Hadar, Pau: یا، Hadad, Pai: تٔمۍ سٕندِ مرنہٕ پتہٕ اوس اکھ اشرافیہ}\n40.\\tتہٕ یِم چھہِ عیسو سٕندِ ڈیوکَن ہٕندِ ناو، تِہندِ خاندانہٕ مطٲبق، تِہندِ ناوٕ سٍتـ̡ تہندِ ناوٕ سٍتـ̡ ۔ ڈیوک تیمنا، ڈیوک الواہ، ڈیوک جیتھیتھ، {الواہ: یا، عالیہ}\n41. ڈیوک اہولیبامہ، ڈیوک ایلاہ، ڈیوک پینن،\n42. ڈیوک کیناز، ڈیوک ٹیمان، ڈیوک مِبزار،\n43. ڈیوک مگدیل، ڈیوک اِرام: یِم چھِ ادومی ہٕندِس ڈیوکَس مُطٲبِق، تِہٕندِس ملکَس مَنٛز تِمن ہٕندِس بستی مُطٲبِق: سُہ چُھ عیسو، یُس ادومی سُند مول چُھ۔ {ادومی: ہیب۔ ایڈوم}","1.\\tتہٕ یعقوب اوس تتھ زمینس منز روزان یتھ منز تٔمۍ سُند مول اجنبی اوس، کنعان کِس سرزمینس مَنٛز۔ {یتھ منز...: ہیب۔ تٔمۍ سٕنٛدس مٲل سٕنٛدس سفرس منٛز}\n2. یِم {چِھ} یعقوب سٕنز نسلہٕ۔ یوسف، سدہ وُہُر آسنہٕ کِنۍ، اوس پننین باین سٍتـ̡ کھیٚوان ۔ تہٕ لڑکہٕ اوس بلحاہ سٕندٮ۪ن نیچوین سٍتۍ، تہٕ زِلپاہ سٕندِس نیچوِس سٍتۍ، تہٕ یوسف دِژ پننِس مٲلِس نِش تِہٕنز بد خبر ۔\n3. وۅنۍ اوس اسرٲیلِس یوسف سٕندِس سارِنٕے شُرِ سٍتـ̡ زیادٕ محبت کران، تکیازِ سُہ اوس بُزرگ سُند نیچو، تہٕ تٔمۍ بنوو تس {واریہ} رنگن ہُند کوٹ۔ {رنگ: یا، ٹُکرٕ}\n4. تہٕ ییلہ تٔمۍ سٕندٮ۪و بٲے وُچھ زِ تِہُند مول چُھ أمِس سارِنٕے باین کھوتہٕ زیادٕ محبت کران، تِمو کٔر أمِس سٍتـ̡ نفرت، تہٕ ہیوٚک نہٕ أمِس سٍتـ̡ سُکون سان کتھ کٔرِتھ۔\n5.\\tتہٕ یوسفَن وُچھ اکھ خواب، تہٕ تٔمۍ ووٚن پننین باین تہٕ تِمو کٔر أمِس سٍتـ̡ زیادٕ نفرت۔\n6.\\tتہٕ تٔمۍ ووٚن تِمَن، بوزو، بہٕ چھُس دُعا کٔرِتھ، یہِ خواب، یُس میہ خواب وچھمُت چھُ:\n7.\\tتکیازِ اسہِ ٲس کھاہس منز گٔنڈتھ تہ ووٚتھ تہ ووٚتھ تہ کھڑا تہِ۔ تہٕ وُچھ، تۅہہِ گٔیہِ اندۍ پکھۍ کھٔسۍ، تہٕ کٔرٕکھ میٲنِس گۅپھس سَجود۔\n8.\\tتہٕ تٔمۍ سٕندٮ۪و بٲے ووٚن أمِس زِ کیا ژٕ پٔزۍ پٲٹھـ̡ اسہِ پیٹھ راج کٔرِتھ؟ یا کیا پزۍ پاٹھۍ چھکھ اسہِ پیٹھ حاکمیت تھاوان؟ تہٕ تِم ٲسۍ أمِس سٕندٮ۪ن خوابن تہٕ تٔمۍ سٕنٛدٮ۪ن کلامَن سۭتۍ زیادٕ نفرت۔\n9.\\tتہٕ تٔمۍ وُچھ بیاکھ خواب، تہٕ وونُن پننین باین تہٕ وونُن، وُچھمُت میہ بییہ اکھ خواب۔ تہٕ وچھ آفتاب تہٕ زون تہٕ کاہ ستارو کٔر میانہِ خٲطرٕ سجد۔\n10.\\tتہٕ تٔمۍ ووٚن پننِس مٲلِس تہٕ پننِس باین تہٕ تٔمۍ سٕندِس مٲلہِ دِژ أمِس ملامت تہٕ وونُن، یہِ کیا چُھہ خواب، یُس ژے خواب وچھمُت چھُ؟ کیا بہٕ تہٕ تہنز موج تہٕ تہند بٲے گژھا پزۍ پاٹھۍ ژےٚ زمینس برونہہ کُن سجدہ کرنہٕ خٲطرٕ؟\n11. تہٕ تٔمۍ سٕندِ بٲے ٲسۍ أمِس حسد کران۔ مگر تٔمۍ سٕندِ مٲلہِ وُچھ یہ قول۔\n12.\\tتہٕ تٔمۍ سٕندِ بٲے گٔیہِ شیکیمس مَنٛز پننِس مٲلہِ سٕندِس کھورِ کھٮ۪نہِ۔\n13. تہٕ اسرایلن ووٚن یوسفس، کیا چُھہ نہٕ تہندِ بٲے شیکیمس مَنٛز کھیٚنہٕ دِوان؟ یِمو تہٕ بہٕ سوزٕ ژے تِمن نِش۔ تہٕ تٔمۍ ووٚن تٔمِس یتھے {بہ}۔\n14.\\tتہٕ تٔمۍ ووٚن أمِس گژھ، گژھ بہٕ ژےٚ دُعا کٔرِتھ، وُچھِو تہٕ پَنٕنٮ۪ن باین تہٕ رٔچھن سٍتـ̡ ٹھیٖک چُھہ ٹھیٖک۔ تہٕ اَنِن مےٚ دُبارٕ لفظ۔ چنانچہ سوٗز سُہ حبرون کِس وادی منزٕ نٮ۪بر تہٕ سُہ آو شیکیمس کُن۔ {وُچھو...: ہیب۔ وُچھِو پننین باین ہُند سکون، وغیرہ۔}\n15.\\tتہٕ أکِس شخصس لوٚب سُہ تہٕ وُچھ سُہ کھاہس مَنٛز نژان تہٕ أمِس پرژھس، ژیہ کیا چھُکھ ژھاران۔\n16.\\tتہٕ تٔمۍ ووٚن، بہٕ چُھس پننین بٲے ژھانڈان: مے وَنُن، بہٕ چُھس ژے دُعا کران، کتہِ چھِ تِم [پنٕنـ̡ چارہٕ}۔\n17.\\tتہٕ مردس ووٚن، تِم گٔیہِ نیرِ۔ تکیازِ میہ بوز تِم ونان زِ أسۍ گژھو دوتھنس کُن۔ تہٕ یوسف گوٚو پننین باین پتہٕ، تہٕ وُچھن تِم دوتھنس منٛز۔\n18.\\tتہٕ ییلہ تِمو سُہ دوٗر وُچھ، تِمو کٔر أمِس مارنٕچ سٲزِش۔\n19. تہٕ تِمو ووٚن اَکھ أکِس سٍتـ̡ ، وُچھِو یہِ خوابن وول یِوان۔ {خواب: ہیب۔ ماسٹر آف ڈریمز}\n20.\\tتێلہِ آو وۅنۍ تہٕ أسۍ مارو أمِس کُنہِ کھۅڈس مَنٛز، تہٕ أسۍ ونو زِ کانہہ بد کار درندٕ چُھ أمِس کھٮ۪ومُت، تہٕ أسۍ وٕچھو تٔمۍ سٕندِس خوابن کیا بنہِ۔\n21.\\tتہٕ روبن بوز تہٕ تٔمۍ کٔر سُہ تِہندِ اتھہٕ نِش نِش۔ تہٕ ووٚنُن، أسۍ کرو نہٕ أمِس مٲرِتھ۔\n22.\\tتہٕ روبن ووٚن تِمَن زِ خوُن تراوُن نہٕ یُس بیابانس مَنٛز چھُ، تہٕ تراوُن نہٕ أمِس پیٹھ اتھہٕ۔ تاکہ سُہ کرِ أمِس تِہندیو اَتھٕ نِش نِش دِنہٕ، تہٕ دُبارٕ پننِس مٲلِس حوالہٕ دِنہٕ۔\n23.\\tتہ سپد ییلہ یوسف پننین باین نِش آو، تِمو کٔڈِتھ یوسف سٕندِس کوٹس منز، تٔمۍ سُند کوٹ {واریہ} رنگن ہُند کوٹ یُس أمِس پیٹھ اوس۔ {رنگ: یا، ٹُکرٕ}\n24.\\tتہٕ تِمو نِش نِش تہٕ ترٛٲوِکھ أکِس کھۄڈس مَنٛز، تہٕ کھۄڈ اوس خٲلی، اَتھ مَنٛز اوس نہٕ آب کُنہِ تہِ۔\n25.\\tتہٕ تِمو بیوٹھ روٹی کھٮ۪نہِ، تہٕ تِمو کٔر أچھ تُلِتھ تہٕ وُچھِتھ گٔیہِ اسماعیلِین ہٕنز اکھ جمٲژ یِمن ہٕندِس اونٹَن ہٕندِس سٍتـ̡ مسالہٕ تہٕ بام تہٕ مرٕچ ہٮ۪تھ گٔیہِ مصرس کُن نِنہٕ۔\n26. تہٕ یہوداہ ہن ووٚن پننین باین زِ اگر أسۍ پنُن بٲے مارِو، تہٕ تٔمۍ سُند خوُن ژوٗرِ تھاوُن تہٕ کیا فٲیدٕ چُھہ؟\n27.\\tیِو اسہِ سُہ اسماعیلِین کٕنُن، تہٕ اسہِ گژھہِ نہٕ أمِس پیٹھ اتھہٕ تھاوُن۔ تکیازِ سُہ چُھ سون بوے {تہٕ} سون ماز۔ تہٕ تٔمۍ سٕندۍ بٲے ٲسۍ مطمئن۔ {ٲس...: ہیب۔ بوزنہٕ آمُت}\n28.\\tاَمہ پتہٕ گٔیہ مدیانین ہٕندِس سوداگرس نِش۔ تہٕ تِمو کٔر یوسف کھۅنہٕ منزٕ تہٕ تُلِتھ تہٕ کُنُن یوسف اسماعیلِین وُہن رۄپہٕ رۄپہٕ منز۔\n29.\\tتہٕ روبن آو گڑھس منز واپس۔ تہٕ وُچھِو، یوسف اوس نہٕ گڑھس منٛز۔ تہٕ تٔمۍ کٔر پنٕنۍ پلو کرایہٕ۔\n30.\\tتہٕ سُہ آو پننین باین نِش واپس، تہٕ وونُن، شُر چُھ نہٕ۔ تہٕ بہٕ کوٚت گژھہٕ بہٕ؟\n31.\\tتہٕ تِمو نِش یوسف سُند کوٹ، تہٕ ژھاوُن اکھ شُر مٲرِتھ تہٕ کورُکھ کوٹ خونس مَنٛز۔\n32.\\tتہٕ تِمو سوزُکھ {واریہ} رنگن ہُند کوٹ، تہٕ تِمو أنِن پننِس مٲلِس نِش۔ تہٕ ووٚنُن، یہ چھُ اسہِ لوٚبمُت: وۅنۍ زان زِ یہ چھا تۅہہِ نیچوۍ سُند کوٹ کِنہ نہ۔\n33.\\tتہٕ أمِس ٲس یہِ پَے تہٕ ووٚنُن، {یہِ} چھُ میٲنِس نیچوۍ سُند کوٹ۔ أکۍ بد درندَن چُھ أمِس کھٮ۪ومُت۔ یوسف چُھ بلا شبہ ٹُکرٕ ٹُکرٕ کٔرِتھ۔\n34.\\tتہٕ یعقوب کٔرٕن پَنٕنـ̡ پَنٕنـ̡ پٲٹھـ̡ تہٕ کورُن واریاہن دۅہن پننِس نی\n35.\\tتہٕ تٔمۍ سٕندِ سارِنٕے نیچوۍ تہٕ تٔمۍ سٕنزِ سارِنٕے کورِ گٔیہِ أمِس تسلی دِنہٕ خٲطرٕ۔ مگر تٔمۍ کوٚر تسلی دِنس انکار۔ تہٕ تٔمۍ ووٚن، تکیازِ بہٕ گژھہٕ قبرِ منز پننِس نیچوِس ماتم کرنہٕ خٲطرٕ۔ یِتھ کٔنۍ اوس أمۍ سُنٛد مول أمۍ سٕنٛدِ خٲطرٕ رووُن۔\n36.\\tتہٕ مدیانیو کُن سُہ مصرس مَنٛز فرعون سٕندِس أکِس افسرس تہٕ گارڈن ہُند کپتان۔ {افسر: ہیب۔ کپتان...: یا، چیف مارشل: ہیب۔ ذبح کرن والن یا جلادن ہند سردار}","1.\\tتہٕ سپد تمہِ وِزِ یہِ زِ یہوداہ ووت پننین باین نِش بۄن تہٕ گۆو أکِس عدُلمی سٕندِس نِش، یٔمۍ سُند ناو اوس حیرا۔\n2.\\tتہٕ یہوداہ وُچھ تتہِ أکِس کنعانی سٕنز کور، یٔمۍ سُند ناو شواہ اوس۔ تہٕ تٔمۍ نیو أمِس نِش تہٕ ژاو أمِس نِش۔\n3. تہٕ أمِس گٔیہِ حاملہٕ، تہٕ زیٚوُن اکھ نیٚچُو۔ تہٕ تٔمۍ ووٚن أمۍ سُنٛد ناو ایر۔\n4. تہٕ أمِس گٔیہِ دُبارٕ حاملہٕ، تہٕ کوٚرُن نیٚچُو۔ تہٕ تٔمۍ ووٚن تٔمۍ سُنٛد ناو اونان۔\n5.\\tتہٕ سۅ گٔیہِ بییہِ بییہ حاملہٕ، تہٕ کوٚرُن نیچو۔ تہٕ وَنُن أمِس ناو شیلَہ: تہٕ سُہ اوس شیزِبَس مَنٛز، ییٚلہِ أمِس زَن أمِس زَن دِنہٕ۔\n6.\\tتہٕ یہوداہ رٔٹ پننِس گۄڈنِکِس شُرِس سٍتـ̡ خانٛدارِن، یٔمِس سُند ناو تمر اوس۔\n7.\\tتہٕ یہوداہ سُند گۅڈنیُک زامُت، اوس خداوند سٕندِس نظرس منز بدکار ۔ تہٕ خداوند کوٚر سُہ مٲرِتھ۔\n8. تہٕ یہوداہَن ووٚن اونانس، گژھ پننِس بٲے سٕنزِ زنانہِ نِش تہٕ أمِس سٍتـ̡ کھاندر کٔرِتھ تہٕ پنہٕ نِس بٲیِس سٍتـ̡ بُنیاد دِنہٕ۔\n9.\\tتہٕ اوننس ٲس پتاہ زِ یہ بیول گژھہِ نہٕ تٔمۍ سُند آسُن۔ تہٕ ییلہ سُہ پننِس بٲے سٕنزِ زنانہِ نِش اژِو، تٔمۍ ترووُن زمینس پیٹھ، تاکہ سُہ دِیہ پننِس بٲیِس بیٲلۍ۔\n10.\\tتہٕ یُس کتھ تٔمۍ کٔر خداوند ناراض تہٕ امہِ مۅکھٕ مور سُہ تہِ۔ {ناراض...: ہیب۔ خداوند سٕنزِ نظرِ منز اوس بُر}\n11.\\tاَمہِ پَتہٕ ووٚن یہوداہَس پننہِ نۅشہِ تامرس زِ پنہٕ نِس مٲلہِ سٕندِس گَرَس مَنٛز روزُن بیواہ روزُن، یوتام نہٕ شیلہ میون نیچو بٔڈِتھ گژھہِ، تکیازِ تٔمۍ ووٚن زِ سُہ تہِ گژھہِ مرُن، یِتھٕ پٲٹھۍ، تٔمۍ سٕندِس بٲے سٍتـ̡ تہِ مرُن۔ تہٕ تمر گٔیہِ مٲلہِ سٕندِس گرس منز روزان۔\n12. تہٕ وقتس سٍتـ̡ گٔیہِ شواہ یہوداہ سٕنزِ زنانہِ ہٕنز کورِ مٔرۍ۔ تہٕ یہوداہ ہُند تسلی دِنہٕ آمُت، تہٕ ووت تِمناتھ تہٕ تٔمۍ سٕندِس یارس ہیرہ عدالمیتس کُن۔ {عملہِ منز...: ہیب۔ دۅہ گٔیہ ضرب کرنہٕ}\n13.\\tتہٕ وونُن زِ وُچھِو تُہُند ہیورٕ چُھ تِمناتھ نِش پَنٕنہِ دانٛد کاسنہٕ خٲطرٕ گژھان۔\n14.\\tتہٕ تٔمۍ لوٚگ پننہِ بیواہ ہٕندِ پلو پانس نِش، تہٕ ؤلِتھ لٔگِتھ لٔگِتھ أکِس یلہٕ جایہ، یُس تِمناتھ کُن وتہِ چھُ۔ تکیازِ تس وُچھ زِ شیلہ ٲس بٔڈۍ گٔمٕژ، تہٕ سۅ آیہ نہٕ أمس زنانہٕ دِنہٕ۔ {اکھ کھلہ...: ہیب۔ اچھن ہند دروازہ، یا اناجیم سُند}\n15.\\tییلہ یہوداہ سُہ وُچھ، تٔمِس باسیوو سُہ کُنہِ تکیازِ تمۍ اوس پنن بُتھ تھوٚپ کورمُت۔\n16.\\tتہٕ ووت أمِس کُن پھیُر، تہٕ ووٚنُن، گژھ بہٕ ژے نِش اژُن۔ (تکیازِ تس ٲس نہ پتاہ زِ سۅ ٲس تسنز نۅشہ ٲس۔) تہٕ تٔمۍ ووٚن، ژٕ کیا دِیہٕ مے یُس مےٚ نِش یِنہٕ؟\n17.\\tتہٕ ووٚن بہٕ سوزٕ ژے رژھہِ منزٕ اکھ شُر۔ تہٕ تٔمۍ ووٚن، کیا ژٕ کٔرٕ {مے} اکھ وعدٕ، یوٚت تام نہٕ ژٕ سوزنہٕ؟ {اکھ بچہ: ہیب۔ ژھاوُن ہُنٛد اکھ شُر}\n18.\\tتہٕ تٔمۍ ووٚن، بہٕ کُس وعدٕ کرٕ ژےٚ؟ تہٕ تٔمۍ ووٚن، تُہند نشان، تہٕ تُہند کٔرٕن، تہٕ تُہند عصا یُس تُہندس اتھس منز چُھ۔ تہٕ أمِس دِژ أمِس نِش، تہٕ أمِس نِش آو تہٕ أمِس گٔیہِ أمِس حاملہٕ۔\n19.\\tتہٕ سۄ ووٚتھ، تہٕ گٔیہِ أمِس نِش لٔگِتھ تہٕ لوٚگُن پننہِ بیواہ ہٕندِ پَلَو۔\n20.\\tتہٕ یہوداہَن سوٗز شُر پننِس یارس عدالمی سٕندِ اتھہٕ سٍتـ̡ زنانہِ ہٕندِس اتھہٕ سٍتـ̡ عہد حٲصل کرنہٕ خٲطرٕ، مگر أمِس لٔب نہٕ۔\n21.\\tاَمہ پتہٕ پرژھ تٔمِس جایہِ ہٕندِس مردس تہٕ وَنُن زِ کَتہِ چھُ یہِ وتہِ نِش یُس {اوس} کھلہٕ وتہِ نِش ٲس۔ تہٕ تِمو ووٚن، اتھ {جایہ} ٲس نہٕ کانہہ بدکار ۔ {کھلہٕ پٲٹھۍ: یا، اناجیمس منز}\n22. تہٕ سُہ آو یہوداہ کُن واپس، تہٕ وونُن، بہٕ چُھس نہٕ یہِ لٔبِتھ۔ تہٕ اَمہ جایہ ہٕندِس مردس تہِ ووٚن، {یہ} اتھ {جایہ} منز ٲس نہٕ کانہہ بدکار ۔\n23.\\tتہٕ یہوداہ ووٚن سُہ نِش نِن، نِش گژھہِ اسہِ شرمندہ گژھُن: وُچھ، مے سوزمُت یہِ شُر، تہٕ ژے لٔبِتھ نہٕ۔ {شرم گژھُن: ہیب۔ حقارت بٔنِو}\n24.\\tتہٕ یہِ سپُد تقریباً تریہ ریتہٕ پَتہٕ یہِ وننہٕ آمُت زِ یہوداہ سٍتـ̡ چُھہ یہِ وَننہٕ آمُت زِ تَمر چُھہ تێہٕنزِ نوٗرِ ہُند کردار ادا کورمُت۔ تہٕ وچھو سۅ چھیہ بچہِ سٍتۍ بچہِ۔ تہٕ یہوداہَن ووٚن، أمِس أنِو نیبر، تہٕ دزنہٕ یِنہٕ۔\n25.\\tییلہ سۅ نیرنہٕ آیہ، تٔمۍ سوز پننِس مٲلس نِش، وونُن، تٔمۍ سٕندِس شخصس سٍتـ̡ یٔمۍ سٕندِس یِم {چِھ} بہٕ چُھس شُرِ سٍتـ̡ سٍتـ̡ تہٕ تٔمۍ ووٚنـ̡ سٍتـ̡ یێمہِ\n26. تہٕ یہوداہ کٔر تِمن ہُند اعتراف تہٕ وونُن، سُہ چُھ میانہِ کھۅتہٕ زیادٕ نیک رودمُت۔ تکیازِ میہ دِژ نہ سۅ پننس نیچوس شیلاہس دِژمژ۔ تہ تس ٲس نہ تس بییہ کانہہ زان۔\n27.\\tتہٕ یہ سپد تسٕندِس مصیبت وِزِ زِ وُچھِو تٔمۍ سٕندِس رحمس منز دُکہٕ بچہٕ۔\n28.\\tتہ سپد یہ سپد ییلہ أمس تھپھ کٔرِتھ دِژ اتھہ تہ دٲی رٔٹِتھ رٔٹِتھ گٔنڈِتھ یہ گۅڈہ نیبر نیرِ۔\n29.\\tتہٕ یہِ سپُد، ییٚلہِ تٔمۍ پنُن اَتھٕ واپس کٔرِتھ، وُچھِتھ آو تٔمۍ سُنٛد بوے نٮ۪بر، تہٕ تٔمۍ ووٚن، ژےٚ کِتھہ کٔنۍ پھٔٹِو؟ {یہ} ژے پیٹھ {be} خلاف ورزی کٔرِتھ: لہذا اوس تٔمۍ سُند ناو فاریز وننہٕ آمُت۔ {کتھہ پاٹھۍ...: یا، ژیہ کیازِ کٔر یہ خلاف ورزی پانس خلاف؟} {فیریز: یہِ چھُ اکھ خلاف ورزی}\n30.\\tتہٕ تمہ پتہ دراو تٔمۍ سُند بوے یٔمِس اتھس پیٹھ سرخ پنہٕ اوس، تہٕ تٔمِس اوس زارہ ناو وننہٕ۔","1. تہٕ یوسف آو مصرس مَنٛز اننہٕ۔ تہٕ فرعون سُند اکھ افسر، محافظن ہُند کپتان، اکھ مصری پوٹیفارن ہیوٚت سُہ اسماعیلین ہٕندِ اتھہٕ نِش ہیوٚت، ییمہ سٍتۍ سُہ تتہِ بۄن آمُت اوس۔\n2. تہٕ خداوند اوس یوسفس سٍتـ̡ تہٕ سُہ اوس اکھ خوشحال انسان۔ تہٕ سُہ اوس پننِس آقا مصری سٕندِس گرس منز۔\n3.\\tتہٕ تٔمۍ سٕندِس آقا وُچھ زِ خداوند اوس أمِس سٍتـ̡ تہٕ خداوند سُہ سورُے یُس تٔمِس سٍتـ̡ کٔرِتھ چُھہ تٔمِس سٍتـ̡\n4.\\tتہٕ یوسفَن لوٚب أمِس نظرِ مَنٛز فضل تہٕ تٔمۍ کٔر أمِس خدمت۔\n5.\\tتہٕ سپُد تمہِ وقتہٕ سٍتـ̡ یێمہِ سٍتـ̡ تٔمِس پَنٕنِس گرس مَنٛز نگراں بنوومُت، تہٕ یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ خداوند سٕندِس گرس سٍتـ̡ یوسف سٕندِ خٲطرٕ برکت دِژمٕژ۔ تہٕ خداوند سٕنز برکت ٲس تٔمِس سارِنٕے سارِنٕے چیزس پیٹھ یُس أمِس گرس تہٕ میدانس مَنٛز اوس۔\n6. تہٕ تٔمۍ ترٲو سُہ سورُے یُس تس یوسفس اتھس منز اوس۔ تہٕ تس ٲس نہ خبرے زِ تس گژھہِ نہٕ تٔمِس روٹی ورٲے یُس سہ کھٮ۪وان اوس۔ تہٕ یوسف اوس {a} نیک {شخص}، تہٕ اصل پسندیدٕ۔\n7.\\tتہٕ یِمو چیزو پَتہٕ سپُد تٔمۍ سٕندِس آقا سٕنزِ زنانہِ یوسفس کُن نظر۔ تہٕ تٔمۍ ووٚن، مےٚ سۭتۍ روزُن۔\n8.\\tمگر تٔمۍ کوٚر اِنکار تہٕ وونُن پننِس آقا سٕنزِ زنانہِ زِ وُچھ، وُچھ، میون آقا چُھنہٕ یہ خیال تھاوان زِ یُس میہ سٍتـ̡ چُھس گرس مَنٛز چُھ، تہٕ یُس سُہ چُھس میٲنس اتھس سٍتـ̡ دِژمُت۔\n9.\\t{یتھ گرس منز} چھہ نہ میہ کھوتہ بوڈ کانہہ تہِ۔ تٔمۍ کٔر نہٕ میانہِ نِش کانہہ تہِ چیز ژوٗر، تکیازِ ژٕ چھے تٔمۍ سٕنز زنانہٕ، تیلہٕ کِتھ کٔنۍ ہیکہٕ بہٕ یِہ بٔڈ بدکاری تہٕ خدایس خلاف گۅناہ کٔرِتھ؟\n10. تہٕ سپُد یہِ یُتھ زن سُہ یوسفس سٍتـ̡ دۅہٕ دۅہہٕ کتھ کران اوس، زِ تٔمِس بوزُن نہٕ أمِس سٍتـ̡ روزُن، {نتہٕ} أمِس سٍتـ̡ روزُن۔\n11.\\tتہٕ سپد یہ وِزِ زِ {یوسف} گۆو گرس منز پنُن کاربار کرنہٕ خٲطرٕ۔ تہٕ {اتہِ} اوس نہٕ اَتھ مکانس منز کانہہ تہِ۔\n12.\\tتہٕ تٔمۍ رٔٹ أمِس پلو تھپھ کٔرِتھ، ووٚنُن میہ سٍتـ̡ پَنُن پلو تہٕ ژٔلِتھ ژٔلِتھ نیبر۔\n13.\\tتہٕ سپُد یہِ سپُد، ییٚلہِ أمِس وُچھ زِ أمِس چُھ پَنُن پلو تٔمِس اتھس مَنٛز ترٛٲومُت، تہٕ ژٔلِتھ،\n14.\\tیہ زِ تٔمۍ کٔر پننِس گرٕ کین نفرن بُلاونہٕ تہٕ تِمن سٍتـ̡ کتھ کٔرِتھ وونُن، وُچھو، تٔمۍ چُھ اسہِ نِش اکھ عبرانی زبان اَننہٕ آمٕژ۔ سُہ آو میہ نِش میہ سٍتـ̡ روزنہٕ خٲطرٕ، تہٕ بہٕ وۆن بَڑِ آوازِ سٍتـ̡ وۆن:{بَڑِ: Heb. عظیم}\n15.\\tتہ سپد ییلہ تس بوز زِ میہ کٔر آواز تھوٚد تہ رووُن، سہ ترٲو میہ نش پنُن پلو تہ ژوٚلتھ ژٔلتھ نیبر نیران۔\n16.\\tتہٕ تٔمۍ ترٲو تٔمۍ سُند پلو پانس سٍتۍ، یوٚت تام تٔمۍ سُند مٲلک گرٕ آو۔\n17.\\tتہٕ تٔمۍ کٔر أمِس سٍتـ̡ یِمن لفظن مطٲبق کتھ کٔرِتھ وونُن، یُس عبرٲنی خادم، یُس ژے اسہِ نِش أنِمُت چُھ، سُہ آو میہ نِش طنز کرنہٕ خٲطرٕ:\n18.\\tتہٕ یہ سپُد، ییلہ میہ آواز تھوٚد تہٕ رووُن، سہ ترٲو میہ نِش پنُن پلو تہٕ ژوٚل نیبر۔\n19.\\tتہٕ سپُد یہِ سپُد، ییٚلہِ تٔمۍ سٕندِس مٲلکَن پننہِ خانٛدارِنہِ ہٕنز کتھ بوز، یُس تٔمِس سٍتـ̡ وَنُن اوس تٔمِس سٍتـ̡ وَننہٕ آمُت، یِتھٕ پٲٹھـ̡ چُھہ تُہٕندِس خادمَس سٍتـ̡ میانہِ سٍت زِ تٔمۍ سُند شرارت آو دزنہٕ۔\n20. تہٕ یوسف سٕندِس مٲلکَن نِیوو سُہ تہٕ تھووُن قٲد خانس مَنٛز، یێتہِ بادشاہ سٕندِ قٲدی بٔنِتھ ٲسِتھ تہٕ سُہ اوس جیلس مَنٛز۔\n21.\\tمگر خداوند اوس یوسفس سٍتـ̡ تہٕ ہٲوُن أمِس رحمت، تہٕ دِتُن أمِس قٲد خانہٕ وٲلِس نظرِ سٍتـ̡ رحمت۔ {ہٲوۍ...: ہیب۔ تٔمِس کٔر رحمت}\n22. تہٕ جیلُک رٲچھ کرن وول کٔر یوسف سٕندِس اتھس مَنٛز یِم سٲری قٲد ٲسۍ۔ تہٕ یُس تہِ تِمو تتہِ کران اوس، سُہ اوس یہِ کرُن وول۔\n23.\\tجیلُک رٲچھ کرن وول اوس نہٕ کُنہِ تہِ چیزس کُن نظر۔ تکیازِ خداوند اوس تس سٍتۍ، تہٕ {یہ} یُس تٔمۍ کوٚر تہٕ خداوند بنوو {یہ} ترقی۔","1. تہٕ یِمو چیزو پَتہٕ سپُد یہِ زِ مصرٕکۍ بادشاہ سٕندِ بٹلر تہٕ تٔمۍ سٕندِس بادشاہس اوس مصرُک بادشاہ ناراض کورمُت۔\n2.\\tتہٕ فرعون گوٚو پننین دۄن افسرن سٍتۍ، بٹلرن ہٕندِس سردارس تہٕ بیکرس ہٕندِس سردارس سٍتـ̡ شرارت۔\n3.\\tتہٕ تٔمۍ تھووُن یِم رٲچھ کَرن وٲلِس کپتان سٕندِس گَرَس مَنٛز، قٲد خانس مَنٛز، یَتھ جایہِ یوسفَس بنٛد اوس کرنہٕ آمُت۔\n4.\\tتہٕ رٲچھ دِنہٕ والہِ کپتانن دِژ یوسفس سٍتـ̡ تِمن سٍتـ̡ تہٕ تِمو کٔر وارڈس مَنٛز أکِس کالس جٲری۔\n5.\\tتہٕ تِمو وُچھ دۅشوے خواب، پرٮ۪تھ أکِس شخٕص سُند خواب، پرٮ۪تھ أکِس شخٕص سٕندِ خوابٕچ تعبیر مُطٲبق، مصرٕکۍ بادشاہ سُند بٹلر تہٕ بیکر، یُس جیلس مَنٛز بٔنِتھ اوس۔\n6.\\tتہٕ یوسف آو صبحٲے تِمن نِش تہٕ وُچھن تِمن وُچھان، تہٕ وُچھِن تِم غمگ۔\n7.\\tتہٕ تٔمۍ پرژھ فرعون سٕندٮ۪ن افسرن یِم أمِس سٍتـ̡ تٔمِس سٍتـ̡ ٲسـ̡ تٔمِس سٍتـ̡ تٔمِس سٍتـ̡ وُچھِتھ وُچھِو۔ {وچھو...: ہیب۔ کیا تہند بُتھ چھا بدکار؟}\n8.\\tتہ تمو ووٚن تمس زِ اسہِ چھہ اکھ خواب، تہ امیک ترجمہ کرن وول چھہ نہ کانہہ تہِ۔ تہٕ یوسفَن ووٚن تِمَن {کیا } تشریحات چھِنہٕ خدایہِ سٕندِس سٍتـ̡ ؟ مے وَن {تِم}، بہٕ چھُس ژےٚ دُعا کران۔\n9.\\tتہٕ چیف بٹلرن ووٚن یوسف پنُن خواب، تہٕ ووٚننس میٲنس خوابس منز، وچھ میہ برونہہ کنہِ اکھ بیل۔\n10.\\tتہٕ بیلس منز ٲس تریہ لنجہِ: تہٕ یہِ {اوس} زن یہ پھُلِتھ پھٔلۍ، {تہٕ} تٔمۍ سٕندِ پوشہٕ پھٔلۍ۔ تہٕ اَمہ منزٕ گٔژھۍ پۄختہٕ انگور نیران۔\n11. تہٕ فرعون سُند پیالہ اوس میٲنس اتھس منز، تہٕ مے رٔٹۍ انگور تہٕ دِژُن فرعون سٕندِس پیالس منز، تہٕ مے دِژُن پیالہ فرعون سٕندِس اتھس منز۔\n12.\\tتہٕ یوسفَن ووٚن أمِس یہِ {چُھ} اَمیُک تشریح: ترےٚ شاخہٕ چھِ ترےٚ دۅہہٕ:\n13. توتہِ ترٮ۪ن دۅہن اندر کرِ فرعون تُہند کلہٕ تُلِتھ تہٕ ژے دِیہِ پننہِ جایہ واپس۔ تہٕ ژے دِیُن فرعون سُند پیالہ أمِس اتھس منز، یێلہِ گۅڈٕ تہٕ تُہۍ تٔمۍ سُند بٹلر ٲس۔ {لفٹ...: یا، حساب}\n14.\\tمگر میہ کٔرِو میہ سٍتـ̡ ییلہ تہِ خیر آسہِ، تہٕ مہربانی کرٕن، بہٕ کٔرِس ژے سٍتـ̡ دُعا تہٕ فرعونس سٍتـ̡ کٔرِن میون ذکر تہٕ کٔرِن میہ یَتھ گرٕ منزٕ نٮ۪بر۔ یاد تھاو مے پانس سٍتۍ}\n15.\\tیِکیازِ پٔزۍ پٲٹھۍ اوسُس بہٕ عبرانین ہٕندِ سرزمینہٕ منزٕ ژوٗرِ نِنہٕ آمُت، تہٕ یتہِ تہِ چُھس نہٕ مے کانہہ تہِ کورمُت زِ تِمو گژھن میہ تہِ کوٹھس منز تراوُن۔\n16.\\tییلہ بٔڈۍ بیکرن وُچھ زِ تعبیر چھیہ اصل، تٔمۍ ووٚن یوسفس، میہ تہِ اوس خوابس منز، تہٕ وُچھ، {میہ ٲس} میٲنس کلس پیٹھ تریہ سفید ٹوٗکرۍ: {سفید: یا، سورو سٍتـ̡ بٔرِتھ}\n17.\\tتہٕ پیٹھمہِ ٹوٗکرِ منز اوس فرعونس خٲطرٕ پرٮ۪تھ قٕسمُک ماز آسان۔ تہٕ جاناوارو کھیوٚو میٲنس کلس پیٹھ ٹوٗکرِ منز۔ {بیکمیٹس...: ہیب۔ فرعون سُند ماز، بیکر سٕنز کٲم، یا رَنُن}\n18.\\tتہٕ یوسفَن دِیُت جواب تہٕ وونُن، یہِ چھُ اَمیُک تشریح: تریہ ٹوٗکرِ چھِ تریہ دۅہہٕ:\n19.\\tتوتہِ تریہ دۅہن اندر تُلِتھ تُلِتھ تُہُند کلہٕ تُلِتھ تہٕ ژیہ کُلِس پیٹھ لٹاونہٕ۔ تہٕ جاناوار کھٮ۪ن تُہند ماز ژےٚ نِش۔ {تُلُن...: یا کٔرِو پنُن عہدٕ پانس نِش}\n20.\\tتہٕ گۆو تریمہِ دۅہہ، یُس فرعون سُند زاہ دۄہ اوس، یێمہِ سٍتـ̡ تٔمۍ پننین سارنٕے خادمَن خٲطرٕ دعوت بنوومُت، تہٕ تٔمۍ تُل پننین خدمتگارن مَنٛز چیف بٹلر تہٕ چیف بیکر سُند کلہٕ۔ {تُلنہٕ...: یا، حساب}\n21.\\tتہٕ تٔمۍ کٔر چیف بٹلر بییہ پننہِ بٹلرشپ پیٹھ بحال۔ تہٕ تٔمۍ دیُت پیالہ فرعونس اتھس منٛز:\n22.\\tمگر تٔمۍ دِژ چیف بیکرس پھٲنسی، یِتھہٕ کٔنۍ یوسفَن تِمن ترجمہٕ کورمُت۔\n23.\\tتوتہِ اوس نہٕ چیف بٹلرس یوسف یاد، مگر کورُن سُہ مٔشِد۔","1. تہٕ پورٕ دۄن ؤرین ہٕندِس ٲخرس پیٹھ سپُد یہ سپدُن زِ فرعونن وُچھ خواب، تہٕ وُچھ سُہ دریاوس نِش کھڑا ۔\n2. تہٕ وُچھِتھ دراو دریاوس منزٕ ستھ رژھ تہٕ موٚٹۍ۔ تہٕ تِم ٲسۍ أکِس مرگہٕ منٛز کھٮ۪وان۔\n3.\\tتہٕ وُچھِتھ آیہِ یِمن پتہٕ سَتھ کۅکرِ دٔریاوٕ منزٕ نِش نِش بد کار تہٕ دٔرۍ۔ تہٕ دٔریاو کِس بٹھس پیٹھ کھڑا {باقی} گاوِ نِش۔\n4.\\tتہٕ بدکار تہٕ دوٚب ماز کٔر سَتھ رژھ رژھ تہٕ موٚٹۍ گٲر کھٮ۪وان۔ چنانچہ فرعون بیدار۔\n5.\\tتہٕ سُہ گۆو شوٚنگتھ تہٕ دوٚیمہِ لٹہِ خواب: تہٕ وُچھ أکِس ڈنڈس پیٹھ ستھ کُن مکایہ، درجہٕ تہٕ اصل۔ {درجہ: ہیب۔ چربی}\n6. تہٕ وُچھِتھ سَتھ پتلہٕ کَن تہٕ مشرِقی واو سٍتۍ پھٔلِتھ وُپھ۔\n7.\\tتہٕ سَتھ پتلہٕ کَن کھٮ۪وان سَتھ درجہٕ تہٕ پوٗرٕ کَن۔ تہٕ فرعون ووت بیدار، تہٕ وُچھ، یہ اوس اکھ خواب۔\n8.\\tتہٕ صبحٲے سپد تٔمۍ سُند روح پریشان۔ تہٕ تٔمۍ سوٗزۍ مصرٕکۍ سارِنٕے جادوگر تہٕ تِمن ہٕندِس سارِنٕے دانشمندن بُلٲوِتھ تہٕ فرعونن ووٚن تِمن پنُن خواب۔ مگر {اتہِ} اوس نہٕ کانہہ تہِ یُس فرعونس سٍتـ̡ تِمن ہٕنز ترجمانی کٔرِتھ ہێکہِ۔\n9.\\tاَمہِ پتہٕ ووٚن بٔڈ بٹلر فرعونس سٍتـ̡ وونُن، مے چُھس از پنٕنۍ غلطی یاد۔\n10.\\tفرعون گوٚو پننین خدمتگارن سٍتۍ شرارت، تہٕ تھووُن میہ تہٕ چیف بیکر سٕندِس کپتانس مَنٛز۔\n11. تہٕ اسہِ اوس أکِس رٲژ منز اکھ خواب، میہ تہٕ سُہ۔ اسہِ اوس پریتھ انسان سندس خوابچ تعبیر مطٲبق خواب۔\n12.\\tتہٕ اَسہ سٍتـ̡ اوس اَکھ نوجوان، یُس رٲچھ کِس کپتانُک خادم اوس۔ تہٕ أسۍ ووٚن أمِس تہٕ تٔمۍ کٔر سانہِ خوابن ہٕنز تعبیر ۔ پرٮ۪تھ أکِس شخصس کٔر أمۍ سٕندِس خوابس مطٲبق تٔمۍ تعبیر کرنہٕ۔\n13.\\tتہٕ سپُد یہِ سپُد، یُتھ زن تٔمۍ اسہِ ترجمہٕ کٔر، یِتھے پٲٹھۍ سپُد۔ مے کٔر تٔمۍ میٲنس دفترس منٛز بحال، تہٕ سُہ پھٲنسی دِنہٕ۔\n14.\\tفرعونن سوٗز تہٕ بُلوو یوسف، تہٕ تِمو أنِن سُہ جلدی سان تہٕ تٔمۍ کٔر پانس کھوٗر تہٕ بدلٲوُن پَنُن پلو تہٕ آو فرعونس نِش۔ {اننہٕ...: ہیب۔ سُہ ژلُن}\n15. تہٕ فرعونن ووٚن یوسفس، میہ چھہ اکھ خواب وچھمُت، تہٕ کانہہ تہِ چُھہ نہٕ یُس امیک تعبیر کٔرِتھ، تہٕ مے چُھہ تۅہہِ متعلق یہ ونُن بوزمُت زِ ژے ہٮکہٕ اکھ خوابُک تعبیر کرُن۔ {توہ...: یا، ییلہ ژیہ کانہہ خواب بوزان چھِو، توہۍ ہیکو امچ تعبیر کٔرتھ}\n16.\\tتہٕ یوسفَن دِیُت فرعونس جواب دِتھ زِ یہِ چُھنہٕ میانہِ مَنٛز تہٕ خدا دِیہِ فرعونس امن ہُند جواب۔\n17. تہٕ فرعونن ووٚن یوسفس، میٲنس خوابس منٛز، بہٕ اوسُس دریاو کِس بٹھس پیٹھ کھڑا اوسمُت:\n18.\\tتہٕ وُچھِتھ دراو دریاو منزٕ سَتھ کۅکرِ یُس موٚٹۍ تہٕ رژھ رٔٹِتھ ٲس۔ تہٕ تِمو دِژ أکِس مرگہٕ مَنٛز کھٮ۪وان:\n19.\\tتہٕ وُچھِو یِمن پَتہٕ سَتھ گٲوۍ بیچارہٕ تہٕ سٮ۪ٹھاہ بد کار تہٕ دوٚب گٲمٕتۍ، یِتھٕ زن میہ سارِنٕے مصرٕچ سرزمینس منز بُردی ہٕندِس سٍتـ̡ وُچھمٕژ ٲس۔\n20.\\tتہٕ دوٚبۍ تہٕ بد کار گٲڑۍ کھیوٚو گۅڈنچہ ستھ چربی کۅکر۔\n21.\\tتہٕ ییلہ تِمو کھٮ۪وان آسہِ، یہ ہیوٚک نہٕ معلوم سپدِتھ زِ تِمو چھِ یِم کھٮ۪مٕتۍ۔ مگر تِم ٲسۍ وُنہِ تہِ بد پسند، یِتھ کٔنۍ زِ شروعاتس منز۔ چنانچہ میہ بیدار۔ {کھیوٚن...: ہیب۔ تمن ہٕندِس اندرمس حصس منز آو\n22.\\tتہٕ وُچھ میہ خوابس منز، تہٕ وُچھ ستھ کَن أکِس ڈنڈس منز، پوٗرٕ تہٕ اصل۔\n23.\\tتہِ وُچھِتھ سَتھ کَن، زٲلۍمٕتۍ، {تہٕ} مشرِقی واو سٍتۍ پھٔٹۍ، تِمن پَتہٕ پھٔٹۍ: {مرٔزۍمٕتۍ: یا، لۄکٹۍ}\n24.\\tتہٕ پتلہٕ کَن کھٮ۪تھ سَتھ اصل کَن: تہٕ مے ووٚن جادوگرن {یہ}۔ مَگَر {تَتہِ} اوس نہٕ کانٛہہ تہِ یُس مےٚ {یہ} اعلان کٔرِتھ۔\n25.\\tتہٕ یوسفَن ووٚن فرعونس سٍتـ̡ فرعون سُند خواب: خداین ہٲو فرعونس یہِ کیا کرُن چُھ۔\n26. سَتھ اصل گُرِ {چھِ} سَتھ ؤری۔ تہٕ ستھ اصل کَن {چھ} ستھ ؤری: خواب {چُھ} اکھ۔\n27.\\tتہٕ یِمن پَتہٕ یِم سَتھ وُہرۍ یِم سَتھ ؤری وٲتِتھ چھِ۔ تہٕ سَتھ خٲلی کَن یِم مشرِقی واو سٍتـ̡ پھٔٹِتھ چھِ، سَتھ ؤری قحط۔\n28.\\tیۅہے کتھ چھیہ میہ فرعونس سیتۍ وننہ آمژ زِ خدا کیا کرُن چھہ سہ فرعونس ہاوان۔\n29.\\tوُچھِو سَتھ ؤری یِوان سٲرِسٕے مصرٕکِس سرزمینس مَنٛز:\n30.\\tتہٕ یِمن پَتہٕ سَتھ ؤری قحط پٲدٕ سپدِ۔ تہٕ مصرٕکِس سرزمینس مَنٛز گژھِ سارِوٕے کُنہِ سٍتـ̡ مشراونہٕ یُن۔ تہٕ قحط گژھہِ زمینس کھٮ۪نہٕ۔\n31. تہٕ امہِ قحط کہِ وجہ سٍتـ̡ گژھہِ نہٕ زمینس مَنٛز سٮ۪ٹھاہ سٍتـ̡ تکیازِ یہ {گژھہِ} سٮ۪ٹھاہ افسوسناک آسہِ۔ {دردناک: ہیب۔ گوٚب}\n32.\\tتہٕ اَمہ مۅکھٕ آو فرعونس دۅیہ لٹہِ خواب۔ {یہٕ چُھ} کیازِ یہٕ چیز {چُھ} خداین قایم کورمُت، تہٕ خدا کرِ جلدٕے یہٕ پورٕ۔{قٲیم...: یا، خدایہ سٕندِ طرفہٕ تیار کرنہٕ}\n33.\\tتێلہِ گژھہِ فرعون أکِس ہوشیار تہٕ عقلمند انسانس وُچھِتھ تہٕ سُہ کرُن مصرٕچ سرزمینس پیٹھ۔\n34.\\tفرعونس کرُن تہٕ سُہ کرُن زمینس پیٹھ افسر مقرر تہٕ سَتن ؤرین منز کرِ مصرٕچ زمینُک پٲنژم حصہٕ۔ {افسر: یا، نگران}\n35.\\tتہٕ یِمن یِنہٕ والٮ۪ن اصل ؤرین ہُند سورُے کھٮ۪ن جمع کٔرِتھ، تہٕ فرعون سٕندِس اتھس تل تھٲوِن مَکٲے تہٕ شہرن مَنٛز کھٮ۪ن تھاوُن۔\n36. تہٕ سُہ غذا گژھہِ سَتن ؤرین ہٕندِس قحطس مَنٛز زمینہٕ خٲطرٕ ذخیرٕ کرنہٕ خٲطرٕ، یُس مصر کِس سرزمینس مَنٛز آسہِ۔ زِ زمین گژھہِ نہ قحط سٍتۍ ختم۔ {فٲرِش...: ہیب۔ ژٹُن گژھِ نہٕ}\n37. تہٕ یہِ چیز اوس فرعون سٕندِس نظرِ تہٕ تٔمۍ سٕندِس سارِنٕے خادمَن ہٕندِس نظرِ منز اصل۔\n38.\\tتہٕ فرعونن ووٚن پننین خدمتگارن زِ کیا أسـ̡ یُس {یُس} یُس {چُھ} ہیو انسان ژھٲنڈِتھ، یێمِس مَنٛز خدایہِ سُند روح {چُھ} چُھ؟\n39. تہٕ فرعونن ووٚن یوسفس، یێلہِ زن خداین ژےٚ یہ سورُے ہٲومُت، {تۅہہِ ہیوٗ ہوشیار تہٕ دانا چُھہ نہٕ}۔\n40. تہٕ تُہۍ گژھ میٲنس گرس پیٹھ، تہٕ چانہِ کلامٕ مطٲبق گژھن میانین سارنٕے لوکن پیٹھ حکمرٲنی کرنہٕ: صرف تختس پیٹھ روزٕ بہٕ ژے کھوتہٕ زیادٕ۔ {حکمرٲنی کرُن: ہیب۔ ہتھیار بٔنِو، یا، بوسہٕ}\n41. تہٕ فرعونن ووٚن یوسفس، وُچھ، مے چُھہ ژے سارِنٕے مصرٕچ سرزمینس پیٹھ تھوومُت۔\n42.\\tتہٕ فرعونن کوٚڈ پننہِ اتھہٕ نِش وٲج تہٕ تھووُن یوسف سٕندِس اتھس پیٹھ، تہٕ لوٚگُن أمِس نٔوۍ کُنہِ کُنہِ پوشہٕ تہٕ لوٚگُن سۅنہٕ ہٕندِس گٔرِس سٍتـ̡ {ٹھیٖک...: یا، ریشم}\n43. تہٕ تٔمۍ بنوو أمِس دوٚیمِس رتھَس منٛز سوار کرنہٕ یُس أمِس اوس۔ تہٕ تِمو دِژ أمِس برونہہ کُن، کۅٹھہِ کٔرِتھ تہٕ بنوو سُہ سٲرۍسٕے مصرٕچ سرزمینس پیٹھ حُکُمران۔ {کمان...: یا، ٹینڈر فادر: ہیب۔ Abrech}\n44. تہٕ فرعونن ووٚن یوسفس، بہٕ چُھس فرعون، تہٕ ژے بغٲر ہێکہِ نہٕ کانہہ تہِ مصرٕچ سرزمینس مَنٛز پنُن اتھہٕ تہٕ کھۄر تُلِتھ۔\n45. تہٕ فرعونن ووٚن یوسف سُند ناو زفناتپانیہ۔ تہٕ تٔمۍ دِژ سُہ زنانہٕ آسناتھ یۄس آن کِس پادٕرۍ پوٹیفیرا سٕنٛز کورِ ٲس۔ تہٕ یوسف دراو مصر کِس سرزمینس پیٹھ۔ {ظفناتھپانیا: یُس قبطی زبانہِ منز راز افشا کرن وول چھُ، یا، سُہ شخص یمۍ سُند راز ظٲہر سپدان چھُ} {پادری: یا، شہزادہ}\n46.\\tتہٕ یوسف اوس ترہ وُہُر ییلہ سُہ مصر کِس بادشاہ فرعونس برونہہ کُن کھڑا اوس۔ تہٕ یوسف دراو فرعون سٕنزِ موجودگی منز، تہٕ ووت مصرٕچ سارِنٕے سرزمینہٕ۔\n47.\\tتہٕ ستن ورین منز آیہ زمینہِ اتھہٕ سٍتـ̡ نیران۔\n48.\\tتہٕ تٔمۍ کٔرٕن ستن ؤرین ہُند سورُے کھیٛن جمع یُس مصر کِس سرزمینس مَنٛز اوس، تہٕ کوٚرُن شہرن مَنٛز کھیٛن: کھہُک کھیٛن، یُس پرٮ۪تھ شہرس اندۍ پٔکھۍ اوس، تٔمۍ تھووُن اَتھ مَنٛز ۔\n49.\\tتہٕ یوسفَن کٔر سمندرٕچ سیکہِ ہٕندۍ پٲٹھۍ، یوتام نہٕ سُہ تعداد دِنہٕ آمُت۔ تکیازِ {یہِ اوس} بغٲر نمبر۔\n50.\\tتہٕ یوسفس زاے قحطہٕ ؤری یِنہٕ برونہہ زٕ نیچوۍ، یُس آن کِس پادٕرۍ پوٹیفیرہ سٕنز کورِ آسناتھ أمِس نِش زٲنِتھ دِنہٕ آمُت۔ {پادری: یا، شہزادہ}\n51.\\tتہٕ یوسفَن ووٚن گۄڈنِکِس زامُت مانسیٰ سُند ناو: خدایہِ سٍتـ̡ چُھہ میہ پنُن سورُے محنتہٕ تہٕ مٲلہِ سُند سارِوٕے گرٕ مٔشِد کٔرِتھ۔ {مناسی: یعنی مٔشِد}\n52.\\tتہٕ دویِمِس سُند ناو چُھس افرائیم وَننہٕ آمُت: کیازِ خداین دِژ میہ پننہِ مصیبت ہٕندِس سرزمینس مَنٛز پھلدار بنوو۔ {افرائیم: یعنی، پھل دار }\n53.\\tتہٕ سَتھ ؤری یُس مصر کِس سرزمینس مَنٛز اوس، ختم گٔیہِ۔\n54. تہٕ سَتھ ؤری یِنہٕ ہیوٚت، یِتھ کٔنۍ یوسف اوس ووٚنمُت: تہٕ سارِنٕے زمینن مَنٛز ٲس کمی ۔ مگر مصرٕچ سارِنٕے سرزمینس منز ٲس روٹی آسان۔\n55.\\tییلہ سارِنٕے مصرٕچ زمینہٕ فاقہٕ گٔیہ، لُکھ کٔر فرعونس روٹی منگنہٕ خٲطرٕ فرٲد۔ تہٕ فرعونن ووٚن سارنٕے مصری لوکن زِ گژھ یوسفس نِش۔ سُہ کیا چُھ ژےٚ وَنان۔\n56.\\tتہٕ قحط اوس سارِنٕے زمینہٕ سٍتـ̡ تہٕ یوسفَن کھولۍ سارِنٕے ذخیرٕ تہٕ کُنُن مصری ۔ تہٕ مصر کِس سرزمینس منز ووت قحط۔ {تمام ذخیرٕ: ہیب۔ سٲری یتھ منز اوس}\n57.\\tتہٕ سارِنٕے مُلُک آیہِ مصرس مَنٛز یوسفس نِش مٔلِتھ مَژٕ۔ تکیازِ یہ قحط اوس سارنٕے زمینن منز {تیوٗت زیادٕ}۔","1.\\tییلہ یعقوب وُچھ زِ مصرس مَنٛز چُھ مکایہ، یعقوبن ووٚن پننین نیچوین زِ تم کیازِ چھِو اکھ أکِس کُن نظرِ تھاوان؟\n2.\\tتہٕ تٔمۍ ووٚن، وُچھ، مے چُھس بوزمُت زِ مصرس مَنٛز چُھ مَکٲے موجود۔ تتہِ نِش أنِو تہٕ اَتہِ ہیوٚن اسہِ خٲطرٕ۔ تاکہ أسۍ ہیٛکو زندٕ روزتھ، تہٕ نہ مرُن۔\n3.\\tتہٕ یوسف سٕندِ دَہ بٲے گٔیہِ مصرس مَنٛز مَکٲے اننہِ۔\n4.\\tمگر یوسف سُند بٲے یعقوب سوٗزُن نہٕ پننین باین سٍتـ̡ ۔ تکیازِ تٔمۍ ووٚن زِ تٔمِس گژھہِ شرارت کرنہٕ۔\n5.\\tتہٕ یِمن منز یِنہٕ وٲلِس سٍتـ̡ آو قحط مٔلِتھ مٔلِتھ مٔنزۍ دِنہٕ۔\n6.\\tتہٕ یوسف اوس زمینس پیٹھ حاکم، {تہٕ} سُہ اوس یُس زمینہٕ کین سارنٕے لُکن کٕنُن: تہٕ یوسف سٕندِ بٲے آیہ، تہٕ گٔیہٕ أمِس برونہہ کُن پنٕنۍ بُتھ زمینہٕ کُن نمان۔\n7.\\tتہٕ یوسفَن وُچھ پَنٕنـ̡ بٲے تہٕ سُہ اوس تِمن سٍتـ̡ زانان، مگر تِمن سٍتـ̡ کوٚرُن پان عجیب تہٕ تِمن سٍتـ̡ کٔرٕن سخٕت کتھ کرنہٕ۔ تہٕ تٔمۍ ووٚن تِمَن زِ تُہۍ کتہِ آو ؟ تہٕ تِمو ووٚن، کنعان کِس سرزمینہٕ پیٹھٕ کھٮ۪ن مٔلۍ ہینہٕ خٲطرٕ۔ {تقریباً...: ہیب۔ تمن سیتۍ مشکل چیز}\n8.\\tتہٕ یوسف اوس پننین باین زانان، مگر تِم ٲسۍ نہٕ أمِس زانان۔\n9.\\tتہٕ یوسفَس یاد یِم خواب وچھان ٲسۍ، تہٕ تِمن وونُن تِمن سٍتـ̡ جاسوس۔ زمینچ ننگہٕ وچھنہٕ خٲطرٕ چھکھ تم آمٕتۍ۔\n10.\\tتہٕ تِمو ووٚن أمِس نہ، نہ، میانہِ آقا، مگر کھٮ۪ن ہینہٕ خٲطرٕ چھِ چانۍ نوکر یِوان۔\n11. أسۍ چھِ سارِنٕے أکِس انسانہٕ سٕندِ نیٚچِوۍ۔ أسۍ {چھِ} پٔزۍ {انسان}، تہند خادم چھِنہٕ کانہہ جاسوٗس۔\n12. تہٕ تٔمۍ ووٚن تِمَن، نہ، مگر زمینٕچ ننگہٕ وُچھنہٕ خٲطرٕ چھِو تُہۍ آمٕتۍ۔\n13.\\tتہٕ تِمو ووٚن، تُہٕندِس خادمَس چھِ باہ بٲے، یِم کنعان کِس سرزمینس مَنٛز أکِس شخصہٕ سٕندِ نیٚچِوۍ۔ تہٕ وچھ سارِوٕے کھۄتہٕ لۄکُٹ {چُھ} از سٲنِس مٲلس سٍتۍ، تہٕ اکھ {چُھ} نہٕ۔\n14.\\tتہٕ یوسفَن ووٚن تِمن سٍتـ̡ یہِ {یہ} یێلہِ مے ژے سٍتـ̡ کتھ کٔرِتھ وونُن، یێلہِ چُھہ تُہۍ جاسوس چھِو:\n15.\\tاَتھ سٍتـ̡ گژھہِ تۅہہ ثٲبت سپدُن: فرعون سٕنزِ زِندٕ سٍتـ̡ گژھِو نہٕ تُہٕندِس لۅکٹِس بٲے سٍتـ̡ یور یِنہٕ۔\n16.\\tتم منزٕ سوزُن اکھ تہٕ سُہ یِن پنُن بٲے أنِتھ تہٕ تۅہہِ یِیہِ قٲد خانس منز تھاونہٕ، یُتھ تۅہہِ ہٕندِس کلامَس ثٲبت سپدِ، نتہٕ فرعون سٕنزِ زندگی سٍتـ̡ چھِو یٔقیٖنی طور تُہۍ جاسوس۔ {تھوو...: ہیب۔ باؤنڈ}\n17.\\tتہٕ تٔمۍ کٔر یِم سارِنٕے ترٚین دۅہن وارڈس مَنٛز یکوٹہٕ۔ {پُٹ: ہیب۔ جمع کٔرِتھ}\n18.\\tتہٕ یوسفَن ووٚن تِمن تریمہِ دۅہ، یہِ کرُن تہٕ زندٕ۔ {for} بہٕ چُھس خدایس کھوژان:\n19.\\tیێلہِ پٔزۍ پٲٹھـ̡ بٔنـ̡ پى۪ٹھ\n20. مگر پنُن لۄکُٹ بوے أنِو میانہِ نِش۔ یِتھٕ پٲٹھۍ گژھِ تُہٕندِ کلامٕچ تصدیق کرنہٕ، تہٕ تُہۍ گژھِو نہٕ مَرُن۔ تہٕ تِمو کوٚر یہِ۔\n21. تہٕ تِمو ووٚن اَکھ أکِس سٍتـ̡ ، أسـ̡ چُھہ پٔزۍ پٲٹھـ̡ پننِس بٲے سٍتـ̡ قصوروار، تێلہِ أسـ̡ أسـ̡ تٔمۍ سٕندِس روحُک دکھ وُچھمُت، یێلہِ تٔمۍ سٍتـ̡ أسـ̡ دِژ تہٕ أسـ̡ بوزان چُھہ نہٕ۔ لہذا چھہ یہ پریشانی اسہِ پیٹھ یوان۔\n22.\\tتہٕ روبنَن دِیُت تِمن جواب دِتھ زِ بہٕ چُھس نہٕ ژےٚ وَنُن زِ شُرِس سٍتـ̡ کٔرِو نہٕ گۅناہ۔ تہٕ تۅہہ بوز نہٕ؟ لہذا، وچھو تٔمۍ سُند خونُک تہِ ضروری۔\n23.\\tتہٕ تِمن ٲس نہٕ پتاہ زِ یوسف اوس سمجھان۔ تکیازِ تٔمۍ کٔر تمن سٍتۍ ترجمہٕ کرن وٲلس سٍتـ̡ کتھ کرنہٕ۔ {تٔمۍ کٔر...: ہیب۔ تمن درمیان اوس اکھ ترجمہٕ کار}\n24.\\tتہٕ تٔمۍ پھیُر پان تِمن نِش تہٕ رووُن۔ تہٕ دُبارٕ تِمن نِش واپس، تہٕ تِمن سٍتـ̡ کٔرٕن سِمعون نِش تہٕ تِمن نِش شمعون تہٕ تِمن ہٕنزِ نظرن برونہہ کُن بٔنِتھ بٔنِتھ۔\n25. پتہٕ دِیُت یوسفَن حُکُم زِ تِہٕندِس بۄرٕ سٍتـ̡ بٔرِتھ تہٕ پرٮ۪تھ أکِس شخصہٕ سُند پونسہٕ بٔرِتھ تہٕ تِمن دِیُن وتہٕ خٲطرٕ رزق دِنہٕ۔\n26.\\tتہٕ تِمو کٔر پَنٕنـ̡ گَرٕ سٍتـ̡ مکایہٕ سٍتـ̡ تہٕ درٛاو تتہِ ۔\n27.\\tتہٕ یِمو منزٕ أکِس سٲرۍسٕے منز پنُن گَرٕ دِنہٕ مۅکھٕ کھول دِنہٕ خٲطرٕ، تٔمۍ کٔر پنٕنۍ پونسہٕ جاسوٗس۔ تکیازِ وچھ یہ {اوس} تٔمۍ سٕندِس بورس منز۔\n28.\\tتہٕ تٔمۍ ووٚن پننین باین زِ میون پونسہٕ آو واپس۔ تہٕ لو، {یہ} تہِ چُھس میٲنس بورس منز تہِ: تہٕ تِہُند دِل گوٚو ناکام {تِم}، تہٕ تِم ٲسۍ کھوژان، اکھ أکِس سٍتـ̡ وَنُن، یہِ {یہ} کیا چُھہ خداین اسہِ سٍتـ̡ کورمُت؟ {ناکام...: ہیب۔ برونٹھ کُن}\n29.\\tتہٕ تِم آیہِ پننِس مٲلِس یعقوب نِش کنعان کِس سرزمینس مَنٛز، تہٕ وونُکھ تِمن سٍتـ̡ سُہ سورُے یُس تِمن سٍتـ̡ سپدیومُت۔ ونُن،\n30.\\tیُس شخٕص یُس زمینُک مٲلک چُھ، تٔمۍ کٔر اسہِ سٍتـ̡ سخٕت کتھ تہٕ بنووُن اسہِ ملکُک جاسوٗس۔ {تقریباً...: ہیب۔ اسہِ سیتۍ مشکل چیز}\n31.\\tتہٕ أسۍ ووٚن أمِس زِ أسۍ چھِ پٔزۍ {انسان}۔ أسۍ چھِنہٕ کانہہ جاسوس:\n32. أسۍ چھِ باہ بٲے، پننِس مٲلہِ سٕندِ نیٚچوۍ۔ اَکھ {چُھ} نہٕ، تہٕ سارِوٕے کھۄتہٕ لۄکُٹ {چُھ} از دۅہہ سٲنِس مٲلِس سٍتـ̡ کنعان کِس سرزمینس مَنٛز۔\n33.\\tتہٕ ملکُک مالک، اَمہ سٍتـ̡ چُھہ بہٕ پٔزۍ پٲٹھـ̡ پٔزۍ {انسان} پَنُن اکھ بٲے تراوُن میہ سٍتۍ، تہٕ نِیُن پَنٕنٮ۪ن گَرَن ہٕندِس قحطس خٲطرٕ، تہٕ نیرُن:\n34. تہٕ پنُن لۄکُٹ بوے أنِو میہ نِش۔ تیلہِ گژھہِ میہ معلوم زِ تہۍ چھِو نہٕ کانہہ جاسوس، مگر تۅہہ چھِو پٔزۍ {مرد} تہٕ بہٕ کٔرٕ ژے پنُن بوے تہٕ ژٕ کٔرِو زمینس مَنٛز سوداگر۔\n35.\\tتہٕ ییلہ تِمو پنٕنۍ بۄٹہٕ خٲلی کٔرِتھ، وُچھِتھ اوس پرٮ۪تھ أکِس شخصہٕ سُند پونسہٕ بنڈل تٔمۍ سٕندِس بورس منز، تہٕ ییلہ تِمو تہٕ تِہندِ مٲلہِ دۅشوے پونسہٕ ہٕندِ بنڈل وُچھ، تِم گٔیہِ کھوژان۔\n36.\\tتہٕ یعقوب یِمن ہٕندِس مٲلہِ سٍتـ̡ وۆن، مے چُھہ میانین شُرین سٍتـ̡ سوگمُت: یوسف {چُھ} نہٕ تہٕ شمعون {چُھ} نہٕ، تہٕ تُہۍ نِو بنیامین {نِش}: یِم سٲری چیز چِھہ میانہِ خلاف۔\n37.\\tتہٕ روبنَن ووٚن پننِس مٲلِس سٍتـ̡ زِ میانین زٕ نیچوۍ مارٕن، اگر بہٕ نہٕ یہِ ژے نِش أنِتھ، سُہ دِیُن میٲنِس اتھس مَنٛز، تہٕ بہٕ اَننہٕ سُہ دُبارٕ ژے نِش۔\n38.\\tتہٕ تٔمۍ ووٚن، میون نیچو گژھِ نہٕ ژےٚ سٍتـ̡ وسان۔ تکیازِ تٔمۍ سُند بوے چُھ موٗدمُت، تہٕ سُہ چُھ کُنی روزمُت: اگر تٔمِس وَتہِ یَتھ وتہِ یِمن مُشکِل گٔیہِ، تیٚلہِ أنِو میٲنۍ سُرۍ مَس غمٕ سٍتۍ قبرس کُن۔","1. تہٕ قحط اوس زمینس مَنٛز دَرٕ۔\n2.\\tتہٕ سپُد ییلہ تمو سُہ مکایہ کھیوٚو یُس تمو مصرہٕ منزٕ انمُت اوس، تِہندِ مٲلہِ ووٚن تِمن دُبارٕ گژھِ، اسہِ ہیوٚن رژھ کھٮ۪ن۔\n3.\\tتہٕ یہوداہ ووٚن أمِس سٍتـ̡ وۆنُن زِ أمِس سٍتـ̡ وۆن سٍتـ̡ وُچھِتھ تہٕ وُچھِو نہٕ میٲنۍ بُتھ وُچھِو۔ {کیا ...: ہیب۔ احتجاج کٔر احتجاج}\n4. اگر ژٕ سٲنۍ بٲے اسہِ سٍتـ̡ سوزِو، أسـ̡ بۄن تہٕ ژے کھیٛن ہیوٚن:\n5.\\tمگر اگر نہٕ ژیہ سوزِو، أسۍ گژھہِ نہٕ بۄن، تکیازِ تٔمۍ ووٚن اسہِ زِ تۅہہ وُچھِو نہٕ میون بُتھ وُچھِتھ، سوائے پنُن بٲے تہِ آسہِ۔\n6.\\tتہٕ اسرٲیلَن ووٚن زِ ژے کیازِ کٔرِکھ میہ سٍتـ̡ بُرٕ سٍتـ̡ یێلہِ تہٕ یہِ وَنُن زِ ژے چُھہ وُنہِ تہِ بٲے ؟\n7.\\tتہٕ تِمو ووٚن زِ أمِس شخصس پرژھ سانہِ حالتس تہٕ سانین رشتہ دارن مُتعلِق تہٕ وونُن زِ تُہند مول چھا وُنہِ زندٕ؟ کیا تۅہہ چھکھ {بیاکھ بٲے}؟ تہٕ اسہِ وون تس یمن لفظن ہندِ لحاظہ مطٲبق: کیا أسۍ پٔزۍ پٲٹھۍ پتاہ زِ سُہ وَنُن پنُن بوے بۄن؟ {پرژھمُت...: ہیب۔ پرژھکھ اسہِ} {tenor: Heb. ٲس} {ہیٛک...: ہیب۔ یہ زانان زِ اسہِ کیا پتاہ ٲستھ}\n8. تہٕ یہوداہ ووٚن پننِس مٲلِس اسرٲیلس زِ لڑکہٕ سوز میہ سٍتـ̡ تہٕ أسۍ وۅتھان تہٕ نیرِو۔ تاکہ أسۍ ہیکو زندٕ روزِتھ، تہٕ مٔرِتھ نہٕ، أسۍ تہٕ ژےٚ، {تہٕ} پنٕنۍ لۄکٹۍ تہِ۔\n9. بہٕ روزٕ تٔمِس خٲطرٕ ضمانت۔ میانہِ اتھہٕ سٍتـ̡ کٔرِو تٔمِس سٍتـ̡ یێلہِ بہٕ سُہ ژے نِش أنِتھ تہٕ سُہ پانس برونہہ کُن تھاوُن، تیلہِ گژھہِ بہٕ ہمیشہٕ خٲطرٕ الزام تُلُن:\n10.\\tتکیازِ اسہِ آسہ نہ وۅنۍ یہ دوٚیم لٹہِ واپس۔ {یہ: یا، دۄیہِ لٹہِ}\n11.\\tتہٕ تِہٕندِس مٲلہِ اسرٲیلَن ووٚن تِمن یێلہِ تہِ گژھُن، تیلہِ کٔرِو یہِ ۔ زمینٕکۍ بہترین مٮ۪وٕ نِیِو پننٮ۪ن بانن منٛز، تہٕ نِیِو أمِس اکھ تحفہٕ، رژھ بام، تہٕ رژھ ماچھ، مسالہٕ تہٕ مر، مٮ۪وٕ تہٕ بادام۔\n12.\\tتہٕ رٔٹِو دۄگنہٕ پٲنسہٕ اتھس منز۔ تہٕ یُس پونسہٕ یُس تُہنزِ بورِ ہٕندِس ٲسس منز دُبارٕ اننہٕ آمُت اوس، تُلِو بییہ اتھس منز؛ شاید یہ {اوس} اکھ نگرانی:\n13. پَنُن بٲے تہِ رٔٹِتھ تہٕ وُتھُن، دُبارٕ گژھِو مردس نِش۔\n14.\\tتہٕ خدایہ تعالیٰ کرِ تۅہہِ أمِس شخصس برونہہ کُن رحمت، یُتھ سُہ تُہند بیاکھ بوے تہٕ بنیامین ژٔلِتھ دِیہِ۔ اگر بہٕ سوگوار گژھہِ {پننین شُرۍ}، بہٕ چُھس سوگم۔ {اگر...: یا، تہٕ بہ، یتھہ پاٹھۍ میہ آسہِ، وغیرہ۔}\n15.\\tتہٕ مردو رٔٹ سُہ تحفہٕ، تہٕ تِمو رٔٹِتھ دوٚگنہٕ پٲنسہٕ تہٕ بنیجمن۔ تہٕ ووٚتھ تہٕ ووٚتھ مصرس کُن تہٕ ووت یوسفس برونہہ کُن۔\n16.\\tتہٕ ییلہ یوسفن بنیامین تِمن سٍتـ̡ وُچھ، تٔمۍ ووٚن پننِس گرٕ کِس حاکمس زِ یِم نفر أنِو گَرٕ تہٕ مارُن تہٕ تیار کرُن۔ تکیازِ {یِم} نفر گژھن میہ سٍتۍ دوپہرس کھٮ۪ن۔ {سلی: ہیب۔ مارو اکھ قتل} {ڈائن: ہیب۔ کھؠن}\n17.\\tتہٕ أمِس کٔر یوسف سُند حُکم۔ تہٕ مرد أنۍ نفر یوسف سٕندِس گرس منز۔\n18.\\tتہٕ مرد گٔیہِ کھوژان، تکیازِ تِم آیہ یوسف سٕندِس گرس منز اننہٕ۔ تہٕ تِمو ووٚن، یُس پونسہٕ سٲنس بورس منز گۅڈنچہ لٹہِ واپس آو دِنہٕ۔ تاکہ سُہ گژھِ اسہِ خلاف موقعہٕ ژھارن، تہٕ اسہِ پیٹھ پییہِ، تہٕ اسہِ غلام تہٕ سانہِ گَرٕ بٔنِتھ۔ {ژھانڈ...: ہیب۔ اسہِ پیٹھ رول کرُن}\n19.\\tتہٕ تِم وٲتۍ یوسف سٕندِس مکانس نِش تہٕ تِمو کٔر أمِس سٍتـ̡ گرٕ کِس دروازس پیٹھ کتھ باتھ،\n20.\\tتہٕ وونُن، اے جناب، أسۍ آیہ پزۍ پاٹھۍ گۅڈنچہ لٹہِ کھٮ۪ن ہینہٕ خٲطرٕ: {أسۍ...: ہیب۔ بۄن آو أسۍ بۄن}\n21.\\tتہٕ ییلہ أسۍ سراءِ منز وٲتۍ، اسہِ کھولۍ پنٕنۍ بورۍ، تہٕ وُچھ، پرٮ۪تھ کٲنسہِ انسان سُند پونسہٕ اوس تٔمۍ سٕندِس بورس منز، سون پونسہٕ پورٕ وزنس منز، تہٕ أسۍ اوٚن سُہ دُبارٕ پننِس اتھس منز۔\n22.\\tتہٕ باقٕے پٲنسہٕ چھِ کھٮ۪ن مٔلۍ ہینہٕ خٲطرٕ پننین اَتھن مَنٛز أنِمٕتۍ: أسۍ ہیکو نہٕ یہ ؤنِتھ زِ کٔمۍ چھِ سانہِ پونسہٕ سانٮ۪ن بورین مَنٛز ترٛٲومٕتۍ۔\n23. تہٕ تٔمۍ ووٚن، تُہٕندِس خدایہِ سٕندِس خداہَن تہٕ تُہٕندِس مٲلہِ سٕندِس خداہَن دِژ ژےٚ بۄرِس مَنٛز خزانہٕ۔ تہٕ تٔمۍ أنۍ شمعون تِمن نِش۔ {میہ اوس...: ہیب۔ چانۍ پونسہ آو میہ نِش}\n24.\\tتہٕ یہِ مرد اوٚن یوسف سٕندِس گَرَس مَنٛز، تہٕ دِتُن آب تہٕ تِمو کٔرٕن پنٕنۍ کھۅر چھلان۔ تہٕ تٔمۍ دِژ تِمن ہٕندِس گَردٕ پروونڈر۔\n25.\\tتہٕ تِمو کٔر یوسفس خلاف تحفہٕ تیار، تکیازِ تِمو بوز زِ تِم پزِ تتہِ روٹی کھٮ۪نۍ۔\n26.\\tییلہ یوسف گرٕ آو، تِمو أنِتھ أمِس سُہ تحفہٕ یُس تہندِس اتھس منز اوس، تہٕ کٔرٕکھ أمِس زمینہِ برونہہ کُن نمُن۔\n27.\\tتہٕ تٔمۍ پرژھ تِمن ہٕنزِ خیریت مُتلق، تہٕ وونُن، {چُھس} چُھہ تُہند مول ٹھیٖک ٹھیٖک، سُہ بُزرگ یٔمِس متعلق تۅہہ کتھ کٔرِو؟ {کیا سُہ چھا وُنہِ زِندٕ؟ {ویلفیئر: ہیب۔ امن} {کیا تُہُند...: ہیب۔ کیا چانہِ مٲلس چھا امن؟}\n28.\\tتہٕ تِمو دِژ جواب، تُہند خادم سٲنۍ مول چُھہ صحت مند تہٕ سُہ چُھ وُنہِ تہِ زندٕ۔ تہٕ تِمو کٔر کلہٕ نوٚمُت، تہٕ سجدٕ کٔرٕن۔\n29.\\tتہٕ تٔمۍ کٔر أچھ تُل، تہٕ وُچھُن پنُن بوے بنیامین یُس پننہِ ماجہِ ہُند نیچو اوس، تہٕ وُچھن، {کیا یہ} چُھہ تُہند لۄکُٹ بوے یُس میہ سٍتـ̡ کتھ کٔرِتھ؟ تہٕ تٔمۍ ووٚن، خدایہ کرِ ژےٚ مہربان میانہِ نیچو۔\n30. تہٕ یوسفَن کٔر جلدی ۔ تکیازِ تٔمۍ سٕندِس بٲیِس ٲس تٔمۍ سٕندِس بٲے سٍتۍ تڑپاونہٕ آمٕژ، تہٕ تٔمۍ ژھانڈ کتہِ روُن۔ تہٕ سُہ ژاو پننِس کمرس منز، تہٕ ووت تتہِ رووُن۔\n31.\\tتہٕ تٔمۍ کٔر پنُن بُتھ واش تہٕ نٮبر تہٕ رٔٹِتھ ووٚنُن روٹ۔\n32. تہٕ تِمو کٔر أمِس خٲطرٕ پانَے تہٕ تِمن ہٕندِ خٲطرٕ، یِمو أمِس سٍتـ̡ کھٮ۪وان ٲس، تِکیازِ مصری ہێکہِ ہێکہِ نہٕ عبرانین سٍتـ̡ روٹی کھٮ۪وان۔ تکیازِ یہ چھہ مصرین ہندِ خاطرہ اکھ مکروہ عمل۔\n33.\\tتہٕ تِم بِہتھ أمِس برونہہ کُن، گۅڈٕ زامُت تہٕ سارِوٕے کھۄتہٕ لۄکُٹ، تہٕ مرد گٔیہِ اَکھ أکِس سٍتـ̡ حٲران۔\n34.\\tتہٕ تٔمۍ نِش نِش تہٕ سوزُن تِمن برونہہ کُنہِ تہِ گۅنہٕ زیادٕ۔ تہٕ تِم ٲسۍ شیٚوُن، تہٕ أمِس سٍتۍ ٲسۍ خۅش گٔژھان۔ {ٲس...: ہیب۔ واریہس حدس تام چُھ پیومُت}","1.\\tتہٕ تٔمۍ دِیُت پننِس گرٕ کِس مٲلِس حُکُم تہٕ وونُن زِ مردن ہٕندِس بۄٹہٕ بٔرِتھ کھٮ۪نہٕ سٍتـ̡ بٔرِتھ، تہٕ پرٮ۪تھ أکِس شخصہٕ سٕندِس پٲنسہٕ ترٲوِن تٔمِس بۄرٕ سٕندِس ٲسس منٛز۔ {سٹیورڈ...: ہیب۔ سُہ یُس أمۍ سٕنٛدِس مکانس پیٹھ اوس}\n2. تہٕ میون پیالہ رۄپہٕ پیالہ تھووُن لۄکٹِس بوری ہٕندِس ٲسس منز، تہٕ تٔمۍ سٕندِس مکایہٕ پٲنسہٕ۔ تہٕ تٔمۍ کٔر تتھ لفظس مطٲبق یُس یوسف اوس بولمُت۔\n3.\\tیُتھُے صُبح گاش گوو، مرد سوزنہٕ آمٕتۍ، تِم تہٕ تِہٕندِس گٔرۍ۔\n4. {تہٕ}ییلہ تِم شہرٕ نیبر نیرِتھ، {تہٕ} وُنہِ تہِ دوٗر نہٕ، یوسفَن ووٚن پننِس نوکرس سٍتـ̡ ہیوٚر پَتہٕ۔ تہٕ ییلہ تِمن لٔگِتھ تہٕ تِمن ؤنِو، کیازِ دِیُت بُرُک بدلہٕ؟\n5. {یہ} چُھ نہٕ یہٕ {یہ} یتھ مَنٛز میون رب چیوان چُھ، تہٕ کمہِ سٍتـ̡ چُھہ سُہ خدایہ دِوان؟ تۅہہ کٔر یہ کٔرِتھ بُرۍ۔ {خدایہ: یا، کٔرِتھ آزمٲیش؟}\n6.\\tتہٕ تٔمۍ کٔر تِمن سٍتـ̡ یۅہے کتھ تہٕ تِمن سٍتـ̡ یۅہے کتھ کٔرِتھ۔\n7. تہٕ تِمو ووٚن أمِس زِ میانہِ آقا کیازِ چُھ یِم کتھ ونان ؟ خدا نہ کرِ تہندِ خادمَن یَتھ کتھہِ مُطٲبِق کرُن:\n8.\\tوُچھ، یُس پونسہٕ اسہِ پننین بورن ہٕندِس ٲسس مَنٛز لبنہٕ آو، أسۍ دُبارٕ کنعان کِس سرزمینہٕ منزٕ ژٔرِتھ ژٔرِتھ: تیلہِ کِتھہ کٔنۍ کٔرِو أسۍ تہندِ آقا سٕندِ گرٕ منزٕ رۄپہٕ یا سۄنہٕ ژوٗرِ نِن؟\n9.\\tچانہِ خادمَن مَنٛز یُس تہِ لبنہٕ ییہِ، سُہ گژھہِ دۅشوے مَرُن، تہٕ أسۍ تہِ بٔنِو میانہِ آقا سٕندِ بند۔\n10.\\tتہٕ ووٚن، وۅنۍ تہِ گژھ یہ تہِ تہِ پننہِ کلامَس مطٲبق {بنہِ}: یُس یُس یہ لبنہٕ ییہِ سُہ آسہِ میون خادم۔ تہٕ تُہۍ گژھِو بے عیب ۔\n11. پَتہٕ تِمو ژٔٹِتھ پرٮ۪تھ أکِس شخٕصس سُند بۄٹہٕ زٔمیٖنس پیٹھ، تہٕ کھولُن پرٮ۪تھ أکِس شخصس پنُن بۄرٕ۔\n12.\\tتہٕ تٔمۍ ژھانڈُن، {تہٕ} لوٚگ زِٹھِس پیٹھ، تہٕ لوٚگ لۄکٹِس پیٹھ، تہٕ پیالہ آو بنیامین سٕندِس بورس منز لبنہٕ۔\n13.\\tپَتہٕ کٔرِکھ تِمو پَنٕنہِ پَلَو کٔرِتھ، تہٕ پرٮ۪تھ أکِس شخٕصس سٕندِس گٔرِس سٍتـ̡ دِژٕکھ تہٕ واپس شہر\n14. تہٕ یہوداہ تہٕ تٔمۍ سٕندِ بٲے آیہ یوسف سٕندِس گرس منز۔ تکیازِ سُہ اوس وُنہِ تہِ تتہِ: تہٕ تِم پیوٚو أمِس برونہہ کُن زمینس پیٹھ۔\n15.\\tتہٕ یوسفَن ووٚن تِمَن زِ یہِ کُس عمل چُھ کٔرمُت؟ ژیہ کیا چھہ نہ یہ زِ میہ ہیو انسان ہیکہِ یقینا خدایہ کٔرتھ۔ {خدایہ: یا، کٔرِو مقدمہٕ؟}\n16. تہٕ یہوداہ ووٚن، أسۍ کیا وَنُن پننِس آقا؟ اسہِ کیا کتھ کرو ؟ یا أسۍ کِتھٕ کٔنۍ کرو پنُن پان صاف کٔرتھ؟ خداین چُھ تہندٮ۪ن بندن ہٕنز بدکاری ہُند پتہ لوٚگمُت: وُچھِو أسۍ چھِ میانِس آقا سٕندِ خادم، أسۍ تہٕ سُہ تہِ یِمن سٍتـ̡ پیالہ لبنہٕ آمُت چھُ۔\n17.\\tتہٕ ووٚن خدایہ نَہ زِ بہٕ کرٕ یہِ کرُن: {مگر} یٔمۍ سٕندِس اتھس مَنٛز پیالہ لبنہٕ آسہِ، سُہ آسہِ میون خادم۔ تہٕ یوٚت تام تۅہہِ وُچھِو، تُہۍ تھوٚد پننِس مٲلِس نِش۔\n18.\\tتێلہِ آو یہوداہ أمِس نِش تہٕ وونُن، اے میانہِ آقا، تێہٕنـ̡ خادم، بہٕ چُھس دُعا کران زِ تێنـ̡ پننِس خادمس سٍتـ̡ کُنہِ\n19.\\tمیانہِ مالہِ پرژھ پننین خدمتگارن زِ کیا تۅہہ چھا مول یا بٲے؟\n20. تہٕ أسۍ ووٚن پننِس آقاہس زِ اسہِ چُھ اکھ مول، اکھ بُزرگ، تہٕ اکھ بُزرگ شُر، اکھ لۄکُٹ۔ تہٕ تٔمۍ سُنٛد بوے چُھ موٗدمُت، تہٕ سُہ چُھ تنہا ماجہٕ نِش بچومُت، تہٕ تٔمۍ سُنٛد مول چُھ أمس محبت۔\n21. تہٕ ژے ووٚن پننین خادمَن زِ سُہ أنِو میانہِ نِش یُتھ بہٕ أمِس کُن نظر تھاوُن۔\n22.\\tتہٕ أسۍ ووٚن میٲنِس مٲلس زِ لڑکہٕ ہیکہِ نہٕ پننِس مٲلس ترٲوِتھ، تکیازِ {یێلہ} سُہ پننِس مٲلس تراوُن، {تٔمۍ سُند مول} گژھہِ مرُن۔\n23. تہٕ ژے ووٚن پننین خادمَن زِ یوٚت تام تُہند لۄکُٹ بٲے ژےٚ سٍتـ̡ بۄن یِنہٕ، تۅہہ وُچھِو نہٕ میون بُتھ وُچھِتھ۔\n24. تہٕ یہِ سپُد ییٚلہِ أسۍ تُہٕندِس خادمَس نِش وٲتِو، أسۍ وَنُن أمِس پننِس آقا سٕندِ کلام۔\n25.\\tتہٕ سٲنِس مٲلہِ ووٚن، بییہِ گژھ اَسہ رژھ کھٮ۪ن۔\n26. تہٕ أسۍ ووٚن، أسۍ ہیٛکو نہٕ بۄن گژھِتھ: اگر سون لۄکُٹ بوے اسہِ سٍتـ̡ آسہِ، تیلہِ گژھو أسـ̡ بۄن پٲٹھۍ، تکیازِ أسـ̡ ہێکہِ نہٕ أمِس شخصہٕ سُند بُتھ وُچھِتھ، سوائے پننِس لۄکٹِس بٲے سٍتـ̡ اسہِ سٍتـ̡ ۔\n27.\\tتہٕ تُہٕندِس خادمَس ووٚن میانہِ مٲلہِ زِ میانہِ زنانہِ چھے میہ زٕ نیچوۍ:\n28.\\tتہٕ سُہ دراو میانہِ نِش، تہٕ میہ وونُن، یٔقیٖنی طور چُھ سُہ ٹُکرٕ ٹُکرٕ کرنہٕ آمُت۔ تہٕ مے وُچھ نہٕ سُہ تنہٕ پتہٕ:\n29.\\tتہٕ اگر ژے یہ تہِ میانہِ نِش نِش نِتھ تہٕ أمِس مُشکِل گژھہِ، تہٕ ژے کٔرِو میٲنۍ سٲرۍسٕے مس غمس سٍتۍ قبرس کُن۔\n30. تێلہِ ییلہ بہٕ پننِس خادمس نِش یِوان چھُس، پننِس مٲلس تہٕ لڑکہٕ گژھہِ نہٕ اسہِ سٍتـ̡ ۔ یہ وُچھِتھ زِ تٔمۍ سٕنز زندگی چھے لڑکہٕ سٕنزِ زندگی سٍتۍ وابستہٕ؛\n31.\\tییلہ سُہ وُچھِتھ زِ لڑکہٕ {چُھ} نہٕ اسہِ سٍتـ̡ سٍتـ̡ سُہ مرُن، تہٕ تۅہٕندِس خادمَس سٍتـ̡ سٍتـ�\n32.\\tتکیازِ تُہند خادم بنیوو میٲنِس مٲلِس نِش أمِس سٍتـ̡ ضامن تہٕ وونُن زِ اگر بہٕ نہٕ سُہ ژےٚ نِش أنِتھ تہٕ بہٕ ہمیشہٕ پننِس مٲلِس سٍتـ̡ الزام برداشت کٔرِتھ۔\n33.\\tتێلہِ چُھس بہٕ ژے دُعا کران زِ پنُن خادم روزُن لڑکہٕ سٕندِ بدلہٕ میانِس آقا سُند غلام ۔ تہٕ لڑکہٕ گژھن پننین باین سٍتۍ۔\n34.\\tبہٕ کِتھہ کٔنۍ گژھہٕ پننِس مٲلِس نِش، تہٕ لڑکہٕ آسہِ نہٕ مےٚ سٍتۍ؟ بہ اوسس نہ میہ وچھان یُس میٲنس مٲلس پیٹھ ییہِ۔ {آ...: ہیب۔ میون مول ژھانڈُن}","1. تیلہِ ہیوٚک نہٕ یوسف تِمن سارِنٕے سارِنٕے سٍتـ̡ پانس سٍتـ̡ رُکٲوِتھ یِم أمِس سٍتـ̡ تہٕ تٔمۍ ووٚن، پرٮ۪تھ کانٛہہ نفر کٔرِو میانہِ نِش نیبر۔ تہٕ تس سٍتـ̡ اوس نہٕ کانہہ نفر کھڑا ییلہ زن یوسفن پننین باین نِش پانس واقف کٔرِتھ۔\n2. تہٕ سُہ روو بَڑِ پٲٹھۍ، تہٕ مصری تہٕ فرعون سٕندِس گھرس بوز۔ {روُن...: ہیب۔ دِژ وَننہٕ سٍتـ̡ پنٕنۍ آواز}\n3. تہٕ یوسفَن ووٚن پننٮ۪ن باین زِ بہٕ چُھس یوسف۔ میون مول چھا وُنہِ تہِ زندٕ؟ تہٕ تٔمۍ سٕندۍ بٲے ہیوٚک نہٕ أمس جواب دِتھ۔ تکیازِ تِم ٲسۍ تٔمۍ سٕنزِ موجودگی سٍتۍ پریشان۔ {پریشان: یا، خوفزد}\n4.\\tتہٕ یوسفَن ووٚن پننین باین زِ یِمو میہ نزدیک، بہٕ چُھس ژےٚ دُعا کران۔ تہٕ تِم آیہِ نزدیک۔ تہٕ تٔمۍ ووٚن، بہٕ چُھس یوسف تُہند بوے یُس ژے مصرس مَنٛز کٕنُن۔\n5. تێمہِ کِنۍ گژھ نہٕ غمگیٖن تہٕ نہ پانس سٍتـ̡ ناراض گژھُن، یێلہِ ژے مے یێلہِ کٕنـ̡ دِژمُت چُھ، کیازِ خداین اوس مے ژے برونہہ کُن زُو رژھراونہٕ خٲطرٕ سوزمُت۔ {nor...: Heb. نہ گژھہِ چانہِ اچھن منز شرارت آسُن}\n6.\\tیمن دۅن ؤرین منز چھہ قحط {رود} زمینس منز، تہ توتہِ چھہِ پانژھ ؤری، یمن منز {تتہِ} آسہِ نہ کُن تہ نہ فصل۔\n7. تہٕ خداین سوز میہ ژے برونہہ کُن تہِ زِ تۅہہِ سٍتـ̡ زمینس مَنٛز اولاد رژھراونہٕ خٲطرٕ، تہٕ تُہند زُو بچاونہٕ خٲطرٕ۔ {محفوظ کرنہٕ خٲطرٕ...: ہیب۔ تۅہہِ خٲطرٕ اکھ باقیات تھاونہٕ خٲطرٕ}\n8. تہٕ وُنہِ اوس نہٕ ژے یُس میہ یور سوزمُت، بلکہ خدایہ تہٕ تٔمۍ بنوو میہ فرعونس سُند مول تہٕ پننِس سارِنٕے گرُک مٲلک، تہٕ سارِنٕے مصرٕچ سرزمینس منز حکمران۔\n9. جلدی کرو تہٕ میٲنس مٲلس نِش گژھ تہٕ ونُن زِ تُہند نیچو یوسف چُھ ونان زِ خداین بنوو مے سارِنٕے مصرُک مٲلک۔\n10. تہٕ ژٕ روزو گوشن کِس ملکس مَنٛز روزُن، تہٕ تہٕ تُہۍ گژھِو میہ نزدیک، تہٕ پنٕنۍ شُرۍ، تہٕ پنٕنۍ بچن ہٕندِس شُرۍ، تہٕ پنٕنۍ چارٕو، تہٕ تُہۍ یِمن سارِنٕے چیزن ہٕندِس نزدیک۔\n11. تہٕ اَتہِ کٔرٕ بہٕ ژےٚ رچھ۔ تکیازِ توتہِ چھہ پانژھ ؤری قحط۔ متان، تُہۍ تہٕ تُہند گرٕ تہٕ یُس تہٕ تُہٕندِس سارِنٕے سٍتـ̡ غریبی ہُند شکار گژھہِ۔\n12. تہٕ وُچھِو تُہٕنزِ أچھ تہٕ میٲنِس بٲے بنیامین سٕنزِ أچھ وُچھان زِ یہِ چُھہ میٲنۍ ٲسِس یُس ژے سٍتـ̡ کتھ کران چُھ۔\n13.\\tتہٕ ژٕ وَنُن میٲنِس مٲلِس مصرس مَنٛز میانہِ سارِنٕے عظمتٕچ تہٕ یُس تہٕ یُس ژے وُچھمُت چھُ۔ تہٕ تُہۍ کٔرِو جلدی کٔرِتھ میون مول یور والنہٕ۔\n14.\\tتہٕ سُہ پیوٚو پننِس بٲیِس بنیامین سٕنزِ گردنہِ پیٹھ تہٕ ووٚنُن۔ تہٕ بینجمن ووٚتھ گردنہِ پیٹھ۔\n15.\\tامہِ علاوٕ کٔر تٔمۍ پننین سارنٕے باین بوسہ تہٕ رووُن تِمن سٍتـ̡ تہٕ تمہ پتہٕ کٔر تٔمۍ سٕندِس بٲے سٍتـ̡ أمِس سٍتـ̡ کتھ باتھ۔\n16.\\tفرعون سٕندِس گرس مَنٛز آو اَمہِ سٕنز شہرت بوزنہٕ، یہِ وَنُن زِ یوسف سٕندِ بٲے آیہ آمٕتۍ، تہٕ اَمہ سٍتـ̡ گٔیہِ فرعونس تہٕ تٔمۍ سٕندِس خادمَن خۅش گٔیہِ۔ {خوش...: ہیب۔ فرعون سٕنزِ نظرِ منز اوس اصل}\n17. تہٕ فرعونن ووٚن یوسفس زِ پننین باین وَنُن تہٕ تُہۍ کٔرِو یہِ کٔرِو۔ پَنٕنۍ درندٕ رٔٹِو، تہٕ گژھِو کنعان کِس سرزمینس تام۔\n18. تہٕ پنُن مول تہٕ پنٕنۍ گرٕ نِتھ تہٕ یِمو مےٚ نِش۔ تہٕ بہٕ دِیہٕ ژے مصرٕچ زمینٕچ بھلائی تہٕ تہٕ ژٕ کھیٚیہٕ زمینُک چربی ۔\n19.\\tوۅنۍ چُھہ تۅہہِ حکم دِنہٕ آمُت، یێلہِ کٔرِو یہِ کٔرِو۔ پننین لۅکٹٮن بچن تہ زنانن ہندِ خاطرہ نٮبر نیرِو مصر چہ زمینہِ منزہ نیبر تہ پنن مول أنِتھ یِن۔\n20.\\tپننہِ چیزس تہِ ما کرُن۔ مصرٕچ سارِنٕے سرزمینہٕ ہٕنز بھلائی خٲطرٕ چھُ تُہٕندِس سٍتـ̡ ۔ {حوالہٕ...: ہیب۔ پنٕنۍ أچھ گژھ نہٕ بچاونہٕ، وغیرہ۔}\n21. تہٕ بنی اسرائیلو کٔر یہِ تہٕ یوسف دِژ فرعون سٕندِ حُکمہٕ مُطٲبق تِمن گاڑِ تہٕ دِتُن تِمن وتہِ خٲطرٕ رزق دِنہٕ۔ {حکم: حب۔ ٲس}\n22.\\tتِمن سارِنٕے دِژ تِمو پرٮ۪تھ أکِس انسانس پَلَو بدلاوُن۔ مگر بینجمنس دِژ تٔمۍ ترے ہتھ رۄپہٕ تہٕ پانژھ بدلہٕ پلو۔\n23.\\tتہٕ تٔمۍ سوٗز پننِس مٲلِس یِتھٕ پٲٹھۍ۔ دَہ گَرٕ یِم مصرٕچ اصل چیز سٍتۍ بٔرِتھ، تہٕ دَہ گَرٕ یِم مکایہٕ تہٕ روٹی تہٕ ماز ہیتھ ٲسِتھ پننِس مٲلِس سٕندِ خٲطرٕ۔ {لادن...: ہیب۔ کیرینگ}\n24.\\tیێلہِ سوٗزۍ تٔمۍ پَنٕنـ̡ بٲے تہٕ تِم درٛاو تہٕ تِمو وَتہِ پى۪ٹھ۔\n25. تہٕ تِم گٔیہِ مصرہٕ پٮ۪ٹھٕ نٮ۪بر تہٕ وٲتِتھ کنعان کِس ملکس مَنٛز پننِس مٲلِس یعقوب نِش۔\n26.\\tتہٕ وونُن أمِس زِ یوسف چُھ وُنہِ تہِ زندٕ، تہٕ سُہ چُھ سارِنٕے مصرٕچ سرزمینس پیٹھ گورنر۔ تہٕ یعقوب سُند دِل گوو بے ہوش، تکیازِ تس اوس نہٕ تمن پیٹھ یقین کرنہٕ۔{یعقوب سُند: حب۔ ہس}\n27.\\tتہٕ تِمو ووٚن أمِس یوسف سٕندِ سٲری کلام، یِم تٔمۍ تِمن وَننہٕ خٲطرٕ سوزمٕژ ٲس، یِمن ہٕندِس مٲلِس یعقوب سُند روح وُچھمُت:\n28. تہٕ اسرایلن ووٚن {یہ} کٲفی۔ یوسف میون نیچو {چُھ} وُنہِ تہِ زندٕ: بہٕ گژھٕ مرنہٕ برونٛہہ أمِس وُچھان۔","1. تہٕ اسرٲیلَن کٔر پنُن سفر یُس تٔمِس نِش موجود اوس، تہٕ آو بیرشبع تہٕ کوٚرُن پننِس مٲلِس اسحاق سٕندِس خداہس خٲطرٕ قربانی۔\n2. تہٕ خداین کٔر رٲژ ہٕندِس خوابس مَنٛز اسرٲیلِس سٍتـ̡ کتھ تہٕ وونُن، یعقوب، یعقوب۔ تہٕ تٔمۍ ووٚن، یتھے {am} I.\n3. تہٕ ووٚن بہٕ چُھس خدا، تہٕ چُھس پننِس مٲلہِ سُند خدا: مصرس مَنٛز گژھنہٕ نِش گژھ نہٕ خوف۔ تکیازِ بہٕ بناوٕ تتہِ ژے اکھ عظیم قوم:\n4. بہٕ گژھٕ ژے سٍتـ̡ مصرس مَنٛز۔ تہٕ بہٕ تہِ کرٕ ژےٚ یٔقیٖنی طور تُہٕندِس أچھن پیٹھ اتھہٕ۔\n5.\\tتہٕ یعقوب ووت بیرشبع پیٹھٕ تہٕ یعقوب سٕندِ نیچو نِش یعقوب پنُن مول تہٕ تِہٕندِس لۅکٹۍ شُرۍ تہٕ زنانہٕ یِمن واگنن منز یِم فرعونن أمِس نِنہٕ خٲطرٕ سوزمٕژ ٲس۔\n6. تہٕ تِمو نِیہِ پنٕنۍ چاروٲے تہٕ پنُن سامان، یُس تِمو کنعان کِس سرزمینس مَنٛز حٲصل اوس کوٚرمُت، تہٕ آیٔے مصرس منز، یعقوب تہٕ تٔمۍ سُند سورُے بُل پانس سٍتـ̡ ۔\n7.\\tتٔمۍ سٕندِ نیچوۍ، تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡ تہٕ تٔمۍ سٕندِس نیچوِس سٍتـ̡ س�\n8.\\tتہٕ یِم چھِ یعقوب سٕندِس نیچوِس سٍتـ̡ یعقوب سٕندِ گۅڈنیُک ناو۔\n9. تہٕ روبن سٕندِ نیچو۔ ہنوچ، تہٕ پھالو، تہٕ ہیزرون، تہٕ کارمی۔\n10. تہٕ شمعون سٕندِ نیٚچوۍ۔ جیموئیل، تہٕ یمین، تہٕ اوہد، تہٕ جاچین، تہٕ زوہر، تہٕ شاؤل یُس کنعانی زنانہِ ہُند نیچو۔ {جیموئیل: یا، نیموئیل} {جاچین: یا، جریب} {زوہر: یا، زرہ}\n11. تہٕ لیوی سٕندِ نیٚچوۍ۔ گرشون، کوہاتھ تہٕ میراری۔ {گیرشن: یا، گرشوم}\n12. تہٕ یہوداہ سٕندِ نیٚچوۍ۔ ایر، تہٕ اونان، تہٕ شیلہ، تہٕ فراز، تہٕ زراح: مگر ایر تہٕ اونان موٗد کنعان کِس سرزمینس منٛز۔ تہٕ فریض سٕندۍ نیچوۍ ٲسۍ حزرون تہٕ ہمول۔\n13.\\tتہٕ اِساکر سٕندِ نیچوۍ۔ ٹولا، تہٕ پھووا، تہٕ ایوب تہٕ شمرون۔ {پھوہ، تہٕ ایوب: یا، پواہ تہٕ جاشوب}\n14. تہٕ زبولون سٕندِ نیچو۔ سیرڈ، تہٕ ایلون، تہٕ جاہل۔\n15.\\tیِم چھِ لیہ سٕندِ نیچوۍ، یُس تٔمۍ سٕنزِ کورِ دینہ سٍتـ̡ یعقوبس سٍتـ̡ پڈانارمس مَنٛز زامُت اوس، تٔمۍ سٕندِس نیچوِس تہٕ کورِ ہٕندِ سارِنٕے روحہٕ آسہٕ ترٕہ تہٕ ترٕہ وُہُر۔\n16. تہٕ گاد سٕندِ نیچو۔ زیفیون، تہٕ ہاگی، شونی، تہٕ ایزبون، ایری، تہٕ ارودی، تہٕ اریلی۔ {زیفیون: یا، زیفون} {ایزبون: یا، اوزنی} {ارودی: یا، آروڈ}\n17. تہٕ آشر سٕندِ نیٚچوۍ۔ جِمنہ تہٕ عیشوہ، تہٕ عیسوی، تہٕ بریاہ تہٕ سیرہ تِہٕنز بیٚنہِ: تہٕ بریاہ سٕندِ نیٚچِو۔ ہیبر تہٕ مالچیل۔\n18.\\tیِم چھِ زِلپاہ سٕندِ نیچوۍ، یِم لبن لیہ ہٕنز کورِ دِژمٕژ تہٕ یِم یعقوب سٕندِس نِش دِژمٕژ چھِ، یِم شُراہ روح۔\n19. ریچل جیکب سٕنزِ زنانہِ ہٕندۍ نیچوۍ۔ جوزف تہٕ بینجمن۔\n20.\\tتہٕ یوسفس سٍتـ̡ زاے منسیٰ تہٕ افرائیم، یُس آن کِس پادٕرۍ پوٹیفیرہ سٕنزِ کورِ آسناتھ أمِس نِش بٔرِتھ اوس۔ {پادری: یا، شہزادہ}\n21.\\tتہٕ بنیامین سٕندِ نیچوۍ ٲسۍ بیلہ، تہٕ بیکر، تہٕ اشبل، گیرا، تہٕ نعمان، ایہی، تہٕ روش، مُپِم، تہٕ ہُپِم تہٕ ارد۔ {ایہی: یا، اہیرم} {مُپِم: یا، شُپھم یا، شُپِم} {ہپِم: یا، ہپھام}\n22. یِم {چِھ} راحیل سٕندِ نیچوۍ، یِم یعقوب زامٕتۍ ٲسۍ: سارِنٕے روحہٕ ٲسۍ ژۄداہ۔\n23. تہٕ دانن سٕندِ نیچو۔ حشم۔ {ہشیم: یا، شوہام}\n24. تہٕ نفتالی سٕندِ نیٚچوۍ۔ جہزیل، تہٕ گونی، تہٕ جیزر، تہٕ شِلم۔\n25.\\tیِم چھہِ بلہہ سٕندِ نیچوۍ، یُس لابنن راحیلس پننہِ کورِ دِژمُت اوس، تہٕ تٔمۍ دِژ یعقوبس نِش یِم سَتھ ۔\n26.\\tیعقوب سٕندِس نیچوِس سٍتـ̡ یێمہِ سٍتـ̡ یعقوب سٕنزِ زنانہٕ سٍتـ̡ سارِنٕے روحہٕ یِم یعقوب سٕندِس نیچوِس سٍتـ̡ دِنہٕ آمٕتۍ، تِم سارِنٕے روحہٕ ٲسۍ تریہ تہٕ شےٚ۔ {loins: Heb. ران}\n27.\\tتہٕ یوسف سٕندِ نیچوۍ، یُس مصرس مَنٛز زامُت اوس، ٲسۍ زٕ روح: یعقوب سٕندِ گرٕکۍ سٲری روح، یُس مصرس مَنٛز آو، اوس تریہ تہٕ داہ۔\n28.\\tتہٕ تٔمۍ سوٗز یہوداہ پانس برونہہ کُن یوسفس نِش، یُس تٔمۍ سُند بُتھ گوشنس کُن واتناوُن۔ تہٕ تِم آیہ گوشن کِس سرزمینس منز۔\n29.\\tتہٕ یوسفَن کٔر پنُن رتھ تیار، تہٕ ووت پننِس مٲلِس اسرٲیلِس نِش مِلنہٕ خٲطرٕ، گوشنس نِش تہٕ کوٚرُن أمِس نِش پیش۔ تہٕ سُہ پیوٚو گردنہِ پیٹھ، تہٕ رودُن واریاہس کالس گردنہِ پیٹھ۔\n30. تہٕ اسرائیلن ووٚن یوسفس، وۅنۍ گژھ میہ مرُن، کیازِ میہ چُھہ تُہند بُتھ وُچھمُت، کیازِ ژٕ چُھکھ وُنہِ زندٕ۔\n31.\\tتہٕ یوسفَن ووٚن پننِس بٲے تہٕ پننِس مٲلہِ سٕندِس گرس منز، بہٕ گژھٕ ہیوٚر تہٕ فرعونس ہٲوِتھ تہٕ أمِس وَنُن، میانہِ بٲے تہٕ میٲنِس مٲلہِ سُند گرٕ یُس کنعان کِس سرزمینس مَنٛز اوس، چھُ میہ نِش آمُت۔\n32.\\tتہٕ مرد چِھہ چرواہ ، تکیازِ تِہند سودا چُھ چاروٲے چارہ دِنہٕ خٲطرٕ۔ تہٕ تِمو چھِ پنٕنۍ ریوٕ، تہٕ پنٕنۍ کھیٚلہٕ تہٕ یِمن نِش سٲرِسٕے چیٖز أنِمٕتۍ۔ {تہنز تجارت...: ہیب۔ تِم چِھ چارواین ہٕندۍ مرد}\n33.\\tتہٕ یێلہِ یێلہِ فرعون ژےٚ بُلاونہٕ تہٕ وَنُن زِ تُہُند پیشہٕ کیا چُھہ؟\n34.\\tیُتھ تہٕ تُہۍ وَنُن زِ تہندٮ۪ن خادمَن ہُند سودا چُھ سانہِ جوانی پیٹھٕ وُنیُک تام چارواین متعلق، أسۍ تہٕ سانین مٲلن تہِ: یُتھ زن تُہۍ گوشن کِس سرزمینس مَنٛز روزِو۔ پرٮ۪تھ کُنہِ چرواہ سٍتـ̡ چُھہ مصرین ہٕندِ خٲطرٕ مکروہ ۔","1. اَمہِ پَتہٕ آو یوسف تہٕ فرعونس ووٚن، تہٕ وونُن، میون مول تہٕ میٲنۍ بٲے تہٕ تِہٕندِ گالہٕ تہٕ تِہٕندِ چارٕ تہٕ یِمن ہُند سارِوٕے چیٖز چھُ کنعان کِس سرزمینہٕ منزٕ نیبر آمُت۔ تہٕ وچھ، تم {چِھ} گوشن کس سرزمینس منٛز۔\n2.\\tتہٕ تٔمۍ رٔٹۍ پنٕنۍ کینہہ بٲے تہٕ پانژھ نفر تہٕ کٔرٕن فرعونس برونہہ کُن پیش۔\n3. تہٕ فرعونن ووٚن پننین باین زِ تُہند پیشہٕ کیا چُھ؟ تہٕ تِمو ووٚن فرعونس زِ تہند خادم چِھہ چرواہ ، أسۍ دۅشوے تہٕ پنُن باپ تہِ۔\n4.\\tتِمو ووٚن فرعونس تہِ زِ أسۍ چھِ زمینس منز روزنہٕ خٲطرٕ یِوان۔ تکیازِ تہندٮ۪ن خادمَن چُھنہٕ پننین چارن ہٕندِ خٲطرٕ کانہہ مرگہٕ۔ تِکیازِ قحط چُھہ کنعان کِس سرزمینس مَنٛز دَگ دِنہٕ آمُت: تێمہِ کِنۍ چُھہ أسـ̡ ژے دُعا کران زِ پۯاوٕنـ̡ پى۪ٹھہٕ پى۪ٹھ۔\n5. تہٕ فرعونن ووٚن یوسفس سٍتـ̡ زِ تُہند مول تہٕ تُہند بٲے چھِ تۅہہِ نِش آمٕتۍ۔\n6. مصرٕچ سرزمین{چُھ} تۅہہِ برونہہ کُن۔ بہتٔریٖن زمینس مَنٛز بناو پنُن مول تہٕ بٲے روزنہٕ خٲطرٕ؛ گوشین کِس سرزمینس منز روزن تِم روزُن: تہٕ اگر ژیہ تِمن منز کانہہ تہِ سرگرمی تھاون وٲلۍ نفر زانان چھِ، تیلہِ بنٲوِو تِم میانین چارواین پیٹھ حکمران۔\n7. تہٕ یوسف اوٚن پنُن مول یعقوب تہٕ تھووُن فرعونس برونہہ کُن۔ تہٕ یعقوبن کٔر فرعونس برکت۔\n8. تہٕ فرعونن ووٚن یعقوبس زِ ژے کوتاہ وٲنسہِ؟ {کتھہ پاٹھۍ...: ہیب۔ چانہِ زندگی ہندۍ کٲتیا دۅہ چھہِ؟}\n9.\\tتہٕ یعقوبن ووٚن فرعونس زِ میانہِ زیارتٕکۍ ؤرین ہٕندِ دۅہہٕ چھِ ہتھ ترہ ؤری: میانہِ زندگی ہٕندِ ؤرین ہٕندِ دۅہہٕ چھِ کم تہٕ بُرٕ گٔمٕتۍ، تہٕ میانین مٲلن ہٕنزِ زندگی ہٕندِس دۅہس تام وٲتِتھ چھِنہٕ تِمن ہٕندِس زیارتس مَنٛز وٲتِتھ۔\n10. تہٕ یعقوبن کٔر فرعونس برکت تہٕ درٛاو فرعونس برونہہ کُن۔\n11.\\tتہٕ یوسفَن تھووُن پنُن مول تہٕ بٲے تہٕ دِتُن فرعونن حُکُم کٔرِتھ مصرٕکِس سرزمینس مَنٛز، بہترین زمینس مَنٛز، یِتھ کٔنۍ فرعونن حُکُم کوٚرمُت۔\n12. تہٕ یوسفَن کٔر پننِس مٲلِس تہٕ بٲے تہٕ مٲلہِ سٕندِس سارِنٕے گرس تہٕ تِہندِ خاندانہٕ مُطٲبق روٹی رچھان۔ {مطٲبق...: یا، یتھے پاٹھۍ چھہ لۅکٹۍ شُرۍ پرورش سپدان: ہیب۔ بقول لۅکٹۍ}\n13.\\tتہٕ سارِنٕے زمینس منز اوس نہٕ کانہہ روٹی ۔ تکیازِ قحط اوس سٮ۪ٹھاہ درد، یێلہِ زِ مصرٕچ سرزمین تہٕ کنعانٕچ سرزمینہٕ گٔیہِ قحط کِنۍ بے ہوش۔\n14. تہٕ یوسف کٔر مصرٕچ سرزمینس تہٕ کنعان کِس سرزمینس مَنٛز لبنہٕ آمٕتۍ سٲری پونسہٕ جمع یُس تِمو ہیوٚتمُت اوس تہٕ یوسف اوٚن پٲنسہٕ فرعون سٕندِس گھرس منز۔\n15.\\tییلہ مصر کِس سرزمینس تہٕ کنعان کِس سرزمینس مَنٛز پٲنسہٕ ناکام گٔیہ، سٲری مصری آیہِ یوسفس نِش تہٕ وونُن، اسہِ دِیُن روٹی، کیازِ اسہِ کیازِ گژھہِ چانہِ حضوری منز مرُن؟ پونسہٕ چُھ ناکام گژان۔\n16.\\tتہٕ یوسفَن ووٚن، پنٕنۍ چاروٲے دِیُن۔ تہٕ بہٕ دِیہ ژے چانہِ چارواین ہٕندِ بدلہٕ، اگر پٲنسہٕ ناکام گٔیہِ۔\n17. تہٕ تِمو أنۍ پنٕنۍ چاروٲے یوسفس نِش۔ تہٕ یوسفَن دِژ تِمن گُرٮ۪ن تہٕ چاروَن تہٕ گَرٮ۪ن ہٕندِ بدلہٕ روٹی تہٕ تِمن دِژ تِمن سارِنٕے چارواین ہٕندِ خٲطرٕ روٹی دِنہٕ۔ {فیڈ...: ہیب۔ تمن رہنمائی}\n18.\\tییلہ سُہ ؤری مۄکلیوو، تِم آیہِ أمِس نِش دۆیمہِ ؤریس نِش، تہٕ وونُن زِ أسۍ کٔرِو نہٕ پننِس مٲلکَس نِش ژوٗرِ روزُن، یُس سون پونسہٕ کِتھہ پٲٹھۍچُھہ خرچ سپدان۔ میانہِ مالہِ تہِ چھِ سانہِ چارواین ہٕندِ کھیٚلہٕ تہِ۔ میانِس آقا سٕندِس نظرس منز چُھنہٕ کانہہ باقٕے روزُن، بلکہ چُھہ سانہِ جسمہٕ تہٕ سانہِ زمینہٕ سٍتـ̡ باقٕے روزُن:\n19. اسہِ کیازِ مرو اسۍ تہِ پننہِ نظرِ برونہہ کنہِ۔ اسہِ تہٕ پنٕنۍ زمین ہینہٕ روٹی خٲطرٕ، تہٕ أسۍ تہٕ پنٕنۍ زمین بٔنِو فرعونس سٕندِ خادم: تہٕ دِیُن اسہِ بیٲل، یُتھ أسۍ زِندٕ روزِتھ تہٕ مٔرِتھ نہٕ مٔرِتھ، یُتھ زِ زمین گژھہِ نہٕ ویران۔\n20. تہٕ یوسفَن ہیوٚت فرعونس خٲطرٕ مصرٕچ سورے زمین۔ تکیازِ مصریو کُن پریتھ انسانس پنُن کھیت کُن، تکیازِ قحط اوس تمن پیٹھ غالب، تہ یتھہ پاٹھۍ بنیوو یہ زمین فرعونس سٍتۍ۔\n21.\\tتہٕ لُکن ہُند تعلق چھُ، تِمو کٔرِن مصرٕکِس سرحدٕ کِس اَکہِ اندس پیٹھٕ شہرن مَنٛز تہٕ اَمہ کِس اندس تام۔\n22.\\tصرف پادٕرین ہٕنزِ زمینہٕ ہیوٚت نہٕ۔ تکیازِ پادٕرین اوس فرعونن سُند اکھ حصہٕ تہٕ تِمو کھیوٚو پنُن حصہٕ یُس فرعونن تمن دِیُتمُت اوس، اوے کٕنۍ نہٕ تِمو پنٕنۍ زمینہٕ کٕننہٕ۔ {پادٕرۍ: یا، شہزادٕ}\n23. اَمہِ پَتہٕ ووٚن یوسفَن لُکن زِ وُچھو، یێلہِ چُھہ ژےٚ تہٕ تُہٕنٛز زمین فرعونس خٲطرٕ ہیوٚتمُت، یێلہِ چُھہ تۅہہِ خٲطرٕ بیول تہٕ تُہۍ کٔرِو زمینہٕ وونہٕ۔\n24.\\tتہٕ یێلہِ ہُرراونہٕ سٍتـ̡ گژھہِ ژۅن حِصہٕ فرعونس دِنہٕ، تہٕ ژور حصہٕ گژھہِ تۅہہِ ہٕندِس کھہٕ کِس بیٲلِس تہٕ کھٮ۪نہٕ خٲطرٕ، تہٕ تِمن ہٕندِ خٲطرٕ تہٕ پننین شُرین ہٕندِ کھٮ۪نہٕ خٲطرٕ۔\n25.\\tتہٕ تِمو ووٚن، ژے بچٲوۍ سانہِ زُو تہٕ أسۍ بٔنِو فرعون سٕندِس خادم۔\n26.\\tتہٕ یوسفَن بنوو از تام مصرٕچ سرزمینس پیٹھ شریعت ، {یُس} فرعونس گژھہِ پٲنژِم حصہٕ۔ صرف پادٕرین ہٕنزِ سرزمینہٕ ورٲے، {یُس} بنیوو نہٕ فرعونن سُند۔ {پادٕرۍ: یا، شہزادٕ}\n27. تہٕ اسرائیل اوس مصر کِس ملکس مَنٛز، گوشن کِس ملکس مَنٛز روزان۔ تہٕ تمن ٲس اتھ منٛز ملکیت، تہٕ گٔیہٕ بڑان، تہٕ گٔیہٕ واریاہ زیادٕ۔\n28.\\tتہٕ یعقوب روٗد مصر کِس سرزمینس مَنٛز سدہ وُہُر، یِتھٕ پٲٹھۍ اوس یعقوب سُند سورُے وٲنسہِ اکھ ہتھ تہٕ ستتٲجی وُہُر۔ {پورٕ...: ہیب۔ تمۍ سنزِ زندگی ہندین ؤرین ہندۍ دۅہ}\n29.\\tتہٕ ووت وقت نزدیک زِ اسرٲیلِس گژھہِ مرُن، تہٕ تٔمۍ بُلوو پنُن نیچو یوسف، تہٕ وونُن تٔمِس زِ اگر وُنہِ میہ چانہِ نظرِ منز فضل میلہِ، بہٕ تھاوُن ژے پنُن اتھہٕ میانِس رانس تَل تہٕ میانہِ سٍتـ̡ رحمدٲری تہٕ پٔزۍ پٲٹھۍ سلوک کرُن۔ بہٕ چھُس نہٕ ژےٚ دفن کٔرِتھ، مصرس مَنٛز:\n30. مگر بہٕ روزٕ پننین مٲلن سٍتـ̡ تہٕ ژے کٔرِکھ مے مصرہٕ منزٕ نِتھ تہٕ تِہٕنزِ قبرستانس مَنٛز دفن۔ تہٕ تٔمۍ ووٚن، بہٕ کٔرٕ یُتھ ژےٚ ووٚنمُت۔\n31.\\tتہِ ووٚن میہ قسم۔ تہٕ سُہ چُھ أمِس قسم۔ تہٕ اسرٲیلَن کٔر بسترس پیٹھ نمُن۔","1.\\tتہٕ یِمو کتھہٕ پَتہٕ سپُد یوسفس ووٚن زِ تُہند مول چُھ بٮ۪مار، تہٕ تٔمۍ نِیہِ پانس سٍتـ̡ پنٕنۍ زٕ نیچوۍ مناسی تہٕ افرائیم۔\n2. تہٕ یعقوب ووٚن تہٕ ووٚنُن، وُچھ، تُہند نیچو یوسف چُھ توے نِش یِوان، تہٕ اسرٲیلَن کٔر پانس مضبوط، تہٕ بیوٹھ بسترس پیٹھ۔\n3. تہٕ یعقوبن ووٚن یوسفس، خدایہ تعالیٰ آو کنعان کِس سرزمینس مَنٛز لوزس مَنٛز میہ نِش ظٲہر تہٕ کٔرٕن مےٚ برکت،\n4. تہٕ وونُن مے، وُچھ، بہٕ کٔرٕ ژے پھل دار تہٕ ژے بڑاوٕ تہٕ بہٕ بناوٕ ژے اکھ بٔڑ لوکھ۔ تہٕ دِیہٕ یہِ زمین ژےٚ پتہٕ تُہنزِ اولادس دِنہٕ خٲطرٕ۔\n5.\\tتہٕ وۅنۍ چُھہ تُہند زٕ نیچوۍ افرائیم تہٕ منسیہ، یِم میانہِ نِش مصرس منز یِنہٕ برونہہ مصر کِس سرزمینس مَنٛز ژےٚ زامٕتۍ ٲسۍ، چھِ میٲنۍ ۔ روبن تہٕ شمعون سٕندۍ پٲٹھۍ، تِم آسن میٲنۍ ۔\n6. تہٕ تُہُند مسلہٕ، یُس تہٕ تِمن ہٕندِس وراثتس مَنٛز یِیہِ تِہٕندِس بٲے سٕندِس ناوٕ سٍتـ̡ وننہٕ یُن۔\n7.\\tتہٕ یێلہِ بہٕ پادان پٮ۪ٹھٕ آو، راحیل موٗد میانہِ دٔسۍ کنعان کِس سرزمینس مَنٛز، یێلہِ تہٕ اَفراتھس تام واتنٕچ وَتھ ٲس، تہٕ مے کٔر سُہ اَفراتھ سٕندِ وتہِ دفن۔ یۅہے بیت اللحم۔\n8. تہٕ اسرٲیلَن وُچھ یوسف سٕندِس نیچوِس تہٕ وُچھِن، یِم کُس چھِ؟\n9. تہٕ یوسفَن ووٚن پننِس مٲلِس زِ تِم چھِ میٲنۍ نیٚچِوۍ، یِم خداین مےٚ یَتھ جایہِ دِژمٕژ چھِ۔ تہٕ تٔمۍ ووٚن، تِم أنِو، بہٕ چھُس ژےٚ دُعا کَران، تہٕ بہٕ کَرٕ تِمن برکت۔\n10.\\tوۅنۍ ٲس اسرٲیلٕچ أچھ وٲنسہِ سٍتـ̡ مدھم گٔمٕژ، {یێلہِ} ہیوٚک نہٕ تس وُچھان۔ تہٕ تٔمۍ أنۍ تِم پانس نزدیک۔ تہٕ تٔمۍ کٔر تمن بوسہ تہٕ رٔٹتھ رٔٹ۔ {ڈِم: ہیب۔ گوٚب}\n11. تہٕ اسرائیلن ووٚن یوسفس، میہ اوس نہٕ تُہند بُتھ وُچھنُک خیال تہٕ یێلہِ خداین ہٲومُت تُہند بُتھ تہِ۔\n12.\\tتہٕ یوسف کٔر یِم پننیو کۅٹھو منزہ نیبر تہٕ تٔمۍ کٔر زمینس کُن بُتھ تھٲوِتھ نمُن۔\n13.\\tتہٕ یوسفَن رٔٹِتھ یِم دٔچھُن اَتھٕ کُن اِسرٲیلِس کُن تہٕ منسیٰ دٔچھُن اَتھٕ کُن اِسرٲیلِس دٔچھنِس اتھس کُن، تہٕ أنِن تِم پانس نزدیک۔\n14. تہٕ اسرائیلن ترووُن پنُن دٔچھُن اتھٕ تہٕ تھووُن افرائیم سٕندِس کلس پیٹھ، یُس لۄکُٹ اوس، تہٕ تٔمۍ سُند کھوورٕ اتھہٕ منسیٰ سٕندِس کلس پیٹھ، تہٕ کوٚرُن تٔمۍ سٕندِس اتھہٕ سٍتـ̡ زٲنِتھ پٲٹھۍ۔ تکیازِ مناسیٰ اوس گۅڈنیُک زامُت۔\n15. تہٕ تٔمۍ کٔر یوسف سُند دُعا تہٕ وونُن، خدایہ، یٔمۍ سٕندِ برونہہ میانہِ باپ ابراہیم تہٕ اسحاق پکان ٲسۍ، سُہ خدایہ یٔمۍ از تام میانہِ سارِوٕے وٲنسہِ کھٮ۪ن دِژمُت،\n16.\\tفرشتہ یمۍ میہ سارِوٕے بدی نِش نجات دِژ، سُہ کرِ لڑکہٕ دعا۔ تہٕ یِمن پیٹھ گژھہِ میون ناو تہٕ میانین بابن ابراہیم تہٕ اسحاق سُند ناو تھاونہٕ۔ تہٕ تِم گژھن زمینہٕ کِس وسطس منز بٔڑِتھ بٔڑِتھ۔ {بڑو: ہیب۔ یتھ کٔنۍ گاڈٕ چِھ بڑان}\n17.\\tتہٕ ییلہ یوسف وُچھ زِ تٔمۍ سٕندِس مٲلہِ اوس افرائیم سٕندِس کلس پیٹھ دٔچھُن اتھہٕ تھوومُت، تٔمِس کٔر تٔمِس ناراض تہٕ تٔمۍ تُل پننِس مٲلہِ سُند اتھہٕ افرائیم سٕندِس کلس پیٹھٕ منسیٰ سٕندِس کلس پیٹھ۔ {ناراض...: اوس تٔمۍ سٕنزِ نظرن منز بدکار}\n18.\\tتہٕ یوسفَن ووٚن پننِس مٲلِس زِ یێلہِ چُھہ نہٕ میانہِ مٲلہِ سٍتـ̡ یێلہِ چُھہ گۅڈٕ زامُت۔ پنُن دٔچھُن اَتھٕ تھٲوِو أمۍ سٕنٛدِس کلَس پیٹھ۔\n19.\\tتہٕ تٔمۍ سٕندِس مٲلہِ کٔر اِنکار، تہٕ وونُن، بہٕ چُھس پتاہ زِ سُہ تہِ بنہِ قوم تہٕ سُہ تہِ بٔڈ بنہِ، مگر پٔزۍ پٲٹھۍ آسہِ تٔمۍ سُند لۄکُٹ بوے أمِس کھۅتہٕ بوڈ تہٕ تٔمۍ سُند بُل بنہِ قومن ہُند بٔڈ۔ {کثیر: ہیب۔ مکمل آسن}\n20. تہٕ تٔمۍ دِژ تِمن دُعا دُعا دِتھ وونُن، اِسرٲیلِس دِیہِ توے سٍتـ̡ برکت تہٕ وونُن زِ خدایہِ بناو ژے افرائیم تہٕ منسی ہٕندِس پٲٹھۍ، تہٕ تٔمۍ تھوو افرائیم منسیہس برونہہ کُن۔\n21. تہٕ اسرائیلن ووٚن یوسفس، وچھ بہٕ مرُن، مگر خدا آسہِ توے سٍتۍ، تہٕ اَننہٕ تہٕ تُہہِ دُبارٕ پننین آباؤ اجدادن ہٕندِس سرزمینس مَنٛز۔\n22.\\tامہِ علاوٕ چُھس مے ژے پننین باین ہُند اکھ حصہٕ دِژمُت، یُس میہ پننہِ تلوار تہٕ کمانہٕ سٍتـ̡ اموری سٕندِ اتھہٕ سٍتـ̡ نِش نِیومُت۔","1. تہٕ یعقوبن بُلوو پننین نیچوین تہٕ ووٚنُن، یُس ژے وَنُن یُس ٲخری دۅہن منز سپدِ۔\n2. یعقوب سٕندِس نیٚچو، یعقوب سٕندِس فرزندو سٍتـ̡ پَنُن پان جمع کٔرِو۔ تہٕ پَنُن باپ اسرٲیلِس سٍتـ̡ بوزُن۔\n3. روبن، ژے چُھہ میون گۅڈنیُک زامُت، میٲنۍ طاقت، تہٕ میانہِ طاقتُک آغاز، عظمتٕچ برتری تہٕ طاقتٕچ برتری ہُند:\n4. آبہٕ ہٕندۍ پٲٹھۍ غیر مستحکم، تہٕ ژے گژھِ نہٕ سبقت حٲصل کٔرِتھ۔ تکیازِ ژے چھکھ پننس مٲلہِ سٕندِس بسترس تام ووتمت؛ اَمہ پتہٕ کٔر ژے ناپاک کٔرِتھ: سُہ ووت میٲنِس کاؤچس پیٹھ۔ {توے کرُن...: ہیب۔ ژیہ ما کرو بہتر} {سہ گۆو...: یا، میون کاؤچ گومُت}\n5. شمعون تہٕ لیوی {چِھ} بٲے۔ ظُلمٕکۍ آلہٕ {چِھ} تِمن ہٕندِس بستی منز۔ {آلات...: یا، تہنز تلوار چھِ تشددک ہتھیار}\n6.\\tاے میانہِ روح، ژیہ نہ تہندِس رازس منز اژُن۔ تِہٕنزِ مجلسہٕ خٲطرٕ، میانہِ عزت، ژٕ گژھ نہٕ یکجا گژھُن: کیازِ پننہِ شرارتس منز مور تِمو اکھ انسان، تہٕ پننہِ مرضی سٍتۍ کھٔنِتھ کٔر دیوار۔ {کھٔنِتھ...: یا، ہوٚگ بیل}\n7.\\tتِمن ہُند غصہٕ بد دعا کٔرِتھ، تکیازِ {یہِ} اوس شدید۔ تہٕ تِہُند غصہٕ، تکیازِ یہِ اوس ظالمانہٕ: بہٕ کٔرٕ تِم یعقوبس مَنٛز تقسیٖم، تہٕ کٔرٕ تِم اسرٲیلس مَنٛز پھٔٹِتھ۔\n8. یہوداہ، تُہۍ چُھہ سُہ یٔمِس تُہٕندِس بٲے تعریف کرِ: تُہُند اَتھٕ آسہِ تُہٕندِس دُشمن ہٕندِس گردنَس مَنٛز۔ تہندِس مٲلہِ سٕندِ شُرۍ گٔژھن ژےٚ برونہہ کُن نمن۔\n9.\\tیہوداہ چُھہ شیر سُند بُر: شِکارٕ نِشہ چُھہ میانہِ نیچو، ژے ہیوٚت تھوٚد: سُہ ووت بوٚن، سُہ اوس شیر سٕندِ پٲٹھۍ، تہٕ بُزرگ شیر۔ تس کُس کرِ بیدار؟\n10.\\tیہوداہ سٍتـ̡ گژھِ نہٕ یہوداہ سٍتـ̡ نیرُن، تہٕ نہ کانہہ شریعت دِنہٕ وٲلِس کھورِ منز، یوتام نہٕ شیلوہ یِنہٕ۔ تہٕ أمِس خٲطرٕ گژھِ لُکن ہُند اجتماع {be}۔\n11.\\tپننِس بچہٕ سٍتۍ گٔنڈِتھ تہٕ تٔمۍ سٕندِس گٔرِس گُرِ سٍتۍ گٔنڈِتھ۔ تٔمۍ چھلکھ پنٕنۍ پلو شرابس منٛز، تہٕ پنٕنۍ پلو چھلنہٕ انگور کِس خونس منٛز:\n12.\\tتٔمۍ سٕنزِ أچھ گٔژھ شرابٕ سٍتۍ وۄزل تہٕ دند گژھن دۄدٕ سٍتۍ سفید۔\n13. زبولون روزِ سمندرٕ کِس پناہ گاہَس مَنٛز۔ تہٕ سُہ آسہِ جہازن ہٕندِس پناہ گاہٕ خٲطرٕ؛ تہٕ تٔمۍ سُند سرحد آسہِ زیدونس تام۔\n14. اِساکر {چُھ} اکھ مضبوٗط گَرٕ یُس دۄن بوجھن درمیان بٔنِتھ چُھ:\n15.\\tتہ وُچھ سہ آرام {اوس} اصل، تہٕ زمین یُس {یہ} خۄشگوار اوس۔ تہٕ بنیوو پنن پھیُر برداشت کرنہٕ خٲطرٕ، تہٕ بنیوو خراج تحسین پیش کرنہٕ خٲطرٕ نوکر۔\n16.\\tدان کرِ پننین لوکن ہند فیصلہ یُس اسرٲیلِک قبیلہٕ منزٕ اکھ سٍتـ̡ دِنہٕ۔\n17.\\tدان گژھہِ وتہِ وتہِ منز اکھ ناگ، یُس گُرِ کھورِ کھورِ کھسِتھ ژٹان آسہِ، یُس سُہ سوارِ پوٚت پیوٚو۔ {اکھ ایڈر: ہیب۔ اکھ تیر ناگ}\n18. اے خداوند، بہٕ چُھس چانہِ نجات ہُند انتظار کورمُت۔\n19. گاڈ، اکھ فوج کرِ أمِس پیٹھ غلبہٕ، مگر سُہ گژھہِ ٲخرس پیٹھ فتح حٲصل۔\n20.\\tآشرس سٍتـ̡ گژھہِ تٔمۍ سٕنزِ روٹی موٚٹۍ، تہٕ سُہ گژھہِ شٲہی لذیذ دِنہٕ۔\n21.\\tنفتالی چھہ اکھ ہِندِ یلہٕ تراوان: سہ چھہ نیک کلام دوان۔\n22.\\tیوسف چُھہ اکھ پھلدار کُن، {حتیٰ کہ} چُھہ کُنہِ پھلہٕ دار لُن؛ {whose} لنجہٕ چِھ دیوارس پیٹھ پکان: {branches: Heb. کورِ}\n23.\\tتیر اندازو چُھ أمِس سٮ۪ٹھاہ غمگسار کورمُت، تہٕ گوٗلۍ لگٲوِکھ أمِس سٍتـ̡ نفرت:\n24.\\tمگر تٔمۍ سٕنز کمان ٲس طاقتہٕ سٍتـ̡ بٔنِتھ تہٕ یعقوب سٕندِ طاقتور خدایہِ سٕندِ اتھہٕ سٍتـ̡ گٔیہٕ تٔمۍ سٕندِ اتھن ہٕنزِ نٔر مضبوٗط۔ (تتہِ پیٹھہ چُھہ چرواہ، اسرٲیلُک پتھر:)\n25.\\tتہِ چُھہ پننِس مٲلہِ سٕندِ خدایہِ سٕندِ سٍتـ̡ ، یُس تُہٕندِ مدتھ کرِ۔ تہٕ خداتعالیٰ سٕندِ قسم، یُس ژے پیٹھمہِ آسمانٕچ برکت، بۅنہ کنہِ سرٛنِچ برکت، سینن تہٕ رحمن ہٕنز برکت:\n26.\\tتێہٕندِس مٲلہِ سٕنزِ برکت چھے میانین آبن ہٕنزِ نعمتہٕ سٍتـ̡ ابدی بالن ہٕندِس سارِوٕے سٍتـ̡ سٍتـ̡ غٲلب: تِم گژھن یوسف سٕندِس کلس پیٹھ، تہٕ تٔمِس سٕندِس کلہٕ سٕندِس تاجس پیٹھ یُس تٔمۍ سٕندِس بٲے نِش الگ اوس۔\n27.\\tبنیامین کرِ اکھ رامہٕ ہُند شکار، صبحٲے کھٮ۪یہِ شِکار، تہٕ رٲژ کرِ غنیمت بٲگراونہٕ۔\n28.\\tیِم سٲری چھِ اسرٲیلٕکۍ باہ قبیلہٕ: تہٕ یِہ چھُ یِہُند مٲل تِمن سٍتـ̡ کتھ کٔرمٕژ تہٕ تِمن دُعا دِژمٕژ۔ پرٮ۪تھ أکِس کٔر پننہِ دُعا مُطٲبِق تِمن دُعا دِنہٕ۔\n29.\\tتہٕ تٔمۍ ووٚن تِمن ہُند حکم تہٕ وونُن بہٕ یِم پننین لوکن مَنٛز جمع کرنہٕ یُن: میہ کٔرِو پننین مٲلن سٍتـ̡ تتھ غارس مَنٛز دفن یُس افرون دی ہِٹی سٕندِس میدانس مَنٛز چُھ،\n30.\\tتتھ غارس مَنٛز یُس {چُھ} مَمرے برونہہ کُن، کنعان کِس سرزمینس مَنٛز، یُس ابراہیمَن افرون دی ہِٹی سٕندِس کھاہس سٍتـ̡ دفن کرنٕچ جاے حٲصل کرنہٕ خٲطرٕ ہیوٚتمُت۔\n31.\\tاَتہِ کٔر تِمو ابراہیم تہٕ سارہ تٔمۍ سٕنزِ زنانہِ دفن۔ تتہٕ کٔر تمو اسحاق تہٕ ربیکا تٔمۍ سٕنز زنان دفن۔ تہٕ تتہِ کٔر میہ لیہ دفن۔\n32.\\tکھیت تہٕ غار ہٕنز مٔلِتھ یُس {چھُ} اتھ منز {اوس} ہیتھ کین شُرین نِش مٔلِتھ۔\n33.\\tتہٕ یعقوب کٔر پننین نیچوین ہُند حُکُم ختم کرنہٕ، تٔمۍ کٔر بسترس منز پنٕنۍ کھۅر تہٕ ترووُن بھوت تہٕ کوٚرُن پننین لوکن نِش جمع کرنہٕ۔","1. تہٕ یوسف پیوٚو پننِس مٲلہِ سٕندِس بُتھِس پیٹھ، تہٕ روُن أمِس تہٕ بوسہ دِنہٕ۔\n2. تہٕ یوسفَن دِیُت پننِس خادمَن حکیمَن پننِس مٲلِس حنوط کرنُک حُکُم۔\n3. تہٕ تٔمِس خٲطرٕ گٔیہٕ ژتٲجی دۄہ پوٗرٕ۔ یِتھٕ پٲٹھۍ چھِ تِمن ہٕندِ دۅہ پوٗرٕ سپدان یِم حنوط کرنہٕ آمٕتۍ چھِ: تہٕ مصریو کٔر أمۍ سٕندِ خٲطرٕ تریہ تہٕ دہن دۅہن ہُند ماتم ۔ {سوگ: ہیب۔ روُن}\n4. تہٕ ییلہ تٔمۍ سٕندِ ماتم ہٕندِ دۅہ گٔیہِ، یوسفَن ووٚن فرعون سٕندِس گرس سٍتـ̡ وونُن، یێلہِ وۆنـ̡ چُھہ تێلہِ تێلہِ چُھہ تێلہِ بێیہِ تہٕ بێیہِ کٔرِتھ کٔرِو فرعون سٕندِس کَنَس مَنٛز،\n5.\\tمیانہِ مٲلہِ دِژ میہ قسم، لو، بہٕ مرُن: پننہِ قبرِ مَنٛز یُس میہ کنعان کِس سرزمینس مَنٛز کھننہٕ آمُت چھُ، تتہِ کٔرٕ میہ دفن۔ وۅنۍ گژھ میہ تھوٚد، بہٕ ژیہ دُعا کران تہٕ پنُن مول دفن کرُن، تہٕ بہٕ یِنہٕ دُبارٕ۔\n6. تہٕ فرعونن ووٚن، تھوٚد گژھ تہٕ پنُن مول دفن کرُن، یِتھہٕ پٲٹھۍ تٔمۍ ژےٚ قسم۔\n7. تہٕ یوسف ووت پننِس مٲلِس دفن کرنہٕ خٲطرٕ، تہٕ أمِس سٍتـ̡ گٔیہِ فرعون سٕندِ سارِنٕے خادم، تٔمۍ سٕندِس گرٕکۍ زِٹھۍ تہٕ مصرٕکۍ سارِنٕے زِٹھۍ،\n8.\\tتہٕ یوسف سُند سارِوٕے گرٕ تہٕ تٔمۍ سٕندِس بٲے تہٕ مٲلہِ سُند گر، صرف تِہٕندِ لۄکٹۍ شُرۍ، تہٕ تِہٕندِ چارٕ تہٕ تِہٕندِس گاوٕرِس گٔیہِ گوشن کِس ملکس مَنٛز۔\n9.\\tتہٕ تٔمِس سٍتـ̡ گٔیہِ دۅشوے رتھ تہٕ گُرۍ سوار: تہٕ یہِ ٲس سٮ۪ٹھاہ بٔڈ صحبت۔\n10.\\tتہٕ تِم وٲتۍ عطاد کِس تھریشِنگ فلورس پیٹھ، یُس اردن اپارِ چُھ، تہٕ تتہِ کٔر تِمو سٮ۪ٹھاہ سٮ۪ٹھاہ ماتم تہٕ سٮ۪ٹھاہ ماتم تہٕ تٔمۍ کٔر پننِس مٲلہِ سٕندِ خٲطرٕ ستن دۅہن ماتم ۔\n11.\\tتہٕ ییلہ زمینہٕ کین بسکینو کنعانیو عطاد کِس فرشس مَنٛز ماتم وُچھ، تِمو ووٚن زِ یہِ چھُ مصرین ہٕندِ خٲطرٕ اکھ غمگسار ماتم تہٕ اَمہ کِس ناوُک ناو آو اَبلمزرائیم وننہٕ، یُس اردن نیبر چھُ۔ {Abbelmizraim: یعنی مصرین ہند ماتم }\n12. تہٕ تٔمۍ سٕندٮ۪و نیچویو کٔر أمِس سٍتـ̡ یُتھ تٔمِس حُکُم دِیُت:\n13.\\tتکیازِ تٔمۍ سٕندیو نیچوو نِتھ سُہ کنعان کِس سرزمینس مَنٛز، تہٕ دفن کٔرِکھ مکھہ کِس گۅپھِ مَنٛز، یُس ابراہیمَن ممرَس برونہہ کُن افرون دی ہِٹی سٕندِس دفن جایہِ ہٕندِس قبضس مَنٛز ہیوٚت۔\n14. تہٕ یوسف آو مصرس منز واپس، سُہ تہٕ تٔمۍ سٕندِ بٲے تہٕ تٔمۍ سٕندِس مٲلس دفن کرنہٕ پتہٕ تس سٍتـ̡ پننِس مٲلس دفن کرنہٕ خٲطرٕ ہیوٚت۔\n15. تہٕ ییلہ یوسف سٕندٮ۪و بٲے وُچھ زِ تِہُند مول چُھ موٗدمُت، تِمو ووٚن زِ یوسف کرِ اسہِ سٍتـ̡ نفرت، تہٕ یێلہِ دِیہِ اسہِ سارِنٕے بُرٕے سٍتـ̡ یُس أسـ̡ أمِس سٍتـ̡ کورمُت چُھ۔\n16.\\tتہٕ تِمو سوٗز یوسفس نِش اکھ قاصد تہٕ وونُن زِ تُہند مٲل اوس مرنہٕ برونہہ حُکُم دِژمُت، {سُوُن: عبرانی۔ چارج شُد}\n17. یێلہِ کٔرِو ژے یوسف سٍتـ̡ وَنُن، معافی دِیُن، بہٕ چُھس وُنـ̡ تہٕ تِہٕندِس گۅناہ سٍتـ̡ دُعا کٔرِتھ۔ تِکیازِ تِمو کٔر تۅہہِ سٍتـ̡ بد کار تہٕ وۅنۍ چھِ أسـ̡ ژے دُعا کران زِ پننِس مٲلہِ سٕندِس خدایہِ سٕندِس خادمَن ہٕندِس خۅدمَن ہٕندِس خطاہس سٍتـ̡ معافی دِنہٕ۔ تہٕ یوسف روو ییلہِ تِمو أمِس سٍتـ̡ کتھ کٔرِ۔\n18.\\tتہٕ تٔمۍ سٕندِ بٲے تہِ گٔیہِ تٔمۍ سٕندِس بُتھِس برونہہ کُن۔ تہٕ تِمو ووٚن، وُچھِو أسۍ تُہٕندِس خادم۔\n19.\\tتہٕ یوسفَن ووٚن تِمَن زِ خوفہٕ نہٕ کٔرِو، یێلہِ بہٕ چُھس خدایہِ سٕندِس جایہِ پٲٹھۍ؟\n20.\\tمگر ژے کٔر میانہِ خلاف بد خیال۔ {مگر} خدایہ سُند مطلب اوس یہِ اصل، یِتھ کٔنۍ زِ {یہِ} از چُھ، واریاہ لوٗکھ زِندٕ بچاونہٕ خٲطرٕ۔\n21. تێمہِ کِنۍ گژھ نہٕ ژےٚ خوفہٕ: بہٕ کٔرٕ ژےٚ تہٕ تُہٕندٮ۪ن لۄکٹٮ۪ن ہٕنز رچھ۔ تہٕ تٔمۍ کٔر تِمن تسلی دِنہٕ، تہٕ کٔرٕن تِمن سٍتۍ مہربانی سان کتھ کرنہٕ۔ {مہربانی...: ہیب۔ تہندٮ۪ن دلن تام}\n22. تہٕ یوسف اوس مصرس مَنٛز روزان، سُہ تہٕ تٔمۍ سٕندِس مٲلہِ سٕندِس مکانس مَنٛز۔ تہٕ یوسف روٗد ہتھ تہٕ داہ ؤری۔\n23.\\tتہٕ یوسفن وُچھ افرائیم سٕندِ تریمہِ پیدائشہِ ہٕندِس شُرۍ: منسیٰ سٕندِس نیچوِس مکھیر سٕندِ شُرۍ تہِ آیہ یوسف سٕندِس کۅٹھن پیٹھ پرورش کرنہٕ۔ {اننہٕ...: ہیب۔ پیدائش}\n24.\\tتہٕ یوسفَن ووٚن پننٮ۪ن باین زِ بہٕ چُھس مَرُن، تہٕ خدا کرِ یٔقیٖنی طور ژےٚ نِش تہٕ یَتھ زمینہِ منزٕ نِنہٕ یِنہٕ وٲلِس زمینس مَنٛز یُس تٔمۍ ابراہیم، اسحاق تہٕ یعقوب سٍتـ̡ قسم دِژمُت اوس۔\n25.\\tتہٕ یوسفَن کٔر بنی اِسرٲیلِس سٍتـ̡ حلف زِ خدا کرِ یٔقیٖنی طور تہٕ یێلہِ نِش میٲنۍ أڈجہِ تُلِتھ۔\n26.\\tیێلہِ گۆو یوسف ہتھ دہہ وُہُر، تہٕ تِمو کٔر أمِس حنوط تہٕ سُہ آو مصرس مَنٛز تابوتس مَنٛز تھاونہٕ۔"];
